INSERT INTO `expert_posts` VALUES
(17,'7834897649939964240','ન્યુઝ હેડલાઇન્સ - બુધવાર, માર્ચ 18, 2026',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjD-FU1a99i80m0Mt7pGGZSAsFso2oFxMgcu3E0TPfCdDFxutUXgo_i836cONdTk3HSOZRJRA1vrSBtyS_YyQa2YdAQ6jnZh_id919B6NuKr0IIdru_MXOu285GrVfh1icGKIlw8MxePQcvpZ3EZiC4Qp0fviWoHAebFPc5wBLQL6YrUIrkKnQKzFP6KIk/s330/image%20(1).png\"><img height=\"320\" src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjD-FU1a99i80m0Mt7pGGZSAsFso2oFxMgcu3E0TPfCdDFxutUXgo_i836cONdTk3HSOZRJRA1vrSBtyS_YyQa2YdAQ6jnZh_id919B6NuKr0IIdru_MXOu285GrVfh1icGKIlw8MxePQcvpZ3EZiC4Qp0fviWoHAebFPc5wBLQL6YrUIrkKnQKzFP6KIk/s320/image%20(1).png\" width=\"203\" alt=\"image%20(1).png\" /></a></div><div style=\"text-align:center;\"><span style=\"color:#2b00fe;\"><b>Daily News: બુધવાર, માર્ચ 18, 2026</b></span></div><p style=\"text-align:center;\"><span style=\"color:#2b00fe;\"><b>નવીન દેસાઈ - ન્યુ જર્સી  +1(201)699-8042</b></span></p><p style=\"text-align:center;\"><span style=\"color:#2b00fe;\"><b>contact@example.com</b></span></p><p>ઇન્ડિયન ન્યૂઝ:</p><p>1. Share Market : શેર બજારમાં 4 કારણોથી તોફાની તેજી, સેન્સેક્સમાં 567 તો નિફ્ટીમાં 172 પોઈન્ટનો વધારો, 2... મજબૂત ગ્લોબલ સંકેતો, 3... વોલેટિલિટીમાં ઘટાડો, 4... રૂપિયામાં મજબૂતી. ઈન્ડેક્સ : આજે ઈન્ડેક્સ 75826.68 થી શરૂ થઇ નીચે 75324.73 થયો અને ઉપરમાં 76304.26 થયા પછી બંધ 76070.84 રહ્યો.</p><p>2. હોર્મુઝને બાયપાસ કરતો સાઉદીનો \'પ્લાન B\', જાણો ઈરાન યુદ્ધ વચ્ચે પણ દુનિયાભરમાં કેવી રીતે ઓઈલ પહોંચી રહ્યું છે. સાઉદીની \'પૂર્વ-પશ્ચિમ પાઇપલાઇન 1,201 કિલોમીટર, વર્ષ 1981માં ઈરાન-ઇરાક યુદ્ધ પૂર્ણ થયું હતું, 70 લાખ બેરલ પ્રતિદિન. નવા રસ્તે તેલ લઈ જવામાં પણ જોખમ છે, આ વિસ્તાર હુથી બળવાખોરો દ્વારા કરાતા હુમલા માટે જાણીતો છે, </p><p>2. ઈરાન નેતૃત્વ વિહોણું? ખામેનેઈ બાદ નંબર-2 નેતા અલી લારિજાનીનું પણ મોત: ઈઝરાયલનો દાવો</p><p>3. ગુજરાત હાઈકોર્ટનો મહત્ત્વનો ચુકાદો, 16 વર્ષીય દુષ્કર્મ પીડિતાને ગર્ભપાત માટે આપી મંજૂરી</p><p>4. બાળક દત્તક લેનારી મહિલાઓને પણ મળશે મેટરનિટી લીવ: સુપ્રીમ કોર્ટનો ઐતિહાસિક ચુકાદો</p><p>5. ઈરાન પર 7 હજારથી વધુ હુમલા કર્યા, નેવીના 100 જહાજો ડૂબાડી દીધા: ડોનાલ્ડ ટ્રમ્પનો નવો દાવો</p><p>6. ભારતીય વિદ્યાર્થીની કેનેડામાં કરપીણ હત્યા, 10-12 લોકોએ માર મારી કાર ફેરવી દીધી</p><p>7. સસ્પેન્ડ થયેલા 8 સાંસદોનું સસ્પેન્શન રદ પણ શરતો લાગુ ! લોકસભા સ્પીકર પર કાગળો ફેંક્યા હતા</p><p>8. ત્રણ છોકરીઓએ મસ્કની xAI સામે કર્યો કેસ: Grok દ્વારા તેમના સેક્સ્યુઅલ ડીપફેક બનાવવામાં આવ્યો હોવાનો આરોપ…અમેરિકાના ટેનેસી રાજ્યની ત્રણ છોકરીઓ. આ પ્રકારનો કેસ કિશોર વયના બાળકો દ્વારા દાખલ થવાનો આ પહેલો બનાવ માનવામાં આવી રહ્યો છે. xAIએ નફા માટે સુરક્ષા અવગણીઃ વકીલનો આરોપ. ફોટો વાયરલ કરનાર શંકાસ્પદની ધરપકડ.</p><p>9. અમદાવાદ: સરદારનગરમાં અસામાજિક તત્ત્વોનો આતંક, હથિયારધારી ટોળાએ મકાન પર કર્યો હુમલો,</p><p>10. ભદ્રના પાથરણાવાળાની રોજીરોટી આખરે પરત, ફેરિયાઓની તરફેણમાં હાઈકોર્ટના આદેશ બાદ 844 ઘરોમાં ખુશહાલી</p><p>11. વરુણ ગાંધીનો \'રાજકીય વનવાસ\' પૂરો? પરિવાર સાથે PM મોદીની મુલાકાતથી અટકળો તેજ</p><p>12. વસંતનો આરંભ અને દિવસ-રાત સરખા... આગામી 20 માર્ચનો દિવસ એ ખગોળની દૃષ્ટિએ પણ મહત્ત્વનો</p><p>13. ઓડિશાની સરકારી હોસ્પિટલના આઇસીયુમાં આગ, 10 દર્દીનાં મોત- ઇલેક્ટ્રિક ઉપકરણમાં શોર્ટ સર્કિટથી મોટી ઘટના- સાત દર્દીના સ્થળ પર જ્યારે ત્રણના સારવાર દરમિયાન મોત, હોસ્પિટલા સ્ટાફના 11 લોકોને ઇજા </p><p>14. ઈરાનમાં ભારતના ગેટવે ચાબહાર બંદર પર અમેરિકાનો હવાઈ હુમલો- ઈરાન સામેના યુદ્ધમાં ભારતને નુકસાન કરવાનો ટ્રમ્પનો કારસો- ઈરાનના હુમલાના કારણે દુબઈ એરપોર્ટ કલાકો બંધ રાખવું પડયું અમેરિકા-ઇઝરાયેલના લશ્કરી થાણાને પણ નિશાન બનાવાયા</p><p>15. ચીનમાં નવો ચોંકાવનારો ટ્રેન્ડ ‘સાયબર વિડો’: AI બોયફ્રેન્ડ-ગર્લફ્રેન્ડ ગુમાવતા લોકો થઈ રહ્યા છે દુખી, ….. પોતાને સાયબર વિડો કહી રહ્યાં છે. જ્યારે સિસ્ટમ અપડેટ અથવા સર્વર બંધ થવાના કારણે આ સંબંધનો અંત આવે છે. ડિજિટલ પાર્ટનર તરફ વધી રહ્યાં છે લોકો</p><p>16. સિલિન્ડર સંકટ વચ્ચે કેન્દ્ર સરકારની ઓફર, LPGમાંથી PNGમાં શિફ્ટ થશો તો મળશે ફ્રી ગેસ</p><p>17. ભારતમાં એક વર્ષમાં 24 અબજપતિ વધ્યા, ફોર્બ્સની નવી યાદી જાહેર, જુઓ સૌથી વધુ ધનવાનોનું લિસ્ટ</p><p>18. LPG સંકટ વચ્ચે મોટા સમાચાર: 32 લાખ સિલિન્ડર ભરાય એટલો ગેસ લઈને ‘શિવાલિક’ જહાજ ગુજરાત પહોંચ્યું!</p><p>19. ઇરાન યુદ્ધથી 16 દેશમાં હાહાકાર:મોંઘવારી-ભૂખમરાનો અજગર ભરડો, ગેસથી ખતરનાક ખાતર સંકટ, દુનિયામાં ભયાનક અસર, ગલ્ફમાં 90 લાખ ભારતીયો મુશ્કેલીમાં</p><p>20. દાવો- ભારતે હોર્મુઝ પાસે બે યુદ્ધ જહાજો તૈનાત કર્યા:ઓઇલ-ગેસ ભરેલા ભારતીય જહાજોને સુરક્ષા આપશે; આજે પહેલું LPG જહાજ ગુજરાત પહોંચ્યું</p><p>21. ભણો કે ન ભણો, ડિગ્રી લઈને મોજ કરો!:વેરાવળમાં કોંગ્રેસના જોટવા પરિવારની કોલેજમાં ગેરરીતિનો ઘટસ્ફોટ, કાગળ પર સેંકડો વિદ્યાર્થી, ચોરી રોકનાર સ્ક્વોડને પડ્યો હતો માર</p><p>22. સુરતની 12 વર્ષીય માસૂમને પ્રેગ્નન્ટ કરનાર પાડોશીને આજીવન કેદ:દવા લેવા ગયેલી પીડિતાને નિ:વસ્ત્ર કરીને બે વાર કુકર્મ કર્યું, કોર્ટે 10 લાખનું વળતર ચૂકવવા કર્યો હુકમ</p><p>23. રાજકોટમાં યુવકનું કારમાં અપહરણ કરી કુહાડી-પાઈપથી મોતને ઘાટ ઉતાર્યો:અડધો કિમી દૂર લઈ જઈ ફેંકી દીધો, સાનભાન ખોઈ બેસેલી પત્નીએ કહ્યું-મરી જઈશ, મને મારો ભાવલો જોઈએ</p><p>24. બ્રાહ્મણો જાઓ અને યૂરિન પીઓ\':કેનેડામાં હિંદુ યુવક સાથે મારઝૂડનો VIDEO, ખાલીસ્તાનીએ ગાળો આપી; PM મોદીનો આભાર માનવા રેલી કાઢી હતી</p><p>25. એરફોર્સના રિટાયર્ડ ગુજરાતી અધિકારી 1.25 કરોડમાં જાયરોકોપ્ટર વેચશે:એન્જિન ફેલ થઇ જાય તો પણ લેન્ડ થઇ શકે, જોયરાઇડથી લઇને સુરક્ષા માટે પણ ઉપયોગ થઇ શકશે</p><p>26. સુરતમાં પ્રેમલગ્ન કરનાર પરિણીતા પર ગેંગરેપ:રત્નકલાકાર પતિએ ઘરમાં દારૂની મહેફિલ બાદ પત્નીને 3 મિત્રને સોંપી દીધી; મોઢું ખોલ્યું તો લાશ પણ નહીં મળેની ધમકી</p><p>27. કિંજલ રબારીનો યુ-ટર્ન: \'હું રાહ ભટકી ગઈ હતી\':ઘરે પરત ફર્યા બાદ ઈન્સ્ટા પર પોસ્ટ મુકી; \'મેં સ્વેચ્છાએ પરિવાર સાથે રહેવાનો નિર્ણય કર્યો છે, અફવાઓથી દૂર રહેવા અપીલ\'</p><p>28. ટ્રમ્પને ચીન-જાપાન પાસેથી મદદ શા માટે માગવી પડી, શું અમેરિકા ઈરાનથી હારી રહ્યું છે; હોર્મુઝ સ્ટ્રેટ ખોલાવવું આટલું મુશ્કેલ કેમ?</p><p>29. કાવ્યા મારન પર સુનીલ ગાવસ્કર બરાબરના ભડક્યા:સનરાઇઝર્સમાં પાકિસ્તાની ખેલાડીની એન્ટ્રી પર કહ્યું- ભારતીયોના જીવ સાથે ચેડાં કરવા સમાન</p><p>30. રાજ્યસભા ચૂંટણી- હરિયાણામાં 6 કલાક પછી મતગણતરી શરૂ:પરિણામ થોડીવારમાં; NDAએ બિહાર-ઓડિશાની 9માંથી 8 બેઠકો જીતી</p><p>31. ઉનાના ચકચારી દલિતકાંડમાં 5 આરોપી દોષિત:ગાયનું ચામડું ઉતારી રહ્યા હોવાનો આરોપ લગાવી માર માર્યો હતો; દાયકા પછી સેશન્સ કોર્ટનો ચૂકાદો, 38 નિર્દોષ</p><p>32. PNG-LPG બંને કનેક્શન હોય તો બુધવાર સુધીમાં સરેન્ડર કરવું પડશે:પરિવાર દીઠ 5 લિટર કેરોસીન અપાશે, ગુજરાતમાં ગેસ પુરવઠા પર સરકારનો નિર્ણય</p><p>33. મોરબીમાં 250 સિરામિક કારખાના બંધ થતાં હજારો શ્રમિકોએ રોજગારી ગુમાવી:પરપ્રાંતિય શ્રમિકો પરિવાર સાથે વતન જવા રવાના, વાંકાનેર રેલવે સ્ટેશન પર ભીડ</p><p>34. ઈરાન યુદ્ધ વચ્ચે લેબનોન કબજે કરવામાં વ્યસ્ત નેતન્યાહુ:આખરે \'ગ્રેટર ઇઝરાયલ\'નું સ્વપ્ન શું છે; શું આ કારણે 29 મહિનાથી યુદ્ધ ચાલુ છે</p><p>35. ₹80 લાખનો ડ્રેસ અને કરોડોની જ્વેલરી!:ઓસ્કરમાં ઈશા અંબાણી અને પ્રિયંકાનો \'રોયલ ઠાઠ\' જોઈ હોલિવૂડની આંખો અંજાઈ; \'દેશી ગર્લ\'ના વિદેશી પતિની હિન્દુ આસ્થા દેખા</p><p>36. ચાર સગીરનો SSCના વિદ્યાર્થી પર રેમ્બો છરીથી હુમલો:ત્રણ ઘા ઝીંકતા ગંભીર, અઢી માસ પહેલાં ઓનલાઇન ચપ્પુ મંગાવી રાખ્યું\'તું, ડાન્સ સમયે પગ વાગતા અદાવત રાખી</p><p>37. ભઠ્ઠીના ‘અગ્નિસંસ્કાર’ મોંઘા, ₹1100 આપવા પડશે:સુરતના સ્મશાનોને મફતમાં મળતો ગેસ પુરવઠો બંધ; રોજના 20થી 25 અગ્નિદાહ, ગેસ કંપનીઓ ટૂંક સમયમાં ભાવ વધારી શકે</p><p>38. સાઇકલવાળાને કહ્યું ‘હું પડુ છું જોજો.. કહીને કેનાલમાં કૂદી ગયો’:વડોદરામાં યુવકે આપઘાત કરતા દુકાન માલિકે બુમાબુમ કરી મૂકી, અઠવાડિયાથી કહેતો\'તો હું આજે કેનાલમાં પડીને મરી જઈશ</p><p>39. યુવાનોમાં હાઈ બ્લડ પ્રેશરનું પ્રમાણ વધ્યું!:નાની ઉંમરે હાઇપરટેન્શન થવા પાછળ 9 કારણો જવાબદાર; 11 ગંભીર બીમારીઓથી બચવા 14 ટિપ્સ અપનાવો</p><p>40. ધર્મેન્દ્રને ઓસ્કરમાં સન્માન ન મળતા હેમા માલિની લાલઘૂમ:એક્ટ્રેસે કહ્યું- \'જેને કરોડો ચાહકો પ્રેમ કરે છે, તેવા કલાકારની અવગણના ઓસ્કર કમિટી માટે શરમની વાત છે\'</p><p>41. કાન્યે વેસ્ટનો દિલ્હીનો કોન્સર્ટ પોસ્ટપોન:ઈરાન-ઈઝરાયલ યુદ્ધને પગલે શો પર અસર; અમેરિકી રેપરને રુબરુ સાંભળવા ચાહકોએ બે મહિના રાહ જોવી પડશે</p><p>42. ગાંધીનગરના કર્મયોગી ભવનને બોમ્બથી ઉડાવી દેવાની ધમકી:સેક્ટર-10ના તોલમાપ વિભાગને ધમકીભર્યો ઈમેલ મળ્યો, BDDS અને ડોગ સ્ક્વોડ દ્વારા સર્ચ ઓપરેશન</p><p>43. બંગાળમાં ભાજપે 144 ઉમેદવારોની પહેલી યાદી બહાર પાડી:સુવેન્દુ અધિકારીને મમતાની બંને બેઠકો ભવાનીપુર-નંદીગ્રામથી ટિકિટ, કેરળમાં 47 ઉમેદવારોની જાહેરાત</p><p>44. BCG રિપોર્ટ: પાર્ટ-2 યુએસમાં ભારતવંશીઓનું કેટલું પ્રભુત્વ?:અમેરિકી પેટન્ટમાં ભારતવંશીઓની ભાગીદારી 50 વર્ષમાં 5 ગણી વધી ગઈ</p><p>45. BCG રિપોર્ટ: પાર્ટ-2 યુએસમાં ભારતવંશીઓનું કેટલું પ્રભુત્વ?:અમેરિકી પેટન્ટમાં ભારતવંશીઓની ભાગીદારી 50 વર્ષમાં 5 ગણી વધી ગઈ</p><p>46. સંકટ સમયે કોઈની સામે હાથ ફેલાવવાની જરૂર નથી!:ગણતરીની મિનિટોમાં \'ઇમરજન્સી લોન\' મેળવો, જાણો સ્ટેપ-બાય-સ્ટેપ પ્રક્રિયા; ફ્રોડ એપ્સથી બચવાની ટિપ્સ</p><p>47. કેફેએ લીંબુ પાણી પર 5% ગેસ-ક્રાઇસિસ ચાર્જ વસૂલ્યો:₹358ના બિલ પર ₹17 વધારાના લીધા; યુઝર્સે કહ્યું- આ બનાવવામાં કયો ગેસ લાગે છે. બેંગલુરુ</p><p>48. કેફેએ લીંબુ પાણી પર 5% ગેસ-ક્રાઇસિસ ચાર્જ વસૂલ્યો:₹358ના બિલ પર ₹17 વધારાના લીધા; યુઝર્સે કહ્યું- આ બનાવવામાં કયો ગેસ લાગે છે. બેંગલુરુ</p><p>49. પૂર્વ PM દેવગૌડાએ રાહુલના પ્રદર્શનની ટીકા કરી:સોનિયાને પત્ર લખીને કહ્યું- સંસદની સીડીઓ પર ચા-નાસ્તો કરવાથી તેની ગરિમા ખરડાય છે</p><p>50. ભૂત બંગલા\'માત્ર હોરર-કોમેડી નહીં, પણ રહસ્યોનો ખજાનો!:રાજપાલ યાદવે કહ્યું, \'હું ક્યારેય પ્રિયદર્શન સર પાસેથી ફિલ્મની સ્ક્રિપ્ટ માગતો નથી</p><p>51. ભૂત બંગલા\'માત્ર હોરર-કોમેડી નહીં, પણ રહસ્યોનો ખજાનો!:રાજપાલ યાદવે કહ્યું, \'હું ક્યારેય પ્રિયદર્શન સર પાસેથી ફિલ્મની સ્ક્રિપ્ટ માગતો નથી</p><p>52. રબને બના દી જોડી!:વર બંને પગે દિવ્યાંગ, વધૂ બોલી-સાંભળી નથી શકતી; ઉદયપુરમાં દેશભરમાંથી આવેલા દિવ્યાંગોનાં અનોખાં \'ડેસ્ટિનેશન વેડિંગ\'</p><p>53. સલમાનને મળ્યા અખિલેશ યાદવ:પિતા સલીમ ખાનની તબિયત પૂછવા મુંબઈ આવ્યા; સોશિયલ મીડિયા પર ફોટો શેર કર્યો</p><p>54. પતિએ છુટાછેડા આપી દેવાની ધમકી આપતા પરિણીતાએ દવા ગટગટાવી- ગઢડા પોલીસ મથકમાં સાસુ અને પતિ વિરુદ્ધ ફરિયાદ નોંધાઈ- પતિ અને સાસુએ પરિણીતા સાથે ઝઘડો કરી માર માર્યો હતો</p><p>55. અમદાવાદના નોબલનગર નજીક કચરામાં મહિલાનો સળગેલી હાલતમાં મૃતદેહ મળ્યો, પોલીસે તપાસ હાથ ધરી</p><p>56. ઘરમાં એક સમયે કેટલા ગેસ સિલિન્ડર રાખી શકાય? નિયમો તોડનારાને ખાવી પડશે જેલની હવા</p><p>57. આ હત્યાકાંડ છે, ઓપરેશન નહીં... પાકિસ્તાનના હુમલામાં 400 મોત બાદ અફઘાનિસ્તાનને ભારતનો ટેકો. હવે ડિપ્લોમેસી નહીં, પાકિસ્તાનને તેની જ ભાષામાં જવાબ આપીશું: 400 મોત બાદ અફઘાનિસ્તાનની પ્રતિજ્ઞા</p><p>58. રાષ્ટ્રપતિ દ્રૌપદી મુર્મૂની વૃંદાવન મુલાકાત: વાંદરાઓના ત્રાસને રોકવા તંત્રનો અનોખો પ્લાન</p><p>59. ભારતમાં આતંકવાદી કાવતરું: NIAએ 6 યુક્રેનિયન 1 અમેરિકન નાગરિકની કરી ધરપકડ</p><p>60. ઇસ્લામોફોબિયાની કાલ્પનિક વાર્તાઓ બનાવવામાં પડોશી દેશ માહેર: UNમાં ભારતનો પાકિસ્તાન પર પ્રહાર</p><p>આંતરાષ્ટ્રીય સમાચાર:</p><p>1. ખામેનેઈ સહિત 40 કમાન્ડર્સના મોત છતાં US-ઈઝરાયલને કેવી રીતે હંફાવી રહ્યું છે ઈરાન? મોઝેક ફોર્મ્યુલા, આર્થિક નાકાબંધી, મીડિયા વોરફેર, સચોટ મેસેજિંગ, આંતરિક એકતા</p><p>2. અહંકાર નડ્યો! ટ્રમ્પની આ 5 મોટી ભૂલોને કારણે ઈરાન યુદ્ધમાં ખરાબ રીતે ફસાયું અમેરિકા</p><p>3. વેનેઝુએલા, ઈરાન બાદ હવે આ દેશ પર ટ્રમ્પની નજર, કહ્યું- હું જે ઈચ્છું તે કરી શકું છું. ક્યુબા</p><p>4. અમને પૂછીને શરૂ કર્યું હતું? ઈરાન સાથેના યુદ્ધમાં સાથીઓ શોધી રહેલા ટ્રમ્પને આ દેશે આપ્યો ઝટકો. નાટોના સભ્ય દેશ જર્મનીએ આ યુદ્ધમાં જોડાવાની ચોખ્ખી ના પાડી દીધી.</p><p>5. ચીની ઈ-કોમર્સ કંપની અલીબાબા AI માટે અલગ બિઝનેસ ગ્રુપ બનાવશે- ગૂગલ, માઈક્રોસોફ્ટને ટક્કર આપવાની તૈયારી- ક્લાઉડ કમ્પ્યુટિંગ, લાર્જ લેંગ્વેજ મોડલ્સ અને અન્ય ટેકનોલોજી પ્રોજેક્ટ્સને એક સાથે લાવવામાં આવશે</p><p>6. ઈરાન-ઈઝરાયેલ-અમેરિકા યુદ્ધને પગલે હવે દૂધ સપ્લાય જોખમમાં- ગેસ સંકટની અસર હવે ડેરી ઉદ્યોગ પર, 10 દિવસનો પેકેજિંગ જ સ્ટોક બાકી- એલપીજીની અછત મિલ્ક પ્રોસેસિંગ, પેશ્ચરાઇઝેશન અને પેકેજિંગ પર અસર : ડેરી સંચાલકોની સરકારને ચેતવણી</p><p>7. ભારત-અમેરિકા ટ્રેડ ડીલ અમેરિકાનું નવું ટેરિફ માળખું બનશે પછી જ થશે- ભારતે વેપાર કરારની વાટાઘાટો લંબાવી- બંને પક્ષ હાલમાં કરારની અન્ય વિગતોને અંતિમ ઓપ આપવા પર કામ કરી રહ્યા છે- ટ્રમ્પે હાલમાં નાખેલો 10 ટકા ટેરિફ પાંચ મહિના સુધી ચાલશે, પછી યુએસ કોંગ્રેસની મંજૂરી લેવી પડશે</p><p>8. હોર્મુઝ ખાડીમાં યુદ્ધ જહાજો મોકલવા સાથી દેશોનો ઇનકાર- અમેરિકાના પ્રમુખ ડોનાલ્ડ ટ્રમ્પ વિશ્વમાં એકલા પડી ગયા: આ યુદ્ધ અમારું નથી: યુરોપ  - મધ્ય-પૂર્વમાં યુદ્ધ ઇરાને શરૂ કર્યુ નથી, પહેલા તમે યુદ્ધ બંધ કરો પછી વાટાઘાટ થશે: ચીને અમેરિકાની બોલતી બંધ કરી</p><p>9. વ્લાદિમીર પુતિન \'છુપાઈ જાય છે\' કારણ કે તેમને ડર છે કે તેમના પર નજર રાખવામાં આવશે અને તેમની હત્યા થઈ શકે છે.</p><p>10. અટકાયતમાંથી મુક્તિ મેળવવા માંગતા ઇમિગ્રન્ટ્સ તરફથી કટોકટીના મુકદ્દમા તાજેતરના અઠવાડિયામાં ઘટ્યા છે, કારણ કે ટ્રમ્પ વહીવટીતંત્રે, ઓછામાં ઓછા હાલ માટે, મિનિયાપોલિસ અને દેશભરના શહેરોમાં કરેલા આક્રમક, લશ્કરી-શૈલીના ઇમિગ્રેશન અમલીકરણથી થોડું પીછેહઠ કરી છે.</p><p>11. વિરોધ પ્રદર્શનની હિંસક રાત્રિ દરમિયાન ક્યુબન લોકો \'સામ્યવાદ મુલતવી રાખો\' ના નારા લગાવે છે, સરકારી ઇમારત પર હુમલો કરે છે</p><p>12. યુદ્ધભૂમિ ટેકનોલોજી પરીક્ષણ શરૂ થતાં યુક્રેનમાં માનવીય સૈનિક રોબોટ્સ પહોંચ્યા</p><p>13. યુએસ નેવી ડિસ્ટ્રોયર્સ નાટો એરસ્પેસમાં ઉડતી ઈરાની મિસાઇલોને તોડી પાડવા માટે ટોચના ઇન્ટરસેપ્ટર્સ ફાયર કરી રહ્યા છે</p><p>14. તાઇવાન ટાપુ નજીક મોટા પાયે ચીની નાની બોટો નુ ઝુંડ અને લશ્કરી વિમાનોની હાજરીનો અહેવાલ આપે છે</p><p>15. બરાક ઓબામાએ જાહેરાત કરી કે તેઓ અને મિશેલ ઓબામા આખરે આ ઉનાળામાં શિકાગોમાં તેમનું \'ઓબામા પ્રેસિડેન્શિયલ સેન્ટર\' ખોલી રહ્યા છે ત્યારે ચાહકોએ પ્રતિક્રિયા આપી: \'સુંદર લાગે છે\'</p><p>16. મેક્સીકન અધિકારીઓએ એક શંકાસ્પદ ડ્રગ ટ્રાફિકરની ધરપકડ કરી છે જેણે ગયા મહિને મેક્સીકન ડ્રગ લોર્ડ નેમેસિયો ઓસેગુએરાના મૃત્યુ તરફ દોરી ગયેલા દરોડામાં મુખ્ય ભૂમિકા ભજવી હતી, એમ સંરક્ષણ મંત્રાલયે રવિવારે જણાવ્યું હતું.</p><p>17. એરલાઇન એક્ઝિક્યુટિવ્સ કોંગ્રેસને સરકારી શટડાઉન દરમિયાન TSA કામદારોને વધુ સારી રીતે ટેકો આપવા માટે હાકલ કરી રહ્યા છે. તેઓએ કહ્યું કે TSA અધિકારીઓ માટે \"$0 પગાર\" મેળવવો \"માત્ર અસ્વીકાર્ય\" છે. ઘણા અવેતન કામદારો શિફ્ટ છોડી રહ્યા છે, જેના કારણે એરપોર્ટ પર લાંબી કતારો અને રાહ જોવાનો સમય આવે છે.</p><p>18. જાપાનમાં યુ.એસ. બેઝ બાંધકામ સ્થળ પર વિદ્યાર્થીઓને લઈ જતી હોડીઓ પલટી જતાં ૨ લોકોના મોત. જાપાન કોસ્ટ ગાર્ડે જણાવ્યું હતું કે હોડીઓમાં સવાર ૨૧ લોકોમાંથી ૧૮ લોકો ક્યોટો હાઇ સ્કૂલના વિદ્યાર્થીઓ હતા જેઓ તેમના શાંતિ શિક્ષણ કાર્યક્રમના ભાગ રૂપે હેનોકો વિસ્તારનું નિરીક્ષણ કરવા માટે ત્યાં ગયા હતા.</p><p>19. પરિવારોને નકલી રાખ આપવા બદલ ભૂતપૂર્વ અંતિમ સંસ્કાર સ્મશાન માલિકને ૨૦ વર્ષની જેલની સજાનો સામનો કરવો પડી શકે છે. અંતિમ સંસ્કાર સેવાઓ માટે ૧૩૦,૦૦૦ ડોલરથી વધુ લેવા અને તેના બદલે ઘણીવાર કોંક્રિટ મિશ્રણથી ભરેલા ભઠ્ઠીઓ સોંપવા બદલ કેરી હોલફોર્ડને ૨૦ વર્ષની જેલની સજાનો સામનો કરવો પડી શકે છે.</p><p>20. દાયકાઓ જૂના ઓડિયો સાધનો પર શોધાયેલ એક ભૂતિયા વ્હેલ ગીત વિશાળ પ્રાણીઓ કેવી રીતે વાતચીત કરે છે તેની નવી સમજ ખોલી શકે છે, સંશોધકોના મતે, જે આ પ્રકારની સૌથી જૂની રેકોર્ડિંગ હોવાનું માને છે.</p><p>21. ઈરાન યુદ્ધ પર ટ્રમ્પ - \"કદાચ આપણે ત્યાં બિલકુલ ન હોવું જોઈએ... તે લગભગ એવું છે કે આપણે આદત માટે કરીએ છીએ\"</p><p>22. ઇમિગ્રન્ટ ટ્રકર્સ માટે ટ્રમ્પ દ્વારા લાઇસન્સ રદ કરવાનો નિર્ણય અમલમાં આવ્યો</p><p>23. મધ્ય પૂર્વમાં સોંપાયેલા અમેરિકાના ૩ mines-શિકાર જહાજોમાંથી ૨ એશિયામાં જોવા મળ્યા</p><p>24. દેશનિકાલ કરાયેલા ઈરાની ક્રાઉન પ્રિન્સ કહે છે કે તેઓ \'ઈસ્લામિક રિપબ્લિકનું પતન થતાં જ\' ઈરાનનું નેતૃત્વ કરવા તૈયાર છે</p><p>25. પ્રેસ કોન્ફરન્સ દરમિયાન પુતિન અનિયંત્રિત રીતે ખાંસી ખાતો હોવાનો વીડિયો સરમુખત્યારના સ્વાસ્થ્ય વિશે નવા પ્રશ્નો ઉભા કરે છે</p><p>26. ભૂતપૂર્વ નેવી સીલ રોબર્ટ જે. ઓ\'નીલ કહે છે કે તેણે ૨૦૧૧માં પાકિસ્તાનમાં યુ.એસ. નેવી સીલ ટીમ સિક્સના દરોડા દરમિયાન ઓસામા બિન લાદેનને મારવા માટે ગોળી ચલાવી હતી. તેને ખેલાડીઓને પ્રોત્સાહિત કરવા માટે લાવવામાં આવ્યો હતો અને X પર પણ પોસ્ટ કરવામાં આવ્યો હતો, તેમને \"Knock ‘Em Dead Tonight Boys” કહેવાનું કહેવામાં આવ્યું હતું.</p><p>27. Nasdaq ના CEO Adena Friedman ને ખાતરી છે કે AI સોફ્ટવેર માટે મૃત્યુદંડ નથી.</p><p>28. આ અઠવાડિયે ફેડના ચેરમેન તરીકે જેરોમ પોવેલની અંતિમ બેઠક છે - એવી અપેક્ષા રાખશો નહીં કે તેઓ વોલ સ્ટ્રીટ પર ઘણા સંકેતો આપશે.</p><p>29. ઇલિનોઇસ સેનેટ સીટ માટે ડેમોક્રેટિક લડાઈ JB પ્રિટ્ઝકર, ક્રિપ્ટો-પ્રો-ફોર્સ અને ICE-વિરોધી મેસેજિંગના પ્રભાવનું પરીક્ષણ કરી રહી છે.</p><p>30. ઈરાનના ગુમ થયેલા નવા સુપ્રીમ લીડર \'હવાઈ હુમલામાં અપંગ થયા પછી જીવન સહાય પર છે જેમાં તેમના આતંકવાદી પિતાનું મૃત્યુ થયું હતું\'.</p><p>31. હોમલેન્ડ સિક્યુરિટી વિભાગ ટૂંક સમયમાં નવા સંચાલન હેઠળ આવશે, રાષ્ટ્રપતિ ડોનાલ્ડ ટ્રમ્પના ઇમિગ્રેશન એજન્ડાને ફરીથી સેટ કરવાની અથવા અમેરિકન ઇતિહાસમાં સૌથી મોટી દેશનિકાલ કામગીરી હાથ ધરવાના તેમના સહી ઝુંબેશના વચનને બમણું કરવાની તક.</p><p>32. સુપ્રીમ કોર્ટના ટેરિફ ચુકાદા પછી મલેશિયા યુએસ ટ્રેડ ડીલને \'શૂન્ય અને રદબાતલ\' જાહેર કરનાર પ્રથમ દેશ બન્યો</p><p>33. રશિયા કહે છે કે તેના હવાઈ સંરક્ષણે થોડા કલાકોમાં સેંકડો યુક્રેનિયન ડ્રોનને અટકાવ્યા છે, અને દાવો કર્યો છે કે યુદ્ધમાં પહેલાં ક્યારેય ન જોયેલા હવાઈ હુમલાનો મોટો જથ્થો છે.</p><p>34. ગયા અઠવાડિયે યુએસ દ્વારા નવી વેપાર તપાસ શરૂ કર્યા પછી, ચીને સોમવારે કહ્યું કે તેણે \"રજૂઆતો નોંધાવી છે\" અને વોશિંગ્ટનને \"તેના ભૂલભરેલા રસ્તાઓ સુધારવા\" વિનંતી કરી છે, જેમાં બંને દેશોના વાટાઘાટકારો પેરિસમાં મળ્યા હતા.</p><p>35. ઈરાન સાથે જોડાયેલા હેકર્સ \'મહત્વપૂર્ણ\' સાયબર હુમલો કરે છે</p><p>36. ન્યુ જર્સી સ્થિત એક વૈશ્વિક શિપિંગ કંપની એક કાર્ગો જહાજની માલિકી ધરાવે છે જેના પર આ અઠવાડિયે પર્સિયન ગલ્ફમાં હુમલો કરવામાં આવ્યો હતો, જેના કારણે એક ક્રૂ સભ્યનું મૃત્યુ થયું હતું, કંપનીના અધિકારીઓએ જણાવ્યું હતું.</p><p>37. ટેનેસી પબ્લિક સ્કૂલ્સમાં ઇમિગ્રેશન સ્ટેટસ ચેકની આવશ્યકતા ધરાવતું બિલ વિધાનસભામાં આગળ વધ્યું </p><p>38. ટ્રમ્પ કહે છે કે જો તેઓ હમણાં ઈરાન છોડી દે તો “તેમને ફરીથી બનાવવામાં ૧૦ વર્ષ કે તેથી વધુ સમય લાગશે — પણ હું હજુ પણ તે પૂરું થવાનું જાહેર કરી રહ્યો નથી”</p><p>39. રશિયાએ સોવિયેત નેતા ખ્રુશ્ચેવની પ્રપૌત્રીને \'વિદેશી એજન્ટ\' તરીકે જાહેર કરી</p><p>40. ટ્રમ્પ વહીવટીતંત્રને ટિકટોક ડીલમાંથી ૧૦ બિલિયન ડોલર મળવાના અહેવાલ છે</p><p>41. અમેરિકા અને તેના સાથી દેશો રશિયા સાથે નાટોની સરહદ પર કાઉન્ટર-ડ્રોન નેટવર્ક બનાવી રહ્યા છે. પરીક્ષણ પ્રક્રિયા ઝડપથી ચાલ, ઝડપથી નિષ્ફળ, ઝડપી સુધારવાના અભિગમને અનુસરે છે. કવાયતમાં વિવિધ સેન્સર અને કાઉન્ટર-ડ્રોન ઇન્ટરસેપ્ટર્સ સામેલ હતા.</p><p>42. જ્યારે મધ્ય પૂર્વમાં તણાવ વધે છે, ત્યારે તેની અસરો એક સરહદ સુધી મર્યાદિત રહેતી નથી. નજીકના દેશો શાંતિથી ગોઠવણ કરવાનું શરૂ કરે છે - એકમો ખસેડે છે, સરહદોને મજબૂત બનાવે છે અને એવી સમસ્યાઓ માટે તૈયારી કરે છે જે ક્યારેય ન આવે પણ ધ્યાન માંગે છે. પાકિસ્તાન તે દેશોમાંનો એક છે જે પરિસ્થિતિને કાળજીપૂર્વક જોઈ રહ્યો છે.</p><p>43. કિવ પ્રદેશ પર રશિયન હુમલામાં ૪ લોકોના મોત અને ૧૫ ઘાયલ, શાંતિ વાટાઘાટો સ્થગિત</p><p>44. ગોલ્ડમેનના ટોચના આંતરરાષ્ટ્રીય અધિકારીઓ કહે છે કે ઈરાન યુદ્ધ રશિયાના યુક્રેન પરના આક્રમણ સાથે સમાનતા ધરાવે છે, પરંતુ તેમાં મુખ્ય તફાવતો છે</p><p>45. \'અસ્વીકાર્ય\' ઇરાક ડ્રોન હુમલામાં ફ્રેન્ચ સૈનિક માર્યો ગયો અને છ ઘાયલ થયા, મેક્રોન કહે છે</p><p>46. ઉત્તર કોરિયામાં સુપ્રીમ પીપલ્સ એસેમ્બલીની ચૂંટણી યોજાઈ, KCNA અહેવાલો</p><p>47. માન્યતા માટે એક દાયકા લાંબી કાનૂની લડાઈ પછી, ચેપકોચ ટૂ એક ઉચ્ચ-દાવના ઉત્તરાધિકાર કેસમાં વિજયી બન્યા છે જેણે કેન્યાને મોહિત કરી દીધો છે. ગયા અઠવાડિયે, એલ્ડોરેટ શહેરની હાઇકોર્ટે તેમને સત્તાવાર રીતે KANU યુગના સુપ્રસિદ્ધ પાવર બ્રોકર, સ્વર્ગસ્થ માર્ક કિપ્ટારબેઇ અરાપ ટૂની જૈવિક પુત્રી જાહેર કરી. પ્રમુખ ન્યાયાધીશ અનુરો વાનાન્ડા દ્વારા આપવામાં આવેલા ચુકાદાથી ચેપકોચને અંદાજિત શિલિંગ ૭ અબજ (લગભગ $૫૪ મિલિયન) ની મિલકતના લાભાર્થી તરીકે કાનૂની દરજ્જો મળે છે.</p><p>48. ઝેલેન્સકી દ્વારા મધ્ય પૂર્વમાં ડ્રોન સંરક્ષણ નિષ્ણાતો મોકલ્યા બાદ ઈરાને યુક્રેન પર હુમલો કરવાની ધમકી આપી: \'કાયદેસર લક્ષ્ય\'</p><p>49. તુર્કીનું કહેવું છે કે નાટો સંરક્ષણ દળોએ ઈરાનથી ત્રીજી મિસાઈલ અટકાવી, તેહરાનને સ્પષ્ટતા કરવા કહ્યું</p>','https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjD-FU1a99i80m0Mt7pGGZSAsFso2oFxMgcu3E0TPfCdDFxutUXgo_i836cONdTk3HSOZRJRA1vrSBtyS_YyQa2YdAQ6jnZh_id919B6NuKr0IIdru_MXOu285GrVfh1icGKIlw8MxePQcvpZ3EZiC4Qp0fviWoHAebFPc5wBLQL6YrUIrkKnQKzFP6KIk/s320/image%20(1).png','2026-03-18','active','2026-09-25 07:55:05','2026-09-25 07:55:05'),
(18,'4314612080849912770','Nifty Outlook :- 17.03.2026 - CFA Hitesh Somani',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgxlN_mamNj3kBhg4XAA33peHkHHRlIuqoTbPWjYNOLDWS6EksJOWp1Mgh8fpMJwznpWo7uu62T09lknPMxNjT_28hq4UJo8gT3w3DFu9AC7bUFVBHLVannkW61VvSgoUD1rdkeQCG6-ob0ix_HEi6-AJ_mDBmQKpRub7nSfd_dmn2Akfi8oemgv43N5pU/s622/image.png\"><img height=\"301\" src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgxlN_mamNj3kBhg4XAA33peHkHHRlIuqoTbPWjYNOLDWS6EksJOWp1Mgh8fpMJwznpWo7uu62T09lknPMxNjT_28hq4UJo8gT3w3DFu9AC7bUFVBHLVannkW61VvSgoUD1rdkeQCG6-ob0ix_HEi6-AJ_mDBmQKpRub7nSfd_dmn2Akfi8oemgv43N5pU/s320/image.png\" width=\"320\" alt=\"image.png\" /></a></div><br /><div style=\"text-align:justify;\"><div style=\"text-align:center;\"><b><b><span>CFA Hitesh Somani</span></b></b></div><div style=\"text-align:center;\"><b><b><span>MD - <a href=\"https://www.google.com/search?ved=1t:260882&amp;q=Aapka+Investments&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">Aapka Investments</a> </span></b></b></div><div style=\"text-align:center;\"><b><b><span>Website - https://www.aapkainvestments.in</span></b></b></div></div><p><b><span>Markets in deep selling panic, <a href=\"https://www.google.com/search?ved=1t:260882&amp;q=Nifty+index+overview&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">Nifty</a>, <a href=\"https://www.google.com/search?ved=1t:260882&amp;q=Sensex+index+overview&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">Sensex</a> and <a href=\"https://www.google.com/search?ved=1t:260882&amp;q=Banknifty+index+overview&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">Banknifty</a> are facing\r\nheavy selling pressure, Banknifty plunges 7000 points from top, what next?</span></b></p><div style=\"text-align:justify;\"><div style=\"text-align:center;\">\r\n\r\n\r\n\r\n<div style=\"font-weight:bold;text-align:justify;\"><span>Last week markets have faced a heavy\r\nselling pressure amid war situations and rising gas cylinder prices, we saw a\r\nglobal sell off in the markets and all index fell with heavy selling panic.\r\nNifty fell near 23000 levels and banknifty was dragged 7000 points down and\r\nfell below 54000 from its recent high near 61000. <a href=\"https://www.google.com/search?ved=1t:260882&amp;q=PSU+banks+stock+performance&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">PSU banks</a> was the most who\r\nfell on Friday. In the whole week, there was no positive day on the markets,\r\neveryday nifty closed with nearly 400 – 500 points down which shows that\r\nmarkets are in deep panic amid global war tensions</span></div><div style=\"text-align:justify;\"><span style=\"font-weight:bold;\">In the last week nifty fell more than 1400\r\npoints and closed near 23150 levels. Now nifty is near its support @23000 if in\r\nthe coming week nifty closes below 23000 then we may see it fall further and it\r\nmay fall towards 22000 levels also. Banknifty also fell sharply towards 54000\r\nlevels indicating a further downside till 52000 and 50000 levels.</span></div>\r\n\r\n<p style=\"font-weight:bold;text-align:justify;\"><span>In the coming week also we can see some\r\nfurther downside in the markets, but if the war situations gets under control,\r\nmarkets may revive from the bottom levels but in the current scenarios markets\r\nare in sell on rise mood. We can only expect good upside in the markets if\r\nnifty manages to sustain above 25000 levels till that time investors must\r\nremain cautious and wait to buy on dips.</span></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><b><span><span>Important Levels for Nifty Next Week</span></span></b></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Major Support Levels for Nifty</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Support 1 – 23000</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Support 2 – 22500            </span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Support 3 – 22000</span></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Major Resistance Levels for Nifty</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Resistance 1 – 23700</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Resistance 2 – 24200</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Resistance 3 – 24800</span></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><b><span><span>Important Levels for Banknifty Next Week</span></span></b></p>\r\n\r\n\r\n\r\n<div style=\"font-weight:bold;text-align:left;\"><span>Major Support Levels for Banknifty</span></div>\r\n<div style=\"text-align:left;\">Support 1 – 53500</div>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Support 2 – 52800</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Support 3 – 52200</span></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span> Major Resistance Levels for Banknifty</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Resistance 1 – 54200</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Resistance 2 – 54900</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Resistance 3 – 55400</span></p>\r\n\r\n\r\n\r\n<p style=\"text-align:left;\"><span><b><span>Important Stocks to Watch Next Week</span></b></span></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><b><span>1) <a href=\"https://www.google.com/search?ved=1t:260882&amp;q=HINDUNILEVER+stock+price&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">HINDUNILEVER</a></span></b></p>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>CMP 2160</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Buy Above 2200</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:left;\"><span>Stop Loss Below 2110</span></p>\r\n\r\n<div style=\"font-weight:bold;text-align:left;\"><span>Targets – 2290, 2390 AND 2490</span></div>\r\n\r\n\r\n\r\n\r\n<div style=\"text-align:left;\"><span><span style=\"font-weight:bold;\">2) </span><b><a href=\"https://www.google.com/search?ved=1t:260882&amp;q=AUROPHARMA+stock+price&amp;bbid=7838494089008335820&amp;bpid=4314612080849912770\" target=\"_blank\" rel=\"noreferrer noopener\">AUROPHARMA</a></b></span></div><div style=\"text-align:left;\">CMP 1290</div>\r\n<div style=\"text-align:left;\">BUY ABOVE 1320</div>\r\n<div style=\"text-align:left;\">STOP LOSS BELOW 1260</div>\r\n<div style=\"text-align:left;\">TARGETS – 1360, 1420 AND 1480</div>\r\n\r\n</div></div>','https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgxlN_mamNj3kBhg4XAA33peHkHHRlIuqoTbPWjYNOLDWS6EksJOWp1Mgh8fpMJwznpWo7uu62T09lknPMxNjT_28hq4UJo8gT3w3DFu9AC7bUFVBHLVannkW61VvSgoUD1rdkeQCG6-ob0ix_HEi6-AJ_mDBmQKpRub7nSfd_dmn2Akfi8oemgv43N5pU/s320/image.png','2026-03-17','active','2026-09-25 07:55:05','2026-09-25 07:55:05'),
(19,'2632555707892423805','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૪ ડીસેમ્બર ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjiJipnEG79HiCiSeM5Wa_5dz8x8U6R-vbenlxZofUTekJg1puKC6-HCOZSXIjBdD8HlRZrcMY3X7UjEgGHbAqVuzrBYOUZ0VtxSz-xGelfgE7HowWgrD2Vt65avqZtAPcObbNAjWzh_Wh8UfjkAVi7wMUX6GC1qbaRM98RPL-ul22BhDvSK_mllyWPJ3M\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjiJipnEG79HiCiSeM5Wa_5dz8x8U6R-vbenlxZofUTekJg1puKC6-HCOZSXIjBdD8HlRZrcMY3X7UjEgGHbAqVuzrBYOUZ0VtxSz-xGelfgE7HowWgrD2Vt65avqZtAPcObbNAjWzh_Wh8UfjkAVi7wMUX6GC1qbaRM98RPL-ul22BhDvSK_mllyWPJ3M\" width=\"281\" /></a></div><br /> <b><span style=\"color:#0000FF;\">સંકલન :-</span></b><b><span style=\"color:#0000FF;\">આશિષ\r\nશાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>નવી </span><span>CPI\r\n</span><span>સિરીઝ માટે સરકાર ઈ-ટેઇલર અને ઑનલાઈન સ્ત્રોતોમાંથી ભાવ\r\nમાહિતી એકત્રિત કરશે</span></li><li style=\"text-align:justify;\"><span>HDFC </span><span>બેંકે </span><span>FY</span><span>25 દરમિયાન </span><span>CSR\r\n</span><span>પર </span><span>₹</span><span>1,068 </span><span>કરોડ</span><span>ખર્ચ્યા</span></li><li style=\"text-align:justify;\"><span>હેડજિંગ</span><span>ખર્ચ</span><span>વધતા</span><span>RBI</span><span>એ </span><span>FX </span><span>સ્વેપ્સ કર્યા</span></li><li style=\"text-align:justify;\"><span>બાયોકોન</span><span>બાયોનોલોજિક્સને</span><span>બાયોસિમિલર</span><span>એડાલિમુમેબના</span><span>વૈશ્વિક</span><span>હક્ક</span><span>મળ</span><span>્યા</span></li><li style=\"text-align:justify;\"><span>વારી</span><span>ટ્રાન્સપાવરને</span><span>₹</span><span>100 </span><span>કરોડના</span><span>ટ્રાન્સફોર્મર</span><span>સપ્લાય</span><span>ઓર્ડર</span><span>મળ્યા</span></li><li style=\"text-align:justify;\"><span>અમેઝોનની</span><span>ઝૂક્સે</span><span>સોફ્ટવેર</span><span>ભૂલને</span><span>કારણે</span><span>US</span><span>માં 332 વાહનો\r\nરીકૉલ કર્યા: </span><span>NHTSA</span></li><li style=\"text-align:justify;\"><span>શ્રી</span><span>સિમેન્ટે</span><span>રાયપુરના</span><span>બલોદા</span><span>બજાર</span><span>પ્લાન્ટનો</span><span>લોકઆઉટ</span><span>પાછો</span><span>ખેંચ્યો</span></li><li style=\"text-align:justify;\"><span>નિસસ</span><span>ફાઇનાન્સે</span><span>દુબઈ</span><span>મોટર</span><span>સિટીમાં</span><span>₹</span><span>536 </span><span>કર</span><span>ોડમાં રહેણાંક ટાવર મેળવ્યો</span></li><li style=\"text-align:justify;\"><span>Q</span><span>2</span><span>FY</span><span>26માં ક્રેડિટ\r\nકાર્ડ ઇશ્યુઅન્સમાં ઘટાડો</span><span>, </span><span>ગ્રાહક ક્રેડિટ\r\nવૃદ્ધિ ધીમી: </span><span>JM\r\n</span><span>ફાઇનાન્સિયલ</span></li><li style=\"text-align:justify;\"><span>મોલ્સ</span><span>અને</span><span>હાઈ</span><span>સ્ટ્રીટ્સમાં</span><span>રિટેલ</span><span>સ્પેસ</span><span>લીઝિંગ</span><span> 15% </span><span>વધ્યું</span><span>,\r\n</span><span>માંગ-પુરવઠા સુધારાથી: </span><span>C&amp;W</span></li><li style=\"text-align:justify;\"><span>BPCL </span><span>માટે ભારતનું સૌથી મોટું લવચીક પેટ્રોકેમિકલ પ્લાન્ટ બનાવવા\r\n</span><span>L&amp;T\r\n</span><span>ઑનશોર વર્ટિકલને મોટો ઓર્ડર</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>ભારતનું </span><span>₹</span><span>2.3 લાખ કરોડનું </span><span>REIT </span><span>બજાર\r\nહૉંગકોંગને પાછળ પાડ્યું</span><span>; </span><span>યિલ્ડ 8-9% પર\r\nસ્થિર</span></li><li style=\"text-align:justify;\"><span>AI </span><span>કન્ટેન્ટ લેબલિંગ અંગે ચર્ચા પૂર્ણ</span><span>, </span><span>નિયમો ટૂંક\r\nસમયમાં જાહેર થશે: </span><span>IT </span><span>સચિવ</span></li><li style=\"text-align:justify;\"><span>ગેલે છત્તીસગઢ સાથે 12.7</span><span> LMT </span><span>ગેસ\r\nઆધારિત યુરિયા પ્રોજેક્ટ માટે </span><span>MoU </span><span>કર્યો</span></li><li style=\"text-align:justify;\"><span>ડૉલર વધારાનો પુરવઠો અને </span><span>NDF </span><span>દબાણ વચ્ચે\r\nબેન્કરો </span><span>RBI </span><span>હસ્તક્ષેપની માંગ કરે છે કારણ કે રૂપીયા ફોરવર્ડ્સ અશાંત</span></li><li style=\"text-align:justify;\"><span>ન્યૂઝીલેન્ડ ભારતમાં જોડાયેલા </span><span>FTA </span><span>હેઠળ ભારતીય\r\nમાલ માટે </span><span>GI </span><span>રજિસ્ટ્રેશન મંજૂર કરશે</span></li><li style=\"text-align:justify;\"><span>અમદાવાદ</span><span>, </span><span>કોલકાતા</span><span>, </span><span>પુણે સૌથી વધુ\r\nસસ્તા</span><span>, </span><span>મુંબઈ 50%</span><span> EMI </span><span>રેશિયો\r\nકરતાં નીચે ખસ્યું</span></li><li style=\"text-align:justify;\"><span>ઓલા ઇલેક્ટ્રિકે સમ-ડે સર્વિસ ગેરંટી સાથે હાઇપરસર્વિસ સેન્ટર્સ શરૂ કર્યા</span></li><li style=\"text-align:justify;\"><span>ટાટા મોટર્સ ફાઇનાન્સે </span><span>NCD </span><span>ઇશ્યૂ મામલે </span><span>₹</span><span>32 લાખમાં સેબી કેસ સેટલ કર્યો</span></li><li style=\"text-align:justify;\"><span>GE </span><span>વર્નોવાની મૂલ્યાંકનમાં વૃદ્ધિ શક્યતા અને આવકનો પ્રતિબિંબ</span></li><li style=\"text-align:justify;\"><span>કોરઇએલને એરૉસ્પેસ-ડિફેન્સ પ્રોજેક્ટ્સ માટે $30 મિલિયન સિરીઝ </span><span>B </span><span>ફંડિંગ</span></li><li style=\"text-align:justify;\"><span>IRB </span><span>ઇન્ફ્રાસ્ટ્રક્ચર ટ્રસ્ટે ઓડિશામાં </span><span>NHAI</span><span>ની </span><span>TOT-</span><span>18 હાઈવે કન્સેશન જીત્યો</span></li><li style=\"text-align:justify;\"><span>ઓલા ઇલેક્ટ્રિકે સમ-ડે સર્વિસ ગેરંટી સાથે હાઇપરસર્વિસ સેન્ટર્સ શરૂ કર્યા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ :</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>2026 સુધી ભારતમાં 3 નવા ટાટા ઇલેક્ટ્રિક </span><span>SUV </span><span>લોન્ચ માટે કન્ફર્મ</span></li><li style=\"text-align:justify;\"><span>પવન ઉર્જાને ફરી ગતિ આપવા સરકાર મોટું આયોજન કરી રહી છે</span></li><li style=\"text-align:justify;\"><span>વજન ઘટાડા માટેની દવાની વૈશ્વિક બજારોને ટાર્ગેટ કરવા અજંતા ફાર્માનો બાયોકોન સાથે\r\nકરાર</span></li><li style=\"text-align:justify;\"><span>HCL </span><span>ટેકે </span><span>AI </span><span>અને ડેટા સક્ષમતા માટે </span><span>M&amp;A </span><span>ખર્ચ વધાર્યા</span></li><li style=\"text-align:justify;\"><span>HDFC </span><span>બેંક ડેબિટ કાર્ડ યુઝર્સ માટે એરપોર્ટ લાઉન્જ ઍક્સેસ\r\nનિયમોમાં ફેરફાર કરશે</span></li><li style=\"text-align:justify;\"><span>એર ઈન્ડિયા અને અકાસાના મોટા જેટ ડિલિવરી ઓર્ડર વચ્ચે બોઇંગ ઉત્પાદન વધારવાનું\r\nવિચારે છે</span></li><li style=\"text-align:justify;\"><span>કૉલ ઇન્ડિયાની </span><span>BCCL </span><span>હરીફાઈ માટે </span><span>₹</span><span>1,300 કરોડ </span><span>IPO</span><span>ની તૈયારી</span></li><li style=\"text-align:justify;\"><span>ભારતનો પાવર સેક્ટર બેટરી સ્ટોરેજને નવી મોટી તક માન્યું</span></li><li style=\"text-align:justify;\"><span>લીઝ-ટુ-ઓન કંપની ફ્લેક્સશોપર </span><span>CEO</span><span>ને બરતરફ કર્યા બાદ બૅંકરપ્સી માટે અરજી કરે છે</span></li><li style=\"text-align:justify;\"><span>જાપાન વિવાદ વચ્ચે ચાઇનીઝ એરલાઈન્સ માટે નફાની આશા ઓછી પડી</span></li><li style=\"text-align:justify;\"><span>AI </span><span>ડેટા સેન્ટર એક્સપાન્શન વચ્ચે એલ્ફાબેટે ઇન્ટરસેક્ટને </span><span>$</span><span>4.75 બિલિયનમાં એક્વાયર\r\nકરવાની જાહેરાત કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjiJipnEG79HiCiSeM5Wa_5dz8x8U6R-vbenlxZofUTekJg1puKC6-HCOZSXIjBdD8HlRZrcMY3X7UjEgGHbAqVuzrBYOUZ0VtxSz-xGelfgE7HowWgrD2Vt65avqZtAPcObbNAjWzh_Wh8UfjkAVi7wMUX6GC1qbaRM98RPL-ul22BhDvSK_mllyWPJ3M','2025-12-24','active','2026-09-25 07:55:06','2026-09-25 07:55:06'),
(20,'8073807999022542992','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૩ ડીસેમ્બર ૨૦૨૫',NULL,'<h2 style=\"text-align:center;\"> <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhMd3eTm4DBn2qTDdXfGykMzlJDMT1ZFyElwvBpFehsct8X-HbJiH5eicHpOMrcQ-x8CPlSwTSBC6Oncyz-Yh9CRj9mrWW7OnlDH5KHHdb2akYbbBinoQ7w4KP52Fu82QjRBCfq9bUqyfg6xKBBWfTCPubRKwM5zLHn9pQWefec3O5MMkh59uobAunrIHM\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhMd3eTm4DBn2qTDdXfGykMzlJDMT1ZFyElwvBpFehsct8X-HbJiH5eicHpOMrcQ-x8CPlSwTSBC6Oncyz-Yh9CRj9mrWW7OnlDH5KHHdb2akYbbBinoQ7w4KP52Fu82QjRBCfq9bUqyfg6xKBBWfTCPubRKwM5zLHn9pQWefec3O5MMkh59uobAunrIHM\" width=\"281\" /></a><br /><b><span style=\"color:#0000FF;\">સંકલન :-</span></b><b><span style=\"color:#0000FF;\">આશિષ\r\nશાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /> </span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></h2>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>આરબીઆઈ બુલેટિન:\r\nભારતને ઉચ્ચ વૃદ્ધિના માર્ગ પર રાખવા માટે મજબૂત બેઝિક્સ અને સુધારાઓ પર ધ્યાન\r\nકેન્દ્રિત</span></li><li style=\"text-align:justify;\"><span>સેન્ટ્રલ</span><span>બેંક</span><span>દ્વારા</span><span>FY</span><span>26 માટે ભારતની જીડીપી વૃદ્ધિનો અંદાજ વધારો</span><span>,\r\n</span><span>હવે 7.3%</span></li><li style=\"text-align:justify;\"><span>ત્રણ</span><span>દિવસની</span><span>તેજી</span><span>બાદ</span><span>રૂપિયા</span><span>નબળો</span><span>પડ્યો</span><span>, </span><span>દેશી કંપનીઓ તરફથી\r\nડોલરની માંગ વધી</span></li><li style=\"text-align:justify;\"><span>બજારો</span><span>ઉત્સવના</span><span>અંતિમ</span><span>તબક્કા</span><span>માટે</span><span>તૈયાર</span><span>; </span><span>રોકાણકારોને\r\nડિસેમ્બર અંતે \"સાંતા રેલી\"ની આશા</span></li><li style=\"text-align:justify;\"><span>એનએચપીસી</span><span> 2,000 </span><span>મેગાવોટ</span><span>સુબંસિરી</span><span>લોઅર</span><span>હાઇડ્રો</span><span>પ્રોજેક્ટ</span><span>યુનિટનું</span><span>વ્યાપારિક</span><span>ઉત્પાદન</span><span>શરૂ</span><span>કરશ</span><span>ે</span></li><li style=\"text-align:justify;\"><span>પિરામલ</span><span>ફાઇનાન્સ</span><span>ગેર</span><span>-</span><span>મૂખ્ય</span><span>રોકાણમાંથી</span><span>બહાર</span><span>;\r\n</span><span>શ્રીરામ લાઈફમાંનો હિસ્સો </span><span>₹</span><span>600 </span><span>કરોડમાં</span><span>વેચ્યો</span></li><li style=\"text-align:justify;\"><span>બોન્ડ</span><span>માર્કેટની</span><span>ચિંતાઓ</span><span>વચ્ચે</span><span>સોનાએ</span><span>દાયકાઓમાં</span><span>સૌથી</span><span>મજબૂત</span><span>વાર્ષિક</span><span>પ્રદર્શન</span><span>આપ્યું</span></li><li style=\"text-align:justify;\"><span>ઇન્ફોસિસ</span><span>ADR </span><span>ગડબડ: </span><span>NYSE</span><span>માં ટેક્નિકલ તકલીફથી 40% ઉછાળો અને ટ્રેડિંગ અટકાવવું પડ્યું</span></li><li style=\"text-align:justify;\"><span>ઘરેલું</span><span>ઇલેક્ટ્રિક</span><span>કાર</span><span>બજારમાં</span><span>પ્રવેશ</span><span>પહેલાં</span><span>“સંપૂર્ણ</span><span>સમાધાન”ની</span><span>રાહ</span><span>જોશે</span><span>મારુતિ</span><span>સુઝુકી</span></li><li style=\"text-align:justify;\"><span>ભૂ</span><span>-</span><span>રાજકીય</span><span>જોખમો</span><span>વચ્ચે</span><span>ક્રૂડ</span><span>ઓઈલ</span><span>દબાણમાં</span><span>; </span><span>વૈશ્વિક ભાવ બેરલ\r\nદીઠ </span><span>$</span><span>60થી </span><span>નીચે</span><span>ગયા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>સુપ્રીમ કોર્ટએ </span><span>FADA</span><span>ની </span><span>GST </span><span>કંપન્સેશન સેસ\r\nઅરજી સ્વીકારી</span><span>; </span><span>કેન્દ્ર સરકારને નોટિસ</span></li><li style=\"text-align:justify;\"><span>નવી ટેકનોલોજીના પ્રભાવથી રૂટીન નોકરીઓ ખતમ થશે</span><span>, </span><span>નારાયણ\r\nમૂર્તીનો ચેતાવણી સંદેશ</span></li><li style=\"text-align:justify;\"><span>ભારત–ન્યૂઝીલેન્ડ વેપાર કરાર: 100% નિકાસ પર 0% ડ્યુટી</span><span>, </span><span>અને વેલિંગ્ટનની $20 અબજ એફડીઆઈની પ્રતિબદ્ધતા</span></li><li style=\"text-align:justify;\"><span>ભારત બાયોટેક અને બાયોફાબ્રિ દ્વારા ક્ષયરોગ વેક્સિન </span><span>MTBVAC </span><span>માટે ટેક-ટ્રાન્સફર કરાર</span></li><li style=\"text-align:justify;\"><span>2025માં મ્યુચ્યુઅલ ફંડ્સના </span><span>NFO</span><span>માં કલેક્શન\r\nઘટ્યું</span><span>; </span><span>સક્રિય ઇક્વિટી ઈન્ટરેસ્ટ ઠંડો પડ્યો</span></li><li style=\"text-align:justify;\"><span>એલઆરએસ હેઠળ વિદેશી રેમિટન્સ ઓક્ટોબરમાં 2% ઘટ્યું</span><span>; </span><span>પ્રવાસ\r\nઅને શિક્ષણ ખર્ચમાં ઘટાડો</span></li><li style=\"text-align:justify;\"><span>બેંક ઑફ અમેરિકા સર્વે: ચીન “અન્ડરવેઈટ” બનતા ભારત ફરીથી ફેવરિટ માર્કેટ</span></li><li style=\"text-align:justify;\"><span>કોર સેક્ટરની વૃદ્ધિ ઓક્ટોબરની ગિરાવટ બાદ નવેમ્બરમાં 1.8% સુધી સુધરી</span></li><li style=\"text-align:justify;\"><span>નિખિલ કામત અને કિશોર બિયાણી દ્વારા સ્ટાર્ટઅપને માર્ગદર્શિત અને ફંડ કરવા “ધ ફાઉન્ડરી”\r\nલોન્ચ</span></li><li style=\"text-align:justify;\"><span>LIC </span><span>હાઉસિંગ ફાઇનાન્સે નવા હોમ લોન પર વ્યાજદર 7.15% સુધી ઘટાડ્યા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ફાઈનાન્સિયલ\r\nએક્સપ્રેસ :</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>અદાણી સિમેન્ટ્સ સમીકરણ: </span><span>ACC </span><span>અને ઓરિયન્ટ\r\nસિમેન્ટ થશે અંબુજા સિમેન્ટ સાથે મર્જ</span></li><li style=\"text-align:justify;\"><span>DGCA</span><span>એ </span><span>IndiGo</span><span>ની તુર્કિશ એરલાઇન્સની વેટ-લીઝ્ડ ફ્લાઇટ્સ માર્ચ બાદ\r\nવધારવાનો ઇનકાર કર્યો</span></li><li style=\"text-align:justify;\"><span>સરકાર પ્રધાનમંત્રી મુદ્રા યોજનાને વધુ પાંચ વર્ષ</span><span>, 2030</span><span> સુધી લંબાવવાની શક્યતા</span></li><li style=\"text-align:justify;\"><span>સ્ટાર્ટઅપ મૂલ્યાંકન સુધારો: </span><span>2025</span><span>માં માત્ર\r\nપાંચ ભારતીય સ્ટાર્ટઅપ યુનિકોર્ન બન્યા</span></li><li style=\"text-align:justify;\"><span>આરબીઆઈએ સોનાના ભાવમાં તેજ વોલેટિલિટી અંગે ચેતાવ્યું</span><span>; </span><span>બેંકો\r\nઅને </span><span>NBFC </span><span>લોન મર્યાદા કડક કરી</span></li><li style=\"text-align:justify;\"><span>RRP </span><span>સેમિકન્ડક્ટર સ્ટોકમાં </span><span>55,000%</span><span> ઉછાળો</span><span>; BSE</span><span>એ સ્ક્રિપને સપ્તાહમાં એક વખત ટ્રેડિંગ માટે ખસેડ્યું</span></li><li style=\"text-align:justify;\"><span>રેલવે દ્વારા છ મહિનામાં બીજી વખત જેટલા ક્લાસમાં મુસાફરી ભાડાં વધાર્યા</span></li><li style=\"text-align:justify;\"><span>નાના </span><span>FMCG </span><span>પૅક્સમાં “વિચિત્ર કિંમતો” જોવા મળી</span><span>; </span><span>ઇનપુટ કૉસ્ટ બદલાવનો અસર</span></li><li style=\"text-align:justify;\"><span>17</span><span> ડિસેમ્બર\r\nસુધી નેટ ડાયરેક્ટ ટેક્સ કલેક્શન </span><span>8%</span><span> વધ્યું</span><span>; </span><span>રિફંડ </span><span>13.5%</span><span> ઘટ્યા</span></li><li style=\"text-align:justify;\"><span>જાપાનની </span><span>MUFG </span><span>બેંક </span><span>Shriram Finance</span><span>માં </span><span>₹</span><span>39,000 </span><span>કરોડનું રોકાણ કરીને </span><span>20% </span><span>હિસ્સો લેશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ :</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>મજબૂત માંગને કારણે </span><span>SBI</span><span>નું હોમ લોન\r\nબુક આગામી વર્ષમાં </span><span>₹</span><span>10 લાખ કરોડ પાર કરશે</span></li><li style=\"text-align:justify;\"><span>મુકેશ અંબાણી: ભારતે </span><span>AI </span><span>ક્ષેત્રનું\r\nનેતૃત્વ કરવું જોઈએ</span><span>, </span><span>પરંતુ ટેકમાં માનવ સંવેદનાનું મહત્વ જાળવવું જરૂરી</span></li><li style=\"text-align:justify;\"><span>અમેરિકી કોર્ટએ </span><span>Infosys McCamish </span><span>ડેટા બ્રિચ\r\nકેસમાં $17.5 મિલિયન સેટલમેન્ટને મંજૂરી આપી</span></li><li style=\"text-align:justify;\"><span>UltraTech Cement </span><span>₹</span><span>782.2 કરોડના </span><span>GST </span><span>ડિમાન્ડ નોટિસને પડકારશે</span></li><li style=\"text-align:justify;\"><span>ટાઇટનને અપેક્ષા: આગામી બે વર્ષમાં વોચ વ્યવસાય બિલિયન-ડોલર વેચાણ પાર કરશે</span></li><li style=\"text-align:justify;\"><span>ડિસેમ્બરમાં સ્મોલ અને મિડકૅપ સ્ટૉક્સ લીડ કરી રહ્યા છે</span><span>; </span><span>નિફ્ટી સ્મોલકૅપ 100 ટેકનિકલ બ્રેકઆઉટ દર્શાવે છે</span></li><li style=\"text-align:justify;\"><span>Zomato</span><span>ની સફરની વાત: દીપિન્દર ગોયલની કહાની “</span><span>Unseen” </span><span>ક્રોનીકલ્સમાં</span></li><li style=\"text-align:justify;\"><span>ભારત–ઓમાન </span><span>FTA: </span><span>તંગ સંબંધોને કારણે તુર્કીશ માર્બલના બદલે ઓમાનના માર્બલ\r\nબ્લોક્સ આવશે</span></li><li style=\"text-align:justify;\"><span>એફઆઈઆઈ ફરી બજારમાં પરત</span><span>; </span><span>₹</span><span>1,831 કરોડની નેટ ખરીદી</span></li><li style=\"text-align:justify;\"><span>ફેબ્રુઆરી 2026થી નવી રિટેઈલ મોંઘવારી અને </span><span>GDP </span><span>ડેટા સિરીઝ આવશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhMd3eTm4DBn2qTDdXfGykMzlJDMT1ZFyElwvBpFehsct8X-HbJiH5eicHpOMrcQ-x8CPlSwTSBC6Oncyz-Yh9CRj9mrWW7OnlDH5KHHdb2akYbbBinoQ7w4KP52Fu82QjRBCfq9bUqyfg6xKBBWfTCPubRKwM5zLHn9pQWefec3O5MMkh59uobAunrIHM','2025-12-23','active','2026-09-25 07:55:06','2026-09-25 07:55:06'),
(21,'5624051617584475416','Nifty Outlook :- 22.12.2025 - CFA Hitesh Somani',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhRaejOq4WyvKI3DxnKL_UEPOpwKTngciyvfeR7NQpu05iK6zvgUVMGCLbdMHdVdjWLJiu0aqBxG3-IJo8K8Ut_eAzf_wYIriBHKpZdS30hK4_xN5OKLsQPIACQKso5c-zhw91n5OI8tlrRGL4Z-bQvOLa_K-e102W_z35HqdFHOOppnBqc-SBf__ZvLT0\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhRaejOq4WyvKI3DxnKL_UEPOpwKTngciyvfeR7NQpu05iK6zvgUVMGCLbdMHdVdjWLJiu0aqBxG3-IJo8K8Ut_eAzf_wYIriBHKpZdS30hK4_xN5OKLsQPIACQKso5c-zhw91n5OI8tlrRGL4Z-bQvOLa_K-e102W_z35HqdFHOOppnBqc-SBf__ZvLT0\" width=\"255\" /></a></div></div><div style=\"text-align:center;\"><b><span>CFA Hitesh Somani<br /></span></b><b><span style=\"color:#000000;\">MD - Aapka Investments <br /></span></b><b><span style=\"color:#000000;\">\r\nWebsite - https://www.aapkainvestments.in</span></b></div>\r\n\r\n\r\n\r\n<p><b><span>“Nifty was bearish this week. Will we see the\r\nsame trend next week, or can we expect a reversal?”</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>“Last\r\nweek, the market fell quite sharply, but after that it opened with a gap up and\r\nshowed a strong bullish movement, covering more than 80% of the entire fall.\r\nLooking at this, it clearly seems that the market is still respecting the\r\n25,700-support level very well, and at the same time it is also respecting the\r\n26,050-resistance level. If the market breaks the strong resistance at 26,050,\r\nthen we can see a good bullish movement. And if Nifty breaks the major support\r\nat 24,700, then we may see further downside.”</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>“Last\r\nFriday, Nifty closed at 26,046, and this Friday it closed at 25,966, which is a\r\nbearish move of 80 points. But as we can see, it is still stuck between the\r\nmajor resistance at 26,050 and the major support at 24,700.”</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>“Bank\r\nNifty was quite weak this week compared to Nifty. Even though Bank Nifty opened\r\nwith a gap down on the first day, it showed a strong bullish move and filled\r\nthe gap. But after that, it fell continuously for three days. On the last day,\r\nit opened with a gap up and tried to cover the fall, but overall Bank Nifty\r\nremained bearish this week with a move of 320 points. Last Friday, Bank Nifty\r\nclosed at 59,390, and this Friday it closed at 59,069, which is a decline of\r\n320 points.</span></p><p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n<ul style=\"text-align:left;\"><li><span style=\"text-align:justify;\">Major\r\nSupport Levels for Nifty</span><ul><li><ul><li><span>Support\r\n1 – 25900</span></li><li><span>Support\r\n2 – 25600</span></li><li><span>Support\r\n3 – 25300</span></li></ul></li></ul></li></ul><ul style=\"text-align:left;\"><li><span>Major\r\nResistance Levels for Nifty</span><ul><li><ul><li><span>Resistance\r\n1 – 26050</span></li><li><span>Resistance\r\n2 – 26250</span></li><li><span>Resistance\r\n3 – 26350</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<ul style=\"text-align:left;\"><li><span style=\"text-align:justify;\">Major\r\nSupport Levels for Banknifty</span><ul><li><ul><li><span>Support\r\n1 – 58900</span></li><li><span>Support\r\n2 – 58500</span></li><li><span>Support\r\n3 – 58100</span></li></ul></li></ul></li></ul><ul style=\"text-align:left;\"><li><span>Major\r\nResistance Levels for Banknifty</span><ul><li><ul><li><span>Resistance\r\n1 – 59200</span></li><li><span>Resistance\r\n2 – 59700</span></li><li><span>Resistance\r\n3 – 60200</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n<div style=\"text-align:justify;\"><b><span>1) SONACOMS<br /></span></b><span>CMP @ 495<br /></span><span>Buy Above @ 501<br /></span><span>Stop Loss Below @ 470<br /></span><span>Targets @ 520, 540 and 565 </span></div><div style=\"text-align:justify;\"><b><span>2)\r\nCEAT LTD</span></b></div><div style=\"text-align:justify;\"><span>CMP @ 3930<br /></span><span>Buy Above @ 3970<br /></span><span>Stop Loss @ 3650<br /></span><span>Targets @ 4100, 4250 and 4400</span></div><div style=\"text-align:justify;\"><b><span>3)\r\nPOLYCAB</span></b></div><div style=\"text-align:left;\"><span>CMP\r\n@ 7438<br /></span><span>Buy\r\nAbove @ 7460<br /></span><span>Stop\r\nLoss @ 7000<br /></span><span>Targets\r\n@ 7650, 7850 and 8100</span></div><div style=\"text-align:left;\"><span><span style=\"background-color:#FFFFFF;color:#FF0000;text-align:justify;\">The securities quoted are for illustration only and are not recommendatory. Investment in securities market are subject to market risks. Read and agree Disclaimer and related all the documents carefully before investing, mentioned on </span><span style=\"background-color:#FFFFFF;color:#666666;text-align:justify;\"><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;\">www.nikhilbhatt.in</span></a></span></span></div>','https://blogger.googleusercontent.com/img/a/AVvXsEhRaejOq4WyvKI3DxnKL_UEPOpwKTngciyvfeR7NQpu05iK6zvgUVMGCLbdMHdVdjWLJiu0aqBxG3-IJo8K8Ut_eAzf_wYIriBHKpZdS30hK4_xN5OKLsQPIACQKso5c-zhw91n5OI8tlrRGL4Z-bQvOLa_K-e102W_z35HqdFHOOppnBqc-SBf__ZvLT0','2025-12-22','active','2026-09-25 07:55:06','2026-09-25 07:55:06'),
(22,'6917756758885692025','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૨ ડીસેમ્બર ૨૦૨૫',NULL,'<h2 style=\"text-align:center;\"> <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgtuD7AG8sTuMAhsNoTZQ1nZkOFHAFPMcEei4mh-8MZfuuPnFN3T863UyH6ZPqnfGurs-3FDGpQgdTGk0mRgF12ZroV0Itkbx2sVmp_ExPtFU_OC34cCP7Q2zpzRTFp6tQhpl19kouXX5QIIqg3Nu1lzEErj9itRYro6wlOK9bhkpkUO2TuYThDqPmm2OI\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgtuD7AG8sTuMAhsNoTZQ1nZkOFHAFPMcEei4mh-8MZfuuPnFN3T863UyH6ZPqnfGurs-3FDGpQgdTGk0mRgF12ZroV0Itkbx2sVmp_ExPtFU_OC34cCP7Q2zpzRTFp6tQhpl19kouXX5QIIqg3Nu1lzEErj9itRYro6wlOK9bhkpkUO2TuYThDqPmm2OI\" width=\"281\" /></a><br /><b><span style=\"color:#0000FF;\">સંકલન :-</span></b><b><span style=\"color:#0000FF;\">આશિષ\r\nશાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /> </span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></h2>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>નીતિ સહાય અને વધતા\r\nખર્ચ વચ્ચે </span><span>2026</span><span>માં ભારતનો ઓટો સેક્ટર વૃદ્ધિ જાળવી રાખશે</span></li><li style=\"text-align:justify;\"><span>શાપૂરજી પલ્લોનજી\r\nરિયલ એસ્ટેટ પ્લોટેડ ડેવલપમેન્ટમાં પ્રવેશ્યું</span></li><li style=\"text-align:justify;\"><span>ફોર્ટિસ બેંગલુરુની\r\nપીપલ ટ્રી હોસ્પિટલ્સને </span><span>₹</span><span>430</span><span> કરોડમાં ખરીદશે</span></li><li style=\"text-align:justify;\"><span>આગામી </span><span>3</span><span> વર્ષમાં ભારતના રિટેલ બૂમમાં </span><span>$3.5</span><span> બિલિયનનું રોકાણ આકર્ષાશે</span><span>, </span><span>જ્યારે અમેરિકાના શોપિંગ મોલ્સ મુશ્કેલીમાં: અનારોક</span></li><li style=\"text-align:justify;\"><span>ક્રિસમસ અને ન્યૂ\r\nઈયર ભીડને ધ્યાનમાં રાખીને ભારતીય રેલવે </span><span>244</span><span> ખાસ ટ્રેન દોડાવશે</span></li><li style=\"text-align:justify;\"><span>2026–27</span><span>માં બાયોગાસ સેક્ટરમાં </span><span>₹</span><span>5,000</span><span> કરોડનું રોકાણ થવાની અપેક્ષા: </span><span>IBA</span></li><li style=\"text-align:justify;\"><span>અલ્ટ્રાટેક\r\nસિમેન્ટને </span><span>GST\r\n</span><span>અધિકારીઓ તરફથી </span><span>₹</span><span>782.2 </span><span>કરોડની નોટિસ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>ડીપીડીપી કાયદો ભારતની પ્રાઇવસી અને સિક્યોરિટી દૃશ્યપટને </span><span>GDPR </span><span>જેમ બદલશે: </span><span>DSCI CEO</span></li><li style=\"text-align:justify;\"><span>એલ એન્ડ ટીનું હરિત હાઇડ્રોજન</span><span>, </span><span>બેટરી સ્ટોરેજ\r\nઅને ટ્રાન્સમિશન-ડિસ્ટ્રિબ્યુશન પર મોટા દાવ</span></li><li style=\"text-align:justify;\"><span>કીસ્ટોન રિયલ્ટર્સ મુંબઈમાં </span><span>₹</span><span>3,000</span><span> કરોડનું અલ્ટ્રા-લક્ઝરી પ્રોજેક્ટ લોન્ચ કરશે: </span><span>CMD</span></li><li style=\"text-align:justify;\"><span>API </span><span>આયાત પર ફ્લોર પ્રાઇસ સ્થાનિક ફાર્મા ઇનપુટની માંગમાં વધારો કરી શકે</span></li><li style=\"text-align:justify;\"><span>ડિસેમ્બરનાં પ્રથમ પખવાડિયામાં </span><span>FPIs </span><span>દ્વારા\r\nફાઇનાન્સ અને </span><span>IT </span><span>સ્ટોક્સમાંથી સૌથી વધુ વેચવાલી</span></li><li style=\"text-align:justify;\"><span>2026</span><span> સુધી એજેન્ટિક </span><span>AI </span><span>સ્વયંસંચાલિત એન્ટરપ્રાઇઝને આગળ ધપાવશે: વિપ્રો </span><span>CTO</span></li><li style=\"text-align:justify;\"><span>મજબૂત માંગને કારણે </span><span>FY26</span><span>માં હોમ લોન\r\nબુક </span><span>₹</span><span>10</span><span>\r\nટ્રિલિયનને પાર જશે: </span><span>SBI </span><span>ચીફ</span></li><li style=\"text-align:justify;\"><span>2025</span><span>માં ભારતે </span><span>₹</span><span>2 </span><span>ટ્રિલિયનના\r\nરોકાણ સાથે </span><span>50 GW </span><span>રિન્યુએબલ એનર્જી ક્ષમતા વધારી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>ઇનોક્સ ક્લીન એનર્જીએ મેક્વેરીની વાયબ્રન્ટ એનર્જી સાથે </span><span>$600</span><span> મિલિયનનો કરાર કર્યો</span></li><li style=\"text-align:justify;\"><span>યુએસ </span><span>EV </span><span>પડકાર વચ્ચે વિનફાસ્ટ</span><span>, </span><span>વિન્ગ્રુપના\r\nભારત પ્રવેશને આગળ ધપાવે છે</span></li><li style=\"text-align:justify;\"><span>માઈક્રોસોફ્ટ ઇન્ડિયા વડાએ </span><span>AI</span><span>નું ભવિષ્ય\r\nદર્શાવી અપસ્કિલિંગની જરૂરિયાત પર ભાર મૂક્યો</span></li><li style=\"text-align:justify;\"><span>અમેરિકા દ્વારા વેનેઝુએલાના તેલ પર પ્રતિબંધથી ક્યુબા ધરાશાયીના કિનારે</span></li><li style=\"text-align:justify;\"><span>ભારતમાં મૂડી રચનામાં મંદી આર્થિક વૃદ્ધિ પર છુપાયેલો ભાર બની રહી છે</span></li><li style=\"text-align:justify;\"><span>ઇન્ડિયા</span><span>RF</span><span>એ સિન્થિમેડ લેબ્સમાં હિસ્સેદારી વેચાણ પ્રક્રિયા શરૂ કરી</span><span>, </span><span>રોથચાઈલ્ડ એન્ડ કોની નિમણૂક કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgtuD7AG8sTuMAhsNoTZQ1nZkOFHAFPMcEei4mh-8MZfuuPnFN3T863UyH6ZPqnfGurs-3FDGpQgdTGk0mRgF12ZroV0Itkbx2sVmp_ExPtFU_OC34cCP7Q2zpzRTFp6tQhpl19kouXX5QIIqg3Nu1lzEErj9itRYro6wlOK9bhkpkUO2TuYThDqPmm2OI','2025-12-22','active','2026-09-25 07:55:06','2026-09-25 07:55:06'),
(23,'3213928667568307619','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૯ ડીસેમ્બર ૨૦૨૫',NULL,'<h2 style=\"text-align:center;\"> <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgPVYlqt8kY3Qdj5eLTRkIl8RTcGiLQZhJOy27upszTFWTt_OZpY_xiotbIosGi0jSa_Hp9rjVHyanA1h1qNm79U-Fj_r-S4qjnvS0ZKXlJ0XABtywosxSn9zVjT94ApfPwcr9UyWv9RT1lxtezGPXde36KfmRYdNsXRhC7TXYhCCt-oitsXXG1FsYdoVw\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgPVYlqt8kY3Qdj5eLTRkIl8RTcGiLQZhJOy27upszTFWTt_OZpY_xiotbIosGi0jSa_Hp9rjVHyanA1h1qNm79U-Fj_r-S4qjnvS0ZKXlJ0XABtywosxSn9zVjT94ApfPwcr9UyWv9RT1lxtezGPXde36KfmRYdNsXRhC7TXYhCCt-oitsXXG1FsYdoVw\" width=\"281\" /></a><br /><b><span style=\"color:#0000FF;\">સંકલન :-</span></b><b><span style=\"color:#0000FF;\">આશિષ\r\nશાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /> </span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></h2>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>ભારતમાં ફૂડ\r\nડિલિવરી પ્લેટફોર્મ સેક્ટરે </span><span>FY</span><span>24માં </span><span>₹</span><span>1.2 </span><span>લાખ</span><span>કરોડનું</span><span>કુલ</span><span>ઉત્પાદન</span><span>ઉત્પન્ન</span><span>કર્યું</span><span>: </span><span>રિપોર્ટ</span></li><li style=\"text-align:justify;\"><span>રિલાયન્સ કન્ઝ્યુમર\r\nપ્રોડક્ટ્સે તમિલનાડુની ઉધૈયમ્સ કંપનીમાં મોટાભાગની હિસ્સેદારી મેળવી</span></li><li style=\"text-align:justify;\"><span>ભારત ખાંડ ઊપજ\r\nવધારા સાથે નિકાસ વધારશે અને વધુ ઇથેનોલ તરફ વળશે</span></li><li style=\"text-align:justify;\"><span>JSW </span><span>એનર્જી સલબોની થર્મલ પાવર પ્લાન્ટને 3,200 મેગાવોટ સુધી ડબલ\r\nકરશે</span><span>;\r\n</span><span>રોકાણ </span><span>₹</span><span>40,000 </span><span>કરોડ</span><span>સુધી</span><span>વધશે</span></li><li style=\"text-align:justify;\"><span>મૅક્સ હેલ્થકેરે\r\nપુણેમાં સુપર સ્પેશિયાલિટી હોસ્પિટલ માટે </span><span>₹</span><span>1,000 </span><span>કરોડનું</span><span>રોકાણ</span><span>કરશે</span></li><li style=\"text-align:justify;\"><span>સ્પર્ધા આયોજક\r\nઇન્ડિગો સામે સ્પર્ધા નિયમ ભંગની ફરિયાદોની સમીક્ષા કરી રહ્યો છે</span></li><li style=\"text-align:justify;\"><span>એક્સિકોમનું નવું\r\nપ્લેટફોર્મ </span><span>EV\r\n</span><span>ચાર્જિંગને સરળ બનાવવાનો દાવો</span></li><li style=\"text-align:justify;\"><span>બે વર્ષમાં ફૂડ\r\nડિલિવરી સેક્ટરમાં રોજગાર 27% વધ્યો: રિપોર્ટ</span></li><li style=\"text-align:justify;\"><span>ICICI </span><span>બેંકને </span><span>₹</span><span>238 </span><span>કરોડનો</span><span>GST </span><span>ડિમાન્ડ નોટિસ</span></li><li style=\"text-align:justify;\"><span>એલાન ગ્રુપ\r\nગુરુગ્રામમાં લક્ઝરી રહેણાંક પ્રોજેક્ટ માટે </span><span>₹</span><span>1,600 </span><span>કરોડ</span><span>રોકશે</span></li><li style=\"text-align:justify;\"><span>લ્યુપિને ફિલિપાઇન્સ\r\nઅને બ્રાઝિલમાં પ્લાસિલ બ્રાન્ડ માટે નેઓફાર્મેડ સાથે લાયસેન્સિંગ કરાર કર્યો</span></li><li style=\"text-align:justify;\"><span>ZTE </span><span>સામે ઇન્સોલ્વન્સી અરજી નકારી કાઢતા આદેશ સામે </span><span>TVS\r\n</span><span>સપ્લાય </span><span>NCLAT </span><span>પહોંચ્યું</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>વીજ મંત્રાલય મહત્વપૂર્ણ સાધનોના સ્થાનિકીકરણ વધારવા માટે યોજના પર કામ કરી\r\nરહ્યું છે</span></li><li style=\"text-align:justify;\"><span>ભારત વૈશ્વિક સેવા નિકાસકાર તરીકે પોતાની ભૂમિકાને મજબૂત કરી રહ્યું છે</span><span>; </span><span>ઈયૂ અને ચીન પાછળ: </span><span>KKR</span></li><li style=\"text-align:justify;\"><span>આરપી-સંજીવ ગોએંકા ગ્રુપ પશ્ચિમ બંગાળમાં </span><span>₹</span><span>15,800 કરોડનું મૂડીરોકાણ કરશે</span></li><li style=\"text-align:justify;\"><span>ઓબેન ઇલેક્ટ્રિકે </span><span>₹</span><span>85 કરોડ ઊભા કર્યા</span><span>, FY</span><span>26માં </span><span>₹</span><span>100 કરોડ આવકનું લક્ષ્ય</span></li><li style=\"text-align:justify;\"><span>નિસાને ભારતમાં ત્રણ નવા મોડલ લોન્ચ કરશે</span><span>, </span><span>વેચાણ\r\nનેટવર્કનો વિસ્તાર કરશે</span></li><li style=\"text-align:justify;\"><span>જાપાનની </span><span>JAPEX </span><span>કંપનીએ $1.3 બિલિયનના અમેરિકન ટાઇટ ઓઈલ અને ગેસ એસેટ્સ\r\nખરીદ્યા</span></li><li style=\"text-align:justify;\"><span>નાના પેટ્રોલ વાહનોને </span><span>CAFE </span><span>માનદંડમાંથી\r\nમુક્ત કરવાના પ્રસ્તાવનો ટાટા મોટર્સ વિરોધ</span></li><li style=\"text-align:justify;\"><span>સે્બીએ નાના મૂલ્યમાં ઝીરો-કૂપન બોન્ડ જારી કરવાની મંજૂરી આપી</span></li><li style=\"text-align:justify;\"><span>પટેલ એન્જિનિયરિંગે અરુણાચલ સાથે ગોંગ્રી પ્રોજેક્ટ પુનઃસ્થાપન માટે કરાર\r\nકર્યો</span></li><li style=\"text-align:justify;\"><span>AM </span><span>ગ્રીન અને મિત્સુઈ ગ્રીન એલ્યુમિનિયમ માટે સંભવિત રોકાણ અને ઓફટેક પર વિચારણા</span></li><li style=\"text-align:justify;\"><span>ચીની મેન્યુફેક્ચરિંગ નિષ્ણાતોને પ્રોત્સાહન આપવા ભારતે બિઝનેસ વિઝા નિયમોમાં\r\nછૂટછાટ આપી</span></li><li style=\"text-align:justify;\"><span>ACME </span><span>સોલારે નવનીકરણ ઊર્જા પ્રોજેક્ટ્સ માટે </span><span>₹</span><span>4</span><span>,</span><span>725\r\nકરોડનું ફંડિંગ મેળવ્યું</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>ભારત-ઓમાન ફ્રી ટ્રેડ એગ્રીમેન્ટ સહી</span><span>, </span><span>નિકાસ\r\nજોખમ ઘટાડવા માટે મોટું પગલું</span></li><li style=\"text-align:justify;\"><span>TCS</span><span>AI </span><span>આવક </span><span>$1.5</span><span> બિલિયન અને નવી\r\nસેવાઓથી </span><span>$11</span><span> બિલિયન ગણાવી</span></li><li style=\"text-align:justify;\"><span>ભારતીય મૂળના રોહિત પ્રસાદ એમેઝોન છોડશે</span><span>; </span><span>એન્ડી\r\nજેસીએ નવા નેતાનું એલાન કર્યું</span></li><li style=\"text-align:justify;\"><span>અમેરિકા દ્વારા તાઇવાનને </span><span>$11</span><span> બિલિયનનાં\r\nહથિયાર વેચાણને મંજૂરી</span><span>, </span><span>ચીન નારાજ</span></li><li style=\"text-align:justify;\"><span>મિત્સુઈ </span><span>AM </span><span>ગ્રીનના લો-કાર્બન એલ્યુમિનિયમ રોકાણ પર વિચાર કરી રહ્યું\r\nછે</span></li><li style=\"text-align:justify;\"><span>JLR </span><span>સાયબર આક્રમણ બાદ </span><span>TCS </span><span>મુખ્ય\r\nક્લાયંટ્સ માટે સુરક્ષા ધોરણો મજબૂત બનાવશે</span></li><li style=\"text-align:justify;\"><span>ઍન્ટોની વેસ્ટ હેન્ડલિંગ સેલને </span><span>₹</span><span>1,330</span><span> કરોડનો </span><span>JV </span><span>ઓર્ડર</span></li><li style=\"text-align:justify;\"><span>સ્પેસ સ્ટાર્ટઅપ્સમાં આવક વૃદ્ધિની અપેક્ષા</span><span>, </span><span>રોકાણકારો\r\nફરી વિશ્વાસુ</span></li><li style=\"text-align:justify;\"><span>ભારતે મેડિકલ ડિવાઈસ માટે પરમનેન્ટ લાયસેન્સિંગ અને સમાન ટેસ્ટિંગ પ્રસ્તાવિત\r\nકર્યું</span></li><li style=\"text-align:justify;\"><span>યુએસ ફેડે સિટી પરના રિસ્ક કંટ્રોલ નોટિસો સમાપ્ત કરી: સૂત્રો</span></li><li style=\"text-align:justify;\"><span>AMD</span><span>એ </span><span>16GB VRAM </span><span>સાથે લો પાવર </span><span>Radeon RX 9060 XT </span><span>લોન્ચ કર્યું</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgPVYlqt8kY3Qdj5eLTRkIl8RTcGiLQZhJOy27upszTFWTt_OZpY_xiotbIosGi0jSa_Hp9rjVHyanA1h1qNm79U-Fj_r-S4qjnvS0ZKXlJ0XABtywosxSn9zVjT94ApfPwcr9UyWv9RT1lxtezGPXde36KfmRYdNsXRhC7TXYhCCt-oitsXXG1FsYdoVw','2025-12-19','active','2026-09-25 07:55:06','2026-09-25 07:55:06'),
(24,'6176356340935866616','Fund Houses Update - 19 December 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhenmyN9Tku_FJ0BcPGHK5Gvkhqlmi9bj1W80HZ4PBwqzcrEZaIplB9zioIN2GqIx1FmSbj_QzJclrzC4fy_MHdHa31ObqrP2Zq8idVu_iBHG927brgl8dlVeZzPiVUsGk3fiFNEDCFg-bAUyIeDoiRW7lzFpPsxa1LtnpZUHqcldXLh8wCIsFAKD_OhHg\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhenmyN9Tku_FJ0BcPGHK5Gvkhqlmi9bj1W80HZ4PBwqzcrEZaIplB9zioIN2GqIx1FmSbj_QzJclrzC4fy_MHdHa31ObqrP2Zq8idVu_iBHG927brgl8dlVeZzPiVUsGk3fiFNEDCFg-bAUyIeDoiRW7lzFpPsxa1LtnpZUHqcldXLh8wCIsFAKD_OhHg\" width=\"266\" /></a></div><br /><span style=\"text-align:justify;\">Dear\r\nTrader...</span>\r\n\r\n<p style=\"text-align:justify;\"><span>Fund\r\nHouses Recommendations </span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Macquarie on Lenskart: </span><span>Initiate\r\nOutperform on Company, target price at Rs 530/Sh <span style=\"color:#0000FF;\">(Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Investec on USL: </span><span>Maintain Buy on\r\nCompany, target price at Rs 1673/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">GS on Max Health: </span><span>Maintain Buy on\r\nCompany, target price at Rs 1325/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Kotak on SBI Cards: </span><span>Maintain Overweight\r\non Company, target price at Rs 975/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Citi on Voltas: </span><span>Maintain Buy on\r\nCompany, target price at Rs 1775/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Jefferies on Voltas: </span><span>Ma