(152,'7192894282448237689','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૮ ઓગસ્ટ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEg-tJbq_kkA-1_aF0YPojV76IT--7VJEOaGyZLJaFQJbhFkRBFoe0lHQhiNjQH_lcAMSimDSqSPS3l43HkLTsRd-Emc4KTtHlTWvR41XMLbSL1E8gY6perPjXy9dm9sbdrhzu7zTdogKOmXzVNLCjgB53YY3YP8e_8o1gHCjo_Qw2mOfGVtlfwjN6LUuUw\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEg-tJbq_kkA-1_aF0YPojV76IT--7VJEOaGyZLJaFQJbhFkRBFoe0lHQhiNjQH_lcAMSimDSqSPS3l43HkLTsRd-Emc4KTtHlTWvR41XMLbSL1E8gY6perPjXy9dm9sbdrhzu7zTdogKOmXzVNLCjgB53YY3YP8e_8o1gHCjo_Qw2mOfGVtlfwjN6LUuUw\" width=\"281\" /></a></div>\r\n\r\n\r\n\r\n<div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>S&amp;P </span><span>એ </span><span>18</span><span> વર્ષ પછી ભારતનું સોવરિન રેટિંગ </span><span>BBB\r\n</span><span>સુધી અપગ્રેડ કર્યું</span></li><li><span>ટ્રમ્પે ફેડ ગવર્નર લિસા કૂકને હટાવ્યા</span><span>, </span><span>સેન્ટ્રલ બેંક પર\r\nનિયંત્રણ માટેનો સંઘર્ષ વધ્યો</span></li><li><span>વિદેશી બેટિંગ સાઇટ્સને ફાયદો</span><span>,\r\n</span><span>કારણ કે વાસ્તવિક-પૈસા ગેમિંગ પ્રતિબંધથી સ્થાનિક ખેલાડીઓ\r\nપાછા ખેંચાયા</span></li><li><span>FPIs </span><span>એ ઓગસ્ટમાં વેચાણ\r\nચાલુ રાખ્યું</span><span>, </span><span>ફાઈનાન્સ અને આઈટી સ્ટોક્સ પર સૌથી વધુ અસર</span></li><li><span>તહેવારની સિઝન પહેલાં તમામ ખાદ્ય અને ટેક્સટાઇલ પર </span><span>GST </span><span>કાપની ચર્ચા</span></li><li><span>બેન એન્ડ કંપની અનુસાર ભારતનો ડિજિટલ એડવર્ટાઈઝિંગ માર્કેટ દર વર્ષે </span><span>15%</span><span>થી વધશે</span></li><li><span>જાપાન ભારતના આર્થિક વિકાસ અને સ્થિરતા જોતા વધુ રોકાણ કરવા ઇચ્છે છે</span></li><li><span>આઈટી કંપનીઓએ યુએસની અનિશ્ચિતતા ઘટાડવા ઓસ્ટ્રેલિયા</span><span>, </span><span>મધ્ય પૂર્વ</span><span>, </span><span>નોર્ડિક ક્ષેત્રોમાં આવક વધારી</span></li><li><span>ઓપનએઆઈ અધિકારીએ જણાવ્યું કે ભારતમાં </span><span>ChatGPT </span><span>વપરાશકર્તાઓમાંથી\r\nઅડધા </span><span>24</span><span> વર્ષથી નીચેના છે અને અભ્યાસ માટે તેનો ઉપયોગ કરે છે</span></li><li><span>ટેલિકોમ કંપનીઓએ વરસાદ-પૂરથી પ્રભાવિત વિસ્તારોમાં ગ્રાહકો માટે રાહત પગલાં\r\nજાહેર કર્યા</span></li><li><span>ભારતે </span><span>₹</span><span>10 </span><span>ટ્રિલિયન શિપિંગ\r\nરોકાણ માટે </span><span>100 </span><span>દેશોનો સંપર્ક કર્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>આજે નજરમાં રહેનારા સ્ટોક્સ</span><span>, </span><span>28 ઓગસ્ટ\r\n2025: ઈન્ડિગો</span><span>, </span><span>ઓઈલ ઈન્ડિયા</span><span>, BPCL, SMS </span><span>ફાર્મા પર ફોકસ</span></li><li><span>અમેરિકાએ ભારતીય માલ પર 50% શુલ્ક લગાવ્યું</span><span>; </span><span>નિકાસકારોએ\r\nતાત્કાલિક રાહત માગી</span></li><li><span>EY-JLL </span><span>રિપોર્ટ મુજબ ભારતનો સિનિયર લિવિંગ માર્કેટ 2030 સુધીમાં $8 બિલિયન સુધી\r\nપહોંચશે</span></li><li><span>રાકેશ ગંગવાલ પરિવાર ઈન્ડિગોમાંથી 3.1% સુધીનો હિસ્સો વેચશે</span></li><li><span>ઓઈલ ઈન્ડિયા અને </span><span>BPCL </span><span>અરૂણાચલ પ્રદેશમાં ગેસ વિતરણ માટે સંયુક્ત સાહસ કરશે</span></li><li><span>VVIP </span><span>ઈન્ફ્રાટેકના શેરમાં 3% વધારો</span><span>, </span><span>બોર્ડે </span><span>₹</span><span>100 કરોડ </span><span>QIP </span><span>દ્વારા ઉઠાવવાનો નિર્ણય કર્યો</span></li><li><span>આઈઆઈટી કાઉન્સિલ એઆઈ યુગ માટે અભ્યાસક્રમમાં બદલાવ માટે ટાસ્ક ફોર્સ બનાવશે</span></li><li><span>ભારતની કંપનીઓની </span><span>Q</span><span>1 પછી કમાણીની ગતિ નબળી પડી: ટોપ 5</span><span> EPS </span><span>અપગ્રેડ અને ડાઉનગ્રેડ</span></li><li><span>વાયુસેનાના પ્રમુખે ઓપરેશન સિંદૂરની સંયુક્ત કામગીરીની પ્રશંસા કરી</span><span>, </span><span>કહ્યું: થિયેટર કમાન્ડ્સ તરફ દોડશો નહીં</span></li><li><span>સરકાર 40 દેશોમાં ટેક્સટાઈલ નિકાસ વધારવા માટે અભિયાન શરૂ કરશે</span></li><li><span>યુવા રોકાણકારોના હિસ્સામાં </span><span>FY</span><span>26માં ફરી\r\nવધારો</span><span>, </span><span>અગાઉના વર્ષોમાં ઘટાડો થયો હતો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ફાઈનાન્સિયલ એક્સપ્રેસ:</span></b></span></p>\r\n\r\n<ul><li><span>ટ્રમ્પના ટેરિફ્સ: ભારતીય અર્થતંત્ર પર સેકન્ડરી અને ટર્શરી અસરો પડકારરૂપ</span><span>, </span><span>નાણાં મંત્રાલયનું નિવેદન</span></li><li><span>ઓનલાઈન ગેમિંગ પ્રતિબંધ પછી ડેવલપર્સે નવા આવક સ્ત્રોત શોધ્યા</span></li><li><span>ટ્રમ્પે ફેડ ગવર્નર લિસા કૂકને દૂર કર્યા</span><span>, </span><span>પત્ર\r\nઓનલાઇન શેર કર્યો</span></li><li><span>સરકારે પરક્વિઝિટ ટેક્સેશન માટે નવા ઈન્કમ ટેક્સ નિયમો જાહેર કર્યા</span><span>, </span><span>સુધારેલ મર્યાદા સાથે</span></li><li><span>નાણાકીય ખાધની ચિંતાને કારણે બોન્ડ યિલ્ડ 5 મહિનાના ઉચ્ચ સ્તરે</span></li><li><span>મહિન્દ્રાએ હ્યુન્ડાઈને પાછળ છોડીને 25 વર્ષ પછી ભારતની નં. 2 કાર કંપની બની</span></li><li><span>એલએન્ડટી પરમાણુ ઊર્જા પ્રોજેક્ટ્સ માટે ભાગીદારોની શોધમાં</span></li><li><span>તહેવારો પહેલાં મુખ્ય રૂટ્સ પર હવાઈ ભાડાંમાં ઉછાળો</span></li><li><span>આર્જેન્ટિનાએ યુએસ ટુરિસ્ટ વિઝા ધરાવતા ભારતીય મુસાફરો માટે વિઝા નિયમો શિથિલ\r\nકર્યા</span></li><li><span>ટ્રમ્પે પોતાના નજીકના સહયોગી સર્જિયો ગોરને ભારત માટેના નવા અમેરિકન રાજદૂત તરીકે\r\nનામાંકિત કર્યા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>અમેરિકાના 50% ટેરિફ બાદ સ્ટોક માર્કેટ નીચું ખૂલવાની સંભાવના</span></li><li><span>વોશિંગ્ટન દ્વારા ડોનાલ્ડ ટ્રમ્પ સામે શહેર પોલીસ પર કબ્જા મામલે કેસ</span></li><li><span>વોશિંગ્ટન ડીસી બાદ શિકાગોમાં સૈન્ય તહેનાત કરવાની પેન્ટાગનની યોજના</span></li><li><span>COVID-</span><span>19 દરમિયાન ગેરકાયદે છટણી બદલ ક્વાન્ટાસ એરવેઝને $90 મિલિયન દંડ</span></li><li><span>યુક્રેનની જમીન મુદ્દે પુતિને શાંતિ માટે કડક શરતો મૂકી</span></li><li><span>યુરોપ માટે અમેરિકાની સ્ટોક-માર્કેટ હેકડારી આકસ્મિક સ્થિતિ સમાન</span></li><li><span>એલોન મસ્કની </span><span>xAI </span><span>એ ગ્રોક 2.5 મોડલ ઓપન સોર્સ કર્યું</span></li><li><span>JSW </span><span>નવી </span><span>EV </span><span>મોડલ્સ અને ઓટો બિઝનેસમાં નવા રોકાણ કરશે</span></li><li><span>સરકાર 40 દેશોમાં ટેક્સટાઇલ નિકાસ વધારવા માટે અભિયાન શરૂ કરશે</span></li><li><span>નવી ટેરિફ નિયમોને કારણે ઈન્ડિયા પોસ્ટે અમેરિકામાં પાર્સલ સેવા તાત્કાલિક બંધ\r\nકરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEg-tJbq_kkA-1_aF0YPojV76IT--7VJEOaGyZLJaFQJbhFkRBFoe0lHQhiNjQH_lcAMSimDSqSPS3l43HkLTsRd-Emc4KTtHlTWvR41XMLbSL1E8gY6perPjXy9dm9sbdrhzu7zTdogKOmXzVNLCjgB53YY3YP8e_8o1gHCjo_Qw2mOfGVtlfwjN6LUuUw','2025-08-28','active','2026-09-25 07:55:33','2026-09-25 07:55:33'),
(153,'9148782564359621165','Research Report : Indian Financial Markets Outlook - 28th August 2025',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEinW6H0Qps6a01fYjrvzA-Yglq0HY0Zr5ORWiPsqgz_Ke1sOS8E6qg1ZgYwcwKLTbV5l9SiN9edhjG1e2CQFoYh1HBdig5ageOhn5ztzsRP1Yy9Dk2fxw1SFaFIlG52UX13sm9C5zDuInI3z73xYBUgRA2NIJHUiTq8Jzdj48hdatm5YX47H0jH_pcxwoI\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEinW6H0Qps6a01fYjrvzA-Yglq0HY0Zr5ORWiPsqgz_Ke1sOS8E6qg1ZgYwcwKLTbV5l9SiN9edhjG1e2CQFoYh1HBdig5ageOhn5ztzsRP1Yy9Dk2fxw1SFaFIlG52UX13sm9C5zDuInI3z73xYBUgRA2NIJHUiTq8Jzdj48hdatm5YX47H0jH_pcxwoI\" width=\"240\" /></a></b></div><div><b><span>Ravi Bhatt</span></b></div><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">India reels under US 50% tariff, market sentiments to remain weak</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgsDO65zVnTPlGdW2XBjhvZcio6pv-7xO4UWdU8in4DE00qO_TQtZrAKEs7r5Mp6F-yhlOO8mCjcM4izu6nu31jtO-cG-4aO-RuC0EeAkFdE6EKYv79FOSPmyQC3shzGzT9SiFhGx5BqJPmJhxQZSxNMfF66UiuAqjM3JvIIcVKcikwh1oiQOvEac11w_E\"><img alt=\"\" height=\"299\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgsDO65zVnTPlGdW2XBjhvZcio6pv-7xO4UWdU8in4DE00qO_TQtZrAKEs7r5Mp6F-yhlOO8mCjcM4izu6nu31jtO-cG-4aO-RuC0EeAkFdE6EKYv79FOSPmyQC3shzGzT9SiFhGx5BqJPmJhxQZSxNMfF66UiuAqjM3JvIIcVKcikwh1oiQOvEac11w_E=w532-h299\" width=\"532\" /></a></div>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty was down 44 points or 0.18% at 24,621 in the morning session,\r\nindicating a negative start for the benchmark Nifty 50 as US tariffs of 50% on\r\nIndian goods kicked in a day ago. Asian Pacific markets were mixed in the\r\nmorning, with Japanese and South Korean benchmarks trading higher. Futures for\r\nHong Kong and Chinese stocks were weak as Meituan’s warning pushed an index of\r\nUS-listed Chinese companies lower. US index futures too retreated after Nvidia\r\nCorp.\'s sales outlook missed lofty expectations, weighing on sentiment around\r\nthe world’s most valuable listed company.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Earlier,\r\nthe NSE Nifty 50 ended 255.7 points or 1.02% lower at 24,712.05 and the BSE\r\nSensex closed 849.37 points or 1.04% lower at 80,786.54. The FPIs sold stocks\r\nworth approximately Rs 6,580.1 crore, according to provisional data from the\r\nNational Stock Exchange. The DIIs stayed net sellers for the second session and\r\nbought stakes worth Rs 6,807.90 crore.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Aditya Birla Capital - </span></b><span>Reserve Ba\r\ngranted \'in-principle\' authorization to arm to operate as an online payment\r\naggregator. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Jaiprakash Associates -</span></b><span> CCI\r\napproved the acquisition of Jaiprakash Associates by Adani Group entities. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">SBI Cards -</span></b><span> The Company signed an agreement\r\nwith Flipkart to launch the Flipkart SBI co-branded credit card.<span style=\"color:#0000FF;\"> Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BSE -</span></b><span> Arms BSE Investments &amp; BSE\r\nAdministration and Supervision to merge with BSE Technologies. <span style=\"color:#0000FF;\">Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY - </span></b><span>Nifty tumbled below near term\r\nsupport and closed sharply lower at 24,712 on Tuesday. Market sentiments have\r\nbeen battered by higher US trade tariff and further fall is expected. Index\r\nsupport is now shifted to 24,600 while 24,850 is near term resistance. Today’s\r\nrange 24,600 – 24,850.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY - </span></b><span>Bank nifty too slipped below 55K and\r\nsettled at two months’ low 54,450 on Tuesday. Index has now near term support\r\nat 53,600 while 55K is strong resistance. Today’s range – 54,000 – 54,800.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing research\r\nreport. We shall not be in any way responsible for any loss or damage in\r\nanalysis or views obtained from the use of information contained in this report\r\nand especially states that we have no financial liability whatsoever to the\r\nuser of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEinW6H0Qps6a01fYjrvzA-Yglq0HY0Zr5ORWiPsqgz_Ke1sOS8E6qg1ZgYwcwKLTbV5l9SiN9edhjG1e2CQFoYh1HBdig5ageOhn5ztzsRP1Yy9Dk2fxw1SFaFIlG52UX13sm9C5zDuInI3z73xYBUgRA2NIJHUiTq8Jzdj48hdatm5YX47H0jH_pcxwoI','2025-08-28','active','2026-09-25 07:55:33','2026-09-25 07:55:33'),
(154,'5301688776469812628','Fund Houses Update - 28 August 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgIbMOagtD2tUO9XsfzOms56d9J9l79mm3oIK84JpS5H9xlEghUsnGrFfjaUOI9HLayWo8QuVnSbyHbdeTajdHjzQ43ZTU6xVM-l3RThmQ8YhBcHt6MkX6kJYLY6WlVdgUqR3MPkFoI6o1xnM7EOH8RfUj7OZnJsKK5X2pcOqN0fQC5C-q_p7og0mRi1SA\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgIbMOagtD2tUO9XsfzOms56d9J9l79mm3oIK84JpS5H9xlEghUsnGrFfjaUOI9HLayWo8QuVnSbyHbdeTajdHjzQ43ZTU6xVM-l3RThmQ8YhBcHt6MkX6kJYLY6WlVdgUqR3MPkFoI6o1xnM7EOH8RfUj7OZnJsKK5X2pcOqN0fQC5C-q_p7og0mRi1SA\" width=\"266\" /></a></div><br /><span style=\"text-align:justify;\">Dear\r\nTrader...</span>\r\n\r\n<p style=\"text-align:justify;\"><span>Fund\r\nHouses Recommendations </span></p>\r\n\r\n<ul><li><span style=\"color:#0000FF;\">Jefferies on Hero Motocorp: </span><span>Upgrade\r\nto Hold on Company, raise target price at Rs 5200/Sh<span style=\"color:#0000FF;\">\r\n(Positive)</span></span></li></ul><ul><li><span style=\"color:#0000FF;\">Jefferies on TVS Motors: </span><span>Maintain Buy\r\non Company, raise target price at Rs 4250/Sh<span style=\"color:#0000FF;\">\r\n(Positive)</span></span></li></ul><ul><li><span style=\"color:#0000FF;\">Jefferies on Maruti: </span><span>Maintain Buy on\r\nCompany, raise target price at Rs 17500/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li></ul><ul><li><span style=\"color:#0000FF;\">Jefferies on Eicher Motors: </span><span>Maintain\r\nBuy on Company, raise target price at Rs 6925/Sh <span style=\"color:#0000FF;\">(Positive)</span></span></li></ul><ul><li><span style=\"color:#0000FF;\">Jefferies on Bajaj Auto: </span><span>Maintain\r\nHold on Company, raise target price at Rs 9000/Sh <span style=\"color:#0000FF;\">(Positive)</span></span></li></ul><ul><li><span style=\"color:#0000FF;\">Jefferies on M&amp;M: </span><span>Maintain Buy\r\non Company, raise target price at Rs 4200/Sh<span style=\"c