(218,'3954188900026336532','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૫ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgEIfc7WKzVwmnNl3vb2damrc_A4I-6U5HOc1Fmb8GDdw6UdQdUOwy12CEavDNqU1ZVU-qIywLpZMFwBZ6NKPonW4sMY_Bah9qYl4a8PdiDJ3Amv81zhp4jehZsw5jNpVxc4CjG5RJnOKElkg3jFqtFifpRJWzJMceGl5-MlkSZOCvcuErUw90Le7NwDzU\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgEIfc7WKzVwmnNl3vb2damrc_A4I-6U5HOc1Fmb8GDdw6UdQdUOwy12CEavDNqU1ZVU-qIywLpZMFwBZ6NKPonW4sMY_Bah9qYl4a8PdiDJ3Amv81zhp4jehZsw5jNpVxc4CjG5RJnOKElkg3jFqtFifpRJWzJMceGl5-MlkSZOCvcuErUw90Le7NwDzU\" width=\"281\" /></a></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>એરટેલ આફ્રિકાનો </span><span>Q</span><span>1 નફો 5 ગણો વધીને $156 મિલિયન થયો</span></li><li><span>ટોરેન્ટ પાવર </span><span>L&amp;T</span><span>ની પાવર યુનિટ $1 અબજમાં\r\nખરીદવા વાતચીતમાં</span></li><li><span>Executive Centre India </span><span>એ </span><span>IPO </span><span>માટે </span><span>Sebi </span><span>સાથે </span><span>DRHP </span><span>ફાઇલ\r\nકર્યું</span><span>; </span><span>₹</span><span>2,600 કરોડના નવા ઇશ્યૂથી ભંડોળ ઊભું કરશે</span></li><li><span>SBI </span><span>જનરલ ઈન્શ્યોરન્સ </span><span>Q</span><span>1</span><span>FY</span><span>26 માં 21.5% વૃદ્ધિ નોંધાવે છે</span><span>, </span><span>ઉદ્યોગના\r\n6.2% વૃદ્ધિને પાછળ છોડે છે</span></li><li><span>PhysicsWallah IPO </span><span>માટે </span><span>Sebi</span><span>ની મંજૂરી મેળવનારી પહેલી એડટેક કંપની</span></li><li><span>MCX </span><span>એ ટેક્નિકલ ખામીથી ટ્રેડિંગ વિક્ષેપ પર સ્પષ્ટતા કરી</span></li><li><span>બ્રિગેડ હોટેલ </span><span>IPO </span><span>પ્રથમ દિવસે 48% સબ્સ્ક્રાઇબ</span></li><li><span>તહેવારોની માંગ અને ઘટેલી કિંમતોને કારણે </span><span>H</span><span>2 માં\r\nભારતનો પામ તેલ આયાત વધશે : </span><span>IVPA </span><span>પ્રમુખ</span></li><li><span>MakeMyTrip </span><span>વૈશ્વિક પ્રવાસ અનુભવ ક્ષેત્રમાં પ્રવેશ્યું</span><span>; </span><span>ટૂર્સ\r\nઅને આકર્ષણ બુકિંગ પ્લેટફોર્મ શરૂ કર્યું</span></li><li><span>લોટ્ટે ઇન્ડિયાએ બિસ્કિટ નાસ્તો </span><span>PEPERO </span><span>લોન્ચ\r\nકર્યો</span><span>, </span><span>2025 સુધીમાં </span><span>₹</span><span>2,000 કરોડના આવકનું લક્ષ્ય</span></li><li><span>PVC </span><span>પાઇપ અને ફિટિંગ્સ બનાવતી કંપનીઓ આ નાણાકીય વર્ષમાં પુનરુત્થાન જોશે : ક્રિસિલ\r\nરેટિંગ્સ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>NTPC </span><span>ને ટ્રાંચિસમાં </span><span>₹</span><span>18,000</span><span> કરોડના </span><span>NCDs </span><span>જારી\r\nકરવા માટે શેરહોલ્ડર્સની મંજૂરી મળી</span></li><li><span>ભારતમાં એજ ડેટા સેન્ટર ક્ષમતા </span><span>2027</span><span> સુધીમાં ત્રણ\r\nગણું થવાની શક્યતા : </span><span>ICRA</span></li><li><span>રાજસ્થાને </span><span>4</span><span> વર્ષ પછી લઘુ ખનિજો પર રોયલ્ટી </span><span>30%</span><span> સુધી વધારી</span></li><li><span>ભારત-બ્રિટન મુક્ત વેપાર કરાર પર હસ્તાક્ષર</span><span>; </span><span>વાર્ષિક\r\n</span><span>$34</span><span> અબજના વેપારમાં વૃદ્ધિ થશે</span></li><li><span>અજય સેથ </span><span>IRDAI</span><span>ના ચેરમેન તરીકે ત્રણ વર્ષ માટે નિયુક્ત</span><span>, </span><span>પાંડા પછી પદ સંભાળશે</span></li><li><span>Indiqube Spaces IPO </span><span>બીજા દિવસે સંપૂર્ણપણે સબ્સ્ક્રાઇબ</span><span>, </span><span>રિટેલ\r\nરોકાણકારો આગેવાની કરે છે</span></li><li><span>EVeez </span><span>એ ગીગ વર્કર્સ માટે ઇલેક્ટ્રિક મૂવેબિલિટી સેવાઓ વિસ્તરાવવા </span><span>$5.4</span><span> મિલિયન ઉઠાવ્યા</span></li><li><span>ટિયર-</span><span>2</span><span> શહેરોમાં વપરાયેલા લક્ઝરી કારના વેચાણમાં </span><span>30%</span><span> વૃદ્ધિ</span><span>; 80%</span><span> ખરીદી\r\nહવે ડિજિટલ</span></li><li><span>ટેક્સટાઇલ કંપની </span><span>AB Cotspin </span><span>₹</span><span>1,500</span><span> કરોડના રોકાણથી ઉત્પાદન ક્ષમતા વધારશે</span></li><li><span>8</span><span>\r\nશહેરોમાં એપ્રિલ-જૂનમાં રિટેલ જગ્યા લીઝિંગમાં </span><span>6%</span><span> ઘટાડો\r\n: </span><span>C&amp;W</span></li><li><span>ઝાયડસ લાઈફસાયન્સિસને બ્લડ કેન્સરના જનરિક દવાના </span><span>USFDA</span><span>ના પ્રાથમિક મંજૂરી</span></li><li><span>સેન્ટ્યુરીપ્લાયે તમિલનાડુમાં ભારતનો સૌથી મોટો પાર્ટિકલ બોર્ડ પ્લાન્ટ શરૂ\r\nકર્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારત-બ્રિટન લાંબા સમયથી ચાલી રહેલા વાટાઘાટો પછી ઐતિહાસિક મુક્ત વેપાર કરાર\r\nપર હસ્તાક્ષર</span></li><li><span>ભારત-યુકે </span><span>FTA: </span><span>વેપાર વૃદ્ધિના કારણે એર કનેક્ટિવિટી સર્વોચ્ચ સ્તરે\r\nપહોંચશે</span></li><li><span>એર ઇન્ડિયાનો </span><span>FY</span><span>25 નો નુકસાન વધ્યો</span><span>, </span><span>પરંતુ\r\nઆવકના મામલે ઇન્ડિગો સાથેનો અંતર ઘટ્યો</span></li><li><span>નુકસાન હોવા છતાં </span><span>FY</span><span>25 માં એર\r\nઇન્ડિયાની આવક ઇન્ડિગોની નજીક પહોંચી</span></li><li><span>SBI </span><span>લાઇફ </span><span>Q</span><span>1 પરિણામ : શુદ્ધ નફામાં 14% નો વધારો થઈ </span><span>₹</span><span>594 કરોડ થયો</span></li><li><span>કોઠારી મહિન્દ્રાએ </span><span>₹</span><span>8 કરોડ સુધીની ક્રેડિટ લાઇન સાથે સોલિટાયર પ્રોગ્રામ શરૂ કર્યો</span></li><li><span>કેનારા </span><span>HSBC </span><span>લાઇફ </span><span>IPO </span><span>ને </span><span>IRDAI</span><span>ની મંજૂરી મળી</span><span>, </span><span>ઓક્ટોબર સુધી\r\nભારતીય બજારમાં આવશે</span></li><li><span>રિલાયન્સ પાવર</span><span>, </span><span>રિલાયન્સ ઈન્ફ્રાએ </span><span>ED</span><span>ની\r\nકાર્યવાહીનો નાણાકીય અસર નકારી</span></li><li><span>LIC </span><span>ના જૂન-ક્વાર્ટર રોકાણમાં મોમેન્ટમમાંથી વેલ્યૂ ઈન્વેસ્ટિંગ તરફ વળાંકના\r\nસંકેતો</span></li><li><span>સ્ટારબક્સ ઇન્ડિયા \"મંદ ગતિ\" પછી સ્ટોર વિસ્તરણને વેગ આપશે</span></li><li><span>ખર્ચમાં કાપ લાવવાથી </span><span>OPmobility</span><span>ની </span><span>H</span><span>1 કમાણીમાં સુધારો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgEIfc7WKzVwmnNl3vb2damrc_A4I-6U5HOc1Fmb8GDdw6UdQdUOwy12CEavDNqU1ZVU-qIywLpZMFwBZ6NKPonW4sMY_Bah9qYl4a8PdiDJ3Amv81zhp4jehZsw5jNpVxc4CjG5RJnOKElkg3jFqtFifpRJWzJMceGl5-MlkSZOCvcuErUw90Le7NwDzU','2025-07-25','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(219,'4300668913005779685','Research Report : Indian Financial Markets Outlook - 24th July 2025',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhBzF1lXSQkz68pkMIVYzzQlXnP4Q347-wM6ml0AjiY5BNCqGT5UtQHgBbQ9gZU0SvvhGInUyDMydVvZPc_oLk90F-szqdShkDUHUoN-26LkPJ6QiIvmZM-zsNYD9fJskPpMpUivilGpoyDYoZLwmMiU4ZVeiyQLHZppp88HgvPk8eJuCm-9EvTbSM-jvk\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhBzF1lXSQkz68pkMIVYzzQlXnP4Q347-wM6ml0AjiY5BNCqGT5UtQHgBbQ9gZU0SvvhGInUyDMydVvZPc_oLk90F-szqdShkDUHUoN-26LkPJ6QiIvmZM-zsNYD9fJskPpMpUivilGpoyDYoZLwmMiU4ZVeiyQLHZppp88HgvPk8eJuCm-9EvTbSM-jvk\" width=\"240\" /></a></b></div><div style=\"text-align:center;\"><b><span>Ravi Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">Asian\r\nmarkets continued in positive territory over US Japan trade deal</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhMzVnGxpt_w7mXioWStOKSvja8cAPqh91PQf43BiHPUD6oGcA5pArqK1lx1PjaqhSYn7Z3aHvupAxNWuUn24HsKb4hXi0RKwVSKuY-HacuXnJSLkUtRbvi8iMqlYmSgUbd9gY9U6WM2SnRiBjjW0T66QuRFbuAFoQXZgblpvD3xKkas1LlGBnPlryw9rI\"><img alt=\"\" height=\"328\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhMzVnGxpt_w7mXioWStOKSvja8cAPqh91PQf43BiHPUD6oGcA5pArqK1lx1PjaqhSYn7Z3aHvupAxNWuUn24HsKb4hXi0RKwVSKuY-HacuXnJSLkUtRbvi8iMqlYmSgUbd9gY9U6WM2SnRiBjjW0T66QuRFbuAFoQXZgblpvD3xKkas1LlGBnPlryw9rI=w570-h328\" width=\"570\" /></a></div>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>Asian\r\nmarkets continued marching upward for a sixth straight session after a US-Japan\r\ntrade agreement signalled potential for further deals, lifting market\r\nconfidence across the region. The MSCI Asia Pacific index gained 0.7%, marking\r\nits longest rally since January. Japan’s equity benchmarks opened more than\r\n1.3% higher in the morning session. In the US, the S&amp;P 500 closed 0.8%\r\nhigher, setting a record for the third day in a row. The NSE Nifty 50 ended 159\r\npoints or 0.63% higher at 25,219.90, while the BSE Sensex closed 539.83 points\r\nor 0.66% up at 82,726.64. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT NIFTY traded steady in the morning session at 25,298. Foreign portfolio\r\ninvestors remained net sellers of Indian shares for the third consecutive day\r\non Wednesday as they sold stocks worth Rs 4,209.11 crore, according to\r\nprovisional data from the National Stock Exchange. The domestic institutional\r\ninvestors, who stayed buyers for the 13th straight session, obtained stocks\r\nworth Rs 2,944.9 crore.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Infosys -</span></b><span> Q1FY26 (QoQ) Revenue up 3.3% to Rs\r\n42,279.00 crore versus Rs 40,925 crore. EBIT 3.3% to Rs 6,921 crore versus Rs\r\n7,033 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Force Motors</span></b><span> - Q1FY26 (YoY) Revenue up 21.9% to\r\nRs 2,297 crore versus Rs 1,885 crore. Ebitda up 33.3% to Rs 332 crore versus Rs\r\n249 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Bikaji Foods</span></b><span> - Q1FY26 (YoY) Revenue up 14.2% to\r\nRs 653 crore versus Rs 572 crore. Ebitda up 5% to Rs 96.2 crore versus Rs 91.6\r\ncrore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#006600;\">Cigniti Technologies</span></b><span> - Q1FY26\r\n(QoQ) Revenue up 0.8% to Rs 534 crore versus Rs 530 crore. EBIT flat at Rs 81.5\r\ncrore versus Rs 81.3 crore. <span style=\"color:#006600;\">Neutral</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty recovered over 150 points to\r\nsettle above 25,200 at 25,219 on Wednesday. Index crossed the near term\r\nresistance at 17 day EMA of 25,200 to move towards 25,350. The support lies at\r\n25,150. Today’s range – 25,150 – 25,350.</span></li></ul>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhBzF1lXSQkz68pkMIVYzzQlXnP4Q347-wM6ml0AjiY5BNCqGT5UtQHgBbQ9gZU0SvvhGInUyDMydVvZPc_oLk90F-szqdShkDUHUoN-26LkPJ6QiIvmZM-zsNYD9fJskPpMpUivilGpoyDYoZLwmMiU4ZVeiyQLHZppp88HgvPk8eJuCm-9EvTbSM-jvk','2025-07-24','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(220,'1199282944387887608','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૪ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgy-eM_fZ_Zs13ITF2qTc6EwibkYeR0FTMMJ1hvE8wfgkSAVC4EYB5i9QNxyi8sbmnleWfWgFUh2DkqNV07fYImDXOa82AXmZCjipcQDxDwlhehWCJ06rZrcodCa1i8ZrIw-VHz1MsT-r1gGqhYKu6QnpRQ4UVt2VjKUnTK7I8O08DSETskN2N8LvB7AhM\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgy-eM_fZ_Zs13ITF2qTc6EwibkYeR0FTMMJ1hvE8wfgkSAVC4EYB5i9QNxyi8sbmnleWfWgFUh2DkqNV07fYImDXOa82AXmZCjipcQDxDwlhehWCJ06rZrcodCa1i8ZrIw-VHz1MsT-r1gGqhYKu6QnpRQ4UVt2VjKUnTK7I8O08DSETskN2N8LvB7AhM\" width=\"281\" /></a></b></div><h2 style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /> </span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></h2>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતે ટેરિફ નીતિની\r\nઅનિશ્ચિતતાના વચ્ચે પણ સ્થિરતા જાળવી: આરબીઆઈ બુલેટિન</span></li><li><span>જુનમાં</span><span>સૌદી</span><span>અરેબિયા</span><span>રશિયન</span><span>ફ્યુઅલ</span><span>ઓઈલનો</span><span>સૌથી</span><span>મોટો</span><span>ખરીદદાર</span><span>રહ્યો</span></li><li><span>રેડિસન</span><span>હોટલ</span><span>ગ્રુપે</span><span>ઈટ્રાવેલી</span><span>ગ્રુપ</span><span>સાથે</span><span>મળી</span><span>ભારતમાં</span><span>રેડિસન</span><span>ફ્લાઈટ્સ</span><span>લોન્ચ</span><span>કરી</span></li><li><span>ઈન્ડોસો</span><span>લ સોલાર સરકારના સહયોગથી 2026 સુધીમાં 10</span><span>GW\r\n</span><span>ક્ષમતા હાંસલ કરવા ઇચ્છે છે</span></li><li><span>ભારતમાં</span><span>મોબાઈલ</span><span>એક્સપોર્ટ</span><span> $20.5 </span><span>બિલિયન</span><span>સાથે</span><span>વિશ્વમાં</span><span>ત્રીજા</span><span>ક્રમે</span><span>પહોંચ્યું</span></li><li><span>વર્ટિસ</span><span>ઈન્ફ્રાસ્ટ્રક્ચર</span><span>ટ્રસ્ટે</span><span>SLB </span><span>મારફતે રૂ. 900\r\nકરોડ એકત્ર કર્યા</span></li><li><span>વિદાંતા</span><span>કર્નાટકમાં</span><span>આયર્ન</span><span>ઓર</span><span>માઇનિંગ</span><span> માટે </span><span>\'</span><span>પસંદીદા બિડર</span><span>\' </span><span>તરીકે પસંદ</span></li><li><span>પેટ્રોનેટ</span><span>,\r\n</span><span>ભારતની ટોચની </span><span>LNG </span><span>આયાતક કંપની</span><span>,\r\n</span><span>સ્થાનિક રીતે $1.4 બિલિયન લોન શોધે છે</span></li><li><span>કોટક</span><span>મહિન્દ્રા</span><span>બેંક</span><span>\'</span><span>અન્ડરસર્વ્ડ</span><span>\' </span><span>અફલ્યૂઅન્ટ વિભાગ\r\nપર મોટો દાવ લગાવે છે</span></li><li><span>મારુતિ</span><span>સુઝુકી</span><span>અને</span><span>DPIIT\r\n</span><span>વચ્ચે ઓટો અને મોબિલિટી સ્ટાર્ટઅપ નવું ઇનોવેશન વધારવા </span><span>MoU</span></li><li><span>સરકારી</span><span>માઇન</span><span>ઈન્સ્પેક્શનના</span><span>પગલે</span><span>કોંકિંગ</span><span>કોલના</span><span>ભાવ</span><span>પાંચ</span><span>મહિનાના</span><span>ટોચે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>એડિબી (</span><span>ADB)</span><span>એ ભારતના 2025-26ના વિકાસ અનુમાનને 6.5% સુધી ઘટાડ્યું</span><span>; </span><span>અમેરિકાના ટેરિફના પ્રભાવને કારણ જણાવ્યું</span></li><li><span>IHH</span><span>એ પેન-ઇન્ડિયા પ્લેટફોર્મ મજબૂત કરવા માટે ફોર્ટિસ-ગ્લેનઇગલ્સ સાથે ઓ</span><span>&amp;M </span><span>કરાર કર્યો</span></li><li><span>આરબીઆઈની </span><span>LRS </span><span>યોજના હેઠળ બહાર જતા રકમોમાં મે 2025માં 4.4% ઘટાડો</span><span>, </span><span>કુલ $2.3 બિલિયન</span></li><li><span>રેનોલ્ટ હવે ચેન્નઈ પ્લાન્ટમાં પૂર્ણ ક્ષમતા સુધી પહોંચવા માંગે છે</span><span>, </span><span>કોઈ નવા પાર્ટનરનો પ્લાન નથી</span></li><li><span>મ્યુચ્યુઅલ ફંડ ઉદ્યોગે લચીલાપણું અને વૃદ્ધિ દર્શાવી: </span><span>ICRA </span><span>એનાલિટિક્સ</span></li><li><span>દીપાલી નાયર હવે બાયોકોન બાયોલોજિક્સમાં બ્રાન્ડ અને કોર્પોરેટ કમેનીયૂકેશનનું\r\nનેતૃત્વ સંભાળશે</span></li><li><span>આરબીઆઈએ મેમાં વિદેશી વિનિમય બજારમાં $1.76 બિલિયન નેટ ખરીદી કરી</span></li><li><span>ઈનબાઉન્ડ એરસ્પેસે સ્પેશિયલ ઇનવેસ્ટના નેતૃત્વ હેઠળ $1 મિલિયનનું પ્રી-સીડ ફંડિંગ\r\nમેળવ્યું</span></li><li><span>ભારતમાં ગ્લોબલ કેપેબિલિટી સેન્ટર્સ (</span><span>GCCs) </span><span>સ્થાપવા માટે </span><span>MNCs </span><span>સંસ્થાકીય ઓફિસ એસેટ્સને પ્રાથમિકતા આપે છે: </span><span>C&amp;W</span></li><li><span>SBI </span><span>હવે આવનારા 5 વર્ષમાં માર્કેટ વેલ્યુ મુજબ દુનિયાના ટોપ 10 બેંકોમાં સ્થાન\r\nમેળવવા ઈચ્છે છે</span></li><li><span>વિર્લપૂલ ઈન્ડિયાના હિસ્સા વેચાણના દોરમાં </span><span>EQT </span><span>અને બેઈન આગળ</span><span>, </span><span>રિલાયન્સ અને હવેલ્સ પછાડી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>હાલના કૃષિ લોન </span><span>₹</span><span>28 લાખ કરોડથી વધુ છે</span><span>, </span><span>પણ\r\nસરકાર દ્વારા ક્યારેય માફી યોજનાનું આયોજન નથી</span></li><li><span>યુરોપિયન યુનિયને અમેરિકાના 30% ટેરિફ સામે 100 બિલિયન યુરોનું કોઈ-સમજુતું પ્લાન\r\nતૈયાર કર્યું</span></li><li><span>ઇન્ફોસિસમાં </span><span>Q</span><span>1માં પર્સનલ છૂટાછૂટ દર 14.4% રહ્યો</span><span>, </span><span>8,456 નવા કર્મચારીઓ જોડાયા</span></li><li><span>ફોનપેએ </span><span>SBI </span><span>કાર્ડ સાથે બે કો-બ્રાન્ડેડ ક્રેડિટ કાર્ડ લોન્ચ કર્યા</span></li><li><span>FY</span><span>25માં\r\nરાષ્ટ્રીય હાઈવે નિર્માણનો દર ઘટીને દરરોજ 29 કિમી થયો: નિતિન ગડકરી</span></li><li><span>સુપ્રીમ કોર્ટે મારન દ્વારા સ્પાઈસજેટ સામે દાખલ કરેલી </span><span>₹</span><span>1,323 કરોડની અરજી રદ કરી</span></li><li><span>ગુપશપે નવા ફંડિંગમાં $60 મિલિયન ઊભું કર્યું</span><span>, </span><span>આગામી\r\n12-24 મહિનામાં </span><span>IPO </span><span>લક્ષ્ય</span></li><li><span>પેપાલ હવે </span><span>UPI </span><span>સાથે જોડાયું</span><span>, </span><span>ભારત માટે\r\nઆંતરરાષ્ટ્રીય પેમેન્ટ સરળ બનશે</span></li><li><span>સરકારી </span><span>WAPCOS</span><span> ટેક્સ પહેલાંના નફામાં 20.44% વધારો નોંધાવ્યો</span></li><li><span>દસોલ્ટે ફરીથી ફ્રેંકો-જર્મન યુદ્ધવિમાન પ્રોજેક્ટમાં નેતૃત્વ કરવાની નિશાની બતાવી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgy-eM_fZ_Zs13ITF2qTc6EwibkYeR0FTMMJ1hvE8wfgkSAVC4EYB5i9QNxyi8sbmnleWfWgFUh2DkqNV07fYImDXOa82AXmZCjipcQDxDwlhehWCJ06rZrcodCa1i8ZrIw-VHz1MsT-r1gGqhYKu6QnpRQ4UVt2VjKUnTK7I8O08DSETskN2N8LvB7AhM','2025-07-24','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(221,'8838955413918903832','Research Report : Indian Financial Markets Outlook - 23th July 2025',NULL,'<div style=\"text-align:center;\"><p><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjcwEwmjprpLpVIQHRALcjMdeyEBS3ifboN0wErIMsUPcT1FImNmsyuVJqhl5aT_tNF9pfT8rcLybcGiV3iQH0IvV_bLurgSSn7Sy0DbYSIbxikQ1CMRPO39WDeNVxO8r5MGPywrrSMHCNUeF4lizwgr5xysSssNBSELmOUgYVlyuktv9iWukRp6qfKalQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjcwEwmjprpLpVIQHRALcjMdeyEBS3ifboN0wErIMsUPcT1FImNmsyuVJqhl5aT_tNF9pfT8rcLybcGiV3iQH0IvV_bLurgSSn7Sy0DbYSIbxikQ1CMRPO39WDeNVxO8r5MGPywrrSMHCNUeF4lizwgr5xysSssNBSELmOUgYVlyuktv9iWukRp6qfKalQ\" width=\"240\" /></a></p><p><b><span>Ravi Bhatt</span></b></p><div><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com<br /></span></b></a></span></div></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Asian\r\nmarkets cheer over Trump announcement of signing deals with Japan</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgj3wd6dY8rPrGLE_qYCHZBQXVxGkflqFIxVBvHEszDHhY-oSr79SsYhmI6EpbE4OeGo2TwOaKArxdKixMyvM-gxuJcDgUTCXdMh_9blMmuiyTR_WWsiPXR15Xw1kEjDmXzfH7vbWaH-ou7V1_ZaWhiDFOhxFQROo0jiIyd6aK5yp8hPE1w25kr-FZxwUM\"><img alt=\"\" height=\"330\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgj3wd6dY8rPrGLE_qYCHZBQXVxGkflqFIxVBvHEszDHhY-oSr79SsYhmI6EpbE4OeGo2TwOaKArxdKixMyvM-gxuJcDgUTCXdMh_9blMmuiyTR_WWsiPXR15Xw1kEjDmXzfH7vbWaH-ou7V1_ZaWhiDFOhxFQROo0jiIyd6aK5yp8hPE1w25kr-FZxwUM=w600-h330\" width=\"600\" /></a></div><p style=\"text-align:justify;\"><span>Asian\r\nmarket rose at the opening session on Wednesday morning after President Donald\r\nTrump said the US reached a trade deal with Japan, Phillipines and Indonesia.\r\nThe MSCI gauge of Asian shares gained 0.7%. Nikkei was up 2.35% while Topix\r\ngained over 2.4% in the morning session. Kospi was down 0.1% while S&amp;P/ASX\r\n200 up 0.35% and Hang Seng futures up 1%. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty was traded up by 56 points to 25,105 in the morning. Earlier, the\r\nbenchmark equity indices ended the session on a flat note on Tuesday as shares\r\nof Reliance Industries Ltd. and Infosys Ltd. weighed. The NSE Nifty 50 ended\r\n29.8 points or 0.12% lower at 25,060.9, while the BSE Sensex closed 13.53\r\npoints or 0.02% down at 82,186.81. The FPIs continued offloading Indian stocks,\r\nselling over 3K crores shares in yesterday’s session.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Zensar Tech</span></b><span> - Q1FY26 (QoQ) Revenue is up 1.9%\r\nat Rs 1,385 crore versus Rs 1,359 crore. EBIT down 0.6% at Rs 188 crore versus\r\nRs 189 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Dixon Technologies</span></b><span> - Q1FY26 (YoY) Revenue up\r\n95.1% to Rs 12,835.66 crore versus Rs 6,579.80 crore. Ebitda up 95% to Rs\r\n482.37 crore versus Rs 247.90 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Dalmia Bharat</span></b><span> - Q1FY26 (YoY) Revenue up 0.4% to\r\nRs 3,636 crore versus Rs 3,621 crore. Ebitda up 32% to Rs 883 crore versus Rs\r\n669 crore. <span style=\"color:#0000FF;\">Positive </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">United Breweries</span></b><span> - Q1FY26 (YoY) Revenue rises 15.7%\r\nto Rs 2,862 crore versus Rs 2,472 crore. Ebitda up 9% to Rs 310.52 crore versus\r\nRs 284.74 crore.<span style=\"color:#0000FF;\"> Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty continued zig zag movement\r\nfalling over 30 points to settle at 25,060 on Tuesday. Index is facing\r\nresistance at 17 day EMA of 25,200 while 50 day EMA gives strong support at\r\n24,950. Today’s range – 24,950 – 25,200.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty too slipped below 57K to\r\nclose at 56,756 on Tuesday. Index closed tad below 17 day EMA of 56,850 while\r\n57,250 is near term resistance. Today’s range – 56,550 – 57,250.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjcwEwmjprpLpVIQHRALcjMdeyEBS3ifboN0wErIMsUPcT1FImNmsyuVJqhl5aT_tNF9pfT8rcLybcGiV3iQH0IvV_bLurgSSn7Sy0DbYSIbxikQ1CMRPO39WDeNVxO8r5MGPywrrSMHCNUeF4lizwgr5xysSssNBSELmOUgYVlyuktv9iWukRp6qfKalQ','2025-07-23','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(222,'5097637949711774586','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૩ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEg3m1A79oU-pjjSlaxrmn1Zo0qoSnL9xDVddEEDIwK4YKlpstYX4j0dC6Gm3eWkgIuORohbHvLPFZsj4JBVui4pY0p1CZL0hEY-VC4jtz4J3_g6vcVJcJ_jGXkLK9N_vq9g-HvZ_bUyO2vcALvQk0QrN6MZAUXMTwt9xvPrsOKHz_qi-i-_PMWDw-cWFCA\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEg3m1A79oU-pjjSlaxrmn1Zo0qoSnL9xDVddEEDIwK4YKlpstYX4j0dC6Gm3eWkgIuORohbHvLPFZsj4JBVui4pY0p1CZL0hEY-VC4jtz4J3_g6vcVJcJ_jGXkLK9N_vq9g-HvZ_bUyO2vcALvQk0QrN6MZAUXMTwt9xvPrsOKHz_qi-i-_PMWDw-cWFCA\" width=\"281\" /></a></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>એર ઈન્ડિયા </span><span>Boeing\r\n</span><span>777 વિમાનો માટે $200 મિલિયન લોન લેવા માંગે છે</span></li><li><span>Paytm </span><span>₹</span><span>122 </span><span>કરોડ</span><span>નફા</span><span>સાથે</span><span>નફામાં</span><span>ફેરવાઈ</span><span>,\r\n</span><span>આવકમાં 28% વધારો</span></li><li><span>મોતીલાલ ઓસવાલ\r\nએલ્ટરનેટ્સે રિયલ એસ્ટેટ ફંડ દ્વારા </span><span>₹</span><span>2,000 </span><span>કરોડ</span><span>ઉઠાવ્યા</span></li><li><span>Lodha\r\nDevelopers</span><span>એ </span><span>NCDs </span><span>દ્વારા </span><span>₹</span><span>350 </span><span>કરોડથી</span><span>વધુ</span><span>એકત્રિત</span><span>કર્યા</span></li><li><span>Dixon\r\nTechnologies</span><span>નો નફો દોઢગણો થયો</span><span>, </span><span>₹</span><span>280 </span><span>કરોડ</span><span>,\r\n</span><span>આવકમાં 95% ઉછાળો</span></li><li><span>Schloss\r\nBangalore (Leela Palace) </span><span>₹</span><span>9 </span><span>કરોડ</span><span>નફો</span><span>;\r\n</span><span>ગયા વર્ષે </span><span>₹</span><span>75 </span><span>કરોડ</span><span>નુકસાન</span><span>હતું</span></li><li><span>વિશ્વ બેન્ક કહે છે\r\nકે ભારતે 2050 સુધીમાં શહેરોની માળખાકીય સુસજ્જતાને માટે $2.4 ટ્રિલિયનની જરૂર\r\nપડશે</span></li><li><span>Samsung </span><span>વિશ્વમાં સૌથી વધુ સ્માર્ટફોન વેચાણ સાથે આગળ</span></li><li><span>US </span><span>સ્ટાર્ટઅપ </span><span>xLight</span><span>એ ચીન સામેની\r\nસ્પર્ધામાં ચિપ લેઝર માટે $40 મિલિયન ઉઠાવ્યા</span></li><li><span>Escape Plan </span><span>નામની ટ્રાવેલ એસેસરી કંપનીએ </span><span>₹</span><span>5 </span><span>મિલિયન</span><span>ભંડોળ</span><span>ઊભું</span><span>કર્યું</span></li><li><span>મહારાષ્ટ્ર સરકારે\r\nકૃષિ ક્ષેત્ર માટે </span><span>₹</span><span>25,000 </span><span>કરોડની</span><span>નવી</span><span>યોજના</span><span>લાવી</span></li><li><span>ટાટા ગ્રુપ</span><span>,\r\n</span><span>ગુગલ ઈન્ડિયા</span><span>, </span><span>ઈન્ફોસિસ સૌથી\r\nઆકર્ષક નોકરીદાતા બ્રાન્ડ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>IBC </span><span>દ્વારા છેલ્લા 9 વર્ષમાં </span><span>₹</span><span>26 લાખ કરોડના લેણાં ઉકેલાયા</span></li><li><span>અશોક લેલેન્ડ </span><span>LNG </span><span>ટ્રકમાં બૂમ લાવવા પ્રયત્નશીલ</span></li><li><span>સરકારી બેન્કોના </span><span>NPA </span><span>ઘટીને 2.58% રહ્યા</span></li><li><span>RBI</span><span>ના ફાઇનાન્સિયલ ઈન્ક્લૂઝન ઈન્ડેક્સમાં વધારો</span></li><li><span>કેન્દ્રએ આરોગ્ય માળખા માટે રાજ્યોને </span><span>₹</span><span>33,081 કરોડની મંજૂરી આપી</span></li><li><span>બલ્ક ડ્રગ માટે </span><span>PLI </span><span>યોજનાએ </span><span>₹</span><span>1,362 કરોડની આયાત બચત કરી</span></li><li><span>બાંધકામ ઉદ્યોગમાં </span><span>FY</span><span>26માં માજિન 10.25%થી 10.75% વચ્ચે રહેવાની સંભાવના</span></li><li><span>Coca-Cola</span><span>નું ક્યુ2 રિજલ્ટ: આવક $12.62 બિલિયન</span></li><li><span>Zee Entertainment</span><span>નો નફો 22% વધીને </span><span>₹</span><span>143.7 કરોડ થયો</span></li><li><span>રૂપિયા એફપીઆઈના નિકાલથી ઘટી </span><span>₹</span><span>86.37/</span><span>$</span></li><li><span>FY</span><span>24માં કોર્પોરેટ ટેક્સ છૂટથી સરકારને </span><span>₹</span><span>99,000 કરોડનું નુકસાન</span></li><li><span>Colgate-Palmolive</span><span>નો નફો 12% ઘટ્યો</span></li><li><span>Juniper Green Energy</span><span>એ મહારાષ્ટ્રમાં\r\n43</span><span> MWp </span><span>વીજ ઉત્પાદન\r\nશરૂ કર્યું</span></li><li><span>મુંબઈમાં અલ્ટ્રા લક્ઝરી હોમ વેચાણ 20% વધ્યું</span></li><li><span>Reliance, Adani, Mahindra</span><span>ને </span><span>₹</span><span>60,000 કરોડના </span><span>ITI </span><span>અપગ્રેડ પ્લાનમાં સ્થાન</span></li><li><span>Lloyds Metals</span><span> ગડચિરોલી વિસ્તારમાં </span><span>₹</span><span>40,000 કરોડથી વધુનું રોકાણ કરવાનું ઘોષિત કર્યું</span></li><li><span>PhysicsWallah</span><span>એ </span><span>JEE Mains </span><span>માટે </span><span>Aryabhata </span><span>1.0</span><span> AI </span><span>મોડેલ લૉન્ચ કર્યો</span></li><li><span>Ebix Tech</span><span>ને મહારાષ્ટ્ર ટ્રાન્સપોર્ટ કોર્પોરેશન તરફથી </span><span>₹</span><span>140 કરોડનો કોન્ટ્રાક્ટ</span></li><li><span>Mahindra Finance</span><span>નો નફો 3% વધીને </span><span>₹</span><span>530 કરોડ</span></li><li><span>TRAI</span><span>એ સ્પામ અને ફ્રોડ રોકવા </span><span>RBI, SEBI </span><span>સહિતની સંસ્થાઓ સાથે બેઠક કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ફાઇનાન્શિયલ એક્સપ્રેસ\r\n:</span></b></span></p>\r\n\r\n<ul><li><span>છેલ્લા </span><span>6</span><span> વર્ષમાં </span><span>DI</span><span>એ </span><span>FPI </span><span>કરતાં </span><span>7</span><span> ગણી વધુ મૂડી\r\nમૂકી: </span><span>SEBI</span></li><li><span>નવા </span><span>H-1B </span><span>નિયમો હેઠળ કૌશલ્ય અને પગાર આધારિત પસંદગી થશે</span></li><li><span>Axis Bank </span><span>પોતાની ઈન્સ્યોરન્સ કંપનીમાં વધુ </span><span>10%</span><span> હિસ્સો લેવા </span><span>RBI</span><span>ની મંજૂરી માંગશે</span></li><li><span>GST </span><span>દર ઘટાડવાનો કોઈ પ્રસ્તાવ નથી</span></li><li><span>FY23</span><span>માં દેવું ટકાઉ રહ્યું: </span><span>CAG</span></li><li><span>Syngenta </span><span>ભારતમાં નવા ઉત્પાદનો લાવશે</span></li><li><span>કેનેડાએ નાગરિકતા માટે નવો </span><span>Provincial Nominee Program </span><span>જાહેર કર્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>Meta</span><span>એ </span><span>Apple</span><span>ના બે </span><span>AI </span><span>સંશોધકોને $100 મિલિયન પેકેજમાં ભરતી કર્યા</span></li><li><span>જૂનમાં </span><span>FMCG </span><span>માર્કેટમાં\r\n4.6% વૃદ્ધિ</span><span>, </span><span>પીણાંઓમાં\r\nઘટાડો</span></li><li><span>IRFC</span><span>ના નફામાં 10% વધારો થઈ </span><span>₹</span><span>1,745 કરોડ</span></li><li><span>Zensar Tech</span><span>નો નફો 15.3% વધી </span><span>₹</span><span>182 કરોડ</span></li><li><span>JSW Infra</span><span>ના નફામાં 31% વૃદ્ધિ</span><span>, </span><span>આવકમાં 21% વધારો</span></li><li><span>Renee Cosmetics </span><span>નવી રોકાણકાર કંપનીઓ\r\nપાસેથી </span><span>₹</span><span>200 કરોડ ઊભું કરવા સંવાદમાં</span></li><li><span>2024માં નાગરિકોએ </span><span>₹</span><span>22,845 કરોડ સાઇબર ઠગીઓમાં ગુમાવ્યા</span></li><li><span>Mahanagar Gas</span><span>નો નફો 10% વધીને </span><span>₹</span><span>318 કરોડ</span></li><li><span>સરકારએ રેટિંગ એજન્સીઓ સાથે જોડાણ મજબૂત કર્યું</span></li><li><span>14 ક્ષેત્રોમાં </span><span>PLI </span><span>હેઠળ અત્યારસુધીમાં 806 અરજી મંજૂર</span></li><li><span>B L Kashyap &amp; Sons</span><span>એ 2 દિવસમાં </span><span>₹</span><span>1</span><span>,</span><span>067 કરોડના ઓર્ડર મેળવ્યા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEg3m1A79oU-pjjSlaxrmn1Zo0qoSnL9xDVddEEDIwK4YKlpstYX4j0dC6Gm3eWkgIuORohbHvLPFZsj4JBVui4pY0p1CZL0hEY-VC4jtz4J3_g6vcVJcJ_jGXkLK9N_vq9g-HvZ_bUyO2vcALvQk0QrN6MZAUXMTwt9xvPrsOKHz_qi-i-_PMWDw-cWFCA','2025-07-23','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(223,'6574684321847183625','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૨ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjxcuggSA8R8V92hBPdV-z9nPq2BnW1h2BLi_Vq8lMyImGGIdnpbzOPe-Xc7nBWht-Oy4bjxV2HW0k-X_t8zNlExJpBCREs94E5Y1_ME27JKPUEzErSEu5jySdjETcPg2SEVcGzuxNfBgmT-2EW4GYoGnF81esR23CsjuPUp4FKYRYtvEBrPy_Vs2PEook\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjxcuggSA8R8V92hBPdV-z9nPq2BnW1h2BLi_Vq8lMyImGGIdnpbzOPe-Xc7nBWht-Oy4bjxV2HW0k-X_t8zNlExJpBCREs94E5Y1_ME27JKPUEzErSEu5jySdjETcPg2SEVcGzuxNfBgmT-2EW4GYoGnF81esR23CsjuPUp4FKYRYtvEBrPy_Vs2PEook\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતે 48 ગિગાવોટ\r\nઈન્ટર-સ્ટેટ રિન્યુએબલ એનર્જી ટ્રાન્સમિશન નેટવર્ક પૂર્ણ કર્યું</span></li><li><span>ટાઈટન</span><span>દુબઈની</span><span>ડામાસ</span><span>કંપનીમાં</span><span>મેજોરિટી</span><span>હિસ્સો</span><span>ખરીદશે</span><span>,\r\n</span><span>283 મિલિયન ડોલરનું વેલ્યુએશન</span></li><li><span>બોનફિલિયોલી</span><span>ઇન્ડિયાની</span><span>યુનિટ</span><span>₹</span><span>250 </span><span>મિલિયનનું</span><span>IPO </span><span>લાવવાનું વિચારી રહી છે</span></li><li><span>સરકારએ</span><span>NTPC </span><span>ની સહાયક કંપની </span><span>THDC\r\n</span><span>અને </span><span>NEEPCO </span><span>ના બોર્ડનું\r\nપુનર્ગઠન મંજૂર કર્યું</span></li><li><span>ઝોમેટોની</span><span>પેરેન્ટ</span><span>કંપની</span><span>ઇટર્નલએ</span><span>નવા</span><span>ફૂડ</span><span>સર્વિસિસ</span><span>યુનિટ</span><span>Blinkit Foods </span><span>ની સ્થાપના કરી</span></li><li><span>સિગ્નેચર</span><span>ગ્લોબલ</span><span>ગુરુગ્રામમાં</span><span>જુલાઈથી</span><span>સપ્ટેમ્બર</span><span>વચ્ચે</span><span>₹</span><span>6,000 </span><span>કરોડના</span><span>નવા</span><span>હાઉસિંગ</span><span>પ્રોજેક્ટ</span><span>લાવશે</span></li><li><span>અબૂધાબી</span><span>ઇન્વેસ્ટમેન્ટ</span><span>ઓથોરિટી</span><span>માઇક્રો</span><span>લાઈફ</span><span>સાયન્સિસમાં</span><span>₹</span><span>200 </span><span>મિલિયનમાં</span><span> 3% </span><span>હિસ્સો</span><span>ખરીદશે</span></li><li><span>મારુતિ</span><span>સુઝુકી</span><span>FY</span><span>26માં 500 નવી\r\nસર્વિસ સેન્ટર શરૂ કરવાની યોજના બનાવી રહી છે</span></li><li><span>સન</span><span>ટીવી</span><span>બોર્ડે</span><span>ઇંગ્લેન્ડની</span><span>ટીમ</span><span>ધ</span><span>હન્ડ્રેડ</span><span>નોર્ધર્ન</span><span>સુપરચાર્જર્સને</span><span>£</span><span>100.5 </span><span>મિલિયનમાં</span><span>ખ</span><span>રીદવાનું મંજૂર કર્યું</span></li><li><span>સેઈલ</span><span>ઝોજિલા</span><span>ટનલ</span><span>માટે</span><span>સૌથી</span><span>વધુ</span><span> 31,000 </span><span>ટન</span><span>સ્ટીલ</span><span>સપ્લાય</span><span>કરશે</span></li><li><span>સાઉદી</span><span>અરેબિયાના</span><span>ક્રૂડ</span><span>તેલનો</span><span>નિકાસ</span><span>મે</span><span>મહિનામાં</span><span>ત્રણ</span><span>મહિનાના</span><span>ટોચના</span><span>સ્તરે</span></li><li><span>સરકારે</span><span>જણાવ્યું</span><span>કે</span><span>દેશમાં</span><span>અત્યાર</span><span>સુધીમાં</span><span>કુલ</span><span> 3.46 </span><span>કરોડ</span><span>સ્માર્ટ</span><span>ઇલેક્ટ્રિસિટી</span><span>મીટર</span><span>લગાડવામાં</span><span>આવ્યા</span><span>છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારત અને યુકે વચ્ચે વેપાર કરાર 24 જુલાઈએ થશે</span><span>; </span><span>પીયૂષ\r\nગોયલ વડાપ્રધાન મોદી સાથે જશે</span></li><li><span>એલ એન્ડ ટી ભારતનો સૌથી મોટો ગ્રીન હાઈડ્રોજન પ્લાન્ટ પાનિપત </span><span>IOCL </span><span>ખાતે સ્થાપશે</span></li><li><span>બ્રિગેડ હોટેલ વેન્ચર્સ </span><span>FY</span><span>28 સુધીમાં\r\n960 રૂમ ઉમેરશે</span><span>, </span><span>લક્ઝરી સેગમેન્ટ પર ફોકસ</span></li><li><span>સન ફાર્માના સોરિયાસિસ માટેના ડ્રગને આર્થ્રાઈટિસ ટ્રાયલમાં સકારાત્મક પરિણામો</span></li><li><span>ડોમિનોઝના </span><span>Q</span><span>2 યુએસ વેચાણ આંકડા અપેક્ષા કરતા વધુ</span><span>; </span><span>મેનૂ ડીલ્સ અને માંગનો ફાયદો</span></li><li><span>અલ્ટ્રાટેક સિમેન્ટ </span><span>Q</span><span>1</span><span> FY</span><span>26 પરિણામ: નફામાં 49% નો ઉછાળો</span><span>, </span><span>₹</span><span>2,226 કરોડ થયો</span></li><li><span>એડ્યુફંડે $6 મિલિયન સીરિઝ </span><span>A </span><span>ફંડિંગ\r\nમેળવ્યું</span><span>, </span><span>મેટ્રો સિવાય વિસ્તરણની યોજના</span></li><li><span>ડાયગ્નોસ્ટિક કંપની આરતી સ્કેન નોર્થ ઈન્ડિયા તરફ વધશે</span><span>, </span><span>₹</span><span>350 કરોડની મૂડી રોકાણ યોજના</span></li><li><span>વૈશ્વિક મંદી વચ્ચે ભારતનું વિસી ફંડિંગ $3.5 અબજ સુધી પહોંચી ગયું</span><span>, </span><span>ફિનટેક આગળ</span></li><li><span>ભારતીય ઈવી ઉત્પાદકો તરફથી એઆઈ અને હાઇ-પર્ફોર્મન્સ કમ્પ્યુટિંગ સોલ્યુશન\r\nઅપનાવવાથી મીડીટેકને મોટો ફાયદો</span></li><li><span>રિલાયન્સના ગ્રીન એનર્જી ક્ષેત્રમાં પ્રવેશથી એનાલિસ્ટ્સમાં આત્મવિશ્વાસ વધ્યો</span></li><li><span>રશિયા સાથે જોડાયેલા રિફાઈનરી નયારા એનર્જીએ વેચાણ શરતો કડક કરી</span><span>, </span><span>અગાઉ ચુકવણીની માંગણી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતનું કોર સેક્ટર આઉટપુટ જૂનમાં 1.7% જેટલું વધ્યું</span></li><li><span>ભારતમાં કુલ </span><span>GCC (</span><span>ગ્લોબલ કેપેબિલિટી સેન્ટર) માંથી લગભગ 55% બેંગલુરુ</span><span>, </span><span>હૈદરાબાદ અને ચેન્નઈમાં સ્થિત: વેસ્ટિયન</span></li><li><span>ઇક્વિટાસ સ્મોલ ફાઇનાન્સ બેંક </span><span>₹</span><span>500 કરોડ </span><span>NCD </span><span>દ્વારા ફંડ ઉઠાવશે</span></li><li><span>રિપોર્ટ મુજબ રાષ્ટ્રીય સુરક્ષા માટે ભારતને </span><span>AI </span><span>ક્ષેત્રે સક્રિય સરકારે ટેકો આપવો જોઈએ</span></li><li><span>ઇટર્નલ </span><span>Q</span><span>1 પરિણામ: ઝોમેટોનો </span><span>PAT </span><span>90% ઘટી </span><span>₹</span><span>25 કરોડ થયો</span></li><li><span>ખેડૂતો સરકારે ક્રેડિટ સ્કોરને ખેતી લોન સાથે જોડવાનું આદેશ પાછું ખેંચવા માંગ\r\nકરી</span></li><li><span>IDBI </span><span>બેંક </span><span>Q</span><span>1 પરિણામ: નફામાં 17%નો વધારો</span><span>, </span><span>₹</span><span>2,007 કરોડ થયો</span></li><li><span>ચીનનું કહેવું છે કે વેલ્સ ફાર્ગોના બેન્કર ગુનાહિત કેસમાં સંડોવાયેલા</span></li><li><span>યુકૉ બેંક </span><span>Q</span><span>1 પરિણામ: નફામાં 10%નો વધારો</span><span>, </span><span>₹</span><span>607 કરોડ થયો</span><span>, NII </span><span>માં 7% વૃદ્ધિ</span></li><li><span>કેપ્ટન ફ્રેશ </span><span>IPO </span><span>માટે ઓગસ્ટ મધ્ય સુધીમાં કાગળ ફાઈલ કરશે</span><span>, </span><span>$50-75 મિલિયન પ્રી-</span><span>IPO </span><span>રાઉન્ડ લાવશે</span></li><li><span>CAG </span><span>રિપોર્ટમાં ભારતીય રેલવેમાં </span><span>₹</span><span>573 કરોડની અનિયમિતતાઓ ઉઘારી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjxcuggSA8R8V92hBPdV-z9nPq2BnW1h2BLi_Vq8lMyImGGIdnpbzOPe-Xc7nBWht-Oy4bjxV2HW0k-X_t8zNlExJpBCREs94E5Y1_ME27JKPUEzErSEu5jySdjETcPg2SEVcGzuxNfBgmT-2EW4GYoGnF81esR23CsjuPUp4FKYRYtvEBrPy_Vs2PEook','2025-07-22','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(224,'1382689840071564329','Research Report : Indian Financial Markets Outlook - 22th July 2025',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhFyGz7aHoyVoemTiHF-6IZHbhNKXq0P_NL7Y7QBZMeTtmrSUAhLUjUGGIW2e6JcHQG3pQWZ3WgbaZdPHHPcS9gpgaF0PYaNCFdMOiVwYVthCmeXbdI9L5WUYFENRSNSFW_9KczmjS7R8Jz0ofUwak4xRZxmigcsYFZ-NdApQ9oMOJc3e-0wX-sFaCKFE0\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhFyGz7aHoyVoemTiHF-6IZHbhNKXq0P_NL7Y7QBZMeTtmrSUAhLUjUGGIW2e6JcHQG3pQWZ3WgbaZdPHHPcS9gpgaF0PYaNCFdMOiVwYVthCmeXbdI9L5WUYFENRSNSFW_9KczmjS7R8Jz0ofUwak4xRZxmigcsYFZ-NdApQ9oMOJc3e-0wX-sFaCKFE0\" width=\"240\" /></a></b></div><div style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Markets\r\nremain in positive territory in absence of Trump tariff threats</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhkS1my_8SOpJBBW8WNiqH0q1Ymo5pKUnLbvZ0WlU9kigs11vqojuI3_Hzi_P7xe5-x7mGNED5bfcFus5zGGEGlif2SR-AUgrP6k4Vsz0I7I-LnQw_tEzsRjzhdLttpmjy2FoObCDPAQhdZ3FcKqo54RytYGdS61oPVPqUknm43zqmscTUMaKRWP2P8UdQ\"><img alt=\"\" height=\"311\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhkS1my_8SOpJBBW8WNiqH0q1Ymo5pKUnLbvZ0WlU9kigs11vqojuI3_Hzi_P7xe5-x7mGNED5bfcFus5zGGEGlif2SR-AUgrP6k4Vsz0I7I-LnQw_tEzsRjzhdLttpmjy2FoObCDPAQhdZ3FcKqo54RytYGdS61oPVPqUknm43zqmscTUMaKRWP2P8UdQ=w547-h311\" width=\"547\" /></a></div><p style=\"text-align:justify;\"><span>Asian\r\nPacific stocks posted a modest gain with Japanese markets staging a relief\r\nrally after Prime Minister Shigeru Ishiba said he would carry on as leader even\r\nafter the ruling coalition lost its majority in the upper house election. The\r\nMSCI regional stock gauge advanced 0.1% after the S&amp;P 500 index closed\r\nabove 6,300 for the first time. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>US\r\nstocks reached new record highs on Monday, propelled by a busy earnings week\r\nfeaturing upcoming quarterly reports from big names like Tesla Inc. and\r\nAlphabet Inc the GIFT Nifty gained over 95 points to 25,184 in the morning,\r\nindicating a higher start for the benchmark Nifty 50. Oil was little changed\r\nafter two modest declines as talks between the US and its trading partners gain\r\nurgency ahead of next week’s deadline. International benchmark Brent traded\r\nnear $69 a barrel while West Texas Intermediate was around $67.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">PNB Housing Finance</span></b><b><span> -</span></b><span> Q1FY26\r\n(YoY) Net interest income up 16% to Rs 733.57 crore versus Rs 631.25 crore. Net\r\nProfit down 6.2% at Rs 531.73 crore versus Rs 567.11 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">CIE Automotive -</span></b><span> Q1FY26 (YoY) Revenue up 3.3% at Rs\r\n2,369 crore versus Rs 2,293 crore. Ebitda down 6.4% at Rs 337 crore versus Rs\r\n360 crore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Oberoi Realty -</span></b><span> Q1FY26 (YoY) Revenue down 29.7% at\r\nRs 988 crore versus Rs 1,405 crore. Ebitda down 36.2% at Rs 520 crore versus Rs\r\n815 crore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Havells India -</span></b><span> Q1FY26 (YoY) Revenue down by 6% at\r\nRs. 5,455 crores versus Rs. 5,806 crores EBITDA down 9.9% At Rs. 516 crores\r\nversus Rs. 572 crores. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><div><span style=\"color:#FF0000;\">Technical Update</span></div>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty took a support at 50 day EMA\r\nand jumped over 25K to settle at 25,090 on Monday. Index is facing resistance\r\nat 17 day EMA of 25,200 while 25K is near term support. Today’s range – 25,000\r\n– 25,250.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty gained over 500 points on\r\nknee jerk reaction after better than expected results from top private lenders.\r\nIndex settled above 17 day EMA at 56,952 on Monday. Index has resistance at\r\n57,250 in the near future. Today’s range – 56,800 – 57,250.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhFyGz7aHoyVoemTiHF-6IZHbhNKXq0P_NL7Y7QBZMeTtmrSUAhLUjUGGIW2e6JcHQG3pQWZ3WgbaZdPHHPcS9gpgaF0PYaNCFdMOiVwYVthCmeXbdI9L5WUYFENRSNSFW_9KczmjS7R8Jz0ofUwak4xRZxmigcsYFZ-NdApQ9oMOJc3e-0wX-sFaCKFE0','2025-07-22','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(225,'3049703411160448064','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૧ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgFxBsY8juJwlDvo5jlyqR2Rgzfc_h3IxrzZRSFCsyfElhKLbOb6LQCYqDJpsAIHPWOXHvkFhdohA37zSz_N0iUoGzhaoUVlk1N2N5xesPWdwMhxUrNZOzV2ufcyy4wSOJ7PZL1TdrZjyLXC3CERUx6ejQ1Mf2VgFu82BGxXofX8F8GvXGSED2dYx0U9Wk\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgFxBsY8juJwlDvo5jlyqR2Rgzfc_h3IxrzZRSFCsyfElhKLbOb6LQCYqDJpsAIHPWOXHvkFhdohA37zSz_N0iUoGzhaoUVlk1N2N5xesPWdwMhxUrNZOzV2ufcyy4wSOJ7PZL1TdrZjyLXC3CERUx6ejQ1Mf2VgFu82BGxXofX8F8GvXGSED2dYx0U9Wk\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>JSW </span><span>પેઇન્ટ્સે અક્ઝો\r\nનોબેલ ઈન્ડિયામાં </span><span>₹</span><span>12,915 </span><span>કરોડ</span><span>માટે</span><span>મોટા</span><span>હિસ્સાની</span><span>ખરીદી</span><span>માટે</span><span>CCI</span><span>ની મંજૂરી માંગી</span></li><li><span>સિગ્નેચર</span><span>ગ્લોબલ</span><span>જુલાઈ</span><span>-</span><span>સપ્ટેમ્બર</span><span>દરમિયાન</span><span>ગુરુગ્રામમાં</span><span>₹</span><span>6,000 </span><span>કરોડના</span><span>મકાનો</span><span>લોન્ચ</span><span>કરશે</span><span>: </span><span>ચેરમેન</span></li><li><span>ડૉ</span><span>. </span><span>રેડ્ડી</span><span>ને</span><span>USFDA </span><span>તરફથી આંધ્ર પ્રાંતમાં આવેલા પ્લાન્ટ માટે સાત ઓબ્ઝર્વેશન\r\nમળ્યાં</span></li><li><span>નવી</span><span>રશિયન</span><span>પ્રતિબંધોની</span><span>પૃષ્ઠભૂમિમાં</span><span>યુરોપિયન</span><span>યૂનિયન</span><span>માટે</span><span>ભારતના</span><span>₹</span><span>15 </span><span>હજાર</span><span>કરોડના</span><span>તેલ</span><span>નિકાસ</span><span>જોખમમાં</span></li><li><span>ઇન્ડિયન</span><span>ઓવરસીઝ</span><span>બેંકે</span><span>કહ્યું</span><span>કે</span><span>તેઓ</span><span>ચાલુ</span><span>નાણાકીય</span><span>વર્ષમાં</span><span>₹</span><span>1,000 </span><span>કરોડથી</span><span>વધુ</span><span>નફો</span><span>જાળવી</span><span>રાખવા</span><span>માટે</span><span>આત્મવિશ્વાસી</span></li><li><span>કલ્પતરુની\r\nપ્રીસેલ્સમાં </span><span>FY</span><span>25 દરમિયાન 41%નો ઉછાળો – મકાનની માંગમાં વધારો</span></li><li><span>બાંગ્લાદેશ</span><span>દ્વારા</span><span> 9 </span><span>લાખ</span><span>ટન</span><span>ભાત</span><span>આયાતના</span><span>યોજના</span><span>અંગે</span><span>ભારતીય</span><span>મિલર્સ</span><span>અને</span><span>નિકાસકર્તાઓ</span><span>આશાવાદી</span></li><li><span>આશોક</span><span>લેલેન્ડ</span><span>નવા</span><span>ઉદ્યોગ</span><span>પ્રવાહોને</span><span>ધ્યાનમાં</span><span>રાખીને</span><span>આગોતરા</span><span>દૃષ્ટિકોણ</span><span>અપનાવવા</span><span>માંગે</span><span>છે</span><span>: </span><span>ચેર</span><span>મેન હિંદુજા</span></li><li><span>FY</span><span>26માં ડબલ ડિજિટ\r\nવૃદ્ધિની અપેક્ષા</span><span>, </span><span>ગ્રામ્ય રિપ્લેસમેન્ટ માર્કેટ વેચાણને આગળ\r\nધપાવશે: </span><span>CEAT</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>બ્રિગેડ હોટેલ વેન્ચર્સ 24 જુલાઈએ </span><span>₹</span><span>749.6 કરોડનો </span><span>IPO </span><span>લાવશે</span></li><li><span>બાંગ્લાદેશ દ્વારા 9 લાખ ટન ભાત આયાત કરવાના આયોજનથી ભારતીય નિકાસકર્તાઓ આશાવાદી</span></li><li><span>ટેસ્લાનો ભારતમાં પ્રવેશ </span><span>EV </span><span>ઇન્શ્યોરન્સ\r\nક્ષેત્રે નવીનતા લાવશે</span></li><li><span>અઝરબૈજાનની </span><span>SOFAZ </span><span>એ એન્ફિનિટીના ઇટાલી સોલાર\r\nએસેટ્સમાં 49% હિસ્સો ખરીદવાનો નિર્ણય લીધો</span></li><li><span>રિલાયન્સ કન્સ્યુમર પ્રોડક્ટ્સ મજબૂત વૃદ્ધિના માર્ગ પર: રિલાયન્સ રિટેલના </span><span>CFO</span></li><li><span>યુએસ</span><span>, </span><span>યુએઈ અને ચીન તરફી માંગને લીધે એપ્રિલ-જૂન ત્રિમાસિકમાં\r\nઇલેક્ટ્રોનિક્સની નિકાસમાં 47%નો ઉછાળો</span></li><li><span>ખાનગી બેંકો માટે </span><span>Q</span><span>1માં રિટેલ\r\nલોન વૃદ્ધિ ધીમી</span><span>, </span><span>તહેવારના સમયે માંગ વધવાની આશા</span></li><li><span>ઓઇલ રેગ્યુલેટરે સિટી ગેસ કંપનીઓ પર કાર્યવાહી કરી</span><span>; </span><span>પાઇપલાઇન\r\nગેસ માટે એકસમાન ભાવની માંગ</span></li><li><span>વૈશ્વિક પડકારો છતાં જાન્યુઆરીથી જૂન વચ્ચે </span><span>IPO </span><span>દ્વારા </span><span>₹</span><span>45</span><span>,</span><span>350 કરોડનું ફંડ રેઇઝિંગ</span><span>, </span><span>45%નો\r\nઉછાળો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ટાટા કમ્યુનિકેશન્સે ખાનગી </span><span>5G </span><span>દિશામાં ફરીથી\r\nઝુંબેશ શરૂ કરી</span></li><li><span>સોના કોમસ્ટાર ચીનના </span><span>EV </span><span>પાર્ટ્સ\r\nમાર્કેટમાં પ્રવેશ કર્યો - ટેરિફ અને રેયર અર્થ મેટલ્સના પડકાર વચ્ચે</span></li><li><span>વેદાંતે વાયસરોય રિસર્ચના </span><span>₹</span><span>2,500</span><span> કરોડના લોન રાઉટિંગના દાવાને નકાર્યો</span></li><li><span>ભારતના ખાંડના નિકાસ </span><span>700,000</span><span> ટન\r\nસુધી પહોંચી</span></li><li><span>સેબી એ જૂન મહિનામાં </span><span>SCORES </span><span>પોર્ટલ\r\nદ્વારા લગભગ </span><span>4,500</span><span> ફરિયાદો ઉકેલી</span></li><li><span>હોન્ડાનો લક્ષ્યાંક – </span><span>2030</span><span> સુધી ભારતના\r\nટૂ-વ્હીલર માર્કેટમાં </span><span>30%</span><span> હિસ્સો\r\nમેળવવાનો</span></li><li><span>ચીનની </span><span>EV </span><span>બ્રાન્ડ ઝીકર અને નેટા એ ઇન્શ્યોરન્સ સ્કીમનો ઉપયોગ કરીને\r\nકાર વેચાણના આંકડા ફુલાવ્યા</span></li><li><span>5G </span><span>નેટવર્ક સ્લાઇસિંગ પેટન્ટની નામંજૂરી સામે નોકિયાએ હાઈકોર્ટનો દરવાજો ખખડાવ્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgFxBsY8juJwlDvo5jlyqR2Rgzfc_h3IxrzZRSFCsyfElhKLbOb6LQCYqDJpsAIHPWOXHvkFhdohA37zSz_N0iUoGzhaoUVlk1N2N5xesPWdwMhxUrNZOzV2ufcyy4wSOJ7PZL1TdrZjyLXC3CERUx6ejQ1Mf2VgFu82BGxXofX8F8GvXGSED2dYx0U9Wk','2025-07-21','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(226,'3129976720950040995','Nifty Outlook :- 21.07.2025 - CFA Hitesh Somani',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjwTnIqxJ5RZef7lLuRJEcy58K8BwbfbWAg9qDcnXS1BpBfPkVT5eYog7rT5gDujLZk948m6YRWQmQOSdlyAq6eY3NgTGGzCY5mb1qKufjYh8a-KUNK4iuxcMi0fyQW5dh4ECgHm_s-s9ZNvVqb9SDR8o4sAJzVERJh6hh9SdkTgvOKTu5eFunt_xGpqxg\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjwTnIqxJ5RZef7lLuRJEcy58K8BwbfbWAg9qDcnXS1BpBfPkVT5eYog7rT5gDujLZk948m6YRWQmQOSdlyAq6eY3NgTGGzCY5mb1qKufjYh8a-KUNK4iuxcMi0fyQW5dh4ECgHm_s-s9ZNvVqb9SDR8o4sAJzVERJh6hh9SdkTgvOKTu5eFunt_xGpqxg\" width=\"255\" /></a></b></div><div style=\"text-align:center;\"><b><span>CFA Hitesh Somani<br /></span></b><b><span style=\"color:#000000;\">MD - Aapka Investments <br /></span></b><b><span style=\"color:#000000;\">\r\nWebsite - https://www.aapkainvestments.in</span></b></div>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Market\r\nhas fallen by approximately 200 points — will it recover or continue in the\r\nsame trend next week?\"</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>On\r\na daily basis, Nifty was flat during the first three days, but in the last two\r\ndays, it fell by approximately 200 points. On the weekly chart, we can see the\r\nthird consecutive bearish candle this week, which indicates that investors are\r\nstill booking profits. Last week, Nifty closed at 25,150, and this Friday it\r\nclosed at 24,968.40 — down by 181 points. Since Nifty has already broken the\r\n25,200 level, we might witness a sharp fall. However, if Nifty moves back to\r\nthe 25,200 level, we can hope for a recovery.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>According\r\nto the previous week, Bank Nifty was weak. This week, compared to Nifty, Bank\r\nNifty fell by 471 points in the last two days of the week. Last week, Bank\r\nNifty closed at 56,754.70, and this Friday it closed at 56,283 — which is a\r\nfall of almost 471 points.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n<ul><li><span><b>Major\r\nSupport Levels for Nifty</b></span><ul><li><ul><li><span>Support\r\n1 – 24700</span></li><li><span>Support\r\n2 – 24500</span></li><li><span>Support\r\n3 – 24300</span></li></ul></li></ul></li></ul><ul style=\"text-align:left;\"><li><span><b>Major\r\nResistance Levels for Nifty</b></span><ul><li><ul><li><span>Resistance\r\n1 – 25300</span></li><li><span>Resistance\r\n2 – 25600</span></li><li><span>Resistance\r\n3 – 25900</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<ul><li><span><b>Major\r\nSupport Levels for Banknifty</b></span><ul><li><ul><li><span>Support\r\n1 – 56000</span></li><li><span>Support\r\n2 – 55500</span></li><li><span>Support\r\n3 – 53900</span></li></ul></li></ul></li></ul><ul><li><span><b>Major\r\nResistance Levels for Banknifty</b></span><ul><li><ul><li><span>Resistance\r\n1 – 56700</span></li><li><span>Resistance\r\n2 – 57400</span></li><li><span>Resistance\r\n3 – 58000 </span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>1)\r\nINDHOTEL</span></b></p>\r\n\r\n<div style=\"text-align:justify;\"><span>CMP @ 765<br /></span><span>Buy Above @ 770<br /></span><span>Stop Loss Below @ 720<br /></span><span>Targets @ 800, 840 and 910</span></div><p style=\"text-align:justify;\"><span>\r\n<b>2) MAHLIFE</b></span></p>\r\n\r\n<div style=\"text-align:justify;\"><span>CMP @ 380<br /></span><span>BUY ABOVE @ 388<br /></span><span>STOP LOSS @ 350<br /></span><span>TARGETS @ 400, 430 and 450</span></div>\r\n\r\n<p style=\"text-align:justify;\"><b><span>3)\r\nHCLTECH</span></b></p>\r\n\r\n<div style=\"text-align:justify;\"><span>CMP @ 1540<br /></span><span>BUY ABOVE @ 1550<br /></span><span>STOP LOSS @ 1500<br /></span><span>TARGETS @ 1580, 1620 and 1650</span></div>','https://blogger.googleusercontent.com/img/a/AVvXsEjwTnIqxJ5RZef7lLuRJEcy58K8BwbfbWAg9qDcnXS1BpBfPkVT5eYog7rT5gDujLZk948m6YRWQmQOSdlyAq6eY3NgTGGzCY5mb1qKufjYh8a-KUNK4iuxcMi0fyQW5dh4ECgHm_s-s9ZNvVqb9SDR8o4sAJzVERJh6hh9SdkTgvOKTu5eFunt_xGpqxg','2025-07-19','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(227,'8606944441721958550','Research Report : Indian Financial Markets Outlook - 18th July 2025',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhVCpC_mlP8X0nYEEP5NAiaGVvbJw5NvwEjGv7puzkSWKuFGHR7v1TbyFsQqP6tngfw_ypB8QN9DoNTnPAeBRatSAUzEMZxaXdBRbvHstEVV_qifw9jn0cSccoMz6_1JOe9O3Hy_HPVt8bM3pOFECAi6bdgK2G9PDElerIsllmLhEeDCsK1aKhVjWAVvU4\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhVCpC_mlP8X0nYEEP5NAiaGVvbJw5NvwEjGv7puzkSWKuFGHR7v1TbyFsQqP6tngfw_ypB8QN9DoNTnPAeBRatSAUzEMZxaXdBRbvHstEVV_qifw9jn0cSccoMz6_1JOe9O3Hy_HPVt8bM3pOFECAi6bdgK2G9PDElerIsllmLhEeDCsK1aKhVjWAVvU4\" width=\"240\" /></a></b></div><h2 style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b></h2><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span>\r\n\r\n<p><span style=\"color:#FF0000;\">Better\r\nthan expected US economic data lifts market sentiments</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjRvupfhIoBbX-yAn7JGoIl9Wf7jDCsLsMFDWpRwCRL54FamSe79PJpnyMea5LaVPKIozz0DPB5Kqe1xJpvLmNo_oMjgaAvPnvE7R2Qvlq0nzbQAYgOyjTdn-Y2SGb01wNJjeQNw_itRHCEibHaIqeIAAyGCfr6eCqR3AhulZZzr7smMP8bR5R5e7_xC6o\"><img alt=\"\" height=\"339\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjRvupfhIoBbX-yAn7JGoIl9Wf7jDCsLsMFDWpRwCRL54FamSe79PJpnyMea5LaVPKIozz0DPB5Kqe1xJpvLmNo_oMjgaAvPnvE7R2Qvlq0nzbQAYgOyjTdn-Y2SGb01wNJjeQNw_itRHCEibHaIqeIAAyGCfr6eCqR3AhulZZzr7smMP8bR5R5e7_xC6o=w593-h339\" width=\"593\" /></a></div><p style=\"text-align:justify;\"><span>In\r\nthe morning session, Asian Pacific stocks made a modest gain on Friday as a\r\nglobal equity rally gained fresh boost on strong economic data that eased\r\nconcerns about the US economy. The MSCI Asia Pacific Index rose 0.2% at the\r\nopen. Equity-index futures for US gained after the S&amp;P 500 and Nasdaq 100\r\nset closing new highs Thursday. Tech stocks rose as a bullish outlook from\r\nTaiwan Semiconductor Manufacturing Co. bolstered confidence in AI spending. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty was trading near 25,200 during early morning on Friday. The futures\r\ncontract based on the benchmark Nifty 50 rose 0.20% at 25,190 indicating a\r\nstart in green for the Indian markets. India\'s benchmark equity indices pulled\r\nback on Thursday after two days of gains, weighed by heavyweights Infosys Ltd.\r\nand HDFC Bank Ltd. Global benchmark Brent crude oil traded above $69 a barrel\r\nafter advancing by more than 1% in the previous session, while West Texas\r\nIntermediate was near $67.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Jio Financial Services -</span></b><span> Q1FY26\r\n(YoY) Net Profit up 3.8% to Rs 325 crore versus Rs 313 crore. Total Income up\r\n48.3% at Rs 619 crore versus Rs 418 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Axis Bank</span></b><span> - Q1FY26 (YoY) NII up 1% to Rs\r\n13,560 crore versus Rs 13,448 crore. Net Profit down 3.8% to Rs 5,806 crore\r\nversus Rs 6,035 crore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Wipro -</span></b><span> Q1FY26 (QoQ) Revenue down 1.65% to\r\nRs 22,134 crore versus Rs 22,504.2 crore. EBIT decreased 9.09% to Rs 3,548\r\ncrore versus Rs 3,902 crore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#006600;\">LTIMindtree -</span></b><span> Q1FY26 (QoQ) Revenue 0.7% up at Rs\r\n9,840.60 crore versus Rs 9,771.70 crore. EBIT up 5% to Rs 1,406.50 crore versus\r\nRs 1,345.40 crore. <span style=\"color:#006600;\">Neutral </span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY - </span></b><span>Nifty could not continue momentum\r\nand slipped below 25,200 to settle at 25,111 on Thursday. Index is facing\r\nresistance at 17 day EMA of 25,250 while 25K is near term support. Today’s\r\nrange – 25,050 – 25,250. </span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY - </span></b><span>Bank nifty too slipped below 57K to\r\nclose at 56,828 on Thursday. Index closed tad below 17 day EMA of 56,850 while\r\n57,250 is near term resistance. Today’s range – 56,550 – 57,250.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhVCpC_mlP8X0nYEEP5NAiaGVvbJw5NvwEjGv7puzkSWKuFGHR7v1TbyFsQqP6tngfw_ypB8QN9DoNTnPAeBRatSAUzEMZxaXdBRbvHstEVV_qifw9jn0cSccoMz6_1JOe9O3Hy_HPVt8bM3pOFECAi6bdgK2G9PDElerIsllmLhEeDCsK1aKhVjWAVvU4','2025-07-18','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(228,'532286849674043782','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૮ જુલાઇ ૨૦૨૫',NULL,'<h2 style=\"text-align:center;\"></h2><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEj4hiuKtl649ZBG9hef8z238iSO14GUdin0EhWXX5SUSpTTPIU1FXROcOORVerc01XfESlMzYM6fSpffcVAyqY8Yv0HtRw9cQjPf1QDvFO9wTV_EchqIqkaNDpv4FmKeYFcY10l7kYFbCeQGnbz5ssluRxWgcJ_1Qu7dQtMVafsDcedaL_5OnR5jBU5emM\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEj4hiuKtl649ZBG9hef8z238iSO14GUdin0EhWXX5SUSpTTPIU1FXROcOORVerc01XfESlMzYM6fSpffcVAyqY8Yv0HtRw9cQjPf1QDvFO9wTV_EchqIqkaNDpv4FmKeYFcY10l7kYFbCeQGnbz5ssluRxWgcJ_1Qu7dQtMVafsDcedaL_5OnR5jBU5emM\" width=\"281\" /></a></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">સંકલન :</span></b><b><span style=\"color:#0000FF;\">-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>Jaguar Land Rover </span><span>સમર્થિત બેટરી રીસાયકલિંગ પ્રોજેક્ટને </span><span>UK </span><span>સરકાર તરફથી નાણાંકીય સહાય</span></li><li><span>HAL </span><span>એક્સેસરીઝના\r\nનિકાસમાંથી આવક વધારવાનું આયોજન કરે છે: અધિકારી</span></li><li><span>ભારતના</span><span>માલની</span><span>નિકાસને</span><span> 2026</span><span>માં</span><span>પડકારોનો</span><span>સામનો</span><span>કરવો</span><span>પડી</span><span>શકે</span><span>છે</span><span>: </span><span>CRISIL</span></li><li><span>WeWork India </span><span>₹</span><span>3,500 </span><span>કરોડના</span><span>IPO </span><span>માટે માર્કેટિંગ શરૂ કરશે</span></li><li><span>વિલમાર</span><span>ઈન્ટરનેશનલ</span><span>એડાની</span><span>જૂથ</span><span>પાસેથી</span><span> 20% </span><span>હિસ્સો</span><span>ખરીદી</span><span>AWL </span><span>એગ્રી બિઝનેસમાં મોટાભાગનો હિસ્સો મેળવ્યો</span></li><li><span>Everta </span><span>2027 સુધીમાં દર\r\nવર્ષે 3,000</span><span> DC </span><span>ચાર્જર સ્થાનિક રીતે બનાવવાની યોજના ધરાવે છે</span></li><li><span>સેબી</span><span>સોનાં</span><span> અને ચાંદીના </span><span>ETF</span><span>ના મૂલ્યાંકન પદ્ધતિમાં સમરસતા લાવવા માટે\r\nસૂચન કરે છે</span></li><li><span>પૉલિકૅબ</span><span>Q</span><span>1 પરિણામ: નફો 50% વધીને </span><span>₹</span><span>592 </span><span>કરોડ</span><span>પર</span><span>, </span><span>આવકમાં 26% વૃદ્ધિ</span></li><li><span>Zuperia Auto </span><span>ઇલેક્ટ્રિક\r\nપેસેન્જર ત્રણ પૈદાની બજારમાં પ્રવેશી</span><span>, </span><span>2 વર્ષમાં 2-વ્હીલર બજારમાં પ્રવેશ કરવાની\r\nયોજના</span></li><li><span>યુનાઇ</span><span>ટેડ બ્રૂઅરીઝ રાજ્ય સરકારો સાથે સમાન કર નીતિ માટે કાર્યરત</span></li><li><span>તાઇવાનના</span><span>બેંકો</span><span>ભારતમાં</span><span>તેમની</span><span>શાખાઓ</span><span>વિસ્તારવા</span><span>માંગે</span><span>છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>ONGC </span><span>ગુજરાતના જામનગરમાં નવી 2,00,000-2,40,000</span><span> BPD </span><span>રિફાઈનરી\r\nસ્થાપવાની યોજના બનાવી રહી છે</span></li><li><span>ભારત અને યુકે આગામી સપ્તાહે સમીક્ષા બાદ મુક્ત વેપાર કરાર પર હસ્તાક્ષર કરવાની\r\nસંભાવના</span></li><li><span>ભારતે રશિયન તેલ ખરીદવાનું ચાલુ રાખવું જોઈએ</span><span>; </span><span>અમેરિકન દબાણનો ઇનકાર કરવો જોઈએ: </span><span>GTRI</span></li><li><span>IRDAI </span><span>કિવી ઈન્સ્યોરન્સની રિટેલ હેલ્થ પોલિસીઓ પર પ્રમોટર જોડાણને\r\nકારણે કડક પગલાં લઈ શકે છે</span></li><li><span>IPO </span><span>પછી ઑફિસ માંગ વધતાં </span><span>Smartworks </span><span>એ 35% વાર્ષિક વૃદ્ધિનો લક્ષ્યાંક રાખ્યો</span></li><li><span>મોંસૂન વહેલો આવતાં રાજસ્થાનમાં પર્યટન ક્ષેત્રમાં તેજી આવી: ઉદ્યોગ જાણકાર</span></li><li><span>ઉત્તર પ્રદેશ સરકારે </span><span>₹</span><span>3.44 ટ્રિલિયનનો નાગરિક પાયાભૂત\r\nઢાંચો ખર્ચ ઘોષિત કર્યો</span></li><li><span>ઓફિસ રિયલ એસ્ટેટમાં નેટ લીઝિંગ </span><span>FY</span><span>26 સુધીમાં ઓલ ટાઈમ હાઈ પહોંચી શકે છે: </span><span>Crisil</span></li><li><span>ટાટા ઈલેક્ટ્રોનિક્સ અને બૉશ વચ્ચે સેમિકન્ડક્ટર અને ઓટો ટેક માટે સહકાર કરાર</span></li><li><span>લોહતત્મ ધાતુ આયાત </span><span>JSW </span><span>સ્ટીલની માંગ અને કિંમતો ઘટતાં વધવાની શક્યતા</span></li><li><span>DLF </span><span>મુંબઈમાં હાઉસિંગ પ્રોજેક્ટમાં </span><span>₹</span><span>900 કરોડનું રોકાણ કરશે</span><span>; </span><span>₹</span><span>2,300 કરોડની આવકની અપેક્ષા</span></li><li><span>ભારતમાં દરરોજ થર્મલ પાવર ઉત્પાદન 62%ની ઐતિહાસિક નીચી સપાટીએ પહોંચી ગયું</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતમાં હરિત ઢાંચાની તેજી નિકાસ માટે નવી તક ઊભી કરી શકે છે: મેક્વેરીના ડૂલી</span></li><li><span>TSMC</span><span>એ </span><span>2025</span><span> માટે આશાઓ વધારી </span><span>AI</span><span>ની\r\nમાંગ માટે મોટો ધક્કો આપ્યો</span></li><li><span>પવન ઉદ્યોગે સરકારે મુખ્ય ઘટકોના તબક્કાવાર સ્થાનિકીકરણની માગ ઉઠાવી</span></li><li><span>વૉલ્ટ ડિઝ્નીએ હૉંગકોંગની કંપની સામે ગેરકાયદેસર મિકી માઉસ દાગીના વેચાણ બદલ\r\nકેસ કર્યો</span></li><li><span>Waaree Renewable Tech Q1</span><span> પરિણામ: નફો </span><span>207%</span><span> વધીને </span><span>₹</span><span>86</span><span> કરોડ થયો</span></li><li><span>ભારતે રશિયન તેલ પર સંભવિત અમેરિકી પ્રતિબંધોની ચિંતા નથી: મંત્રી</span></li><li><span>Uniphore Technologies $250</span><span> મિલિયન સુધી ફંડ ઉપાડવા માટે ચર્ચામાં</span></li><li><span>HDFC AMC Q1</span><span> નફો </span><span>24%</span><span> વધીને </span><span>₹</span><span>748</span><span> કરોડ</span><span>, </span><span>કુલ આવક </span><span>26.5%</span><span> વધી</span></li><li><span>ઇન્ડોનેશિયા જેટ અને ખનિજ મુદ્દે ભારત સાથે ચર્ચા ચાલુ રાખશે</span></li><li><span>ઝોહોએ </span><span>Zia LLM </span><span>લોન્ચ કર્યું</span><span>, </span><span>જેમાં\r\nસ્પીચ-ટૂ-ટેક્સ્ટ મોડેલ અને </span><span>AI </span><span>એજન્ટ\r\nમાર્કેટપ્લેસ શામેલ છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEj4hiuKtl649ZBG9hef8z238iSO14GUdin0EhWXX5SUSpTTPIU1FXROcOORVerc01XfESlMzYM6fSpffcVAyqY8Yv0HtRw9cQjPf1QDvFO9wTV_EchqIqkaNDpv4FmKeYFcY10l7kYFbCeQGnbz5ssluRxWgcJ_1Qu7dQtMVafsDcedaL_5OnR5jBU5emM','2025-07-18','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(229,'8640310988984905422','Research Report : Indian Financial Markets Outlook - 17th July 2025',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhARuIHJPrz91mS3oE-O9RUETzUeqVcKmZQGTkM064VHZYLQ-_pWa-h5fOa6BHcmAewRYnretHif-bgiXsowyYuwEZtx81g56pCBd9NToB70qEdbQoFypvfCR2m_awYllgdzshOs8b-LSVv326wKVAX1d90IfwbAB1jB9OJXMSHWpE5KwcmbpIk0WhINQE\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhARuIHJPrz91mS3oE-O9RUETzUeqVcKmZQGTkM064VHZYLQ-_pWa-h5fOa6BHcmAewRYnretHif-bgiXsowyYuwEZtx81g56pCBd9NToB70qEdbQoFypvfCR2m_awYllgdzshOs8b-LSVv326wKVAX1d90IfwbAB1jB9OJXMSHWpE5KwcmbpIk0WhINQE\" width=\"240\" /></a></div><br /> <b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">India\r\nclose to signing trade deal with US, Trump is optimistic</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiwJmxgwL07ujCuc-zDA7j3vqIOhqlwfoLiSRg1KisdHj1u6VcbrOozfPMVFGwDnA7R-ytosPjZ6Vwh_0YHt2vFg-8x8JLjvlV2zDZLGD_Qv2dQvkXyL2E_pz5UQTzyNoqHg00V89jjmQFQVuL21GTStaMwQU5wH6e2PGvGTAxUjSO7pemiLAT_gcIeoGc\"><img alt=\"\" height=\"371\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiwJmxgwL07ujCuc-zDA7j3vqIOhqlwfoLiSRg1KisdHj1u6VcbrOozfPMVFGwDnA7R-ytosPjZ6Vwh_0YHt2vFg-8x8JLjvlV2zDZLGD_Qv2dQvkXyL2E_pz5UQTzyNoqHg00V89jjmQFQVuL21GTStaMwQU5wH6e2PGvGTAxUjSO7pemiLAT_gcIeoGc=w618-h371\" width=\"618\" /></a></div><p style=\"text-align:justify;\"><span>Markets\r\nin Asia – Pacific region traded in range on Thursday morning amid some relief\r\nfrom uncertainty over U.S. trade tariffs and interest rates, while chipmaking\r\nstocks underperformed ahead of closely watched earnings from bellwether TSMC.\r\nJapan’s Nikkei 225 fell 0.3%, while the TOPIX was flat. Trade data for June\r\nshowed sustained weakness in the country’s exports, amid pressure from U.S.\r\ntariffs on steel and automobiles.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty was trading near 25,270 early Thursday. The futures contract based\r\non the benchmark Nifty 50 was up 0.15% at 25,270 indicating a start in the\r\ngreen for the Indian markets. Earlier, Trump stated that US is very close to\r\nsign deal with India. India\'s benchmark equity indices snapped four sessions of\r\nlosses to close higher on Tuesday, led by gains in auto and financial stocks.\r\nHCL Technologies Ltd. took a beating after June quarter disappointed.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">L&amp;T Technology </span></b><span>- Services Q1FY26 (QoQ)\r\nRevenue down 3.9% to Rs 2,866 crore versus Rs 2,982 crore. EBIT down 3% to Rs\r\n381.30 crore versus Rs 394 crore. <b><span style=\"color:#FF0000;\">Negative</span></b></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">JTL Industries</span></b><span> - Q1FY26 (YoY) Revenue up 5.5% to\r\nRs 544 crore versus Rs 516 crore Ebitda down 41.5% at Rs 23.4 crore versus Rs\r\n40 crore. <b><span style=\"color:#FF0000;\">Negative</span></b></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#006600;\">Tech Mahindra -</span></b><span> Q1FY26 (QoQ) Revenue flat at\r\nRs 13,351.20 crore versus Rs 13,384 crore. EBIT up 7% at Rs 1,477.10 crore\r\nversus Rs 1,378 crore. <span style=\"color:#006600;\">Neutral</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#006600;\">Angel One -</span></b><span> Q1FY26 (QoQ) Total Income up 8.03%\r\nat Rs 1143 crore versus Rs 1058 crore. Net profit down 34.48% at Rs 114 crore\r\nversus Rs 174 crore. <span style=\"color:#006600;\">Neutral</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty made some gain on buying on\r\ndips to settle at 25,212 on Wednesday. Index is facing resistance at 17 day EMA\r\nof 25,265 while 25K is near term support. Today’s range – 25,050 – 25,350.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty slowly moved upwards to\r\nclose at 57,168 on Wednesday. Index taken strong support at 17 day EMA of\r\n56,875 while 57,500 is near term resistance. Today’s range – 56,950 – 57,500.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhARuIHJPrz91mS3oE-O9RUETzUeqVcKmZQGTkM064VHZYLQ-_pWa-h5fOa6BHcmAewRYnretHif-bgiXsowyYuwEZtx81g56pCBd9NToB70qEdbQoFypvfCR2m_awYllgdzshOs8b-LSVv326wKVAX1d90IfwbAB1jB9OJXMSHWpE5KwcmbpIk0WhINQE','2025-07-17','active','2026-09-25 07:55:39','2026-09-25 07:55:39'),
(230,'5111469689686982863','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૭ જુલાઇ ૨૦૨૫',NULL,'<h2 style=\"text-align:center;\"></h2><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgLGvX5gkxd3do1V10WiJHDcrDsEDvowmnJMyXfpvAUrzpTDSdyUskE_SaQAGRiB0OAL86dHynGcZvoLDPPZJvE6vA7YjM8ogAoN5Qih7TDd5ELqV8pRSzDFdrQKbEx_mce5IQkMncid3JTKqcuArh3yTQdRxbWwjPdMHQ0xa-gqLV-Sp9uSYi1Wx7lK8M\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgLGvX5gkxd3do1V10WiJHDcrDsEDvowmnJMyXfpvAUrzpTDSdyUskE_SaQAGRiB0OAL86dHynGcZvoLDPPZJvE6vA7YjM8ogAoN5Qih7TDd5ELqV8pRSzDFdrQKbEx_mce5IQkMncid3JTKqcuArh3yTQdRxbWwjPdMHQ0xa-gqLV-Sp9uSYi1Wx7lK8M\" width=\"281\" /></a></div><br /><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /> </span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>સરકારએ </span><span>NLC\r\n</span><span>ઈન્ડિયાને </span><span>NIRL </span><span>માં </span><span>₹</span><span>7,000 </span><span>કરોડનું</span><span>રોકાણ</span><span>કરવાની</span><span>મંજૂરી</span><span>આપી</span></li><li><span>મોંઘવારી</span><span>દર</span><span> (</span><span>CPI)\r\n</span><span>ચાલુ વર્ષમાં સરેરાશ 4% રહેશે: </span><span>Crisil</span></li><li><span>વ્યાજદરમાં</span><span>ઘટાડા</span><span>પહેલા</span><span>RBI ‘</span><span>ઉપલક્ષમાં રાખી\r\nનજર’ રાખશે: ગવર્નર મલ્હોત્રા</span></li><li><span>જૂન</span><span> 2025</span><span>માં</span><span>નોન</span><span>-</span><span>લાઈફ</span><span>ઇન્શ્યોરન્સ</span><span>પ્રિમિયમમ</span><span>ાં 5.2%નો વધારો: અહેવાલ</span></li><li><span>યુ</span><span>.</span><span>એસ</span><span>.</span><span>ના</span><span>ટેરિફ</span><span>જોખમ</span><span>વચ્ચે</span><span>ભારતની</span><span>IT </span><span>ડિમાન્ડ અંગે\r\nઅનિશ્ચિતતા: વિપ્રો ચેરમેન</span></li><li><span>ઇન્ડિયન</span><span>ઓવરસીઝ</span><span>બેંકે</span><span>તમામ</span><span>સમયગાળામાં</span><span>MCLR</span><span>માં 50 બેસિસ પોઇન્ટ્સનો ઘટાડો કર્યો</span></li><li><span>ડિયાજિયો</span><span>CEO </span><span>ડેબ્રા ક્રૂની\r\nજગ્યા પર અન્યને લાવવા યોજના બનાવી રહી છે: ફાઇનાન્શિયલ ટાઈમ્સ</span></li><li><span>IHCL</span><span>એ પોતાની સંપત્તિ કંપનીમાં </span><span>₹</span><span>165 </span><span>કરોડમાં</span><span> 3.3 </span><span>લાખ</span><span>શેયર્સ</span><span>મેળવ્યા</span></li><li><span>ફોર્ડે</span><span>US</span><span>માં 6.94 લાખથી વધુ\r\nવાહનો પાછા બોલાવ્યા – ઈંધણ લીક તપાસના કારણે</span></li><li><span>FY</span><span>28 સુધી </span><span>EV </span><span>કાર વેચાણ ભારતમાં\r\n7% સુધી પહોંચવાની સંભાવના: કેરએજ</span></li><li><span>લ્યુપિને</span><span>US</span><span>માં આંખોની સારવાર\r\nમાટે જનરિક દવા લોન્ચ કરી</span></li><li><span>શ્નાઈડર</span><span>ઇન્ડિયા</span><span>J.V. </span><span>માં ટેમાસેકની\r\nહિસ્સ</span><span>ेदारी </span><span>ખરીદવા સંવાદમાં: અહેવાલ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>જૂન મહિનામાં સોના આયાતે બે વર્ષનું ન્યૂનતમ સ્તર નોંધાવ્યું કારણ કે ઊંચી\r\nકિંમતે માંગ ઘટી</span></li><li><span>થર્મલ પાવર સેગમેન્ટમાં આગામી 3 વર્ષમાં </span><span>₹</span><span>2.3 લાખ કરોડના રોકાણની સંભાવના: </span><span>Crisil</span></li><li><span>માર્કેટ વોલેટિલિટીમાં ટ્રેડિંગ વધતાં મોર્ગન સ્ટેન્લીની કમાણીમાં વધારો</span></li><li><span>ગોલ્ડમેન સેચની કમાણીમાં તેજી</span><span>, </span><span>ઇક્વિટી\r\nટ્રેડિંગથી રેકોર્ડ કમાણી</span></li><li><span>એમ્બેસી રીટ </span><span>₹</span><span>2,000 કરોડના બોન્ડ વેચાણ સાથે દેવાની બજારમાં પ્રવેશ કરશે</span></li><li><span>વેદાંતા અંગે ક્રેડિટ પ્રોફાઇલ સુધરતા અને આકર્ષક મૂલ્યાંકનને કારણે </span><span>BofA </span><span>સકારાત્મક</span></li><li><span>ક્લાઉડ ખર્ચ અને સાયકલ સમયના કારણે કેટલાક બિઝનેસો પાછા ઓન-પ્રેમિસ ઇન્ફ્રામાં</span></li><li><span>AM/NS </span><span>ઇન્ડિયાએ હઝીરા પ્લાન્ટમાં ઓટો સ્ટીલ લાઇન શરૂ કરી</span><span>, </span><span>આયાતમાં\r\nઘટાડો લક્ષ્ય</span></li><li><span>સેબી દ્વારા </span><span>MCXCCL</span><span>ને 3 વર્ષ માટે ક્લીયરિંગ\r\nકોર્પોરેશન તરીકે પુનઃમંજૂરી</span></li><li><span>EQT </span><span>સમર્થિત ઈન્દિરા </span><span>IVF</span><span>એ </span><span>DRHP </span><span>ફરીથી\r\nસેબીના ગુપ્ત માર્ગે દાખલ કર્યું</span></li><li><span>પાઇપલાઇન ઇન્ફ્રાસ્ટ્રક્ચર અને ક્રાઉન </span><span>LNG </span><span>વચ્ચે આંધ્રપ્રદેશ માટે પાઇપલાઇન કનેક્ટિવિટી અંગે </span><span>MoU</span></li><li><span>બાયોકોન બાયોલોજિક્સે ડાયાબિટીસ માટે </span><span>Kirsty </span><span>નામની દવા માટે </span><span>US FDA </span><span>મંજૂરી મેળવી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>RBI</span><span>ની પૂરતી લિક્વિડિટીની પ્રતિબદ્ધતા વ્યાજદરમાં ઘટાડા માટે અનુકૂળ: </span><span>Fitch</span></li><li><span>મંત્રિમંડળે </span><span>₹</span><span>24,000</span><span> કરોડની કૃષિ સહાય અને ગ્રીન એનર્જી રોકાણ મંજૂર કર્યું</span></li><li><span>ગેઇલ લાંબા ગાળાના </span><span>LNG </span><span>સપ્લાય માટે\r\nઅલાસ્કા સાથે કરાર માટે પ્રયત્નશીલ</span></li><li><span>ટેક મહિન્દ્રાનું </span><span>Q1</span><span> ઍટ્રિશન રેટ </span><span>12.6%, </span><span>કુલ કર્મચારીઓમાં </span><span>897</span><span>નો વધારો</span></li><li><span>મંત્રિમંડળે </span><span>NTPC</span><span>ને </span><span>₹</span><span>20,000</span><span> કરોડ સુધીના રીન્યુએબલ એનર્જી રોકાણ માટે મંજૂરી આપી</span></li><li><span>રોડ કન્સ્ટ્રક્શન માટેના કડક થયેલ નિયમોથી મજબૂત ફાઈનાન્સવાળા પ્લેયરોને લાભ:\r\nરિપોર્ટ</span></li><li><span>2025</span><span>ની બીજી છમાહી માટે સોનું મર્યાદિત ભાવમાં રહેવાની શક્યતા</span><span>, </span><span>વર્ષ દરમિયાન </span><span>5%</span><span> વધે તેવી\r\nઅપેક્ષા: </span><span>WGC</span></li><li><span>ITC </span><span>હોટલ્સ </span><span>Q1</span><span> પરિણામ: નફો </span><span>54%</span><span> વધીને </span><span>₹</span><span>133</span><span> કરોડ</span><span>, </span><span>આવક </span><span>₹</span><span>815</span><span> કરોડ</span></li><li><span>શાપૂર્જી પલ્લોનજી પુણેમાં </span><span>₹</span><span>800</span><span> કરોડની આવક સાથે </span><span>5</span><span> એકરના\r\nહાઉસિંગ પ્રોજેક્ટમાં પ્રવેશ કરશે</span></li><li><span>જિઓ બ્લેકરોકને સેબી તરફથી ચાર પેસિવ ફંડ લોન્ચ કરવા મંજૂરી</span></li><li><span>એપલે રેયર અર્થ મેગ્નેટ માટે </span><span>MP </span><span>મટિરિયલ્સ\r\nસાથે </span><span>$500</span><span> મિલિયનનો કરાર કર્યો</span></li><li><span>IREDA </span><span>મજબૂત કામગીરી છતાં વધતા </span><span>NPA </span><span>ની સમસ્યાઓનો\r\nસામનો કરી રહ્યું છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgLGvX5gkxd3do1V10WiJHDcrDsEDvowmnJMyXfpvAUrzpTDSdyUskE_SaQAGRiB0OAL86dHynGcZvoLDPPZJvE6vA7YjM8ogAoN5Qih7TDd5ELqV8pRSzDFdrQKbEx_mce5IQkMncid3JTKqcuArh3yTQdRxbWwjPdMHQ0xa-gqLV-Sp9uSYi1Wx7lK8M','2025-07-17','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(231,'7762182857350467643','Research Report : Indian Financial Markets Outlook - 16th July 2025',NULL,'<h2 style=\"text-align:center;\"></h2><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjSOHKxicsf6l2dlc0bK7-PzqtbMNnO7e3rQ7wsbEtaH9lUOTgUD8r56btcHbIoRzXWyQUnIlkuaR_e_bWFJGS5ane2soOYUfDyHWlPrrwmdPervjFS12SG0vraIFNlpThGaV0-sHpyBAmWYMZhr9Fu2ni8DAyEWyj4PwYAV2gv3eRhhnrkNXGOKxDFHqc\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjSOHKxicsf6l2dlc0bK7-PzqtbMNnO7e3rQ7wsbEtaH9lUOTgUD8r56btcHbIoRzXWyQUnIlkuaR_e_bWFJGS5ane2soOYUfDyHWlPrrwmdPervjFS12SG0vraIFNlpThGaV0-sHpyBAmWYMZhr9Fu2ni8DAyEWyj4PwYAV2gv3eRhhnrkNXGOKxDFHqc\" width=\"240\" /></a><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span>\r\n\r\n<p><span style=\"color:#FF0000;\">Global\r\nmarkets feel pinch of Trump’s tariff heroic, high inflation data in US hurts</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEh-weraJ9__3MkDNUI9kpF3SLB08S7KLqtkPgwY8JDku1IsJfZ1DSmpxb8AabBDTBSs8qhJ3dOe_EUXsxi9Xx2bxRIbS2UAs2QUTZeXb5ik8Py5UI7yg3uOJnUCADeq_DuJR-iaTdaDOVgeeOgiU2wBHkuf9hya1ajx4A2fF92cUgT5vfcL-v0S5JosmNo\"><img alt=\"\" height=\"324\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEh-weraJ9__3MkDNUI9kpF3SLB08S7KLqtkPgwY8JDku1IsJfZ1DSmpxb8AabBDTBSs8qhJ3dOe_EUXsxi9Xx2bxRIbS2UAs2QUTZeXb5ik8Py5UI7yg3uOJnUCADeq_DuJR-iaTdaDOVgeeOgiU2wBHkuf9hya1ajx4A2fF92cUgT5vfcL-v0S5JosmNo=w569-h324\" width=\"569\" /></a></div><p style=\"text-align:justify;\"><span>Markets\r\nin Asia Pacific region fell at the open on Wednesday after mixed US inflation\r\ndata spurred traders to trim Federal Reserve interest rate-cut bets. The MSCI\r\nregional gauge dropped 0.4% with losses in Australia, Japan and South Korea.\r\nThe GIFT Nifty is trading 95 points or 0.38% down at 25,170.5 in the morning,\r\nindicating a lower start for the benchmark Nifty 50. S&amp;P 500 futures fell\r\n0.2% after the index closed lower Tuesday. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nNSE Nifty 50 ended 113.5 points or 0.45% higher at 25,195.8, while the BSE\r\nSensex closed 317.45 points or 0.39% up at 82,570.91. Foreign portfolio\r\ninvestors turned net buyers of Indian shares on Tuesday after two sessions of\r\nselling as they mopped up stocks worth Rs 104.5 crore, according to provisional\r\ndata from the National Stock Exchange. The domestic institutional investors,\r\nwho remained buyers for the seventh straight session, bought stocks worth Rs\r\n1,477.6 crore.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li><b><span style=\"color:#0000FF;\">HDFC Life Insurance -</span></b><span> Q1FY26 (YoY) Net premium\r\nincome up 15% at Rs 14,466 crore vs Rs 12,509 crore. Annualised premium\r\nequivalent grew 12.5% to Rs 3,225 crore versus Rs 2,866 crore <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li><b><span style=\"color:#0000FF;\">HDB Financial Services -</span></b><span> Q1FY26\r\n(YoY) Net interest income at Rs 2092 crore, up 18% year-on-year. Operating\r\nprofit at Rs1388 crore versus Rs 1179 crore year-on-year, up 18%. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li><b><span style=\"color:#0000FF;\">ICICI Lombard - </span></b><span>Q1FY26 (YoY) Net Profit rises 28.7%\r\nto Rs 747 crore versus Rs 580 crore. Total Income rises 13.7% to Rs 6,083 crore\r\nversus 5,352 crore. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li><b><span style=\"color:#0000FF;\">Just Dial -</span></b><span> Q1FY26 (YoY) Revenue up 6.42% at Rs\r\n298 crore versus Rs 280 crore. Ebitda up 7.66% at Rs 87.1 crore versus Rs 80.9\r\ncrore.<span style=\"color:#0000FF;\"> Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty gained over 100 points to\r\nsettle at 25,195 on Tuesday. Index is facing resistance at 17 day EMA of 25,270\r\nwhile 25K is near term support. Today’s range – 25,000 – 25,300.</span></li></ul><ul><li><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty recovered smartly to\r\nclose tad above 57K at 57,006 on Tuesday. Index breached 17 day EMA of 56,825\r\nwhile 57,500 is now near term resistance. Today’s range – 56,800 – 57,500.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjSOHKxicsf6l2dlc0bK7-PzqtbMNnO7e3rQ7wsbEtaH9lUOTgUD8r56btcHbIoRzXWyQUnIlkuaR_e_bWFJGS5ane2soOYUfDyHWlPrrwmdPervjFS12SG0vraIFNlpThGaV0-sHpyBAmWYMZhr9Fu2ni8DAyEWyj4PwYAV2gv3eRhhnrkNXGOKxDFHqc','2025-07-16','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(232,'5665709942358675078','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૬ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjx4Hesl5n-qtxpOOhZWLwbu3hCZiVbd9K8W1uLlMNBoB8Uc5BWgPfI0SVl3qp6t0WsTcHyV-4NuOqlFpam8Ar76qQTpl4GCtTz3x3PXeEYJTxuLFMxHqEe4bAn4s-VwaFg5e7k5uOs4EL1XcyEAk2VccNLxQ_CYVdrSSbgB3zUf5GXX7jrIlgLxdnpT4A\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjx4Hesl5n-qtxpOOhZWLwbu3hCZiVbd9K8W1uLlMNBoB8Uc5BWgPfI0SVl3qp6t0WsTcHyV-4NuOqlFpam8Ar76qQTpl4GCtTz3x3PXeEYJTxuLFMxHqEe4bAn4s-VwaFg5e7k5uOs4EL1XcyEAk2VccNLxQ_CYVdrSSbgB3zUf5GXX7jrIlgLxdnpT4A\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ખાદ્ય તેલ\r\nરિફાઈનરોના આવકમાં </span><span>FY</span><span>26માં ભાવ ઘટવાને કારણે 2-3% ઘટાડો થવાનો\r\nક્રિસિલનો અંદાજ</span></li><li><span>સિટિબેંક</span><span>ઈન્ડિયા</span><span>: </span><span>\'</span><span>બિલિયન-ડોલર </span><span>IPO\'</span><span>ના કારણે ભારતમાં બિઝનેસમાં વધારો થશે</span></li><li><span>CoreWeave </span><span>એ પેનસિલવેનિયામાં </span><span>AI </span><span>ડેટા સેન્ટર માટે $6 બિલિયનનું રોકાણ કરવાની જાહેરાત કરી</span></li><li><span>જર્મનીએ</span><span>મુખ્ય</span><span>ટેક્નોલોજીમાં</span><span>આગળ</span><span>વધવા</span><span>માટે</span><span>AI offensive </span><span>શરૂ કરવાનો પ્લાન\r\nબનાવી લીધો</span></li><li><span>ટ્રમ્પ</span><span>કહે</span><span>છે</span><span>કે</span><span>UK US </span><span>માટે લડે</span><span>,\r\n</span><span>પણ </span><span>EU </span><span>માટે એવું ન કહી\r\nશકાય</span></li><li><span>MTNL </span><span>એ જૂન 2025 સુધીમાં 7</span><span> PSU </span><span>બેંકોના </span><span>₹</span><span>8,585 </span><span>કરોડના</span><span>મુખ્ય</span><span>મૂડી</span><span>અને</span><span>વ્યાજ</span><span>પર</span><span>ડિફોલ્ટ</span><span>કર્યું</span></li><li><span>કર્ણાટક</span><span>બેંકે</span><span>રાઘવેન્દ્ર</span><span>શ્રીનિવાસ</span><span>ભટને</span><span>હાલના</span><span>કાર્યકારી</span><span>MD </span><span>અને </span><span>CEO\r\n</span><span>તરીકે નિમ્યા</span></li><li><span>ઔરોબિન્દોએ</span><span>HIV </span><span>માટે લાંબી અવધિની\r\nસારવાર આપતી દવાના ઉત્પાદન અને સપ્લાય કરવાની યોજના બનાવી</span></li><li><span>સેબી</span><span>એ</span><span>વેન્ચર</span><span>કેપિટલ</span><span>ફંડ</span><span>માટે</span><span>સેટલમેન્ટ</span><span>યોજના</span><span>જાહેર</span><span>કરી</span><span>;\r\n</span><span>21 જુલાઈથી શરુ થશે</span></li><li><span>જૂનમાં</span><span>ભારતનો</span><span>વેપાર</span><span>તટસ્થ</span><span>ઘટાડીને</span><span> $18.78 </span><span>અબજ</span><span>થયો</span></li><li><span>ઈંદિરા</span><span>IVF </span><span>એ પોતાનું </span><span>₹</span><span>3,500 </span><span>કરોડ</span><span>ઊભું</span><span>કરતું</span><span>IPO </span><span>ફરીથી લાવવાનો વિચાર કર્યો</span></li><li><span>આર્થિક</span><span>અનિશ્ચિતતા</span><span>અને</span><span>ભૂ</span><span>-</span><span>રાજનૈતિક</span><span>તણાવ</span><span>વચ</span><span>્ચે જૂનમાં રત્ન અને આભૂષણનો નિકાસ 14.25%\r\nઘટ્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>TVS </span><span>લોજિસ્ટિક્સ કંપનીએ જણાવ્યું કે </span><span>AI </span><span>અપનાવવાથી કાર્યક્ષમતા વધતી ગઈ છે અને ખર્ચ ઘટ્યો છે</span></li><li><span>ડિલોઇટ દક્ષિણ એશિયા </span><span>CEO </span><span>કહે છે: </span><span>AI </span><span>સાથે સમાયોજન માટે </span><span>\'</span><span>ક્રિટિકલ થિંકિંગ</span><span>\' </span><span>અનિવાર્ય છે</span></li><li><span>છેલ્લાં 3.5 વર્ષમાં </span><span>₹</span><span>2.4 લાખ કરોડના રહેણાંક\r\nપ્લોટ લોન્ચ થયા: પ્રોપઈક્વિટી</span></li><li><span>ઓબેરોય રિયલ્ટી ગ્રુપ દેમાં ગઈ હોટેલ કંપનીને ખરીદવા માટે </span><span>₹</span><span>919 કરોડ ચૂકવશે</span></li><li><span>ઓફિસ સ્પેસ કંપની </span><span>WeWork India </span><span>ને </span><span>IPO </span><span>માટે નિયમનકારી મંજૂરી મળી</span></li><li><span>SBI </span><span>એ ટૂંકાવધિ ખાટીચુકવણી દરોમાં 15 બેઝિસ પોઈન્ટની કપાત કરી</span><span>; </span><span>15 જુલાઈથી\r\nઅમલ</span></li><li><span>WHO </span><span>એ </span><span>HIV </span><span>માટેની ઇન્જેક્ટેબલ દવા લેના કેસેપાવીર ને ઉચ્ચ જોખમ ધરાવતા\r\nસમુદાયો માટે મંજૂરી આપી</span></li><li><span>ACKO </span><span>કંપનીને ભારતમાં ટેસલા ગ્રાહકો માટે પસંદગીની વિમો ભાગીદાર\r\nતરીકે પસંદ કરવામાં આવી</span></li><li><span>ઉચ્ચ આયાત શુલ્કને ટાળવા માટે આયાતકારો </span><span>US </span><span>ડ્રાયફ્રૂટની ક્લિયરન્સ મોડું કરી રહ્યા છે</span></li><li><span>બેંક ઓફ મહારાષ્ટ્રનો </span><span>FY</span><span>26 નો પ્રથમ ત્રિમાસિક નફો 23% વધીને </span><span>₹</span><span>1,593 કરોડ થયો</span></li><li><span>PhonePe </span><span>એ મેટાના શિવનાથ ઠુકરાલને જાહેર નીતિ માટેના ઉપપ્રમુખ તરીકે\r\nનિમ્યા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>અદાણી વિલમર (</span><span>AWL) </span><span>એગ્રી બિઝનેસ: </span><span>Q</span><span>1 નફો 24%\r\nઘટીને </span><span>₹</span><span>238 કરોડ થયો</span></li><li><span>SMFG </span><span>એ </span><span>Yes Bank </span><span>માટે $1.1 બિલિયનની વધારાની ડીલ પર નજર રાખી</span></li><li><span>જૂનમાં વેપાર તટસ્થ $18.78 અબજ સુધી ઘટ્યો</span><span>; </span><span>નિકાસ\r\nઅને આયાત બંને ઘટ્યા</span></li><li><span>ICICI </span><span>પ્રુ લાઈફ: </span><span>Q</span><span>1 નફો 34% વધીને </span><span>₹</span><span>302.08 કરોડ થયો</span></li><li><span>ઇન્ફોસિસ </span><span>CSR </span><span>યૂનિટે 5 લાખ નોકરી શોધનારાઓ માટે સ્કિલ કાર્યક્રમ લૉન્ચ\r\nકર્યો</span><span>; </span><span>પહેલી તબક્કામાં </span><span>₹</span><span>200 કરોડ ફાળવ્યા</span></li><li><span>ભારત વિશ્વના સૌથી ઝડપથી વિકાસ પામતા લક્ઝરી ઘડિયાળ માર્કેટમાંનું એક છે: </span><span>H. </span><span>મોઝર </span><span>&amp; Cie. CEO</span></li><li><span>હેમંત રૂપાણી સપ્ટેમ્બરમાં હિંદુસ્તાન કોકા-કોલા બેવરેજીસના </span><span>CEO </span><span>બનશે</span></li><li><span>US </span><span>સેનેટરો ભારત અને ચીન પર 500% આયાત શુલ્ક લગાવવાની માંગ સાથે ભયંકર દંડની અપીલ\r\nકરે છે</span></li><li><span>ચીનની અર્થવ્યવસ્થા 5.2%ના દરે વધી</span><span>; </span><span>નિકાસ મજબૂત\r\nરહેતાં અંદાજથી વધુ વૃદ્ધિ</span></li><li><span>Nvidia </span><span>એ ચીનમાં </span><span>AI </span><span>ચિપની વેચાણને ફરીથી ચાલુ કરવાની મંજૂરી મેળવી</span><span>; CEO</span><span>એ ટ્રમ્પ સાથે મુલાકાત કરી</span></li><li><span>Specta </span><span>₹</span><span>250 કરોડનું રોકાણ કરીને\r\nઉત્પાદન ક્ષમતા લગભગ ત્રણગણી કરશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને શિક્ષણ\r\nહેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjx4Hesl5n-qtxpOOhZWLwbu3hCZiVbd9K8W1uLlMNBoB8Uc5BWgPfI0SVl3qp6t0WsTcHyV-4NuOqlFpam8Ar76qQTpl4GCtTz3x3PXeEYJTxuLFMxHqEe4bAn4s-VwaFg5e7k5uOs4EL1XcyEAk2VccNLxQ_CYVdrSSbgB3zUf5GXX7jrIlgLxdnpT4A','2025-07-16','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(233,'7381228115426622741','Research Report : Indian Financial Markets Outlook - 15th July 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiG8xFOWL5NLWNqWMwIk0pKIMqkK7y-5t2t291b1CBGGEW2za2Kn2UY7m2NWhTXUa6-ouhVSCfYDkOFOgkzuLNRUa-_kyjtyg_zYp6pjjq5lbnBeZlCdiLHEegzPWmCD7IeOsmZ21hrLjoFUXJ3WJG20S0FlCzfO4rkywLeKTGU_0STYv8geqygWAz0cZA\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiG8xFOWL5NLWNqWMwIk0pKIMqkK7y-5t2t291b1CBGGEW2za2Kn2UY7m2NWhTXUa6-ouhVSCfYDkOFOgkzuLNRUa-_kyjtyg_zYp6pjjq5lbnBeZlCdiLHEegzPWmCD7IeOsmZ21hrLjoFUXJ3WJG20S0FlCzfO4rkywLeKTGU_0STYv8geqygWAz0cZA\" width=\"240\" /></a><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">Markets\r\nbucked the trend despite trump’s tariff threats</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEinTZaUN7dGRkTwiptCnIYrcyZLweIRtr4MWbNIXxx5aFCVqON0eiToD0SLu1JP1oaLLhGLksUxLueCHWAxZ4qklNc6fH99IhdCyb5tVN1LtH7sEHYXBEDiSClV959gilLzaLEXJwWxsyPUXnx-Y7LpK58zK4oTbkCr6_6vwq7elybD2vndQq1Rb8M8vPg\"><img alt=\"\" height=\"280\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEinTZaUN7dGRkTwiptCnIYrcyZLweIRtr4MWbNIXxx5aFCVqON0eiToD0SLu1JP1oaLLhGLksUxLueCHWAxZ4qklNc6fH99IhdCyb5tVN1LtH7sEHYXBEDiSClV959gilLzaLEXJwWxsyPUXnx-Y7LpK58zK4oTbkCr6_6vwq7elybD2vndQq1Rb8M8vPg=w623-h280\" width=\"623\" /></a></div><div style=\"text-align:justify;\"><span>Asian\r\nmarkets followed the US in posting a modest gain as traders brushed off Trump’s\r\nlatest tariff threats as bargaining tactics that are unlikely to derail global\r\ntrade. Shares in Australia and Japan rose while those in South Korea retreated\r\nat the open on Tuesday. Futures on Wall Street were marginally down while\r\nEuropean contracts edged up. S&amp;P 500 futures down 0.13% Euro Stoxx 50\r\nfutures up 0.1%.</span></div><div style=\"text-align:justify;\"><span>The\r\nGIFT Nifty was up 15 points at 25,167 in the morning, indicating a flat start\r\nfor the benchmark Nifty 50. India\'s benchmark equity indices extended losses to\r\na fourth session on Monday, following a decline in Asian shares and US index\r\nfutures. Information technology, defence and financial stocks took a beating.\r\nThe NSE Nifty 50 ended 67.55 points or 0.27% lower at 25,082.3, while the BSE\r\nSensex closed 247.01 points or 0.3% down at 82,253.46. Intraday, the Nifty and\r\nSensex slipped 0.6%.</span></div>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Rallis India - </span></b><span>Q1FY26 (YoY)Revenue\r\nup 22.2% at Rs 957 crore versus Rs 783 crore. Ebitda up 56.3% at Rs 150 crore\r\nversus Rs 96 crore.<span style=\"color:#0000FF;\"> Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">HCLTech - </span></b><span>Q1FY26 (QoQ) Revenue up 0.34% at Rs\r\n30349 crore versus Rs 30246 crore. EBIT down 9.18% at Rs 4942 crore versus Rs 5442\r\ncrore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Tejas Networks</span></b><span> <b><span style=\"color:#FF0000;\">- </span></b>Q1FY26\r\n(YoY) Revenue down 87% at Rs 202 crore versus Rs 1,563 crore. Ebitda loss of Rs\r\n135.67 crore versus profit of Rs 230 crore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Tata Tech -</span></b><span> Q1FY26 (QoQ) Revenue down 3.2% to\r\nRs 1,244.29 crore versus Rs 1,285.65 crore. EBIT down 17% to Rs 168.81 crore\r\nversus Rs 202.26 crore. <span style=\"color:#FF0000;\">Negative</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty traded lower to settle near 25K\r\nat 25,082 on Monday. Index is facing headwind over India – US trade deal\r\nuncertainty while lower corporate quarterly numbers exerts pressure on index.\r\nToday’s range – 24,950 – 25,200.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty continued trading in\r\nnarrow range to close marginally higher at 56,765 on Monday. Index is trading\r\nnear 17 day EMA of 56,733 while 57,000 is near term resistance. Today’s range –\r\n56,550 – 57,000.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in checking\r\nthe correctness and authenticity of the information before publishing research\r\nreport. We shall not be in any way responsible for any loss or damage in\r\nanalysis or views obtained from the use of information contained in this report\r\nand especially states that we have no financial liability whatsoever to the\r\nuser of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEiG8xFOWL5NLWNqWMwIk0pKIMqkK7y-5t2t291b1CBGGEW2za2Kn2UY7m2NWhTXUa6-ouhVSCfYDkOFOgkzuLNRUa-_kyjtyg_zYp6pjjq5lbnBeZlCdiLHEegzPWmCD7IeOsmZ21hrLjoFUXJ3WJG20S0FlCzfO4rkywLeKTGU_0STYv8geqygWAz0cZA','2025-07-15','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(234,'1020867067214117312','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૫ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiVdxDUoqCLLOzLHVXX9ZnMM03i59jDUUb6kjo6wIaV6H7Sqx-2X2Desmu5PjbyznY3XJfpOor2My0Uy2hTupxOGyRdc_Z3vxgRp3twFk5JpkkiqUegCNEK1nuiJHZIbjE7zUc-xdTtJ04kqQrQzIKVrbgtFgLYYvPHd1Nicwzi1mow9pqh-7l_leFxCtQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiVdxDUoqCLLOzLHVXX9ZnMM03i59jDUUb6kjo6wIaV6H7Sqx-2X2Desmu5PjbyznY3XJfpOor2My0Uy2hTupxOGyRdc_Z3vxgRp3twFk5JpkkiqUegCNEK1nuiJHZIbjE7zUc-xdTtJ04kqQrQzIKVrbgtFgLYYvPHd1Nicwzi1mow9pqh-7l_leFxCtQ\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન :</span></b><b><span style=\"color:#0000FF;\">-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતના નવા તાંબાના\r\nઆયાત નિયમોથી પુરવઠો સંકટ ઊભું થઈ શકે છે: ટ્રેડ બોડી</span></li><li><span>સિટીગ્રુપના ભારતના\r\nકમર્શિયલ બેંકિંગ હેડ ભાનુ વોહિતાનું રાજીનામું</span></li><li><span>હીરો મોટેાકોર્પ </span><span>Q2\r\nFY26</span><span>માં યુરોપીય બજારમાં પ્રવેશ કરશે: અધ્યક્ષ પવન મુંજલ</span></li><li><span>ભારતીય સ્વચ્છ\r\nઉર્જા કંપની </span><span>SAEL\r\n$954</span><span> મિલિયનનું સોલાર પ્લાન્ટમાં રોકાણ કરશે</span></li><li><span>DSP </span><span>એસેટ મેનેજર્સ અને </span><span>Cybrilla </span><span>જોડાઈને </span><span>ONDC </span><span>પર મ્યુચ્યુઅલ ફંડ\r\nલાવે છે</span></li><li><span>આયુષ વેલનેસે\r\nન્યુટ્રાસ્યુટિકલ ઉત્પાદનોનો પોર્ટફોલિયો વિસ્તરાવ્યો</span></li><li><span>કર્ણાટક બેંકે\r\nરઘવેન્દ્ર શ્રીનિવાસ ભટને આંતરિમ </span><span>MD </span><span>અને </span><span>CEO\r\n</span><span>તરીકે નિયુક્ત કર્યા</span></li><li><span>સ્ટેલન્ટિસ ભારતમાં\r\nરોકાણ વધારવા માટે તૈયાર</span><span>; </span><span>માર્કેટ શેરમાં\r\nવધારો કરવાનો લક્ષ્ય</span></li><li><span>સરકારી ગેરંટીના\r\nઆધારે જાહેર ક્ષેત્રની બેંકો દ્વારા સબ-પ્રાઇમ લોનિંગમાં વધારો</span></li><li><span>ઇનબ્રૂ અને તિલકનગર\r\nદરેકે </span><span>$500</span><span> મિલિયનના પ્રાઈવેટ ડેટથી </span><span>Imperial\r\nBlue </span><span>ખરીદવા માટે રસ દાખવ્યો</span></li><li><span>એપ્રિલ-જૂન દરમ્યાન\r\nકમર્શિયલ રિયલ એસ્ટેટે ભારતમાં મિલ્કત વ્યવહારોને આગળ ધપાવ્યા</span></li><li><span>સન ફાર્માએ ઇન્સાઇટ\r\nકોર્પ સાથેનો વિવાદ સમાધાન કર્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>કોમર્સ મંત્રાલયની ટીમ અમેરિકામાં</span><span>; </span><span>વેપાર ચર્ચાઓ\r\nશરૂ થવાની શક્યતા</span></li><li><span>રાજસ્થાનની ઔદ્યોગિક સંસ્થા સરકારે રાજ્યમાં કેમિકલ હબ સ્થાપવા માંગ કરી</span></li><li><span>ટેરિફમાં કાપ હોવા છતાં જૂનમાં વેજિટેબલ ઓઇલનું આયાત સ્તર સ્થિર</span></li><li><span>HDFC </span><span>બેંક માટે ઓછી ક્રેડિટ-ડિપોઝિટ અનુકૂળતા અને મજબૂત ડિપોઝિટ વૃદ્ધિ લાભદાયક: </span><span>CEO</span></li><li><span>ઉત્તર પ્રદેશ સરકારે </span><span>₹</span><span>4,000 કરોડના નવા એક્સાઈઝ પ્રસ્તાવો\r\nનોંધાવ્યા</span></li><li><span>ચીન સહિત અન્ય દેશો પર ડ્યુટી વધારો પછી અમેરિકા માટે ભારતની નિકાસ વધુ સ્પર્ધાત્મક\r\nબનશે</span></li><li><span>ટાટા સ્ટીલ પોર્ટ ટાલબોટ </span><span>EAF </span><span>પ્રોજેક્ટ શરૂ\r\nકરશે</span><span>; UK </span><span>તરફથી £500 મિલિયનનું રોકાણ</span></li><li><span>બોશ કંપનીએ ભારતની નિકાસ 2030 અને પછી બેગણી કરવાની યોજના બનાવી</span></li><li><span>ICMR </span><span>નો નવો કેર મોડલ એન્ડોમેટ્રિઓસિસ અને ગાયનેક કેરમાં પરિવર્તન લાવશે</span></li><li><span>સુરજ એસ્ટેટે મુંબઈમાં </span><span>₹</span><span>120 કરોડનું આવાસ યોજના પ્રારંભ\r\nકરી</span></li><li><span>વજન ઘટાડવાની દવા ક્ષેત્રે સ્પર્ધા વધતી જાય છે કારણ કે </span><span>Wegovy </span><span>અને </span><span>Mounjaro</span><span>ની\r\nવેચાણ વૃદ્ધિ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>જૂનમાં રીટેલ મૂલ્યવર્ધન દર ઘટીને છેલ્લા 6 વર્ષથી ઓછો 2.1% થયો</span></li><li><span>જૂનમાં વેજિટેબલ ઓઇલ આયાત સ્થિર રહી છતાં ટેરિફમાં કાપ થયો</span></li><li><span>સરકાર સોલાર અને વિન્ડ પ્રોજેક્ટ માટે </span><span>ISTS </span><span>ચાર્જ માફીમાં વધારો કરવાનો વિચાર નથી કરી રહી</span></li><li><span>શોભા લિ. </span><span>FY</span><span>26માં બ</span><span>ें</span><span>ગલુરુ બહાર નવું લોન્ચિંગ કરીને મોટા વળતરની અપેક્ષા રાખે\r\nછે</span></li><li><span>રશિયા ભારતમાંથી 10 લાખ કુશળ કામદારો આયાત કરશે</span></li><li><span>Paytm</span><span>માં ઘેરલૂ મ્યુચ્યુઅલ ફંડ્સ અને વિદેશી રોકાણકારોની ભાગીદારીમાં વધારો થયો</span></li><li><span>NSE</span><span>એ ડેરિવેટિવ ઇન્વેસ્ટર્સ માટે માસિક ઇલેક્ટ્રિસિટી ફ્યુચર્સ કોન્ટ્રાક્ટ લોન્ચ\r\nકર્યા</span></li><li><span>વિયેતનામ હનોઈના મધ્ય ભાગમાં પ્રદૂષણના કારણે ફોસિલ ફ્યુઅલ બાઈક પર પ્રતિબંધ\r\nલાવશે</span></li><li><span>અમેરિકાની સાથેના ટ્રેડ ટ્રૂસ પછી ચીનની નિકાસ અપેક્ષાથી વધુ વધી</span></li><li><span>પેન્શન ફંડોએ બોન્ડમાં રોકાણના નિયમો સરળ કરવાની માંગ કરી</span></li><li><span>Siemens </span><span>અને </span><span>SAP </span><span>એ યુરોપિયન યુનિયનના </span><span>AI </span><span>નિયમોમાં ફેરફાર કરવાની અપીલ કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEiVdxDUoqCLLOzLHVXX9ZnMM03i59jDUUb6kjo6wIaV6H7Sqx-2X2Desmu5PjbyznY3XJfpOor2My0Uy2hTupxOGyRdc_Z3vxgRp3twFk5JpkkiqUegCNEK1nuiJHZIbjE7zUc-xdTtJ04kqQrQzIKVrbgtFgLYYvPHd1Nicwzi1mow9pqh-7l_leFxCtQ','2025-07-15','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(235,'2081637953008195159','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૪ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhUDBJsruyoWlhbqm9JNvZTrjf_aEy0dSjtUAUpxTPyBJ6Nj-KTwoWY32IzBUgcTrAsYx2q9DyQTFXpjmFw-1p_ulTTkp1_Kf8gxmWj-UGT61WfXV-yyQbanrTzyyhdfDZojMkjlEAgN7J8lKqT-rcsiqvLODhZkOFAFw8j2d4mSWUYKXvt9EGUyqxfcGc\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhUDBJsruyoWlhbqm9JNvZTrjf_aEy0dSjtUAUpxTPyBJ6Nj-KTwoWY32IzBUgcTrAsYx2q9DyQTFXpjmFw-1p_ulTTkp1_Kf8gxmWj-UGT61WfXV-yyQbanrTzyyhdfDZojMkjlEAgN7J8lKqT-rcsiqvLODhZkOFAFw8j2d4mSWUYKXvt9EGUyqxfcGc\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ટિટાગઢ રેલે પશ્ચિમ\r\nબંગાળમાં વિસ્તરણ માટે </span><span>40</span><span> એકર જમીન ખરીદી</span></li><li><span>પોલેન્ડની મોટી\r\nકંપની સહિત </span><span>6</span><span> કંપનીઓ દીઓચા પચામી કોલ ખાણ માટે સ્પર્ધામાં</span></li><li><span>વીલ્સ ઈન્ડિયાે નવા\r\nયુરોપિયન સબસિડિયરીમાં </span><span>€50,000</span><span>નું મૂડીરોકાણ\r\nકર્યું</span></li><li><span>યુ.પી. સરકાર </span><span>PPP\r\n</span><span>મોડલ હેઠળ </span><span>11</span><span> વારસાગત સાઇટોનું\r\nપુનઃસ્થાપન કરશે</span></li><li><span>કૃષિ મંત્રીએ\r\nરાજ્યોએ ખોટા ખાતર વેચાણ સામે કડક પગલાં લેવાનું જણાવ્યું</span></li><li><span>મર્સીડિઝ-બેન્ઝ\r\nઈન્ડિયા સપ્ટેમ્બરથી </span><span>1-1.5%</span><span> ભાવવધારો કરશે</span></li><li><span>ઓટો ઉત્પાદકોને </span><span>Q1\r\nFY26E</span><span>માં ઊંચી ઈનપુટ કોસ્ટ અને ઓપરેશનલ પડકારોથી દબાણનો સામનો\r\nથશે</span></li><li><span>PLI </span><span>યોજનામાં ઈલેક્ટ્રોનિક્સ અને ફાર્મા ક્ષેત્રે </span><span>FY25</span><span>ના કુલ ભુકતાનમાં </span><span>70%</span><span> ભાગ</span></li><li><span>મારિકો </span><span>2030</span><span> સુધીમાં </span><span>₹</span><span>20,000</span><span> કરોડનું </span><span>FMCG\r\n</span><span>બ્રાન્ડ બનવાની યોજના ધરાવે છે</span></li><li><span>સરકાર કોલ પાવર\r\nપ્લાંટ માટેનું ઓછી સલ્ફર ઉત્સર્જન નિયમ નરમ કરે છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>DLF </span><span>રહેણાક અને\r\nવ્યાવસાયિક ક્ષેત્રમાં મજબૂત લોન્ચ યોજના પર નજર રાખે છે</span></li><li><span>ભારતે</span><span>વિદેશી</span><span>ડ્રિલિંગ</span><span>કંપનીઓ</span><span>પાસેથી</span><span>ટેન્ડર</span><span>મેળવવા</span><span>માટે</span><span>મોટી</span><span>દાવપેચ</span><span>લગાવી</span></li><li><span>VinFast </span><span>તમિલનાડુ\r\nફેક્ટરીમાં ઉત્પાદન શરૂ કરશે</span><span>, </span><span>ઓગસ્ટમાં ડિલિવરી શરૂ</span></li><li><span>યુરોપિયન</span><span>યુનિયન</span><span>retaliatory </span><span>ટેરિફ્સ મૂકવાની વિલંબ કરે છે</span><span>, </span><span>1 ઓગસ્ટ પહેલા સમાધાનની આશા</span></li><li><span>InGovern </span><span>દ્વારા </span><span>REL</span><span>માં ગવર્નન્સ અંગે ચિંતા વ્યક્ત</span><span>, ESOP </span><span>ક્લૉબેક પર સવાલ</span></li><li><span>પંજાબ</span><span>એન્ડ</span><span>સિંધ</span><span>બેંક</span><span>અને</span><span>ઇન્ડિયન</span><span>ઓવરસીઝ</span><span>બેંકે</span><span>₹</span><span>500 </span><span>કરોડથી</span><span>વધુની</span><span> 20</span><span> NPA </span><span>વેચાણ માટે મૂક્યો</span></li><li><span>CCI </span><span>એ એશિયન પેઇન્ટ્સ\r\nવિરુદ્ધની તપાસનું આદેશ સુધાર્યો</span><span>, </span><span>અગાઉના નિષ્કર્ષ દૂર કર્યા</span></li><li><span>કરચૂકડાઓએ</span><span>FY</span><span>25માં કુલ વસુલાતના 17.6% હિસ્સો આપ્યો</span><span>, </span><span>ચુકવણી સમયગાળો ઘટ્યો</span></li><li><span>પવન</span><span>અને</span><span>સોલાર</span><span>પ્લાન્ટ</span><span> (50</span><span> MW </span><span>કે વધુ) પર હવામાન મોનિટરિંગ સ્ટેશન\r\nસ્થાપવાની જરૂર: </span><span>CEA</span></li><li><span>યુદ્ધના</span><span>ભ</span><span>ય વચ્ચે જૂનમાં\r\nભારતના રશિયાથી તેલ આયાતમાં 11 મહિનાનો ઉચ્ચતમ સ્તર</span></li><li><span>CAG </span><span>અને </span><span>Janaagraha </span><span>વચ્ચે નગરલોક નાણાકીય વ્યવસ્થા અને ડિજિટલ ઓડિટ મજબૂત કરવા </span><span>MoU</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>FSSAI</span><span>એ ફૂડ બિઝનેસને ખોટી કે ભ્રમિત વાર્ષિક રિટર્ન ફાઇલ નહીં\r\nકરવા ચેતવણી આપી</span></li><li><span>TCS</span><span>નું ધ્યેય વેતન વધારો અને નફાકારક વૃદ્ધિ: </span><span>CFO</span></li><li><span>ઓલાના ટોચના ઇલેક્ટ્રિક સ્કૂટર વેચાતા રાજ્યમાં 90% શોરૂમ બંધ થશે</span></li><li><span>FGD </span><span>નિયમમાં છૂટછાટથી વીજળીની કિંમત 25-30 પૈસા પ્રતિ યુનિટ\r\nઘટશે</span></li><li><span>સિપ્લા ભારતના વેઈટ મેનેજમેન્ટ સેગમેન્ટમાં પ્રવેશ કરશે: એમ.ડી. ઉમંગ વોહરા</span></li><li><span>Nvidia</span><span>ના </span><span>CEO </span><span>જેન્સન હુઆંગ 16 જુલાઈએ બેઇજિંગમાં મીડિયા બ્રિફિંગ કરશે</span></li><li><span>Blip </span><span>ફાસ્ટ ફેશન ડિલિવરી સ્ટાર્ટઅપ બંધ કરવાનો મુશ્કેલ નિર્ણય\r\nલેવાયો: </span><span>Cofounder </span><span>અંશ અગરવાલ</span></li><li><span>Cisco</span><span>ના ચીફ ચક રોબિન્સનું માનવું છે કે સકારાત્મક ભેદભાવ (</span><span>affirmative action) </span><span>વધુ સારા બિઝનેસ માટે મદદરૂપ</span></li><li><span>JPMorgan</span><span>એ ફિનટેક કંપનીઓને ગ્રાહક ડેટા માટે ચૂકવણી કરવાની માગણી\r\nકરી</span></li><li><span>કોસ્ટા કોફી ઇન્ડિયા </span><span>FY</span><span>25 વેચાણમાં 30% વૃદ્ધિ થઈ </span><span>₹</span><span>198 કરોડ</span><span>, </span><span>ગ્રોસ\r\nમાર્જિનમાં થોડી ઘટાડો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhUDBJsruyoWlhbqm9JNvZTrjf_aEy0dSjtUAUpxTPyBJ6Nj-KTwoWY32IzBUgcTrAsYx2q9DyQTFXpjmFw-1p_ulTTkp1_Kf8gxmWj-UGT61WfXV-yyQbanrTzyyhdfDZojMkjlEAgN7J8lKqT-rcsiqvLODhZkOFAFw8j2d4mSWUYKXvt9EGUyqxfcGc','2025-07-14','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(236,'2297891463448603557','Nifty Outlook :- 14.07.2025 - CFA Hitesh Somani',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEh8dtZSrWF5EYYuPLYwHvrhnvn0Tg_MylmPgjHRz2MNHOZMXE6T0hi0-73nmBYCG4NfB29jw4Zp5W1fOX274udE_8pmFXbqO_fDLSdmcniMguPeWKLFZMdyhYUKsNFVvtroHHcZuZAkFthFflZe_vSHY78ymv9TvpI6aCJ6LRQQ0ymhvmd_P4CzqoO4dxY\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEh8dtZSrWF5EYYuPLYwHvrhnvn0Tg_MylmPgjHRz2MNHOZMXE6T0hi0-73nmBYCG4NfB29jw4Zp5W1fOX274udE_8pmFXbqO_fDLSdmcniMguPeWKLFZMdyhYUKsNFVvtroHHcZuZAkFthFflZe_vSHY78ymv9TvpI6aCJ6LRQQ0ymhvmd_P4CzqoO4dxY\" width=\"255\" /></a></b></div><b><span>CFA Hitesh Somani</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#000000;\">MD - Aapka Investments <br /></span></b><b><span style=\"color:#000000;\">Website - https://www.aapkainvestments.in</span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>MARKET\r\nIS WEAK, DOWN 300 TO 400 POINTS. WILL IT RECOVER NEXT WEEK OR GO DOWN FURTHER?</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>\"In\r\nthe first two days of last week, the market performed well, but after that, it\r\ncontinuously declined by 300 to 400 points. Nifty had closed at 25,461 last\r\nweek, and this Friday it closed at 25,150, which is a fall of almost 300 to 350\r\npoints. Looking at this, it is clear that big investors are booking profits at\r\nhigher levels. Next week, we might see further downside, because if Nifty\r\nbreaks the 25,200 level, we could witness a sharp fall. Otherwise, if it goes\r\nup to 25,700, we may see an upward move from there.\"</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>“In\r\nthe last week, Banknifty was flat for the first three days, but in the last two\r\ndays, it also fell by 300 points. However, compared to nifty, Banknifty showed\r\nrelatively stronger performance. If this week banknifty breaks 56000 level, we\r\nmay see a decline in banknifty.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n\r\n\r\n<ul style=\"text-align:left;\"><li><b><span>Major Support Levels for Nifty</span></b><ul><li><ul><li><span>Support 1 – 25000</span></li><li><span>Support 2 – 24800</span></li><li><span>Support 3 – 24500</span></li></ul></li></ul></li></ul><ul style=\"text-align:left;\"><li><b><span>Major Resistance Levels for\r\nNifty</span></b><ul><li><ul><li><span>Resistance 1 – 25400</span></li><li><span>Resistance 2 – 25700</span></li><li><span>Resistance 3 – 26000</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<ul style=\"text-align:left;\"><li><b><span>Major Support Levels for\r\nBanknifty</span></b><ul><li><ul><li><span>Support 1 – 56600</span></li><li><span>Support 2 – 55500</span></li><li><span>Support 3 – 54600</span></li></ul></li></ul></li></ul><ul style=\"text-align:left;\"><li><b><span>Major Resistance Levels for\r\nBanknifty</span></b><ul><li><ul><li><span>Resistance 1 – 57300</span></li><li><span>Resistance 2 – 57700</span></li><li><span>Resistance 3 – 58200</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n<p><b><span>1) COROMANDEL\r\n</span></b></p>\r\n\r\n<div style=\"text-align:left;\"><span>CMP\r\n@ 2320<br /></span><span>Buy\r\nAbove @ 2345<br /></span><span>Stop\r\nLoss Below @ 2190<br /></span><span>Targets\r\n@ 2500, 2635 and 2750</span></div><div style=\"text-align:left;\"><b><span>2) WHIRLPOOL</span></b></div><p><span>CMP\r\n@ 1370 <br />\r\nBuy Above @ 1390<br />\r\nStop Loss @ 1300<br />\r\nTargets @ 1450, 1530 and 1600</span></p><p><b><span>3)\r\nINDUSTOWER</span></b></p>\r\n\r\n<div style=\"text-align:left;\"><span>CMP\r\n@ 400<br /></span><span>Buy\r\nAbove @ 410<br /></span><span>Stop\r\nLoss @ 390<br /></span><span>Targets\r\n@ 430, 480 and 520</span></div>','https://blogger.googleusercontent.com/img/a/AVvXsEh8dtZSrWF5EYYuPLYwHvrhnvn0Tg_MylmPgjHRz2MNHOZMXE6T0hi0-73nmBYCG4NfB29jw4Zp5W1fOX274udE_8pmFXbqO_fDLSdmcniMguPeWKLFZMdyhYUKsNFVvtroHHcZuZAkFthFflZe_vSHY78ymv9TvpI6aCJ6LRQQ0ymhvmd_P4CzqoO4dxY','2025-07-14','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(237,'4515598891306709570','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૧ જુલાઇ ૨૦૨૫',NULL,'<h2 style=\"text-align:center;\"> <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjQmOewMcFSvEsrMyarYMNq6mEEgrS8XNW03CZRk0OqO-9V2BSvECAQ4HGnMc15weoc5A1XopPtpNavp2JnWcYRKUY4WLA2mAEoB0rwm5_-TtYJCHl7mHFNRWB7yz4DXMOd8PGaTJoVfegY9ubzrzpFhGeUxusSphY49UlbtlIFxDhRnmA8DKvt--eyJHs\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjQmOewMcFSvEsrMyarYMNq6mEEgrS8XNW03CZRk0OqO-9V2BSvECAQ4HGnMc15weoc5A1XopPtpNavp2JnWcYRKUY4WLA2mAEoB0rwm5_-TtYJCHl7mHFNRWB7yz4DXMOd8PGaTJoVfegY9ubzrzpFhGeUxusSphY49UlbtlIFxDhRnmA8DKvt--eyJHs\" width=\"281\" /></a><br /></h2><div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">-:</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>કેન્દ્ર સરકારે પૂર\r\nઅને ભૂસ્ખલનથી પ્રભાવિત રાજ્યો માટે 1,066 કરોડ રૂપિયા ફાળવ્યા</span></li><li><span>TCS Q</span><span>1 પરિણામ: નફો 6% વધીને 12,760 કરોડ રૂપિયા</span><span>;\r\n</span><span>શેર દીઠ 11 રૂપિયા ડિવિડન્ડ જાહેર</span></li><li><span>કેન્દ્રે</span><span>eNAM </span><span>પ્લેટફોર્મ પર 7\r\nનવા ઉત્પાદનો ઉમેર્યા</span></li><li><span>NIIF </span><span>$1 બિલિયન પ્રાઈવેટ માર્કેટ્સ ફંડ </span><span>II</span><span>ના $700 મિલિયનના પ્રથમ ક્લોઝર માટે તૈયાર</span></li><li><span>GACM </span><span>ટેક્નોલોજી બોર્ડે 200 કરોડ રૂપિયા સુધીના </span><span>QIP\r\n</span><span>ઈશ્યૂને મંજૂરી આપી</span></li><li><span>ખાનગી</span><span>ARC</span><span>નું </span><span>AUM\r\n</span><span>રિડમ્પશન વધવાથી 4-6% ઘટી શકે: ક્રિસિલ રેટિંગ્સ</span></li><li><span>LIC</span><span>ની જૂન મહિનાની વ્યક્તિગત પ્રીમિયમ આવકમાં 14.6%નો વધારો</span></li><li><span>મણિપાલ</span><span>હેલ્થે</span><span> 6,400 </span><span>કરોડ</span><span>રૂપિયામાં</span><span>સહ્યાદ્રી</span><span>હોસ્પિટલ્સ</span><span>ખરીદી</span></li><li><span>પેનિન્સુલા</span><span>લેન્ડે</span><span> 765 </span><span>કરોડના</span><span>રિયલ્ટી</span><span>પ્લેટફોર્મ</span><span>હેઠળ</span><span>અલીબાગ</span><span>, </span><span>કરજતમાં 40 એકર\r\nજમીન ખરીદી</span></li><li><span>ક્વિક</span><span>-</span><span>કોમર્સ</span><span>ઓર્ડર</span><span>FY</span><span>25માં બમણા થઈને\r\n64,000 કરોડ રૂપિયા</span><span>, FY</span><span>28 સુધીમાં 2 લાખ કરોડ થશે: રિપોર્ટ</span></li><li><span>HCLTech </span><span>એ ડ્યુનડિન સિટી કાઉન્સિલ સાથે 10-વર્ષનો ડિજિટલ\r\nટ્રાન્સફોર્મેશન કરાર કર્યો</span></li><li><span>ફિનટેક</span><span>iCapital</span><span>નું નવીનતમ\r\nફંડરેઝમાં $7.5 બિલિયનથી વધુનું મૂલ્યાંકન</span></li><li><span>Saas </span><span>ફિનટેક પ્લેટફોર્મ આર્ટેરિયા ટેક્નોલોજીસે </span><span>ICICI\r\n</span><span>વેન્ચર પાસેથી 100 કરોડ રૂપિયા એકત્ર કર્યા</span></li><li><span>પાર્ટનર્સ</span><span>ગ્રૂપે</span><span> 1,950 </span><span>કરોડ</span><span>રૂપિયામાં</span><span>ઈન્ફિનિટી</span><span>ફિનકોર્પમાં</span><span>બહુમતી</span><span>હિસ્સો</span><span>ખરીદ્યો</span></li><li><span>ફેરેરો</span><span> 3.1 </span><span>બિલિયન</span><span>ડોલરમાં</span><span>સીરિયલ</span><span>ઉત્પાદક</span><span>WK </span><span>કેલોગ ખરીદશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>આનંદ</span><span>રાઠી</span><span>વેલ્થનો</span><span>Q</span><span>1 નફો 28% વધીને 94 કરોડ રૂપિયા</span><span>, </span><span>આવક 16% વધી</span></li><li><span>125 પ્રવાસી\r\nઅબજોપતિઓ અમેરિકાની $1.3 ટ્રિલિયન સંપત્તિ ધરાવે છે</span></li><li><span>ઉત્તર</span><span>પ્રદેશ</span><span>સરકારે</span><span>Q</span><span>1</span><span>\r\nFY</span><span>26માં 27,858 કરોડ રૂપિયાનું કર આવક એકત્ર કરી</span></li><li><span>દીપક</span><span>ફર્ટિલાઈઝર્સે</span><span>પેટ્રોનેટ</span><span>LNG </span><span>સાથે રિગેસિફિકેશન\r\nમાટે કરાર કર્યો</span></li><li><span>ગ્લેનમાર્ક</span><span>ફાર્માની</span><span>યુનિટ</span><span>,\r\n</span><span>એબવીએ કેન્સર દવા માટે વૈશ્વિક લાઇસન્સિંગ ડીલ કરી</span></li><li><span>એમેઝોન</span><span>એન્થ્રોપિકમાં</span><span>અન્ય</span><span>બહુ</span><span>-</span><span>અબજ</span><span>ડોલરનું</span><span>રોકાણ</span><span>વિચારે</span><span>છે</span></li><li><span>રૂપિયો</span><span>ત્રીજા</span><span>સત્રમાં</span><span>સતત</span><span>આગળ</span><span>વધ્યો</span><span>;\r\n</span><span>3 પૈસા વધીને 85.65/</span><span>$ </span><span>પર બંધ</span></li><li><span>ફિઝિક્સવાલાહ</span><span>અને</span><span>YCMOU</span><span>એ ક્રેડિટ-આધારિત ઓનલાઇન ડિગ્રી ઓફર કરવા હાથ મિલાવ્યા</span></li><li><span>HoABL, </span><span>મિત્તલ બિલ્ડર્સ નાયગાંવમાં 2,000 કરોડનું ટાઉનશિપ સહ-વિકાસ\r\nકરશે</span></li><li><span>ગ્રો</span><span>અને</span><span>ઝેરોધાને</span><span>મોટો</span><span>ફટકો</span><span>,\r\n</span><span>ટોચના બ્રોકર્સમાંથી 20 લાખ સક્રિય રોકાણકારો બહાર નીકળ્યા</span></li><li><span>IPO-</span><span>બાઉન્ડ ઓયો બિઝનેસ ટ્રાવેલ ઓફરિંગ્સ વધારવા યાત્રા સાથે\r\nભાગીદારી કરે છે</span></li><li><span>સરકાર</span><span>OMCs </span><span>માટે 30,000 કરોડની\r\n</span><span>LPG\r\n</span><span>રાહતને એક્સાઇઝ ફંડ દ્વારા મંજૂરીની નજીક</span></li><li><span>પુરવનકરાએ</span><span>પૂર્વ</span><span>બેંગલુરુમાં</span><span> 1,000 </span><span>કરોડના</span><span>હાઉસિંગ</span><span>પ્રોજેક્ટ</span><span>માટે</span><span>JDA\r\n</span><span>કર્યું</span></li><li><span>બેન</span><span>કેપિટલે</span><span>એમ્બેસી</span><span>ઓફિસ</span><span>પાર્ક્સ</span><span>REIT</span><span>માં 1.9% હિસ્સો 691 કરોડમાં વેચ્યો</span></li><li><span>F&amp;O </span><span>ટર્નઓવરમાં 21% ઘટાડો</span><span>, </span><span>જેન સ્ટ્રીટ પ્રતિબંધની અસર બજારમાં</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ફાઇનાન્સિયલ\r\nએક્સપ્રેસ :</span></b></span></p>\r\n\r\n<ul><li><span>ભારત અમેરિકન સ્ટીલ</span><span>, </span><span>એલ્યુમિનિયમ\r\nપર $3.83 બિલિયનની વધારાની ડ્યુટી લાદવાનું વિચારે છે</span></li><li><span>H-</span><span>1</span><span>B </span><span>કામદારો</span><span>, </span><span>વિદ્યાર્થીઓ\r\nઅને પ્રવાસીઓ માટે યુએસ વિઝાની કિંમત 100%થી વધુ વધી</span></li><li><span>શહેરી </span><span>FMCG </span><span>મૂલ્ય વૃદ્ધિ છ ક્વાર્ટરમાં પ્રથમ વખત ગ્રામીણ વૃદ્ધિને\r\nવટાવી</span></li><li><span>ટાટા એલક્સી </span><span>Q</span><span>1 પરિણામ: </span><span>FY</span><span>26ની નબળી\r\nશરૂઆત</span><span>, </span><span>નફો 21.57% ઘટ્યો</span><span>; </span><span>મોટા સોદા</span><span>, </span><span>સેક્ટર રિકવરી આશા આપે છે</span></li><li><span>સરકાર </span><span>LIC</span><span>માં ઓફર ફોર સેલ દ્વારા લઘુમતી હિસ્સો વેચવાનું વિચારે છે:\r\nરિપોર્ટ</span></li><li><span>IREDA Q</span><span>1</span><span>FY</span><span>26 પરિણામ: નેટ નફો 36 ટકા ઘટ્યો</span></li><li><span>વહેલા ચોમાસાને કારણે જળાશયોનું પાણીનું સ્તર 95% વધ્યું</span></li><li><span>CPSEs, NHAI </span><span>અને રેલવેનું </span><span>Q</span><span>1માં કેપેક્સ 15% વધ્યું</span></li><li><span>ભારત-યુએસ હજુ વેપાર સોદા પર ચર્ચા કરી રહ્યા છે</span><span>, </span><span>ટીમ\r\nઆગામી સપ્તાહે વોશિંગ્ટન જશે</span></li><li><span>કેનરા બેંકે અનિલ અંબાણીના લોન ખાતા પરથી ફ્રોડનું ટેગ હટાવ્યું: રિપોર્ટ</span></li><li><span>ટેલિકોમ ઉદ્યોગ </span><span>FY</span><span>30 સુધી 9.8%</span><span> AGR CAGR </span><span>નોંધાવશે</span><span>, ICICI </span><span>સિક્યોરિટીઝ - ટેરિફ વધારો</span><span>, </span><span>ડેટા\r\nવપરાશ</span><span>, </span><span>અન્ય પરિબળો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ટેમાસેકે ગયા વર્ષે યુરોપમાં $7.8 બિલિયનનું રોકાણ કર્યા બાદ વધુ તકો જુએ છે</span></li><li><span>ટેરિફ અનિશ્ચિતતાને કારણે યુરો ઝોન સરકારી બોન્ડ્સ પર નિયંત્રણ</span></li><li><span>રાજ્ય સરકારોએ વિજ્ઞાન અને ટેકનોલોજી કાઉન્સિલને પૂરતું ફંડ પૂરું પાડવું જોઈએ:\r\n</span><span>NITI </span><span>રિપોર્ટ</span></li><li><span>EU</span><span>એ\r\nશક્તિશાળી </span><span>AI </span><span>મોડેલ્સને નિયંત્રિત કરવા માટે ભલામણો જાહેર કરી</span></li><li><span>NPCI </span><span>રૂપે ક્રેડિટ કાર્ડ્સ પર મોટું દાવ લગાવે છે</span><span>, </span><span>બેંકોને\r\nઆકર્ષક પર્ક્સ ઓફર કરે છે</span></li><li><span>જેન્સન હુઆંગે 2025માં $27.6 બિલિયન નેટવર્થ ઉમેરી</span><span>, </span><span>નવીડિયાએ\r\nઈતિહાસ રચ્યો</span></li><li><span>ભારતી સ્પેસ યુટેલસેટમાં વધારાના 1</span><span>,</span><span>200 કરોડ\r\nરૂપિયાનું રોકાણ કરશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjQmOewMcFSvEsrMyarYMNq6mEEgrS8XNW03CZRk0OqO-9V2BSvECAQ4HGnMc15weoc5A1XopPtpNavp2JnWcYRKUY4WLA2mAEoB0rwm5_-TtYJCHl7mHFNRWB7yz4DXMOd8PGaTJoVfegY9ubzrzpFhGeUxusSphY49UlbtlIFxDhRnmA8DKvt--eyJHs','2025-07-11','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(238,'157124788332852592','Research Report : Indian Financial Markets Outlook - 11th July 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhsFyMLL5Ys8T4saaHAR70n4dttCVglKWefzqhBZTbbkhtW6wivgcozOLUs-l1Alrj-wBkrk8e7BzxdYyBhQ6FytsC_-ztpxa8UCKTfqip721X93H8sXV6GjIS5AexFEDijT6OD9M6XT6jxM5-iI8g6M1p_CG7P-au-IoySobhfs5a3_0ntr3xaWfmMDmQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhsFyMLL5Ys8T4saaHAR70n4dttCVglKWefzqhBZTbbkhtW6wivgcozOLUs-l1Alrj-wBkrk8e7BzxdYyBhQ6FytsC_-ztpxa8UCKTfqip721X93H8sXV6GjIS5AexFEDijT6OD9M6XT6jxM5-iI8g6M1p_CG7P-au-IoySobhfs5a3_0ntr3xaWfmMDmQ\" width=\"240\" /></a></div><div style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">More\r\ntariff threat from Donald Trump keep markets nervous Most</span></p>\r\n\r\n\r\n\r\n<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgBNGGZX5lKoRdZ-S9NE_3pHJK40ubBjYJgQw_7m4fIlx5MRHepTJL5188eF9NvF3JaO02RW_kdrjRLOKDeMdjBNAtfkp0sH8e2jqf07ury_oGiUwS5L3MN6SW8HvTPUkRe49oWqP0YKtGh8KVeRZKw33wJ7VHO_N7015sf0K4jwafIsgg4PHnwyJQXMss\"><img alt=\"\" height=\"313\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgBNGGZX5lKoRdZ-S9NE_3pHJK40ubBjYJgQw_7m4fIlx5MRHepTJL5188eF9NvF3JaO02RW_kdrjRLOKDeMdjBNAtfkp0sH8e2jqf07ury_oGiUwS5L3MN6SW8HvTPUkRe49oWqP0YKtGh8KVeRZKw33wJ7VHO_N7015sf0K4jwafIsgg4PHnwyJQXMss=w558-h313\" width=\"558\" /></a></div><br /><div style=\"text-align:justify;\"><span>Most\r\nof the Asian equities were trading in range as dollar strengthened after\r\nPresident Donald Trump ratcheted up trade tensions yet again by floating a\r\nhigher “blanket tariffs” rate on most trading partners. Nikkei was up 0.3% and\r\nHang Sang was up 0.7% while contracts for the S&amp;P 500 reversed their\r\nearlier gains and fell. S&amp;P 500 futures was down 0.5% and Euro Stoxx 50\r\nfutures was down 0.6% in the early trade. Earlier, the Indian benchmark equity\r\nindices continued to fall for a second session on Thursday, dragged by share\r\nprices of Bharti Airtel Ltd., and HDFC Life Insurance Co.</span></div><div style=\"text-align:justify;\"><span>The\r\nNSE Nifty 50 ended 120.85 points, or 0.47% lower at 25,355.25, while the BSE\r\nSensex closed 345.80 points, or 0.41% down at 83,190.28. During the day, Nifty\r\nfell 0.53% to trade at 25,340.45 and Sensex declined 0.48% to 83,134.97. US\r\nequities closed at a new all-time high on Thursday as investors parsed a slew\r\nof tariff headlines and looked ahead to corporate results that are due to start\r\nnext week.</span></div>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Anand Rathi Q1FY26 (QoQ) - </span></b><span>Revenue at\r\nRs 274 crore versus Rs 222 crore up 23.42%. Net profit at Rs 93.91 crore versus\r\nRs 73.4 crore up 27.42%.<span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">TCS Q1FY26 (QoQ) -</span></b><span>Revenue\r\ndown 1.6% to Rs 63,437 crore versus Rs 64,479 crore. EBIT down 1% at Rs 15,514\r\ncrore versus Rs 15,601 crore.<span style=\"color:#FF0000;\">Negative </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">IREDA Q1 FY26 (YoY) - </span></b><span>NII up 36.02% at Rs 691 crore\r\nversus Rs 508 crore. Net profit down 35.67% at Rs 247 crore versus Rs 384\r\ncrore.<span style=\"color:#FF0000;\"> Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Tata Elxsi Q1FY26 (QoQ) - </span></b><span>Revenue down\r\n1.8% to Rs 892.10 crore versus Rs 908.34 crore. EBIT down 11% to Rs 162.44\r\ncrore versus Rs 182.97 crore.<span style=\"color:#FF0000;\">Negative</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Nifty slipped amid uncertainty over\r\ntariff deal and closed lower at 25,355 on Thursday. Index is heading towards\r\n25,200 while 25,500 is strong resistance now. Today’s range – 25,200 – 25,500.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty too weakened and closed\r\ntad lower to 57K at 56,999 onThursday.\r\nIndex has strong support at 17 day EMA of 56,550 while 57,150 is near term\r\nresistance. Today’s range – 56,550 – 57,150.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhsFyMLL5Ys8T4saaHAR70n4dttCVglKWefzqhBZTbbkhtW6wivgcozOLUs-l1Alrj-wBkrk8e7BzxdYyBhQ6FytsC_-ztpxa8UCKTfqip721X93H8sXV6GjIS5AexFEDijT6OD9M6XT6jxM5-iI8g6M1p_CG7P-au-IoySobhfs5a3_0ntr3xaWfmMDmQ','2025-07-11','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(239,'4907666067527838144','Research Report : Indian Financial Markets Outlook - 10th July 2025',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjhsmb75HYy7bZQqYXe1xWGrNTOs3pV0aUJMGESoCJCjBpNNB0hAi-lDFvzYVTkITnrCVK_rJSKjqG0nL_qowclG3psbk-3syfrrvMDpYiuUIMJPtbPvRp569LpSwF_xwiIIi2pvoK_zyrjYWAByX-6-AFU8BxLANn-dcHXAGYyEgYQdc1AA3t55B6AQi4\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjhsmb75HYy7bZQqYXe1xWGrNTOs3pV0aUJMGESoCJCjBpNNB0hAi-lDFvzYVTkITnrCVK_rJSKjqG0nL_qowclG3psbk-3syfrrvMDpYiuUIMJPtbPvRp569LpSwF_xwiIIi2pvoK_zyrjYWAByX-6-AFU8BxLANn-dcHXAGYyEgYQdc1AA3t55B6AQi4\" width=\"240\" /></a></b></div><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt</span></b></div><div style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Six\r\nmore countries received <b>Tariff</b> letter, market shrugged off</span></p><div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiUlW7DCUjixDjcVPpuP8BlG5Bb01lQK6Z2XSlmgKQ4f-bXpuui6xRTuqL3Q7V6ebFub6IMwFPECiCFwPusY8DWCFeSLYLxWex3FEiCULhX6LCNoznxBO6x2tQv18rsv-8JNXsIzyWuXrCqL7dI3kz9rqz-_6a7---CjlD7kFa-PEyXRIgkrtZPKHXXziM\"><img alt=\"\" height=\"181\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiUlW7DCUjixDjcVPpuP8BlG5Bb01lQK6Z2XSlmgKQ4f-bXpuui6xRTuqL3Q7V6ebFub6IMwFPECiCFwPusY8DWCFeSLYLxWex3FEiCULhX6LCNoznxBO6x2tQv18rsv-8JNXsIzyWuXrCqL7dI3kz9rqz-_6a7---CjlD7kFa-PEyXRIgkrtZPKHXXziM\" width=\"320\" /></a></div></div><p style=\"text-align:justify;\"><span>In\r\nthe morning session, Asia Pacific markets were traded in range in the opening\r\nwhile Bitcoin zoomed past record high after rise in technology stocks in USA.\r\nUS equities closed higher Wednesday on the back of mega-cap technology names.\r\nThe S&amp;P 500 Index gained 0.6%, with eight of the eleven sectors were in\r\ngreen, and advances led by utilities and information technology. The Nasdaq\r\nclimbed 0.7%, and the Dow Jones Industrial Average advanced 0.5%. Nvidia Corp.\r\nbecame the first company in history to achieve a $4 trillion market valuation –\r\nclose to India’s GDP! </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty is trading 38 points higher at 25,568 in the morning, indicating a\r\npositive start for the benchmark Nifty 50 later in the morning. Oil steadied as\r\ntraders weighed a large increase in US crude stockpiles and a wave of new\r\ntariff rates from President Donald Trump. WTI held above $68 a barrel after\r\nclosing little changed on Wednesday. Brent Oil settled near $70.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">JSW Energy - </span></b><span>The company has been added to FTSE\r\nRussell’s FTSE4Good Index. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Asian Paints - </span></b><span>The company sold its entire holding\r\nof 20.1 lakh equity shares, or a 4.42% stake, in Akzo Nobel India at Rs 3,651\r\nper share through a bulk deal, amounting to Rs 734 crore.<span style=\"color:#0000FF;\"> Positive</span> </span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Quality Power - </span></b><span>The company and Yash High voltage\r\nhave acquired a 100% stake in Sukrut Electric Company. <span style=\"color:#0000FF;\">Positive\r\n</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Railtel Corporation - </span></b><span>The company received an order\r\nworth Rs 17.5 crore from the Chhattisgarh General Administration Department. <span style=\"color:#0000FF;\">Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY –</span></b><span> Nifty could not sustain above\r\n25,500 and closed lower at 25,476 on Wednesday. Index has been locked in narrow\r\nrange since last nine trading session in anticipation of trade tariff news.\r\nRangebound trading is likely to continue today. Today’s range – 25,350 –\r\n25,650. </span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY –</span></b><span> Bank nifty too traded in narrow\r\nrange of just 250 points and closed steady at 57,213 on Wednesday. Index has\r\nstrong support at 17 day EMA of 56,650 while 57,550 is near term resistance.\r\nToday’s range – 56,950 – 57,500.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjhsmb75HYy7bZQqYXe1xWGrNTOs3pV0aUJMGESoCJCjBpNNB0hAi-lDFvzYVTkITnrCVK_rJSKjqG0nL_qowclG3psbk-3syfrrvMDpYiuUIMJPtbPvRp569LpSwF_xwiIIi2pvoK_zyrjYWAByX-6-AFU8BxLANn-dcHXAGYyEgYQdc1AA3t55B6AQi4','2025-07-10','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(240,'5085769532676245456','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૧૦ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhQAnUfNA0IbKB676JiDdEjERYPoZvquxnSwpbebaC_JkShYnl3_U0KGBSdPAHEj3UkscP_d02OR9QT92FKTtzJNzArerO2JRnV1ZONd53jN2RBv7Td0EtiTYBoKN49ROmY5WtJajfSRVpS2aYc3Vrn38yyprUxpDDNuYBBiqZEjgqSnfkAM1P5FiNRgZQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhQAnUfNA0IbKB676JiDdEjERYPoZvquxnSwpbebaC_JkShYnl3_U0KGBSdPAHEj3UkscP_d02OR9QT92FKTtzJNzArerO2JRnV1ZONd53jN2RBv7Td0EtiTYBoKN49ROmY5WtJajfSRVpS2aYc3Vrn38yyprUxpDDNuYBBiqZEjgqSnfkAM1P5FiNRgZQ\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતે પોતાની\r\nસપ્લાય ચેઇનમાં પથ્થરયુક્ત કોલસા પર ગંભીર પગલાં લીધાં</span></li><li><span>લ્યુપિનએ ઝેન્ટિવા\r\nસાથે </span><span>$50</span><span> મિલિયનનો લાઇસન્સિંગ સોદો કર્યો</span><span>, </span><span>વૈશ્વિક બજારોમાં સર્ટોલિઝુમેબ પેગોલનું વેચાણ કરશે</span></li><li><span>ભારતની રેર અર્થ\r\nલક્ષ્યોને વેગ આપવાની યોજનાએ વેદાંતા</span><span>, JSW</span><span>નું ધ્યાન\r\nખેંચ્યું</span></li><li><span>ગ્રેન્યુલ્સ\r\nઇન્ડિયાએ યુએસમાં </span><span>33,000</span><span> બોટલ બ્લડ પ્રેશર દવા પાછી ખેંચી</span></li><li><span>સાઉદી અરેબિયા </span><span>2026</span><span>થી વિદેશી ખરીદદારો માટે રિયલ એસ્ટેટ બજાર ખોલશે</span></li><li><span>ઇન્ડિયન ઓઇલ - અદાણી\r\nગેસ </span><span>$161</span><span> મિલિયનના એક્સચેન્જેબલ-બોન્ડ વેચાણની યોજના ધરાવે છે</span></li><li><span>મેક્સ હેલ્થકેર</span><span>,\r\n</span><span>એસ્ટન યુનિવર્સિટીએ અદ્યતન શૈક્ષણિક</span><span>,\r\n</span><span>સંશોધન સહકાર માટે ભાગીદારી કરી</span></li><li><span>પ્રેસ્ટિજ\r\nએસ્ટેટ્સનું </span><span>Q1</span><span> પ્રી-સેલ્સ ગાઝિયાબાદ પ્રોજેક્ટના ટેકાથી </span><span>4</span><span> ગણું વધીને </span><span>₹</span><span>12,126</span><span> કરોડ</span></li><li><span>એશિયન પેઇન્ટ્સે\r\nએક્ઝો નોબેલ ઇન્ડિયામાં </span><span>4.42%</span><span> હિસ્સો </span><span>₹</span><span>734</span><span> કરોડમાં વેચ્યો</span></li><li><span>આશરે </span><span>12,500</span><span> મેગાવોટ </span><span>BESS </span><span>પ્રોજેક્ટ્સ\r\nટેન્ડરિંગ હેઠળ</span></li><li><span>રિલાયન્સ-સમર્થિત\r\nકેરએક્સપર્ટ ઇજિપ્તના રાષ્ટ્રીય હેલ્થકેર ડિજિટલ રૂપાંતરણને શક્તિ આપશે</span></li><li><span>એલોન મસ્કના\r\nસ્ટારલિંકને ભારતમાં લોન્ચ માટે અંતિમ નિયમનકારી મંજૂરી મળી</span><span>,\r\n</span><span>સૂત્રો જણાવે છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>આરબીઆઈએ </span><span>VRRR </span><span>હરાજીમાં </span><span>₹</span><span>97,315</span><span> કરોડ સ્વીકાર્યા</span><span>; </span><span>કટ-ઑફ </span><span>5.49%</span><span> સુધી વધ્યો</span></li><li><span>વૈશ્વિક અનિશ્ચિતતાને કારણે ભારત ઇન્કનું </span><span>Q2</span><span> ડીલ\r\nમૂલ્ય </span><span>48%</span><span> ઘટ્યું: </span><span>GT </span><span>ભારત</span></li><li><span>ભારતમાંથી નિકાસ શક્ય</span><span>; </span><span>વૈશ્વિક વેપાર\r\nપર સ્પષ્ટતાની જરૂર: સિસ્કો</span></li><li><span>સેબી વિદેશી અધિકારક્ષેત્રની બહારના સાધનોનું ક્રેડિટ રેટિંગ સ્વીકારી\r\nશકે</span></li><li><span>ઝેપ્ટો નવા ફંડિંગ રાઉન્ડમાં </span><span>$500</span><span> મિલિયન એકત્ર\r\nકરશે</span><span>, </span><span>મૂલ્ય </span><span>$7</span><span> બિલિયન સુધી\r\nપહોંચશે</span></li><li><span>કાર્લાઇલ</span><span>, </span><span>બેક્વેસ્ટ પર </span><span>CCI</span><span>એ સ્પર્ધા\r\nનિયમોનું ઉલ્લંઘન કરવા બદલ </span><span>₹</span><span>4</span><span> લાખનો દંડ ફટકાર્યો</span></li><li><span>આગામી પાંચ વર્ષમાં ડેટા સેન્ટર્સ </span><span>₹</span><span>1.6</span><span> ટ્રિલિયનનું રોકાણ આકર્ષશે: રિપોર્ટ</span></li><li><span>ટેમાસેકે ભારતમાં </span><span>8%</span><span> એક્સપોઝર\r\nવધાર્યું</span><span>, </span><span>ચીનનો હિસ્સો ત્રીજા વર્ષે ઘટ્યો</span></li><li><span>ચીને તાઇવાનના લશ્કર સાથે જોડાયેલી </span><span>8</span><span> કંપનીઓ પર\r\nનિકાસ પ્રતિબંધ લાદ્યો</span></li><li><span>APAC</span><span>ના </span><span>70%</span><span> ઓક્યુપાયર્સ ભારતમાં વેરહાઉસિંગ પોર્ટફોલિયો વિસ્તારવાની\r\nયોજના ધરાવે છે: રિપોર્ટ</span></li><li><span>બર્નસ્ટીનના વ્યૂહરચનાકારો ભારતની આવક અપગ્રેડને શેરબજારની ગતિ વધારનાર માને\r\nછે</span></li><li><span>સેબીએ બ્રોકર સેટલમેન્ટ યોજના શરૂ કરી</span><span>; MSEI </span><span>₹</span><span>1,000 </span><span>કરોડ\r\nએકત્ર કરશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ઇક્વિટી મ્યુચ્યુઅલ ફંડમાં જૂનમાં 24% વૃદ્ધિ સાથે </span><span>₹</span><span>23,587 કરોડનું રોકાણ: </span><span>AMFI</span></li><li><span>ભારત વર્ષના અંત સુધીમાં બિન-ફોસિલ ઇંધણ પાવર ક્ષમતા લક્ષ્ય પૂરું કરી શકે છે</span><span>, </span><span>મનોહર લાલે જણાવ્યું</span></li><li><span>એમિરેટ્સ ટિકિટ બુકિંગ માટે ક્રિપ્ટો પેમેન્ટ વિકલ્પ ઉમેરશે</span><span>, </span><span>સોદો કર્યો</span></li><li><span>ઇન્ટેલ ઓરેગોનમાં 500થી વધુ કર્મચારીઓની છટણી કરશે: રિપોર્ટ</span></li><li><span>ક્રિઝેકે મજબૂત શરૂઆત કરી</span><span>, NSE </span><span>પર </span><span>₹</span><span>281.05 પર લિસ્ટેડ</span><span>, IPO </span><span>ભાવથી\r\n14.71% ઉપર</span></li><li><span>NBFC </span><span>અને વીમા સેગમેન્ટ </span><span>FY</span><span>26ના બીજા\r\nભાગમાં વધુ સારું પ્રદર્શન કરશે: રિપોર્ટ</span></li><li><span>આર્ટેક સોલોનિક્સે કતરથી કરંટ લિમિટિંગ પ્રોટેક્ટર્સનો ઓર્ડર મેળવ્યો</span></li><li><span>ફાર્મા લોબીએ </span><span>\'</span><span>જટિલ</span><span>\' </span><span>નિકાસ નિયમ પર\r\nચિંતા વ્યક્ત કરી</span><span>, </span><span>ફેરફારની માંગ કરી</span></li><li><span>ઝડપી કોમર્સ ફર્મ ઝેપ્ટો $500 મિલિયન સુધી એકત્ર કરે તેવી શક્યતા - રિપોર્ટ</span></li><li><span>ભારતના આયર્ન ઓર પેલેટ ઉત્પાદકોએ ઓમાન દ્વારા ઇરાની આયાત પર અંકુશની માંગ કરી…</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhQAnUfNA0IbKB676JiDdEjERYPoZvquxnSwpbebaC_JkShYnl3_U0KGBSdPAHEj3UkscP_d02OR9QT92FKTtzJNzArerO2JRnV1ZONd53jN2RBv7Td0EtiTYBoKN49ROmY5WtJajfSRVpS2aYc3Vrn38yyprUxpDDNuYBBiqZEjgqSnfkAM1P5FiNRgZQ','2025-07-10','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(241,'6304475656071538848','Research Report : Indian Financial Markets Outlook - 09th July 2025',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjD03MYq6zxeXedVYt2iSRx_rHDi9Qcnb41o6DUXGG2HkGsdAjKhP_f2H0ZzaBOWxqIZ3XtekVZ4S29KvNRcTqlFlpIama9c-OuQ56Uqtnu1uEWx1mD58HaQYdDBfG7-AnLPft6dwAZdHP_exCHMel1VhAEfQkF0fdoqBpNhXEIcv6CyV-T2Eh_BtKhFbc\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjD03MYq6zxeXedVYt2iSRx_rHDi9Qcnb41o6DUXGG2HkGsdAjKhP_f2H0ZzaBOWxqIZ3XtekVZ4S29KvNRcTqlFlpIama9c-OuQ56Uqtnu1uEWx1mD58HaQYdDBfG7-AnLPft6dwAZdHP_exCHMel1VhAEfQkF0fdoqBpNhXEIcv6CyV-T2Eh_BtKhFbc\" width=\"240\" /></a></b></div><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt</span></b></div><div style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div><div style=\"text-align:justify;\"><span style=\"color:#FF0000;text-align:left;\">Volatile\r\nTrump keeps market on edge</span></div><div style=\"text-align:justify;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEg36tDoxwiFnwj01BCcY_CpOdX9K5XMDY3nae2aaS0etNg04I2c5y1ORc4o71dbC31Wt695npuYNzf6qvrDryfNadQmd2tyHFr_EE7f1F6W-iThpRMv7BP44KEwgkGjYSRYQKzuxgEUBmO_c9ZMtWI8t4mUhebf4J150Zzw1P5coPOoT1Yq34igw9vR7Ks\"><img alt=\"\" height=\"311\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEg36tDoxwiFnwj01BCcY_CpOdX9K5XMDY3nae2aaS0etNg04I2c5y1ORc4o71dbC31Wt695npuYNzf6qvrDryfNadQmd2tyHFr_EE7f1F6W-iThpRMv7BP44KEwgkGjYSRYQKzuxgEUBmO_c9ZMtWI8t4mUhebf4J150Zzw1P5coPOoT1Yq34igw9vR7Ks=w542-h311\" width=\"542\" /></a></div><span>Most\r\nof the markets in Asia – Pacific region were trading mixed, while US and\r\nEuropean futures diverged. S&amp;P 500 futures down 0.1% Euro Stoxx futures up\r\n0.2%The GIFT Nifty is trading 25 points lower at 25,579 in the morning,\r\nindicating a muted start for the benchmark. US equities closed slightly lower\r\nTuesday as traders sifted through a trove of trade-related news, including a\r\nwarning from President Donald Trump that there won’t be any extensions to the\r\nnew Aug. 1 tariff deadline, and potential new rates on imports of copper and\r\npharmaceuticals.</span></div>\r\n\r\n<p style=\"text-align:justify;\"><span>Trump\r\nhas threatened to levy 200% duty on pharma products while copper may attract\r\n50% import tariff. Oil steadied as traders weighed signs of swelling US crude\r\nstockpiles and the fallout from President Donald Trump’s tariff regime. Brent\r\nheld near $70 a barrel after a two-day gain, and West Texas Intermediate was\r\naround $68.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Quality Power - </span></b><span>The company has formalised a term\r\nsheet to raise its investment stake in Nebeskie Labs from 14.5% to 26%.<span style=\"color:#0000FF;\"> Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Dixon Technology - </span></b><span>The company has established a\r\n50:50 joint venture named Lightanium Technologies in partnership with Signify\r\nInnovations. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Tata Steel -</span></b><span>The\r\ncompany reported a slight year-on-year dip in crude steel production to 5.26 MT\r\nin the first quarter of fiscal 2026. <span style=\"color:#FF0000;\">Negative</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">5Paisa Capital Q1 FY26 (YoY) - </span></b><span>Net Profit\r\ndown 42.6% at Rs 11.5 crore versus Rs 20.1 crore. Total Income down 24% at Rs\r\n77.7 crore versus Rs 102 crore. <span style=\"color:#FF0000;\">Negative </span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>Late recovery lifted Nifty index to\r\nclose above 25,500 at 25,522 on Tuesday. Index has been under pressure over\r\ntrade tariff news in recent days and uncertainty still continues in absence of\r\ntrade deal announcements. Today’s range – 25,350 – 25,650. </span></li></ul><ul><li><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty zoomed past 57K after\r\nlate buying on private lenders stock to settle at 57,256 on Tuesday. Index has\r\nstrong support at 17 day EMA of 56,650 while 57,550 is near term resistance.\r\nToday’s range – 56,650 – 57,550.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjD03MYq6zxeXedVYt2iSRx_rHDi9Qcnb41o6DUXGG2HkGsdAjKhP_f2H0ZzaBOWxqIZ3XtekVZ4S29KvNRcTqlFlpIama9c-OuQ56Uqtnu1uEWx1mD58HaQYdDBfG7-AnLPft6dwAZdHP_exCHMel1VhAEfQkF0fdoqBpNhXEIcv6CyV-T2Eh_BtKhFbc','2025-07-09','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(242,'8500440565744881206','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૯ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhDLYnaH0DCH2tiG6SB6MGdKkY4Kv6NrCc_DHfQfEQx8cdEvhw5FJotHUkwixF2s-AdwfYl6HEqiKEnfwBgmryjARNTEZwVNX4lKgveuSsNmApL7lfromBm7HBGrFdlsH0pqcBlVouS1AW0mjotsGpArGwqE3uSb6Im_0DAchQL8veA3wz-mddqO7Gwkdk\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhDLYnaH0DCH2tiG6SB6MGdKkY4Kv6NrCc_DHfQfEQx8cdEvhw5FJotHUkwixF2s-AdwfYl6HEqiKEnfwBgmryjARNTEZwVNX4lKgveuSsNmApL7lfromBm7HBGrFdlsH0pqcBlVouS1AW0mjotsGpArGwqE3uSb6Im_0DAchQL8veA3wz-mddqO7Gwkdk\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન :</span></b><b><span style=\"color:#0000FF;\">-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારત </span><span>2026</span><span>થી યુએસમાંથી લગભગ </span><span>10%</span><span> કૂકિંગ ગેસ આયાત કરવાની તૈયારીમાં</span></li><li><span>2020</span><span> પછી પહેલી વખત ભારતની વીજ વપરાશમાં ઘટાડો નોંધાયો</span></li><li><span>ડેકન ગોલ્ડ માઈન્સ\r\nકિર્ગિસ્તાન પ્રોજેક્ટનું શરૂ કરવાનું આયોજન</span></li><li><span>લોઢા ડેવલપર્સે\r\nબિઝનેસ માટે રૂ. </span><span>300</span><span> કરોડ ડિબેન્ચર્સ દ્વારા મેળવ્યા</span></li><li><span>IBM </span><span>એ નવા ચિપ્સ અને સર્વર્સ રજૂ કર્યા – સરળ </span><span>AI\r\n</span><span>ઉદ્દેશ સાથે</span></li><li><span>JioBlackRock\r\n</span><span>મ્યુચ્યુઅલ ફંડે નવા </span><span>8</span><span> ફંડ લોન્ચ કરવા માટે સેબી પાસે મંજૂરી માગી</span></li><li><span>FY25</span><span> બાદ અપોલો ટાયર્સ હવે સાવચેતીભર્યા આશાવાદ સાથે આગળ વધશે</span></li><li><span>વેલક્યુર ડ્રગ્સે </span><span>Q1</span><span>માં </span><span>₹</span><span>300</span><span> કરોડના એક્સપોર્ટ\r\nસોર્સિંગ ઓર્ડર્સ પૂરા કર્યા</span></li><li><span>કેરલ સરકારે તેલ\r\nકાંડ બદલ </span><span>MSC\r\n</span><span>સામે </span><span>$1.1</span><span> બિલિયનનું વળતર\r\nમાગ્યું</span></li><li><span>વિનફાસ્ટે\r\nઇન્ડિયામાં </span><span>EV\r\n</span><span>ચાર્જિંગ અને સર્વિસિંગ માટે રોડગ્રિડ સાથે ભાગીદારી કરી</span></li><li><span>ટાટા મોટર્સના </span><span>Q1</span><span> વૈશ્વિક વેચાણમાં </span><span>9%</span><span> ઘટાડો</span></li><li><span>ઓટો ઘટક ઉદ્યોગે\r\nદુર્લભ ચુંબકીય પદાર્થોની અછત સામે રાષ્ટ્રીય નીતિની માગણી કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારત ઓસ્ટ્રેલિયા સાથે રેર અર્થ મિનરલ્સ મેળવવા માટે ચર્ચા કરી રહ્યું છે</span></li><li><span>હિન્દુસ્તાન પાવરએ યૂ.પી.માં </span><span>435</span><span> એમડબલ્યુપી\r\nસોલાર પ્રોજેક્ટ પર કામ શરૂ કર્યું</span></li><li><span>KVN </span><span>પ્રોપર્ટીઝ અને એસેટ્ઝ ગ્રૂપે </span><span>₹</span><span>1,000</span><span> કરોડના બ</span><span>ें</span><span>ગલુરુ પ્રોજેક્ટ માટે સહયોગ કર્યો</span></li><li><span>સુહોરા અને </span><span>OSK </span><span>ભારતને હાઇપરસ્પેક્ટ્રલ મેપ પર મૂકવા માટે સહયોગ કરશે</span></li><li><span>MCX 10</span><span> જુલાઈએ ભારતના પ્રથમ ઇલેક્ટ્રિસિટી ફ્યુચર્સ કોન્ટ્રાક્ટ લોન્ચ કરશે</span></li><li><span>હ્યુન્ડાઈ મોટરે આઈઆઈટી મદ્રાસ સાથે હાઈડ્રોજન હબ દ્વારા ભારતના હાઇડ્રોજન\r\nસપનાને મજબૂતી આપી</span></li><li><span>ITC </span><span>એ એગ્રી બિઝનેસમાં વેલ્યુ એડેડ પ્રોડક્ટ્સ દ્વારા વૃદ્ધિ લાવવાનું ટાર્ગેટ\r\nલીધું</span></li><li><span>ભારતભરમાં જમીનની ડિમાન્ડ વધી: </span><span>2025</span><span>ના પ્રથમ\r\nઅર્ધવર્ષમાં </span><span>2,900</span><span> એકર જમીન લેવાઈ – </span><span>2024</span><span> કરતાં વધુ</span></li><li><span>લોઢા ડેવલપર્સે ઘર બનાવવા માટે પાંચ જમીનના ટુકડા ખરીદ્યા – કુલ મૂલ્ય </span><span>₹</span><span>22,700</span><span> કરોડ</span></li><li><span>JSW </span><span>ઇન્ફ્રાએ </span><span>₹</span><span>740</span><span> કરોડનો કોલકાતા પોર્ટ પ્રોજેક્ટ મેળવ્યો</span></li><li><span>FATF </span><span>મુજબ ઇ-કોમર્સ અને ઓનલાઈન પેમેન્ટ પ્લેટફોર્મ ટેરર ફાઇનાન્સિંગ માટે ઉપયોગ થઈ\r\nરહ્યા છે</span></li><li><span>સેમસંગનો નફો અડધો થયો – </span><span>2023 </span><span>પછી\r\nપહેલી વખત ચિપ બિઝનેસમાં મોટો સંકટ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતની હાઈડ્રોજનની ડિમાન્ડ 2032 સુધી દર વર્ષે 3% વધીને 8.8</span><span> MTPA </span><span>થવાની શક્યતા</span></li><li><span>વેન્ટિવ હૉસ્પિટાલિટી 2030 સુધી મારિયટ સાથે 6 હોટલ શરૂ કરશે</span></li><li><span>લોઢાની પ્રી-સેલ્સ નબળી રહી પરંતુ બિઝનેસ ડેવલપમેન્ટ મજબૂત છે</span></li><li><span>મોનઝોને યુકે રેગ્યુલેટરે નાણાકીય ગુનાઓ અંગે £28 મિલિયન દંડ ફટકાર્યો</span></li><li><span>મોર્ગન સ્ટેનલીએ કહ્યું કે લીલા હોટેલ ભારતના લક્ઝરી હૉસ્પિટાલિટી બૂમનો શ્રેષ્ઠ\r\nપ્રતિનિધિ છે</span></li><li><span>ભારતમાં જૂન મહિને </span><span>EV </span><span>વેચાણમાં\r\n28.6% વધારો થયો – કુલ વેચાણ: 1,80,238</span></li><li><span>ઑસ્ટ્રેલિયાના સેન્ટ્રલ બેંકે રેટ યથાવત રાખીને બજારમાં આશ્ચર્ય પેદા કર્યું</span></li><li><span>અદાણી પાવરે </span><span>NCLT </span><span>મંજૂરી બાદ વિદર્ભ ઈન્ડસ્ટ્રીઝ પાવરનું અધિગ્રહણ પૂરું\r\nકર્યું</span></li><li><span>BMW </span><span>ગ્રૂપ ઇન્ડિયાએ હર્દીપ સિંહ બરારને પ્રમુખ અને </span><span>CEO </span><span>તરીકે નિયુક્ત કર્યા</span></li><li><span>યુએસના બોન્ડ યીલ્ડ વધ્યા છતાં ભારતીય બોન્ડ બજાર શાંતિપૂર્વક રેંજમાં જ</span></li><li><span>ઇન્ડિયન ઓઇલે ન્યૂક્લિયર પાવર માટે નવી વ્યૂહરચના બનાવી રહી છે – અધ્યક્ષ સહને</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhDLYnaH0DCH2tiG6SB6MGdKkY4Kv6NrCc_DHfQfEQx8cdEvhw5FJotHUkwixF2s-AdwfYl6HEqiKEnfwBgmryjARNTEZwVNX4lKgveuSsNmApL7lfromBm7HBGrFdlsH0pqcBlVouS1AW0mjotsGpArGwqE3uSb6Im_0DAchQL8veA3wz-mddqO7Gwkdk','2025-07-09','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(243,'5770193283800511884','Research Report : Indian Financial Markets Outlook - 08th July 2025',NULL,'<div style=\"text-align:center;\"> <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgS4wCVSUHltKuDiMTIHAIvQZ9yoCyn1MVU_3BsOSiW9jmOdJMLtaFaRuUQYRk7Ge1WIht1kUAnA1XaAT-9ZptE4h7U5EdbT3dSGdUQTsTn0Azu85uBFIxEkgxVva_-mgpJu39NQ0VENVPVGdsm2vdVrPvQ5gMpeDsaYM0sv_S9h6g-SCav7IBpeVAEQqM\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgS4wCVSUHltKuDiMTIHAIvQZ9yoCyn1MVU_3BsOSiW9jmOdJMLtaFaRuUQYRk7Ge1WIht1kUAnA1XaAT-9ZptE4h7U5EdbT3dSGdUQTsTn0Azu85uBFIxEkgxVva_-mgpJu39NQ0VENVPVGdsm2vdVrPvQ5gMpeDsaYM0sv_S9h6g-SCav7IBpeVAEQqM\" width=\"240\" /></a><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span><span style=\"color:#FF0000;\">Trump imposed 25% tariff on 12 countries but left door\r\nopen for negotiation</span></span></p><div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEivF4nM7aWyTG7SGDlDigBYL_lkkFePAiaPPp-Z-8tDQ59NT37o7Mc-1zpxmK3P5EfIJIAnT7hyJB2QrkBOG2eRXMUuvnrNzDy2LbVho8lB5mWYjNCudUMo-AHdFKnBhr1EaJ_R9cq082bRz-jMsUTVK40umsuawWXvkIVPmTBELmUa3lmFmn3IGJkvA4s\"><img alt=\"\" height=\"311\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEivF4nM7aWyTG7SGDlDigBYL_lkkFePAiaPPp-Z-8tDQ59NT37o7Mc-1zpxmK3P5EfIJIAnT7hyJB2QrkBOG2eRXMUuvnrNzDy2LbVho8lB5mWYjNCudUMo-AHdFKnBhr1EaJ_R9cq082bRz-jMsUTVK40umsuawWXvkIVPmTBELmUa3lmFmn3IGJkvA4s=w533-h311\" width=\"533\" /></a></div></div><br /><div style=\"text-align:justify;\"><span>Asian\r\nPacific stock markets edged higher as Trump left the door open for additional\r\nnegotiations after imposing new tariff rates on partners, including Japan and\r\nSouth Korea. Nikkei was up 0.4% while Kospi gained 1.5% and Hang Seng futures\r\nwas marginally down 0.1% in the morning session. US index futures are\r\nunchanged, while European contracts are marginally lower. Earlier, US markets\r\ntumbled yesterday after Trump imposed over 25% additional tariff on 12\r\ndifferent countries including Japan and S.Korea.</span></div>\r\n\r\n<p style=\"text-align:justify;\"><span>Markets\r\nare nervous over unpredictable Trump policies. S&amp;P 500 futures flat Euro\r\nStoxx 50 futures fell 0.1% Oil steadied as investors turned their attention to\r\nthe potential fallout from US levies and an escalation of hostilities in the\r\nRed Sea. Brent held near $69 a barrel after advancing 1.9% on Monday, and West\r\nTexas Intermediate was traded below $68. The GIFT Nifty is trading 20 points\r\nlower at 25,508 points as in the morning, indicating a flat start for the\r\n50-stock benchmark later in the morning.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Mahindra &amp; Mahindra - </span></b><span>The Company\r\nreported that its sales surged by 14% year-on-year in June 2025. <span style=\"color:#0000FF;\">Positive </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Macrotech Developers - </span></b><span>The company\r\nin its quarterly business update reported pre-sales growth of 10% yearon- year\r\nat Rs 4,450 crore while collections grew by 7% year-on-year to 2,880 crore. <span style=\"color:#0000FF;\">Positive </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Kotak Mahindra Bank - </span></b><span>The lender’s net advances for\r\nthe quarter ended June 30 grew by 14%. <span style=\"color:#0000FF;\">Positive </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NLC India - </span></b><span>The Company approved to make an\r\ninvestment of up to Rs 1,631 crore in one or more tranches. <span style=\"color:#0000FF;\">Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY - </span></b><span>The Nifty index traded in narrow\r\nrange to settle unchanged at 25,461 on Monday. Index remained under pressure\r\nover uncertainty on trade deal with USA. Any announcement of deal will gyrate\r\nindex on either side. Today’s range – 25,350 – 25,550.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY - </span></b><span>Bank nifty too traded in range to\r\nsettle marginally lower at 56,949 on Monday. Index has strong support at 17 day\r\nEMA of 56,590 while 57,150 is near term resistance. Today’s range – 56,600 –\r\n57,150.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgS4wCVSUHltKuDiMTIHAIvQZ9yoCyn1MVU_3BsOSiW9jmOdJMLtaFaRuUQYRk7Ge1WIht1kUAnA1XaAT-9ZptE4h7U5EdbT3dSGdUQTsTn0Azu85uBFIxEkgxVva_-mgpJu39NQ0VENVPVGdsm2vdVrPvQ5gMpeDsaYM0sv_S9h6g-SCav7IBpeVAEQqM','2025-07-08','active','2026-09-25 07:55:44','2026-09-25 07:55:44');
INSERT INTO `expert_posts` VALUES
(244,'5256339164637345987','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૮ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgbl1mGZMRt87oiDLcDmcDTK1J9yGdRfECikFZp1J7e17vSZlkBF-GRAVzgxNueMXkGr3SEeRp7rUm9RqBgNqVWNB-zO5StemX6IYmwoEFtpgDFbXdeHmQdG8TtT1GQFH93yUqo6z-wSoNv8VUpYBgKmdzqmS8pUjVpLxNPyO4GOAmyQnpEZUrd3N65crE\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgbl1mGZMRt87oiDLcDmcDTK1J9yGdRfECikFZp1J7e17vSZlkBF-GRAVzgxNueMXkGr3SEeRp7rUm9RqBgNqVWNB-zO5StemX6IYmwoEFtpgDFbXdeHmQdG8TtT1GQFH93yUqo6z-wSoNv8VUpYBgKmdzqmS8pUjVpLxNPyO4GOAmyQnpEZUrd3N65crE\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન :</span></b><b><span style=\"color:#0000FF;\">-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>સરકાર અમેરિકા\r\nતરફથી આવકશુલ્ક ઘટાડાની માંગ વચ્ચે સફરજન આયાત રક્ષણનો પુનર્વિચાર કરી રહી છે</span></li><li><span>મોસમી</span><span>ધીમી</span><span>અસરથી</span><span>જૂનમાં</span><span>ઈંધણની</span><span>માંગમાં</span><span> 4.7% </span><span>ઘટાડો</span></li><li><span>ટાટા</span><span>સ્ટીલ</span><span>ઈન્ક્વિક</span><span>સાથે</span><span>ભાગીદારી</span><span>કરીને</span><span>ભારતમાં</span><span>ઝડપી</span><span>બ્રિજ</span><span>નિર્માણ</span><span>માટે</span><span>મોડ</span><span>્યુલર બ્રિજ ટેક્નોલોજી લાવશે</span></li><li><span>2025</span><span>માં</span><span>ઓફિસ</span><span>માર્કેટ</span><span> 39.45 </span><span>મિલિયન</span><span>સ્ક્વેર</span><span>ફૂટ</span><span>લીજ</span><span>સાથે</span><span>રેકોર્ડ</span><span>વાર્ષિક</span><span>વોલ્યૂમ</span><span>તરફ</span></li><li><span>બિગબાસ્કેટે</span><span>મનીષ</span><span>બજરિયા</span><span>ને</span><span>CFO </span><span>તરીકે નિમણુંક આપી</span></li><li><span>ઇલેક્ટ્રોનિક</span><span>વેસ્ટ</span><span>નિયમોને</span><span>લઈ</span><span>કેરિયર</span><span>કંપનીએ</span><span>ભારત</span><span>સામે</span><span>કેસ</span><span>કર્યો</span></li><li><span>એપલે</span><span>યુરોપીયન</span><span>યુનિય</span><span>નના </span><span>₹</span><span>4,900 </span><span>કરોડના</span><span>એન્ટીટ્રસ્ટ</span><span>દંડ</span><span>વિરુદ્ધ</span><span>અદાલતમાં</span><span>લડત</span><span>આપી</span></li><li><span>જૂન</span><span>ક્વાર્ટરમાં</span><span>ગોલ્ડ</span><span>લોન</span><span>સૌથી</span><span>ઝડપી</span><span>વધતો</span><span>સેક્યુરિટાઈઝેશન</span><span>સેગમેન્ટ</span><span>બન્યો</span></li><li><span>પ્રાદેશિક</span><span>ગ્રામિણ</span><span>બેંકો</span><span> (</span><span>RRBs)</span><span>નું </span><span>IT\r\n</span><span>એકીકરણ 30 સપ્ટેમ્બર સુધીમાં પૂરુ કરાશે: નાબાર્ડ ચેરમેન</span></li><li><span>જિંદલ</span><span>ઇન્ડિયાને</span><span>ઓડિશામાં</span><span>₹</span><span>3,600 </span><span>કરોડના</span><span>સ્ટીલ</span><span>પ્રોજેક્ટ</span><span>માટે</span><span>મંજૂરી</span></li><li><span>મલ્ટીપ્લેક્સ</span><span>ઉદ્યોગ</span><span>સામેની</span><span>સાચી</span><span>પડકાર</span><span>કિંમત</span><span>નહીં</span><span>પણ</span><span>સમય</span><span>છે</span><span> : </span><span>PVR\r\nInox </span><span>ના સંજીવ બિજલીએ કહ્યું</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></p><ul><li><span>બાયોકોન બાયોલોજિક્સને યૂ.કે. </span><span>MHRA </span><span>પાસેથી\r\n</span><span>biosimilars Vevzuo </span><span>અને </span><span>Evfraxy </span><span>માટે\r\nમંજૂરી મળી</span></li><li><span>GMR </span><span>એરો ટેક્નિકે અકાસા એર સાથે ત્રણ વર્ષની બેઝ મેન્ટેનન્સ ડીલ કરી</span></li><li><span>કલ્યાણ જ્વેલર્સની </span><span>Q1</span><span> આવકમાં </span><span>FY26</span><span>માં </span><span>31%</span><span>નો ઉછાળો</span><span>, </span><span>માગમાં ખામીઓ છતાં વૃદ્ધિ</span></li><li><span>ડિજિટલ ભારત નિધીના આરએન્ડડી તરફ વાળવામાં ટેલિકોઝે ચિંતાનો અવાજ ઉઠાવ્યો</span></li><li><span>ભારતે </span><span>2047</span><span> સુધીમાં મકાઈ ઉત્પાદન બમણું કરવાની ઘોષણા કરી : શિવરાજ\r\nચૌહાણ</span></li><li><span>અમેરિકા</span><span>, </span><span>જાપાન અને હોંગકોંગથી ભારતના રિયલ એસ્ટેટમાં વિદેશી રોકાણ\r\nવધી રહ્યું છે</span></li><li><span>જિયો બ્લેકરોક મ્યુચ્યુઅલ ફંડના </span><span>NFO</span><span>માંથી </span><span>₹</span><span>17,800</span><span> કરોડ\r\nઉઘરાવ્યા</span><span>, </span><span>ટોચના </span><span>35</span><span> ફંડ ઘરોમાં\r\nસ્થાન</span></li><li><span>સેફેક્સ કેમિકલ્સે </span><span>DRHP </span><span>દાખલ\r\nકરી</span><span>, </span><span>ઋણ ઘટાડવા </span><span>₹</span><span>450</span><span> કરોડ ઉઘરાવવાની યોજના</span></li><li><span>FY26</span><span>માં સિમેન્ટ કંપનીઓ દાયકાની સરેરાશ નફાકારકતામાં પરત ફરે તેવી શક્યતા: ક્રિસિલ</span></li><li><span>પુરવંકરા કંપની મુંબઈની </span><span>8</span><span> સોસાયટીઓનું\r\nપુનર્વિકાસ કરશે</span><span>, </span><span>₹</span><span>2,100</span><span> કરોડની </span><span>GDV </span><span>શક્યતા</span></li><li><span>IPO </span><span>માટે તૈયારીમાં રહેલી સ્માર્ટવર્ક્સનો </span><span>FY25</span><span>માં નુકસાન </span><span>₹</span><span>63</span><span> કરોડ થયું</span><span>, </span><span>આવકમાં </span><span>32%</span><span> વૃદ્ધિ</span></li><li><span>જૂનમાં ઓટો રિટેલ સેલ્સમાં </span><span>5%</span><span>નો વધારો</span><span>; </span><span>પેસેન્જર વાહનોમાં </span><span>2.5%</span><span>નો ઉછાળો: </span><span>FADA</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ચીન દક્ષિણબાઉન્ડ બોન્ડ કનેક્ટને બમણું કરીને $139 અબજ સુધી વધારવાનો વિચાર\r\nકરી રહ્યું છે</span></li><li><span>ટાટા સન્સના ચેરમેન જણાવે છે કે “વિશાળ ઉપયોગ સાથે ભારતનું ભવિષ્ય તેજસ્વી છે”</span></li><li><span>નાણાં સેવા સચિવે ફિનટેક કંપનીઓને નાણાંકીય સમાવેશને આગળ ધપાવવા અપીલ કરી</span></li><li><span>સીમેન્સ એનર્જી ઈન્ડિયાનો માર્ચ ક્વાર્ટર નફો 36% વધી </span><span>₹</span><span>246 કરોડ થયો</span></li><li><span>પ્રાઇવેટ ઇક્વિટી કંપનીઓ </span><span>Axis Finance </span><span>માં $1 અબજના ડીલ માટે રસ બતાવી રહી છે</span></li><li><span>સેબી </span><span>AIF </span><span>નિયમોને લઈને ઉદ્યોગના વિરોધ પછી નવા નિયમોના પુનર્વિચાર પર\r\nવિચાર કરી શકે છે</span></li><li><span>MSME </span><span>ઉદ્યોગોને સહેલું બનાવવા માટે સરકાર નાનાં દંડ દૂર કરવાની યોજના ધરાવે છે</span></li><li><span>પ્રેસ્ટિજે કંપની બેંગલોરમાં ટ્રાફિક ટાળવા માટે 1.5 કિ.મી.નું ‘ખાનગી ફ્લાયઓવર’\r\nબનાવશે</span></li><li><span>કેપજેમિની</span><span>, </span><span>એઆઈ ક્ષમતા વધારવા માટે </span><span>WNS </span><span>કંપની ખરીદશે</span><span>, </span><span>ડીલ કિંમત $3.3 અબજ</span></li><li><span>છેલ્લાં 11 વર્ષમાં ખનિજ ક્ષેત્રને વેગ આપવા માટે સરકાર દ્વારા મહત્વપૂર્ણ સુધારાઓ\r\nકરવામાં આવ્યા: રેડ્ડી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgbl1mGZMRt87oiDLcDmcDTK1J9yGdRfECikFZp1J7e17vSZlkBF-GRAVzgxNueMXkGr3SEeRp7rUm9RqBgNqVWNB-zO5StemX6IYmwoEFtpgDFbXdeHmQdG8TtT1GQFH93yUqo6z-wSoNv8VUpYBgKmdzqmS8pUjVpLxNPyO4GOAmyQnpEZUrd3N65crE','2025-07-08','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(245,'1734580813003010016','Nifty Outlook :- 07.07.2025 - CFA Hitesh Somani',NULL,'<p style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEi_eoprZ9haGjwF7BeiG-ZrIRUjZFBk_EPkvOJFmlqO6c_VgdYcldG7gXxfDpt6tfYZaDjnuJnYtHUmzv6avQUBqfInrUx74mrPFTBxYOteuUA2vlRnIm_RZ5Fhz8ug8CNO5F0_f6D4SkxDNpuMkc8bgJaR9OuIsnpy_9V77P04eqAHYIJPDxcS8yBzDUk\"><span style=\"color:#000000;\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEi_eoprZ9haGjwF7BeiG-ZrIRUjZFBk_EPkvOJFmlqO6c_VgdYcldG7gXxfDpt6tfYZaDjnuJnYtHUmzv6avQUBqfInrUx74mrPFTBxYOteuUA2vlRnIm_RZ5Fhz8ug8CNO5F0_f6D4SkxDNpuMkc8bgJaR9OuIsnpy_9V77P04eqAHYIJPDxcS8yBzDUk\" width=\"255\" /></span></a></p><h2 style=\"text-align:center;\"><b><span>CFA Hitesh Somani<br /></span></b><b><span>MD - Aapka Investments <br /></span></b><b><span style=\"color:#000000;\">Website - https://www.aapkainvestments.in</span></b></h2>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#2b00fe;\">MARKETS\r\nTRADED ALMOST FLAT IN THE LAST WEEK. WILL THIS WEEK MARKET FIND THE TREND?</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Last\r\nweek we saw nifty with intraday moves but overall market on the weekly basis\r\nwas flat. Nifty last week close was 25637 while on this Friday close that\r\n25461. Which is almost 150 points negative from previous week which shows that\r\nbig investor book some of the profit at the higher level.in the coming week we\r\ncan expect some big moves on either side if nifty closes above 25650 then we\r\ncan see nifty towards 26000 levels and if it breaks below 25200 levels, we can\r\nexpect the sharp fall towards 24700 levels. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Banknifty\r\nin the last week was comparatively stronger than nifty as hdfc bank broke the\r\nbig level of 2000.If in the coming week hdfc bank manages to close above 2100\r\nthen we may expect banknifty towards a new lifetime high.</span></p><p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n<ul style=\"text-align:left;\"><li><b><span>Major Support Levels for Nifty</span></b><ul><li><ul><li><span>Support 1 – 25400</span></li><li><span>Support 2 – 25000</span></li><li><span>Support 3 – 24700</span></li></ul></li></ul></li></ul><ul><li><b><span>Major Resistance Levels for\r\nNifty</span></b></li></ul><ul style=\"text-align:left;\"><li><ul><li><ul><li><span>Resistance 1 – 25600</span></li><li><span>Resistance 2 – 26000</span></li><li><span>Resistance\r\n3 – 26400</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<ul style=\"text-align:left;\"><li><b><span>Major Support Levels for\r\nBanknifty</span></b><ul><li><ul><li><span>Support 1 – 56600</span></li><li><span>Support 2 – 55800</span></li><li><span>Support 3 – 55100</span></li></ul></li></ul></li></ul><ul style=\"text-align:left;\"><li><b><span>Major Resistance Levels for\r\nBanknifty</span></b><ul><li><ul><li><span>Resistance 1 – 57200</span></li><li><span>Resistance 2 – 57600</span></li><li><span>Resistance\r\n3 – 58200</span></li></ul></li></ul></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n<p><b><span>1) NAUKRI</span></b></p>\r\n\r\n<div style=\"text-align:left;\"><span>CMP\r\n@ 1485<br /></span><span>Buy\r\nAbove @ 1490<br /></span><span>Stop\r\nLoss @ 1445</span></div><div style=\"text-align:left;\"><span>Targets\r\n@ 1525, 1580 and 1630</span></div><div style=\"text-align:left;\"><b><span>2)\r\nHAL</span></b></div><p style=\"margin-left:0in;\"><span>CMP\r\n@c4990<br />\r\nBuy Above 5021<br />\r\nStop Loss @ 4850<br />\r\nTargets @ 5200, 5400 and 5600</span></p><p style=\"margin-left:0in;\"><b><span>3)\r\nGUJGAS</span></b></p><p style=\"margin-left:0in;\"><span>CMP\r\n@ 490</span></p><div style=\"text-align:left;\"><span>Buy\r\nAbove</span><span>@ </span><span>510<br /> </span><span>Stop\r\nLoss @ 460<br /></span><span>Targets\r\n@ 570, 630 and 700</span></div>','https://blogger.googleusercontent.com/img/a/AVvXsEi_eoprZ9haGjwF7BeiG-ZrIRUjZFBk_EPkvOJFmlqO6c_VgdYcldG7gXxfDpt6tfYZaDjnuJnYtHUmzv6avQUBqfInrUx74mrPFTBxYOteuUA2vlRnIm_RZ5Fhz8ug8CNO5F0_f6D4SkxDNpuMkc8bgJaR9OuIsnpy_9V77P04eqAHYIJPDxcS8yBzDUk','2025-07-07','active','2026-09-25 07:55:44','2026-09-25 07:55:44'),
(246,'267050764619021677','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૭ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgLYEUx4n0IHlfdWf32YLcaTnIjvj-mFa0HAFP1yHKWfiEl21TiSrOlvNLuuhU30NvGDN5FcvSSvLy0yJ7Q2HO_hfl-qAR7pucShD8pJjtwUMscwyIAD3vhRyqynJ1D5ZXDutTRiuissDni5TpCiXraxrXes40BjHzt-Cpaz9yLkjK-qsdGsC_drfPFkpM\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgLYEUx4n0IHlfdWf32YLcaTnIjvj-mFa0HAFP1yHKWfiEl21TiSrOlvNLuuhU30NvGDN5FcvSSvLy0yJ7Q2HO_hfl-qAR7pucShD8pJjtwUMscwyIAD3vhRyqynJ1D5ZXDutTRiuissDni5TpCiXraxrXes40BjHzt-Cpaz9yLkjK-qsdGsC_drfPFkpM=w281-h240\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન :</span></b><b><span style=\"color:#0000FF;\">-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>NPCI </span><span>એ મુંબઈના </span><span>BKC </span><span>વિસ્તારમાં </span><span>MMRDA </span><span>પાસેથી </span><span>Rs </span><span>829 કરોડમાં\r\nહેડક્વાર્ટર માટે જમીન ખરીદી</span></li><li><span>બોરોસિલ</span><span>રિન્યુએબલ્સ</span><span>જર્મન</span><span>સબસિડિયરી</span><span>બંધ</span><span>કરવાની</span><span>અરજી</span><span>કરી</span><span>; </span><span>હવે ભારતીય સોલાર ગ્લાસ માર્કેટ પર ધ્યાન</span></li><li><span>તુર્કીશ</span><span>એરલાઈન્સ</span><span>સાથે</span><span>કરાર</span><span>પૂરો</span><span>થયા</span><span>પછી</span><span>ઈન્ડિગો</span><span>ઈસ્તાંબુલ</span><span>ફ્લાઇટ</span><span>ચાલુ</span><span>રાખશે</span><span>; </span><span>કોડશેર યથાવત</span></li><li><span>નિસ્સાન</span><span>ઓપ્પામા</span><span>પ્લાન્ટને</span><span>બંધ</span><span>થવાથી</span><span>બચાવવા</span><span>ફોક્સકોન</span><span>સાથે</span><span>ઇવી</span><span>ઉત્પાદનની</span><span>યોજના</span></li><li><span>ભારતીય</span><span>કંપનીઓ</span><span>માટે</span><span>શ્રીલંકામાં</span><span>વિદેશી</span><span>વિસ્તરણ</span><span>માટે</span><span>સારો</span><span>અવસર</span><span>: </span><span>ITC </span><span>ચીફ</span></li><li><span>આવતા</span><span>વર</span><span>્ષોમાં ભારતીય\r\nમાર્કેટમાંથી વૈશ્વિક આવકમાં 20% યોગદાનની અપેક્ષા: હેટિચ</span></li><li><span>દિલ્હી</span><span>હાઈકોર્ટ</span><span>તુર્કી</span><span>કંપની</span><span>Celebi </span><span>ની સુરક્ષા મંજૂરી રદ સામેની અપીલ પર\r\nચુકાદો આપશે</span></li><li><span>લાંબાગાળાની</span><span>નીતિગત</span><span>સ્થિરતા</span><span>અને</span><span>સમરસતા</span><span>ઓટો</span><span>ઉદ્યોગ</span><span>માટે</span><span>જરૂરી</span><span>: </span><span>સ્ટેલાંટિસ</span><span>ઈન્ડિયા</span><span>CEO</span></li><li><span>હિન્દુસ્ત</span><span>ાન કૉપર </span><span>MP </span><span>માં </span><span>₹</span><span>400 કરોડના નવા કન્સેન્ટ્રેટર પ્લાન્ટની યોજના ધરાવે છે: </span><span>CMD</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>વર્ષના પ્રથમ અર્ધભાગમાં કાર પર ભારે ડિસ્કાઉન્ટ</span><span>, </span><span>ગ્રામીણ\r\nભારતમાં બાઇક વેચાણ મજબૂત રહ્યું</span></li><li><span>એજીઆર દેવું: વોડાફોન આઇડિયાને વધુ રાહત કે ચૂકવણી મટાડવાની સંભાવના ઓછી</span></li><li><span>સુનિલ મિત્તલ અને વોર્બર્ગ પિંકસ હાયર ઇન્ડિયામાં 49% હિસ્સો ખરીદવા માટે તાકી\r\nરહ્યા છે</span><span>, </span><span>ભારે ડિસ્કાઉન્ટ પર</span></li><li><span>હિંદુસ્તાન એરનોટિક્સ (</span><span>HAL) </span><span>ના </span><span>CMD </span><span>મુજબ ભારતમાં બીજું ફાઇટર જેટ ઉત્પાદક હોવાની ખાસ જરૂરિયાત\r\nનથી</span></li><li><span>હાઇડ્રોકાર્બન શોધની લિલામ: </span><span>ONGC </span><span>પેટ્રોબ્રાસ</span><span>, </span><span>બીપી અને રિલાયન્સ સાથે ભાગીદારી કરી શકે</span></li><li><span>વૈશ્વિક કંપનીઓ એનટિપીસી સાથે મહા ન્યુક્લિયર પ્રોજેક્ટ માટે ભાગીદારી કરવા\r\nઈચ્છુક</span></li><li><span>ફ્લિપકાર્ટ મેટ્રો શહેરોથી આગળ ક્વિક કોમર્સ લાવે છે</span><span>, </span><span>800\r\nડાર્ક સ્ટોર ટારગેટ</span></li><li><span>નાયકા અપેક્ષા રાખે છે કે </span><span>Q</span><span>1</span><span>FY</span><span>26 માં મિડ-20% આસપાસ કન્સોલિડેટેડ નેટ રેવેન્યુ ગ્રોથ થશે</span></li><li><span>સરકાર દ્વારા સ્થાનિક હથિયાર ખરીદી દ્વારા યુદ્ધક્ષમતામાં આત્મનિર્ભરતા વધારવાનો\r\nપ્રયાસ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ઓપેકના ભાવ વધારો\r\nપછી સાઉદી અરબે એશિયા માટે મુખ્ય તેલના ભાવમાં વધારો કર્યો</span></li><li><span>એડિત્ય</span><span>મંગલાને</span><span>ઇટર્નલ</span><span>ફૂડ</span><span>ડિલિવરી</span><span>બિઝનેસના</span><span>CEO </span><span>તરીકે નિયુક્ત\r\nકરવામાં આવ્યા</span></li><li><span>સિગ્નેચર</span><span>ગ્લોબલે</span><span>ગુરુગ્રામમ</span><span>ાં 10 એકરના બે પ્લોટ ખરીદ્યા</span><span>, </span><span>હાઉસિંગ પ્રોજેક્ટ માટે</span></li><li><span>ઈલેક્ટ્રોનિક્સ</span><span>કંપનીઓ</span><span>માટે</span><span>સોનાના</span><span>યૌગિકોના</span><span>આયાત</span><span>નિયંત્રણથી</span><span>દુહી</span><span>સ્થિતિ</span><span>ઊભી</span></li><li><span>ભારત</span><span>-</span><span>અમેરિકા</span><span>વેપાર</span><span>ચર્ચા</span><span>માટે</span><span>ઉદ્યોગ</span><span>સજ્જ</span><span>છે</span><span>: </span><span>CII\r\n</span><span>ચીફ</span></li><li><span>ભારતીય</span><span>કંપનીઓ</span><span>₹</span><span>5 </span><span>લાખ</span><span>કરોડના</span><span>રોકડ</span><span>જથ્થા</span><span>પર</span><span>બેઠી</span><span>છે</span><span>, </span><span>મૂડી ખર્ચમાં ધીમો\r\nવલણ</span></li><li><span>દુર્લભ</span><span>ખનિજ</span><span>પર</span><span>આધાર</span><span>ઘટાડવા</span><span>માટે</span><span>ઉદ્યોગ</span><span>અને</span><span>સરકાર</span><span>વચ્ચે</span><span>સહયોગ</span><span>જરૂરી</span><span>: </span><span>CII </span><span>પ્રમુખ</span></li><li><span>ફાર્મા</span><span>કંપનીઓ</span><span>Q</span><span>1</span><span>FY</span><span>26 માં વેચાણ અને </span><span>EBITDA</span><span>માં 11% વૃદ્ધિ નોંધાવી શકે: રિપોર્ટ</span></li><li><span>ભારત</span><span>રક્ષણ</span><span>અને</span><span>એરોસ્પેસ</span><span>ક્ષેત્રે</span><span>પસંદગીદાર</span><span>સપ્લાયર</span><span>બની</span><span>શકે</span><span>છે</span><span>: </span><span>પીયૂષ</span><span>ગોયલ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgLYEUx4n0IHlfdWf32YLcaTnIjvj-mFa0HAFP1yHKWfiEl21TiSrOlvNLuuhU30NvGDN5FcvSSvLy0yJ7Q2HO_hfl-qAR7pucShD8pJjtwUMscwyIAD3vhRyqynJ1D5ZXDutTRiuissDni5TpCiXraxrXes40BjHzt-Cpaz9yLkjK-qsdGsC_drfPFkpM=w281-h240','2025-07-07','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(247,'7587980056219784033','Research Report : Indian Financial Markets Outlook - 04th July 2025',NULL,'<p style=\"text-align:center;\"> <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhAvpSJDrsa4q-0B6OKOL5nkeT-HubDtj7phO9wXbmvfGHDpriYVCYpXOtnmvHjNqzRG5k-wqZudpykxbF4lK7jLjT5I3reWCxDZ_mp0vS1c9sS6cdSM7vPbR_PC8JtYZu8k3ZK2UbH2jRJ6VFEbk_jsqJvHdBNlCRx16MLI0FochfrETI9PX3Dn6wX3lQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhAvpSJDrsa4q-0B6OKOL5nkeT-HubDtj7phO9wXbmvfGHDpriYVCYpXOtnmvHjNqzRG5k-wqZudpykxbF4lK7jLjT5I3reWCxDZ_mp0vS1c9sS6cdSM7vPbR_PC8JtYZu8k3ZK2UbH2jRJ6VFEbk_jsqJvHdBNlCRx16MLI0FochfrETI9PX3Dn6wX3lQ\" width=\"240\" /></a><br /></p><div style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div><div style=\"text-align:justify;\"><span style=\"color:#FF0000;text-align:left;\">Markets\r\nin range as Trump signals sending tariff notice to countries</span></div><div style=\"text-align:justify;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEilugjfN3ESMgaLdGtPGul7dKnoKvQHqV4bVgqW-JxmjCxTwkdIJ9ojxHY8iBxsQbYC07VRTe4qW2KKUj2K7oZaYRfGyfbeVEoZ3PJI0O7t7xKXPx_-gv9C6uIdJ40dhjBnHsTQ0YojznePSEnP8AJ8XJnE7mp9xGc2BWKc_RZuExa-iEKUAIkXzyGem70\"><img alt=\"\" height=\"293\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEilugjfN3ESMgaLdGtPGul7dKnoKvQHqV4bVgqW-JxmjCxTwkdIJ9ojxHY8iBxsQbYC07VRTe4qW2KKUj2K7oZaYRfGyfbeVEoZ3PJI0O7t7xKXPx_-gv9C6uIdJ40dhjBnHsTQ0YojznePSEnP8AJ8XJnE7mp9xGc2BWKc_RZuExa-iEKUAIkXzyGem70=w510-h293\" width=\"510\" /></a></div><span>Asian\r\nand Pacific region shares traded in a tight range on Friday morning as renewed\r\ntrade tensions ahead of next week’s deadline for higher levies outweighed a\r\nrecord-extending rally in US stocks. US stocks reached a fresh record in a\r\nholiday-shortened session after data showed job growth exceeded expectations,\r\nboosting investors’ confidence in the health of the economy even as it doused\r\nexpectations for a July Federal Reserve interest-rate cut. </span></div>\r\n\r\n<p style=\"text-align:justify;\"><span>Oil\r\nwas little changed before an OPEC+ meeting that’s set to deliver another\r\noversized production hike, threatening to swell a glut forecast for later this\r\nyear. The GIFT Nifty was trading 34 points higher at 25,529, indicating a\r\npositive start for the benchmark 50-stock index later in the morning. Earlier,\r\nforeign investors remained net sellers in the Indian stock market, offloading\r\nover 1,925 crores of securities as per provisional data from NSE.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Bharat Forge - </span></b><span>The Company has incorporated a\r\nstep-down subsidiary named Agneyastra Energetics. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">UCO Bank - </span></b><span>The bank reported a 13.67%\r\nyear-on-year growth in the April–June quarter of fiscal 2026, driven by\r\nexpansion in its domestic loan book. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">IEX - </span></b><span>The Company reported a 6.5% rise in\r\nelectricity trading volumes to 10,852 million units in June. For the April–June\r\nquarter, volume increased by 15% to 32,382 million units. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Aegis Logistics - </span></b><span>The Company commissioned an\r\nLPG cryogenic terminal at Pipavav with a static storage capacity of 48,000 MT. <span style=\"color:#0000FF;\">Positive</span></span> </li></ul>\r\n\r\n<p><span style=\"color:#FF0000;\">Technical\r\nUpdate</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>The Nifty index continued downward\r\njourney to close below 25,500 at 25,405 on Friday. Index lacks momentum for\r\namid trade tariff uncertainty with USA. Today’s range – 25,250 – 25,600.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty too slipped below 57K to\r\nsettle at 56,791 on Friday. Large public sector lenders faced selling pressure\r\nfrom major fund houses. Index has 17 day EMA of 56,500 as strong support while\r\n57,150 is near term resistance. Today’s range – 56,500 – 57,150.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhAvpSJDrsa4q-0B6OKOL5nkeT-HubDtj7phO9wXbmvfGHDpriYVCYpXOtnmvHjNqzRG5k-wqZudpykxbF4lK7jLjT5I3reWCxDZ_mp0vS1c9sS6cdSM7vPbR_PC8JtYZu8k3ZK2UbH2jRJ6VFEbk_jsqJvHdBNlCRx16MLI0FochfrETI9PX3Dn6wX3lQ','2025-07-04','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(248,'229719871176570120','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૪ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEi5lPltSVugmmaUZQ530UOIWBbacyuW_nJBL77woPbWOVCR7Nj-BZjxyr-GYpVOlFKUwbIEENlKZPYtC9aksB02zMaPbvKCI6fgs00T1wYIZLr131qiQ5kLMR61zd8SysQkEj9nb-TdWtBnh1Fk_suZ3qIfyll7z3-JpqkxPGegcxl8N_R_7SLYgHl4-cM\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEi5lPltSVugmmaUZQ530UOIWBbacyuW_nJBL77woPbWOVCR7Nj-BZjxyr-GYpVOlFKUwbIEENlKZPYtC9aksB02zMaPbvKCI6fgs00T1wYIZLr131qiQ5kLMR61zd8SysQkEj9nb-TdWtBnh1Fk_suZ3qIfyll7z3-JpqkxPGegcxl8N_R_7SLYgHl4-cM\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ :</span></b></span></p>\r\n\r\n<ul><li><span>ભારતનું અર્થતંત્ર </span><span>FY26</span><span> માં </span><span>6.4%</span><span> થી </span><span>6.7%</span><span>ની દરે વધે તેવી સંભાવના: </span><span>CII</span></li><li><span>ઇન્ડોનેશિયાથી આયાત\r\nથતા મલ્ટી-લેયર પેપરબોર્ડ પર એન્ટી-ડમ્પિંગ તપાસ શરૂ</span></li><li><span>રિલાયન્સ રિટેઇલે </span><span>FACEGYM\r\n</span><span>માં ઓછી હિસ્સ</span><span>ेदारी </span><span>મેળવી</span><span>,\r\n</span><span>બ્રાન્ડને ભારતમાં લાવશે</span></li><li><span>ભારત-અમેરિકા વેપાર\r\nકરારમાં </span><span>GM\r\n</span><span>પશુ ખોરાકની આયાત મંજૂરી મળી શકે</span></li><li><span>રક્ષા વિલય પરિષદે </span><span>₹</span><span>1.05</span><span> લાખ કરોડની મૂલ્યની </span><span>10</span><span> મૂડી ખરીદી યોજનાઓ મંજૂર કરી</span></li><li><span>પર્સિસ્ટન્ટે\r\nશિમોના ચઢ્ઢાને મુખ્ય માર્કેટિંગ અધિકારી તરીકે નિમણૂક કરી</span></li><li><span>ગરુડા એરોઝ સ્પેસે\r\nરાજ્ય સરકારોથી </span><span>AI </span><span>આધારિત ડ્રોન સોલ્યુશનના કોન્ટ્રાક્ટ\r\nમેળવ્યા</span></li><li><span>ટ્રમ્પે ચીન માટેના\r\nવેપાર છિદ્રો બંધ કરવાનો સંકલ્પ લીધો</span></li><li><span>અલિબાબા\r\nએક્સચેન્જેબલ બોન્ડથી </span><span>$1.53</span><span> અબજ ઊંચા કરવા\r\nઇચ્છે છે</span></li><li><span>યૂ.કે.ની ડિલિવરી\r\nસ્ટાર્ટઅપ </span><span>HiveD\r\n</span><span>એ નેટવર્ક વિસ્તરણ માટે </span><span>$42</span><span> મિલિયન ઊંચા કર્યા</span></li><li><span>બાયોકોન\r\nબાયોલોજિક્સને યુરોપિયન કમિશનથી હાડકાંના રોગો માટે બે બાયોસિમિલર્સ </span><span>Vevzuo\r\n</span><span>અને </span><span>Evfraxy </span><span>માટે મંજૂરી મળી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ :</span></b></span></p>\r\n\r\n<ul><li><span>સ્થાનિક સ્ટીલ ઉદ્યોગ માટે રક્ષણાત્મક પગલાં લેવાની માગ</span></li><li><span>યૂકો બેંકનો કુલ વ્યવસાય </span><span>Q</span><span>1</span><span>FY</span><span>26 માં 13% વધીને </span><span>₹</span><span>5.24 લાખ કરોડ</span></li><li><span>IEX </span><span>નું </span><span>Q</span><span>1 વીજ વેપાર 15% વધ્યું</span><span>, REC </span><span>વોલ્યુમ્સમાં 149%નો જમ્પ</span></li><li><span>ખાંડ ઉદ્યોગ </span><span>₹</span><span>1 લાખ કરોડનું ઉદ્યોગ બન્યું: ખાદ્ય મંત્રી પ્રહ્લાદ જોશી</span></li><li><span>IL&amp;FS </span><span>એ </span><span>BKC </span><span>મિલ્કત માટે બ્રુકફિલ્ડના </span><span>₹</span><span>1,080 કરોડના બિડને રદ કરાવવા </span><span>NCLT</span><span>માં અરજી કરી</span></li><li><span>2025 ની પ્રથમ છ માસમાં હાઉસિંગ સેલ્સ 2% ઘટી</span><span>, </span><span>ઓફિસ\r\nલીઝિંગ 41% વધી: નાઈટ ફ્રેંક</span></li><li><span>સૌરભ વત્સા નિસાન ઈન્ડિયાના કોમર્શિયલ ઓપરેશન્સ સંભાળશે</span></li><li><span>ઓફિસ લીઝિંગમાં 40%નો વધારો</span><span>, </span><span>બેંગલુરુ અને\r\nપુણે તરફથી મોટી માંગ: એનરોક</span></li><li><span>ક્રૂડ ઓઈલના ભાવ ડિસેમ્બર 2025 સુધીમાં $55-60 પ્રતિ બેરલ સુધી ઘટી શકે: પ્રિમસિષ\r\nદાસ</span></li><li><span>ટાટા પાવર રિન્યુએબલ્સે </span><span>Q</span><span>1</span><span>FY</span><span>26 માં રેકોર્ડ 752 મેગાવોટ સોલાર ક્ષમતા ઉમેર્યું</span></li><li><span>IFC </span><span>અને ઇન્ડીગ્રિડ ભારતનું સૌથી મોટું બેટરી એનર્જી સ્ટોરેજ પ્રોજેક્ટ બનાવશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ :</span></b></span></p>\r\n\r\n<ul><li><span>ઇન્ડિયન ઓઈલ ગ્રીન\r\nહાઈડ્રોજન ફ્યુઅલ રિટેલ નેટવર્ક યોજના બનાવે છે</span></li><li><span>શાપૂરજી પલોનજી\r\nકંપની </span><span>₹</span><span>300</span><span> મિલિયન ઊંચા કરીને જુના દેવીની રિફાઇનાન્સિંગ યોજના બનાવે\r\nછે</span></li><li><span>ASML, </span><span>એરબસ</span><span>, </span><span>મિસ્ટ્રલે યુરોપીય\r\nસંઘને </span><span>AI\r\n</span><span>અધિનિયમ અમલની મુદત ટાળવા અપીલ કરી</span></li><li><span>આરબીઆઈએ બિઝનેસ લોન\r\nપર પ્રીપેમેન્ટ ચાર્જ પર પ્રતિબંધ મૂક્યો </span><span>| </span><span>નાના વ્યવસાય માટે રાહત</span></li><li><span>પોર્ટફોલિયોમાં\r\nઇનફ્લોઝ વધતાં રૂપિયો એક મહિનાના ઉચ્ચ સ્તરે</span><span>, </span><span>વેપાર કરાર આશાવાદથી સહારો</span></li><li><span>મેશોએ </span><span>₹</span><span>4,250</span><span> કરોડના </span><span>IPO </span><span>માટે ગુપ્ત ડ્રાફ્ટ\r\nપેપર્સ ફાઇલ કર્યા</span></li><li><span>માઈક્રોસોફ્ટ\r\nગેમિંગે નોકરીમાં કાપ મૂક્યો</span><span>, Everwild </span><span>અને </span><span>Perfect\r\nDark </span><span>જેવી ગેમ રદ કરી</span></li><li><span>પી.એન. ગડગિલ\r\nજ્વેલર્સે </span><span>₹</span><span>1,000</span><span> કરોડનું ભંડોળ ઉઘરાવવાનું મંજૂર કર્યું</span></li><li><span>સ્પાઈસજેટે તેના\r\nપ્રથમ બે સુધારેલા એન્જિન્સ સ્ટાન્ડર્ડએરો પાસેથી પ્રાપ્ત કર્યા</span></li><li><span>બાજેલ\r\nપ્રોજેક્ટ્સને </span><span>₹</span><span>300-400\r\n</span><span>કરોડની ટ્રાન્સમિશન લાઇન પ્રોજેક્ટ ઓર્ડર મળ્યો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEi5lPltSVugmmaUZQ530UOIWBbacyuW_nJBL77woPbWOVCR7Nj-BZjxyr-GYpVOlFKUwbIEENlKZPYtC9aksB02zMaPbvKCI6fgs00T1wYIZLr131qiQ5kLMR61zd8SysQkEj9nb-TdWtBnh1Fk_suZ3qIfyll7z3-JpqkxPGegcxl8N_R_7SLYgHl4-cM','2025-07-04','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(249,'6590637708234487861','Research Report : Indian Financial Markets Outlook - 03th July 2025',NULL,'<p style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEih6bobvSlUjGk74FZwYKMwMr9D0Nk4glvG6XqJvJvYugvIJVGCFC156s8Xi2R-EnU2BGZO2rBhGvheU6OOh-_p1L32F8Jx0oc6vl1xi_Yq3nAvvf36L4rFjqkNB_BykDHDaTImkKFguhxOaJmzZt870aH6EC46n90ZoUOlMFk95c6vRDd8Ivdw3ooGo-k\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEih6bobvSlUjGk74FZwYKMwMr9D0Nk4glvG6XqJvJvYugvIJVGCFC156s8Xi2R-EnU2BGZO2rBhGvheU6OOh-_p1L32F8Jx0oc6vl1xi_Yq3nAvvf36L4rFjqkNB_BykDHDaTImkKFguhxOaJmzZt870aH6EC46n90ZoUOlMFk95c6vRDd8Ivdw3ooGo-k\" width=\"240\" /></a></b></p><div style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">US\r\ntrade deal with Vietnam lifts hope of economic momentum</span></p><div style=\"text-align:center;\"><div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgDheXU-llHBHbWDwY8WXLIoASoOnZ9J8D7bR3DZyByHrjF2swDa4MdwNym1npcg1S0NGUBAx9APBckne-H-373kAq0SnPZDMRa_U-_JypV2EUKITup62Mv-qQhRS0NgBmIh6ftKFCOAd8LmUSxJ95RpDf1rcpd-TuYFJf8pLwDyO9vX5XXrC0hVWC6SXc\"><img alt=\"\" height=\"331\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgDheXU-llHBHbWDwY8WXLIoASoOnZ9J8D7bR3DZyByHrjF2swDa4MdwNym1npcg1S0NGUBAx9APBckne-H-373kAq0SnPZDMRa_U-_JypV2EUKITup62Mv-qQhRS0NgBmIh6ftKFCOAd8LmUSxJ95RpDf1rcpd-TuYFJf8pLwDyO9vX5XXrC0hVWC6SXc=w563-h331\" width=\"563\" /></a></div><br /></div></div><div style=\"text-align:justify;\"><span>Markets in Asia – Pacific region were marginally positive in the morning\r\nsession with Nikkei 225 was up 0.06%. Kospi is up 0.75% while Australia’s\r\nS&amp;P/ASX 200 down 0.2%. US stock futures held steady on Wednesday evening\r\nafter the S&amp;P 500 and Nasdaq reclaimed record highs, boosted by President\r\nDonald Trump’s announcement of a trade deal with Vietnam. European contracts\r\nrose while Asian shares were mixed. S&amp;P 500 futures flat. Euro Stoxx 50\r\nfutures up 0.15%.</span></div>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty was trading 41 points higher at 25,572 in the morning, indicating a\r\npositive start for the 50-stock benchmark on the NSE later in the morning. The\r\nweekly futures contract for the Nifty will expire today. Foreign portfolio\r\ninvestors stayed net sellers of Indian equities for the second consecutive day on\r\nTuesday and sold shares worth Rs 1,970.1 crore. Domestic institutional\r\ninvestors stayed net buyers and acquired equities worth Rs 771.1 crore.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Max Financial -</span></b><span>Axis Max\r\nLife has initiated an information security assessment and data log analysis.\r\nInvestigation is ongoing with experts. <span style=\"color:#FF0000;\">Negative</span> </span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">RBL Bank –</span></b><span> Bank was denied reports about NBD\r\nBank seeking a minority stake. The bank stated no disclosure was required. <span style=\"color:#FF0000;\">Negative </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Punjab National Bank -</span></b><span> In the first quarter of\r\nfinancial year 2026, global deposits rose 12.8% year-on-year to Rs 15.9 lakh\r\ncrores.<span style=\"color:#0000FF;\"> Positive</span> </span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">AIA Engineering -</span></b><span> Brazil\'s trade department reduced\r\ncountervailing duty from 6.5% to 2.9%. <span style=\"color:#0000FF;\">Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical\r\nUpdate</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>The Nifty index slipped further on\r\nlack of clarity over US India trade deal and settle at 25,453 on Wednesday.\r\nIndex still in range whereby support lies at 25,250 while 25,600 is strong\r\nresistance. Today’s range – 25,375 – 25,650.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty succumbed to persistence\r\nselling by FPIs and settled tad below 57K at 56,999 on Wednesday. Index has 17\r\nday EMA of 56,575 as strong support while 57,500 is near term resistance.\r\nToday’s range – 56,800 – 57,500.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEih6bobvSlUjGk74FZwYKMwMr9D0Nk4glvG6XqJvJvYugvIJVGCFC156s8Xi2R-EnU2BGZO2rBhGvheU6OOh-_p1L32F8Jx0oc6vl1xi_Yq3nAvvf36L4rFjqkNB_BykDHDaTImkKFguhxOaJmzZt870aH6EC46n90ZoUOlMFk95c6vRDd8Ivdw3ooGo-k','2025-07-03','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(250,'75384867890665439','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૩ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjuzSVteOoUb-DxB1YGzELBg-OOZ4Y73tj2kER3VDDbtxt9NmJwhLGZpDF2-rmuTR3eiuLhpkn_88oTAPC49ro5b2kLNwTlBjU0sf3umVw0K70wj1pRJzIKy9RA_dKfwi0kWIpVsUljmSvdC7GwcPwfvMdpVOwpzIFUIgi4r1j3em8fU3vk-I9N47poYig\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjuzSVteOoUb-DxB1YGzELBg-OOZ4Y73tj2kER3VDDbtxt9NmJwhLGZpDF2-rmuTR3eiuLhpkn_88oTAPC49ro5b2kLNwTlBjU0sf3umVw0K70wj1pRJzIKy9RA_dKfwi0kWIpVsUljmSvdC7GwcPwfvMdpVOwpzIFUIgi4r1j3em8fU3vk-I9N47poYig\" width=\"281\" /></a></b></div><b><span style=\"color:#0000FF;\">સંકલન :-</span></b><b><span style=\"color:#0000FF;\">આશિષ\r\nશાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ :</span></b></span></p>\r\n\r\n<ul><li><span>વેન્ચર કેપિટલ\r\nફંડિંગ </span><span>H1\r\n2025</span><span>માં </span><span>$4.9</span><span> બિલિયન પર પહોંચી\r\nગયું</span></li><li><span>GCCs </span><span>એ </span><span>FY25</span><span>માં </span><span>31.8</span><span> મિલિયન ચોરસ ફૂટ ભાડે લીધાં</span><span>, YoY 24%</span><span> નો વધારો</span></li><li><span>વોલ્ટાસ ને </span><span>₹</span><span>265</span><span> કરોડનું </span><span>GST </span><span>શો-કોઝ નોટિસ મળ્યું</span></li><li><span>ટેસ્લા ના\r\nચાઈના-નિર્મિત </span><span>EV\r\n</span><span>વેચાણે નવ મહિનામાં પ્રથમ વખત વધારો દર્શાવ્યો</span></li><li><span>નિસાન </span><span>US</span><span>માં </span><span>4.43</span><span> લાખથી વધુ વાહનો\r\nપાછા બોલાવશે એન્જિન ખામી કારણે</span></li><li><span>ઓલા ઇલેક્ટ્રિક ના </span><span>Q1</span><span>માં </span><span>60,000</span><span> યુનિટ વેચાયા</span><span>;\r\nQ2</span><span>માં માંગમાં સુધારાની અપેક્ષા</span></li><li><span>LIC </span><span>નું </span><span>NSE </span><span>માં રોકાણ હવે\r\nટોચના </span><span>6</span><span> સૌથી મૂલ્યવાન રોકાણમાં સ્થાન પામ્યું</span></li><li><span>ડાઈમલર ઇન્ડિયા એ\r\nખાણખોદ અને બાંધકામ માટે ભારતબેન્ઝ રેન્જ લોન્ચ કરી</span></li><li><span>સિપ્લા ચાઈના\r\nફેક્ટરી માટે નવા ગ્રાહકો શોધી રહી છે</span></li><li><span>ભારત ફોર્જ એ </span><span>AAM\r\n</span><span>ઇન્ડિયાની </span><span>₹</span><span>746.46</span><span> કરોડમાં સંપત્તિ\r\nખરીદી પુરી કરી</span></li><li><span>એક્ઝો નોબેલ </span><span>JSW\r\n</span><span>સાથે લાંબા ગાળાના ભાગીદારી અને એર</span><span>ো</span><span>સ્પેસ-મેરીન કોટિંગમાં તકો શોધી રહ્યું છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ :</span></b></span></p>\r\n\r\n<ul><li><span>વૈશ્વિક મુશ્કેલીઓ વચ્ચે ભારતના ટાયર નિકાસમાં </span><span>9%</span><span> નો\r\nવધારો</span><span>, </span><span>₹</span><span>25,051</span><span> કરોડ\r\nથયું </span><span>FY25</span><span>માં</span></li><li><span>અમેરિકન ભાતમાં સૌથી વધુ આર્સેનિક</span><span>, </span><span>જ્યારે ભારતીય\r\nબાસમતી સૌથી સુરક્ષિત: અભ્યાસ</span></li><li><span>ટાટા સ્ટીલ યુકે અને નેધરલેન્ડમાં લીલી ઊર્જા રૂપાંતરણ તરફ આગળ વધી રહ્યું છે:\r\nચંદ્રશેખરન</span></li><li><span>લોઢા ડેવલપર્સ ને </span><span>VHL </span><span>કેસમાં </span><span>₹</span><span>520</span><span> કરોડ સુરક્ષા\r\nજમા કરાવવાનું રહેશે</span></li><li><span>સ્ટીમહાઉસ ઇન્ડિયા </span><span>₹</span><span>700</span><span> કરોડ ઊંચા કરવા ગુપ્ત રૂપે </span><span>IPO </span><span>દસ્તાવેજ દાખલ કરે છે</span></li><li><span>CBDT </span><span>એ </span><span>FY26</span><span> માટે મૂલ્યવર્ધન સૂચકાંક (</span><span>CII) 376</span><span> કર્યો</span><span>, </span><span>મૂડી નફા ઉપર ટેક્સમાં રાહત અપાશે</span></li><li><span>AU </span><span>સ્મોલ ફાઇનાન્સ બેંક એ બે સ્વતંત્ર ડાયરેક્ટરો અને વરિષ્ઠ અધિકારીઓની નિમણૂંક\r\nકરી</span></li><li><span>કીસ્ટોન રિયલ્ટર્સ રિડેવલપમેન્ટ પ્રોજેક્ટથી </span><span>₹</span><span>3,000</span><span> કરોડ\r\nઆવકનો લક્ષ્યાંક</span></li><li><span>એમ્બેસી </span><span>REIT </span><span>એ </span><span>NCD </span><span>અને ટર્મ લોન\r\nદ્વારા </span><span>₹</span><span>1,550</span><span> કરોડ ઊંચા કર્યા</span></li><li><span>RDI </span><span>યોજના ભારતના </span><span>R&amp;D </span><span>અને ડીપટેક ક્ષેત્ર માટે\r\nમોટું પ્રોત્સાહન: ઉદ્યોગકારો</span></li><li><span>પામ તેલના ભાવ માં વધારો</span><span>, </span><span>માંગમાં\r\nસુધારો અને જૂનમાં ઉત્પાદનમાં ઘટાડાની શક્યતા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ :</span></b></span></p>\r\n\r\n<ul><li><span>કૅપ્ટિવ અને\r\nકમર્શિયલ ખાણોમાંથી કોલનું ઉત્પાદન એપ્રિલ-જૂન </span><span>2025</span><span>માં </span><span>16%</span><span> વધ્યું</span><span>;\r\n</span><span>રવાનગીઓમાં </span><span>13%</span><span> નો વધારો</span></li><li><span>US </span><span>ફેડ સપ્ટેમ્બર પહેલા વ્યાજદર ઘટાડો ન કરે એવી સંભાવના: બેંક\r\nઓફ બરોડા</span></li><li><span>ભારતીય કંપનીઓ\r\nનવીનતા માટે ઇન્ટ્રાપ્રેન્યુરશિપ અપનાવી રહી છે</span></li><li><span>સરકાર હવે કેબ\r\nએગ્રેગેટર્સ ને પીક ટાઈમમાં બેફાળ ભાડું લેવાની મંજૂરી આપે છે (મૂળ ભાડાનો </span><span>2</span><span> ગણો)</span></li><li><span>ફિનટેક આધારિત લોન\r\nવૃદ્ધિ ને લઈને ચિંતાઓ</span><span>, </span><span>ડિફોલ્ટ દરોમાં\r\nવધારો</span></li><li><span>સ્લાઇસ એ\r\nબેંગલુરુમાં પહેલો </span><span>UPI </span><span>આધારિત બેંક બ્રાન્ચ લોન્ચ કર્યો</span></li><li><span>HDFC </span><span>બેંક </span><span>CEO: IPO </span><span>પછી પણ </span><span>HDB\r\n</span><span>ફાઇનાન્સિયલ ને ટેકો આપતા રહીશું</span></li><li><span>પેપ્સિકો ઇન્ડિયા એ\r\nસાક્ષી વર્મા મેનન ને </span><span>Foods </span><span>માર્કેટિંગ\r\nડિરેક્ટર તરીકે નિમણૂંક કરી</span></li><li><span>HDB </span><span>ફાઇનાન્સિયલ સર્વિસીસ ના શેરો </span><span>₹</span><span>835</span><span> પર લિસ્ટ થયા - </span><span>IPO </span><span>કિંમત કરતા </span><span>12.84%</span><span> વધુ ભાવ</span></li><li><span>ડોમિનોઝ\r\nઓસ્ટ્રેલિયા ના </span><span>CEO </span><span>એક વર્ષમાં પદ છોડશે</span><span>,\r\n</span><span>શેરોમાં ઘટાડો</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjuzSVteOoUb-DxB1YGzELBg-OOZ4Y73tj2kER3VDDbtxt9NmJwhLGZpDF2-rmuTR3eiuLhpkn_88oTAPC49ro5b2kLNwTlBjU0sf3umVw0K70wj1pRJzIKy9RA_dKfwi0kWIpVsUljmSvdC7GwcPwfvMdpVOwpzIFUIgi4r1j3em8fU3vk-I9N47poYig','2025-07-03','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(251,'2642089312771226801','Research Report : Indian Financial Markets Outlook - 02th July 2025',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgMEBNyfAtzqxUxvM2YTEm54JARqfnlHsSaVC_KSxPiBIvdUvYftKJH3kjXmqZAHByIucgvBQOoRZ7UXY9uahbFqiG7nXreBnoEE_T8ZOPkIUlWlnc6pWcXOUtUuFZ_O673QCnXtGVijzl40nn2jMwbPwz8xSk44Gh0GiWCeYCnG771BtLnsLZlpoj-5Zs\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgMEBNyfAtzqxUxvM2YTEm54JARqfnlHsSaVC_KSxPiBIvdUvYftKJH3kjXmqZAHByIucgvBQOoRZ7UXY9uahbFqiG7nXreBnoEE_T8ZOPkIUlWlnc6pWcXOUtUuFZ_O673QCnXtGVijzl40nn2jMwbPwz8xSk44Gh0GiWCeYCnG771BtLnsLZlpoj-5Zs\" width=\"240\" /></a></b></div><b><br /><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt</span></b></b></div><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">Reiteration\r\nof 9th July deadline by Trump put pressure on markets</span></p><div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiWq0UaPp8t5kM6MVbOh9JDhb2Xbvi3GsPUXpw7afXjpkwgntxb1cLUaQgDopMIlMDUZFBHWNpdsNfddcpKjQi83yjvv1ylq-I7RmCQR21BeRuHb2I9r9eQtLm4XxWJDfQghLnRZXv2DC8ejRcUomqIDp3lYq9hzBdmXfk4NC-3Gjzl-GfJfOTQeJL43LE\"><img alt=\"\" height=\"335\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiWq0UaPp8t5kM6MVbOh9JDhb2Xbvi3GsPUXpw7afXjpkwgntxb1cLUaQgDopMIlMDUZFBHWNpdsNfddcpKjQi83yjvv1ylq-I7RmCQR21BeRuHb2I9r9eQtLm4XxWJDfQghLnRZXv2DC8ejRcUomqIDp3lYq9hzBdmXfk4NC-3Gjzl-GfJfOTQeJL43LE=w586-h335\" width=\"586\" /></a></div></div><p style=\"text-align:justify;\"><span>Most of Asian Pacific region indices were down after US President Donald\r\nTrump said he wouldn\'t delay the July 9 deadline for imposing higher levies on\r\ntrading partners. Japan’s Topix index was down 0.16% while Kospi was down by\r\n1.35% in the morning. Australia’s S&amp;P/ASX 200 was up 0.38%. The GIFT Nifty\r\nwas trading 20.5 points higher at 25,677 as of early morning, indicating a\r\npositive start for the 50-stock benchmark on the NSE later in the morning.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>US\r\nindex futures were little changed. Foreign portfolio investors stayed net\r\nsellers of Indian equities for the second consecutive day on Tuesday and net\r\nsold shares worth Rs 1,970.1 crore, according to the provisional data from the\r\nNational Stock Exchange. Domestic institutional investors stayed net sellers and\r\noffloaded equities worth Rs 771.1 crore.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Hyundai Motor India – </span></b><span>Company’s passenger vehicle\r\nsales in June stood at 60,924 units, above the estimate of 59,400 units.\r\nDomestic sales were 44,024 units versus 43,861 units in May. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Maruti Suzuki - </span></b><span>Total sales fell 6% year-on-year to\r\n1.68 lakh units, versus an estimate of 1.675 lakh units. <span style=\"color:#2b00fe;\">Neutral</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">JSW Energy - </span></b><span>Subsidiary JSW Renew Energy signed a\r\npurchase pact with Rajasthan Vidyut Utpadan Nigam for a 250 MW/500 MWh battery energy\r\nstorage system. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">India Pesticides – </span></b><span>It commissioned an expansion\r\nof its formulation plant, increasing capacity by 3,500 MTPA from 6,500 MTPA.<span style=\"color:#0000FF;\"> Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical\r\nUpdate</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY – </span></b><span>The Nifty index traded in narrow\r\nrange during day and settle at 25,541 on Tuesday. Index finds support at 25,500\r\nwhile 25,600 remain near term resistance. Today’s range – 25,450 – 25,750.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY – </span></b><span>Bank nifty traded marginally\r\npositive and closed higher by 150 points at 57,460 on Tuesday. Index is well\r\nsupported at 57,100 indicating buying emerges on dips. Today’s range – 57,150 –\r\n57,800.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEgMEBNyfAtzqxUxvM2YTEm54JARqfnlHsSaVC_KSxPiBIvdUvYftKJH3kjXmqZAHByIucgvBQOoRZ7UXY9uahbFqiG7nXreBnoEE_T8ZOPkIUlWlnc6pWcXOUtUuFZ_O673QCnXtGVijzl40nn2jMwbPwz8xSk44Gh0GiWCeYCnG771BtLnsLZlpoj-5Zs','2025-07-02','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(252,'4426848430194026692','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૨ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjOIIOBahT5lFg7YePYibXJ3W0YXd5kMFNxi9Y2w856YEVbnUKCGUBeVKdzN4TjcoYZeXK7o-MDDW_bS-Z11Oe7BqBBqcpTfgXn6F0eCS8Hl0zVA2ZVsTH6HkHBAKl8ccFKgg3My-y1ro2X-DyIpyb_aY95cZ-emT4SpFZlM4tSneUYl6aEBuO8vIwxP3k\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjOIIOBahT5lFg7YePYibXJ3W0YXd5kMFNxi9Y2w856YEVbnUKCGUBeVKdzN4TjcoYZeXK7o-MDDW_bS-Z11Oe7BqBBqcpTfgXn6F0eCS8Hl0zVA2ZVsTH6HkHBAKl8ccFKgg3My-y1ro2X-DyIpyb_aY95cZ-emT4SpFZlM4tSneUYl6aEBuO8vIwxP3k\" width=\"281\" /></a></b></div><div style=\"text-align:center;\"><span style=\"color:#0000FF;\"><b>સંકલન :- </b></span><b><span style=\"color:#0000FF;\">આશિષ શાહ</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers</span></b></div><div style=\"text-align:center;\"><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>ક્રિસિલે </span><span>FY</span><span>26 માટે ભારતના </span><span>GDP </span><span>વૃદ્ધિ અંદાજને\r\nસુધારી 6.5% કર્યો - સારા વરસાદ</span><span>, </span><span>દર ઘટાડો અને\r\nગ્રામ્ય સમર્થનના કારણે</span></li><li><span>ભારતીય</span><span>કંપનીઓ</span><span>હવે</span><span>વધુ</span><span>સસ્તું</span><span>મૂડી</span><span>મેળવા</span><span>માર્કેટ</span><span>તરફ</span><span>વળી</span><span>રહી</span><span>છે</span><span>,\r\n</span><span>બેંક પર ઓછી નિર્ભરતા</span></li><li><span>ક્લીનમેક્સ</span><span>અને</span><span>ટોયોટા</span><span>ત્સુશો</span><span>ઈન્ડિયાએ</span><span>મળીને</span><span> 300 </span><span>મેગાવોટ</span><span>હરીત</span><span>ઊર્જા</span><span>વિકાસનો</span><span>કરાર</span><span>કર્યો</span></li><li><span>SECI</span><span>એ છેલ્લા 14 વર્ષમાં 60</span><span>GW\r\n</span><span>રિન્યુએબલ ઊર્જા માટે વીજ વેચાણ કરાર કર્યા</span></li><li><span>Aptus Value\r\nHousing Finance </span><span>માટે </span><span>CARE </span><span>રેટિંગ અપગ્રેડ</span></li><li><span>CONCOR</span><span>નું બલ્ક સિમેન્ટ ટ્રાન્સપોર્ટ વ્યવસાયમાં પ્રવેશ</span><span>,\r\n</span><span>વિશિષ્ટ કન્ટેનરનો ઉપયોગ</span></li><li><span>ઈન્ડસઈન્ડ</span><span>બેંકે</span><span>MSME </span><span>માટે નવી ડિજિટલ\r\nબેંકિંગ પ્લેટફોર્મ શરૂ કરી</span></li><li><span>JSW </span><span>પેઈન્ટ્સ હવે ડેકોરેટિવ અને ઈન્ડસ્ટ્રીયલ કોટિંગ માર્કેટમાં\r\nમોટો હિસ્સો મેળવવાનો લક્ષ્ય ધરાવે છે: પાર્થ  </span><span>જિંદલ</span></li><li><span>રોયલ</span><span>એનફિલ્ડની</span><span>જૂનમાં</span><span>વેચાણમાં</span><span> 22% </span><span>વધારો</span><span>,\r\n</span><span>કુલ 89,540 યુનિટ</span></li><li><span>જૂનમાં</span><span>વીજળી</span><span>વપરાશ</span><span> 1.5% </span><span>ઘટીને</span><span> 150.04 </span><span>અબજ</span><span>યુનિટ</span><span>રહ્યો</span></li><li><span>પ્રેસ્ટિજ</span><span>ગ્રૂપે</span><span>ચેન્નઈના</span><span>નવા</span><span>હાઉસિંગ</span><span>પ્રોજેક્ટમાંથી</span><span>₹</span><span>3,350 </span><span>કરોડ</span><span>આવકનું</span><span> લક્ષ્ય રાખ્યું</span></li><li><span>રામકૃષ્ણ</span><span>ફોર્જિંગ્સે</span><span>FY</span><span>27થી ચેન્નઈ\r\nપ્લાન્ટમાંથી ફોર્જ્ડ વ્હીલ ઉત્પાદન શરૂ કરવાની યોજના બનાવી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>કોલ ઈન્ડિયા અને હિન્દુસ્તાન કૉપરે તાંબાં અને ખનિજ માટે સહયોગ માટે </span><span>MoU </span><span>પર હસ્તાક્ષર કર્યા</span></li><li><span>ખાનગી ક્ષેત્રના નવીનતા વિકાસ માટે </span><span>₹</span><span>1 લાખ કરોડના </span><span>RDI </span><span>યોજનાને મંજૂરી</span></li><li><span>જૂનમાં </span><span>GST </span><span>વસૂલાતમાં 6.2%નો વધારો</span><span>, </span><span>કુલ </span><span>₹</span><span>1.85 લાખ કરોડ</span></li><li><span>ભારત-કેનેડા વેપાર સંધિને રાજદ્વારી સંબંધોમાં સુધારા સાથે નવી દિશા</span></li><li><span>ઓડીના રિટેલ વેચાણમાં </span><span>H</span><span>1 2025\r\nદરમિયાન 14% ઘટ</span><span>, </span><span>માગમાં ઘટાડાના કારણે</span></li><li><span>કીસ્ટોન કંપની મુંબઈમાં </span><span>MHADA </span><span>સાથે\r\nભાગીદારીમાં વિસ્તારનો વિકાસ કરશે</span><span>, </span><span>કુલ કિંમત </span><span>₹</span><span>4,521 કરોડ</span></li><li><span>છત્તીસગઢે ઉદ્યોગ સમારોહમાં </span><span>₹</span><span>1.25 લાખ કરોડના રોકાણો મેળવ્યા</span></li><li><span>તામિલનાડુમાં પરમાકુડી-રામનાથપુરમ ચાર-લેન રોડ પ્રોજેક્ટને મંજુરી</span></li><li><span>BPTP </span><span>ગ્રૂપે ગુરગાંવમાં 12 એકરની હાઉસિંગ પ્રોજેક્ટ માટે </span><span>₹</span><span>3,000 કરોડનું રોકાણ કરશે</span></li><li><span>આધાર હાઉસિંગ ફાઈનાન્સના </span><span>NCD </span><span>અને બેંક\r\nલોનની રેટિંગ </span><span>CARE </span><span>દ્વારા અપગ્રેડ</span></li><li><span>રેનૉલ્ટે નિસાનમાં હિસ્સ</span><span>ेदारी</span><span>ના કારણે </span><span>H</span><span>1માં $11\r\nબિલિયન નુકસાન જાહેર કર્યું</span></li><li><span>ગોલ્ડમેન સેક્સે 2025 માટે ફેડ રેટ કટની સંખ્યા વધારીને ત્રણ કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>કોલ ઈન્ડિયાના\r\nઉત્પાદનમાં જૂનમાં 8.5%નો ઘટાડો</span></li><li><span>H</span><span>1</span><span>CY</span><span>25માં સોનાની કિંમત\r\nચાંદી અને સેન્સેક્સ કરતાં વધુ રહી</span><span>; H</span><span>2માં ચાંદી આગળ રહી\r\nશકે</span></li><li><span>વૈશ્વિક</span><span>હરિત</span><span> ઊર્જા વૃદ્ધિ\r\nયોગ્ય માર્ગે છે પણ હજી લક્ષ્યથી પાછળ: </span><span>IRENA </span><span>અધિકારી</span></li><li><span>મે</span><span>મહિનામાં</span><span>બેન્કિંગ</span><span>અને</span><span>ફાઈનાન્સિયલ</span><span>સર્વિસિસના</span><span>MEs</span><span>નો </span><span>AUM\r\n</span><span>37% વધીને </span><span>₹</span><span>48,000 </span><span>કરોડ</span></li><li><span>સ્ટાન્ડર્ડ</span><span>ચાર્ટર્ડ</span><span>સામે</span><span> 1</span><span>MDB\r\n</span><span>સાથે સંબંધિત છેતરપિંડી માટે $2.7 બિલિયનનો કેસ</span></li><li><span>IMF</span><span>એ </span><span>UBS </span><span>સાથેના મૂડી સંબંધિત\r\nવિવાદ વચ્ચે સ્વિસ બેંક સુધારા પ્રસ્તાવને સમર્થન આપ્યું</span></li><li><span>SBI</span><span>ના છેલ્લા દાયકા દરમિયાન ડિજિટલ પરિવર્તનથી ગ્રાહકોને વિશાળ\r\nલાભ મળ્યો: નાણાં પ્રધાન</span></li><li><span>બજાજ</span><span>ઑટોની</span><span>જૂનમાં</span><span>વેચાણ</span><span>સ્થિર</span><span>રહ્યો</span><span>,\r\n</span><span>ટૂ-વ્હીલર વેચાણ ઘટ્યું પણ કોમર્શિયલ વાહનો એ વધારાની ભરપાઈ\r\nકરી</span></li><li><span>Q</span><span>1</span><span>FY</span><span>26માં બેન્કોના\r\nનફામાં ઘટાડો આવી શકે છે - નરમ લોન વૃદ્ધિ</span><span>, </span><span>ઓછી માર્જિન અને નબળા ફી આવકના કારણે</span></li><li><span>એપોલો</span><span>આગામી</span><span> 18-21 </span><span>મહીનામાં</span><span>પોતાની</span><span>ફાર્મસી</span><span>અને</span><span>ડિજિટલ</span><span>હેલ્થ</span><span>યુનિટને</span><span>લિસ્ટ</span><span>કરશે</span></li><li><span>ઇવી</span><span>રેસમાં</span><span>ઓલા</span><span>પાછળ</span><span>રહી</span><span>,\r\nTVS </span><span>અને બજાજ આગળ</span></li></ul><h1 style=\"text-align:justify;\"><span style=\"font-weight:normal;\"><span style=\"color:#FF0000;\">નોંધ :- AI અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા બિઝનેસ હેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન, સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને શિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></span></h1>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjOIIOBahT5lFg7YePYibXJ3W0YXd5kMFNxi9Y2w856YEVbnUKCGUBeVKdzN4TjcoYZeXK7o-MDDW_bS-Z11Oe7BqBBqcpTfgXn6F0eCS8Hl0zVA2ZVsTH6HkHBAKl8ccFKgg3My-y1ro2X-DyIpyb_aY95cZ-emT4SpFZlM4tSneUYl6aEBuO8vIwxP3k','2025-07-02','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(253,'468802582520319697','Research Report : Indian Financial Markets Outlook - 01th July 2025',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEidOh5o1pK-MyQfw8jl3SLnMhIpaFJY9TMThhTff1M_k2zqZEjfffHnVeyQle8wMwL5F6gPG8hwdWsin6vx0WLw6hnB624tCATMqUo7VzNHuBWlFj3dZu8xjLfkQqaT-yRqNAkOZTWPxeR0yKX5cc5oEafGrVoNU6hA7PkO0h5jEdqTiT1AjWk-Ub61dFA\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEidOh5o1pK-MyQfw8jl3SLnMhIpaFJY9TMThhTff1M_k2zqZEjfffHnVeyQle8wMwL5F6gPG8hwdWsin6vx0WLw6hnB624tCATMqUo7VzNHuBWlFj3dZu8xjLfkQqaT-yRqNAkOZTWPxeR0yKX5cc5oEafGrVoNU6hA7PkO0h5jEdqTiT1AjWk-Ub61dFA\" width=\"240\" /></a></b></div><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt</span></b></div><div style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span><br /></div>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span><span style=\"color:#FF0000;text-align:left;\">US - India trade deal is very close to announce, markets await details</span></span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhl2cevz4_MQMJjYp8gDOL_Bki5c4vEVAx9evOX_Z2of13_lWHoxnHSvR0loV_ygVyV9jhSD1ptpaK_9McGO6aRdOdRHFHT1dMdw93LhjcGucnJRL21ir9r2td5NjtAIV4DTHQE9ac733xnnP-Csb1IQgbyg0y1pNd6hnpkPfia_XRt2XIleEQLTPiFu9A\"><img alt=\"\" height=\"334\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhl2cevz4_MQMJjYp8gDOL_Bki5c4vEVAx9evOX_Z2of13_lWHoxnHSvR0loV_ygVyV9jhSD1ptpaK_9McGO6aRdOdRHFHT1dMdw93LhjcGucnJRL21ir9r2td5NjtAIV4DTHQE9ac733xnnP-Csb1IQgbyg0y1pNd6hnpkPfia_XRt2XIleEQLTPiFu9A=w557-h334\" width=\"557\" /></a></div><p style=\"text-align:justify;\"><span>Markets\r\nin Asia Pacific region have been mixed during the morning session. Index\r\nfutures for equities in the US and Europe marginally rose while futures for\r\nHong Kong’s Hang Seng Index down 0.06%. Nikkei 225 is down 0.8% while South\r\nKorean Kospi up 1.6% in the early morning. Wall Street ended at record while\r\nthe dollar sunk against most major currencies. The GIFT Nifty traded higher by\r\n31.5 points or 0.12% at 25,632.5 in the morning, signalling a higher start to\r\nIndian equities Earlier, Indian markets snapped a four-session rally as\r\ninvestors rushed to take some profits off the table. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nbroader markets bucked the trend to gain around 50 basis points each, despite\r\nthe muted market sentiment seen in the benchmarks. Foreign institutional\r\ninvestors (FII/FPI) were net sellers on June 30, selling shares worth Rs 832\r\ncrore, while domestic institutional investors (DII) were net buyers of shares\r\nworth Rs 3,497 crore, provisional data showed.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">L&amp;T - </span></b><span>The company\'s subsidiary L&amp;T\r\nEnergy Green Tech has incorporated a wholly owned arm, Panipat Green Hydrogen. <span style=\"color:#0000FF;\">Positive </span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Hindustan Copper –</span></b><span> It signed MoU with Coal\r\nIndia to identify and evaluate opportunities in copper and critical minerals. <span style=\"color:#0000FF;\">Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">ESAF Small Finance Bank –</span></b><span> It\r\ntransferred NPAs and technically written-off loans worth Rs 733.4 crore to an\r\nasset reconstruction company for Rs 73.34 crore. <span style=\"color:#7030a0;\">Neutral</span></span></li></ul><ul><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Bharat Electronics –</span></b><span> It secured additional orders\r\nworth Rs 528 crore, including radars, EVMs, jammers, shelters, and control\r\ncentres. <span style=\"color:#0000FF;\">Positive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical\r\nUpdate</span></p>\r\n\r\n<ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY\r\n- </span></b><span>The\r\nNifty index witnessed pull back of over 120 points to settle at 25,517 on\r\nMonday. Index encountered profit booking at higher level. Index need to cross\r\n25,750 for further decisive move. Today’s range – 25,450 – 25,750.</span></li></ul><ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY\r\n- </span></b><span>Bank\r\nnifty too slipped towards 57K to close at 57,312 on Monday. Index has been\r\nsupported at 57,200 indicating likely resumption of upward journey. Today’s\r\nrange – 57,000 – 57,800.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEidOh5o1pK-MyQfw8jl3SLnMhIpaFJY9TMThhTff1M_k2zqZEjfffHnVeyQle8wMwL5F6gPG8hwdWsin6vx0WLw6hnB624tCATMqUo7VzNHuBWlFj3dZu8xjLfkQqaT-yRqNAkOZTWPxeR0yKX5cc5oEafGrVoNU6hA7PkO0h5jEdqTiT1AjWk-Ub61dFA','2025-07-01','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(254,'893937136662893239','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૦૧ જુલાઇ ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><div style=\"text-align:center;\"><div style=\"text-align:center;\"><div style=\"text-align:center;\"><b><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEj5dWDMdX5zr7i-9iQquuBYjpk9GjEEYcBC_DFGzXxp8Qs3hnQhuUUCiVntMWssTleJosEKoYPUqswY1JMRUbgV2GJtsCOykETO5SZ3t1cGv3lQFNw3lsCUiQyTSUnX_ExETE1d3RjPQoEeBA8LcQ5psi_fsLQWbGAbM-HgFSjoynJsoaSL6s5S3Q-gi1Y\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEj5dWDMdX5zr7i-9iQquuBYjpk9GjEEYcBC_DFGzXxp8Qs3hnQhuUUCiVntMWssTleJosEKoYPUqswY1JMRUbgV2GJtsCOykETO5SZ3t1cGv3lQFNw3lsCUiQyTSUnX_ExETE1d3RjPQoEeBA8LcQ5psi_fsLQWbGAbM-HgFSjoynJsoaSL6s5S3Q-gi1Y\" width=\"281\" /></a></b></b></div><b><b><br /><b><span>આશિષ શાહ</span></b></b></b></div></div></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></p>\r\n\r\n<ul><li><span>ફિનટેક આધારિત\r\nપર્સનલ લોનમાં ખોટ વધી</span><span>, </span><span>છેલ્લા 6\r\nક્વાર્ટરમાં ડિફોલ્ટ સૌથી ઊંચા</span></li><li><span>મોબિક્વિકે</span><span>સૌરભ</span><span>દ્વિવેદીને</span><span>CTO </span><span>અને ધ્રુવ વાધેરાને </span><span>SVP </span><span>તરીકે પ્રમોશન આપ્યું</span></li><li><span>30 </span><span>મે</span><span>સુધીન</span><span>ા પંદરવાડિયામાં બેંક ક્રેડિટ વૃદ્ધિ ઘટીને 4.9 ટકા: </span><span>RBI</span></li><li><span>મહંગી</span><span>રહેણાંક</span><span>મિલકો</span><span>H</span><span>1 2025 દરમિયાન\r\nમુંબઈના રિયલ એસ્ટેટ સેક્ટરને વેગ આપે છે</span></li><li><span>એમ્બેસી</span><span>REIT</span><span>એ ચાર વર્ષના નીચલા\r\nદરે </span><span>₹</span><span>1,550 </span><span>કરોડના</span><span>દેવાની</span><span>વ્યવસ્થા</span><span>કરી</span></li><li><span>સોના</span><span>કોમસ્ટાર</span><span>ભારતમાં</span><span>EV </span><span>મેગ્નેટ્સનું\r\nઉત્પાદન કરશે – ચીનના નિકાસ નિયંત્રણ વચ્ચે</span></li><li><span>DVC</span><span>એ કર્ણાટકના વિજળી વિતરણ વિભાગ સાથે 300</span><span>\r\nMW </span><span>વીજળી પૂરાં પાડવા માટે લાંબા ગાળાની ડીલ કરી</span></li><li><span>ક્યુરફૂડ્સે</span><span>₹</span><span>800 </span><span>કરોડના</span><span>IPO </span><span>માટે </span><span>SEBI </span><span>સમક્ષ </span><span>DRHP\r\n</span><span>દાખલ કર્યું</span></li><li><span>ફિનટેકે</span><span> 2024</span><span>–</span><span>25</span><span>માં</span><span> 11 </span><span>કરોડ</span><span>લોન</span><span>આપી</span><span>ઓપચારિક</span><span>નાણાકીય</span><span>ઍક્સેસ</span><span>વધાર્ય</span><span>ો</span></li><li><span>નિસાને</span><span>રોકડ</span><span>પ્રવાહ</span><span>વધારવા</span><span>સપ્લાયર</span><span>ચુકવણી</span><span>વિલંબ</span><span>કરવા</span><span>પ્રયાસ</span><span>કર્યા</span><span>: </span><span>કંપનીના</span><span>ઈમેલ્સ</span></li><li><span>વર્લ્ડ</span><span>ગોલ્ડ</span><span>કાઉન્સિલે</span><span>જવાબદારીપૂર્વક</span><span>સોનાના</span><span>ખનન</span><span>માટે</span><span>આહવાન</span><span>કર્યું</span><span>–</span><span>ગુનાહિત</span><span>શોષણ</span><span>અટકાવવા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></p>\r\n\r\n<ul><li><span>એપ્રિલ-મેના મહીનામાં નાણાકીય ખાધ પૂર્ણવર્ષના લક્ષ્યના </span><span>0.8%</span><span> પર રહી: સરકારના આંકડા</span></li><li><span>ભારતે સૈન્ય ખર્ચ </span><span>GDP</span><span>ના </span><span>3%</span><span>ના ધોરણે રાખવો જોઈએ: </span><span>EY </span><span>રિપોર્ટ</span></li><li><span>SKF </span><span>ઈન્ડિયા </span><span>2030</span><span> સુધી </span><span>₹</span><span>1,460</span><span> કરોડનું ઉત્પાદન ક્ષેત્રે રોકાણ કરશે</span></li><li><span>AU </span><span>સ્મોલ ફાઇનાન્સ બેન્કે </span><span>LIC </span><span>સાથે ભાગીદારી\r\nકરી જીવન વીમાનો વિસ્તાર કર્યો</span></li><li><span>નાણામંત્રાલયે જાહેર ક્ષેત્રની બેંકોને ખાનગી સ્પર્ધાની વચ્ચે શાખાઓ વધારવા\r\nકહ્યું</span></li><li><span>ઉત્તર પ્રદેશે </span><span>2025</span><span>માં પ્રવાસીઓની આવક </span><span>1.3</span><span> બિલિયન થવાની અપેક્ષા રાખી</span></li><li><span>HCLTech </span><span>અને </span><span>OpenAI </span><span>વચ્ચે ભાગીદારી</span><span>, </span><span>એન્ટરપ્રાઈઝ </span><span>AI </span><span>અપનાવવાનું વેગ આપવા સહકાર</span></li><li><span>એમ્પલ પાર્ક્સે મહિન્દ્રા વર્લ્ડ સિટીમાં </span><span>71</span><span> એકરના\r\nઉદ્યોગ પાર્કનો પ્રારંભ કર્યો</span></li><li><span>એક્સેન્ચર લર્નવેન્ટેજ અને </span><span>IIT </span><span>મદ્રાસ વચ્ચે </span><span>SDV </span><span>ક્ષેત્રે કૌશલ્ય વિકસાવવા માટે સહયોગ</span></li><li><span>ભારતનું ઔદ્યોગિક ઉત્પાદન મે </span><span>2025</span><span>માં </span><span>1.2%</span><span> સુધી ઘટ્યું</span></li><li><span>વિનફાસ્ટ </span><span>myTVS </span><span>સાથે સેવામાં સહયોગ કરીને ભારતીય બજારમાં પ્રવેશ કરશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></p>\r\n\r\n<ul><li><span>ભારતની </span><span>GST\r\n</span><span>વસુલાતે </span><span>2024-25</span><span>માં સર્વોચ્ચ </span><span>₹</span><span>22.08</span><span> લાખ કરોડનો આંકડો પાર કર્યો</span></li><li><span>ભારતના ઉદ્યોગોને\r\nસર્વસમાવિષ્ટ અને પર્યાવરણલક્ષી વિકાસ માટે મહત્વની ભૂમિકા ભજવવી જોઈએ: </span><span>HUL\r\n</span><span>અધ્યક્ષ</span></li><li><span>ભારત વૈશ્વિક\r\nઉત્પાદન હબ તરીકે ઉભરશે: </span><span>M&amp;M </span><span>ગ્રુપના </span><span>CEO\r\n</span><span>અને </span><span>MD</span></li><li><span>ડેટા સેન્ટર\r\nસેક્ટરમાં ઉછાળો: અનંત રાજે દિલ્હીમાં </span><span>$2</span><span> બિલિયનનું રોકાણ\r\nકરવાનું જાહેર કર્યું</span></li><li><span>ટાઈમઝોન ભારતમાં </span><span>₹</span><span>100</span><span> કરોડના ખર્ચે </span><span>2026</span><span> સુધી </span><span>100</span><span> કેન્દ્રો ખોલવાનો યોજના બનાવી રહી છે</span></li><li><span>રેમન્ડ રિયલ્ટી\r\nમાત્ર ત્યારે જ પ્રોજેક્ટ સાઇન કરશે જો નફાકારકતા </span><span>20%</span><span> હોય</span></li><li><span>Torrent\r\nPharmaceuticals</span><span>એ </span><span>JB Pharma </span><span>ડીલ </span><span>15-18</span><span> મહિનામાં પૂર્ણ થવાની અપેક્ષા વ્યક્ત કરી</span></li><li><span>કોમર્શિયલ વાહન\r\nઉદ્યોગમાં આ નાણાકીય વર્ષમાં </span><span>3-5</span><span> ટકા વૃદ્ધિની\r\nશક્યતા: </span><span>ICRA</span></li><li><span>ઇન્ફ્રામાર્કેટે </span><span>IPO\r\n</span><span>પહેલાં </span><span>MARS Growth Capital </span><span>પાસેથી વધુ </span><span>$50</span><span> મિલિયન મળ્યાં</span></li><li><span>ઓરિક્સે ગ્રીનકો\r\nએનર્જીમાં પોતાનું </span><span>17.5%</span><span> હિસ્સો વેચવાનો નિર્ણય લીધો</span><span>;\r\n</span><span>એએમ ગ્રીનમાં નવું રોકાણ કરશે</span></li><li><span>બાહ્ય અસરોથી\r\nભારતનો વિકાસદર ઘટી શકે છે: </span><span>RBI</span><span>ના સંજય માલ્હોત્રા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before investing,\r\nmentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEj5dWDMdX5zr7i-9iQquuBYjpk9GjEEYcBC_DFGzXxp8Qs3hnQhuUUCiVntMWssTleJosEKoYPUqswY1JMRUbgV2GJtsCOykETO5SZ3t1cGv3lQFNw3lsCUiQyTSUnX_ExETE1d3RjPQoEeBA8LcQ5psi_fsLQWbGAbM-HgFSjoynJsoaSL6s5S3Q-gi1Y','2025-07-01','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(255,'7189794929636061031','Research Report : Indian Financial Markets Outlook - 30th June 2025',NULL,'<a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhSIGA_NVOdHa9KukIP_uaKwrqoxNBiSlfSQq_SYnVNPy8ewVPrh25-6T5ni-7fz3PxmDUm0GV9Tz4AUdzNjBPsF21e8G2r-haclOJy4x0F69Mb9DhaxFLBg43sQsPCVV4ZBSnR6Ygduhip0ysY6TeM_TmAypY30cbgt_4Dq7d3fmf-9rgJOqCQuUHDxGI\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhSIGA_NVOdHa9KukIP_uaKwrqoxNBiSlfSQq_SYnVNPy8ewVPrh25-6T5ni-7fz3PxmDUm0GV9Tz4AUdzNjBPsF21e8G2r-haclOJy4x0F69Mb9DhaxFLBg43sQsPCVV4ZBSnR6Ygduhip0ysY6TeM_TmAypY30cbgt_4Dq7d3fmf-9rgJOqCQuUHDxGI\" width=\"240\" /></a><div style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></div>\r\n\r\n<p><span style=\"color:#FF0000;\">Optimism\r\nprevail over trade deals, markets gain over tailwinds</span></p><div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjHLBwecr-qikpDe97AUTDEBkc7EVThTtCyR81th1ql3o1rEgI2ygzxf0xnv1KNCuOe5x5mYJweEGMG52W5rc6TuvGXDrybBAqT9-tmH4zmaxjLZFClQtOFjf8-HX4GLuL14qcizN82c3nqt2pMu-Hg9kECEMa3e9dcTREv9R-jMHxajVLhBPZ2tx8Zas4\"><img alt=\"\" height=\"275\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjHLBwecr-qikpDe97AUTDEBkc7EVThTtCyR81th1ql3o1rEgI2ygzxf0xnv1KNCuOe5x5mYJweEGMG52W5rc6TuvGXDrybBAqT9-tmH4zmaxjLZFClQtOFjf8-HX4GLuL14qcizN82c3nqt2pMu-Hg9kECEMa3e9dcTREv9R-jMHxajVLhBPZ2tx8Zas4=w491-h275\" width=\"491\" /></a></div></div>\r\n\r\n<p style=\"text-align:justify;\"><span><span>Most of the Asian-Pacific markets rose on Monday morning and headed for\r\nsharp monthly gains, supported by hopes of trade deals with U.S. President\r\nDonald Trump, while attention for the day was on factory activity data from\r\nChina, Japan, and South Korea. US futures edged higher in Asian trading hours\r\non Monday. Japan’s Nikkei 225 jumped over 1.6% to its highest level since mid-July,\r\nboosted by tech stocks.</span></span></p><p style=\"text-align:justify;\"><span>The\r\ntrends on Gift Nifty also indicate a positive start for the Indian benchmark\r\nindex. The Gift Nifty was trading around 25,770 level, a premium of nearly 20\r\npoints from the Nifty futures’ previous close. Meanwhile, India’s trade team\r\nextended its stay in US to iron out differences as the two sides look to clinch\r\na deal before the July 9 deadline. Trump also said he doesn’t think he’ll need\r\nto extend the deadline.</span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Fundamental\r\nUpdate</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Torrent Pharma:</span></b><span>Company is\r\ngoing to acquire controlling stake in JB Chemicals at equity valuation of Rs\r\n25,689 crore, followed by merger. <span style=\"color:#0000FF;\">Positive</span></span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Hind Rectifiers</span></b><b><span> – </span></b><span>It\r\nwon Rs 127 crore order from Indian Railways to be executed by FY27. <span style=\"color:#0000FF;\">Positive</span></span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">AU Small Finance Bank </span></b><b><span>– </span></b><span>Bank\r\napproved Rs 11,000 crore fundraising limits for 12 months and appointed Jagajit\r\nMangal Prasad as independent director. <span style=\"color:#0000FF;\">Positive</span></span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Gujarat Industries Power –</span></b><span>It\r\nhas commissioned 105 MW of 600 MW Khavda solar project. <span style=\"color:#0000FF;\">Positive</span></span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Technical\r\nUpdate</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">NIFTY\r\n–</span></b><span>The\r\nNifty index continued upside journey to settle at 25,638 on Friday. Index is\r\nlooking to buck the trend to make over 4% gain in the month of June, on\r\npositive momentum.Today’s range – 25,550 – 25,850.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">BANKNIFTY\r\n– </span></b><span>Bank\r\nnifty has marched further towards all time high to close at 57,444 on Friday.\r\nIndex has broken near term resistance of 57,200 and likely to head towards 58K\r\nthis week. Today’s range – 57,200 – 57,800.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEhSIGA_NVOdHa9KukIP_uaKwrqoxNBiSlfSQq_SYnVNPy8ewVPrh25-6T5ni-7fz3PxmDUm0GV9Tz4AUdzNjBPsF21e8G2r-haclOJy4x0F69Mb9DhaxFLBg43sQsPCVV4ZBSnR6Ygduhip0ysY6TeM_TmAypY30cbgt_4Dq7d3fmf-9rgJOqCQuUHDxGI','2025-06-30','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(256,'6799808815872458683','Nifty Outlook :- 30.06.2025 - CFA Hitesh Somani',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEisNAxO9aR8pjBtUE8-E3O_vCsE7yvX3wLmrwV4ir7ygahqFgtstTnWyw77G9sbjaA6AjPwlm5oquE1UUWSrfe1a2vXCxdOLDQrn93_osMAV9FXP5QbouWnqzF_eFyoQWheeZc-AoMXp2dUBOzyaXobdcwxmK-Avin-Wfz1musvOBiPX92lM2xszx_7Y6E\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEisNAxO9aR8pjBtUE8-E3O_vCsE7yvX3wLmrwV4ir7ygahqFgtstTnWyw77G9sbjaA6AjPwlm5oquE1UUWSrfe1a2vXCxdOLDQrn93_osMAV9FXP5QbouWnqzF_eFyoQWheeZc-AoMXp2dUBOzyaXobdcwxmK-Avin-Wfz1musvOBiPX92lM2xszx_7Y6E\" width=\"255\" /></a></div><br /><div style=\"text-align:center;\"><b><span>CFA Hitesh Somani<br /></span></b><b><span>MD - Aapka Investments <br /></span></b><b><span>Website - https://www.aapkainvestments.in</span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#2b00fe;\">MARKETS\r\nZOOMING BROKE THE MAJOR MAKE OR BREAK LEVEL. WILL NIFTY BREAK THE LIFE HIGH\r\nSOON…..?</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Last\r\nweek we saw a powerful move by bulls in the markets, Nifty broke the major\r\nresistance of 25200 levels and closed near 25600 levels as we predicted in our\r\nlast week report. Now nifty is in all green condition but yet we can see some\r\nprofit bookings at these levels but overall the markets are bullish and\r\ninvestors can now see nifty making new highs soon.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Banknifty\r\nalso witnessed a strong move by bulls in the last week and banknifty made a\r\nfresh life high of 57475 on Friday. Banknifty is comparatively trading stronger\r\nthan nifty as it has made three fresh highs in the recent past still nifty is\r\nyet to break the life high since September 2024 which was 26277, so we can say\r\nnifty is still 700 points aways from its lifetime high. Banknifty now have a\r\nmajor resistance @58000 levels if it breaks above that we may see banknifty\r\n@59000 levels soon also if we some profit bookings at the current levels then\r\nwe must mark the major support @56500 as below that we can see it fall sharply.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Nifty\r\nis overall bullish but we can see some profit bookings @25600 levels, if it\r\nbreaks above that then the major resistance will be 26000 levels and if it\r\nfalls then the support will be @25200 levels.</span></p>\r\n\r\n<p><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n<p><span style=\"text-align:justify;\">Major\r\nSupport Levels for Nifty</span></p>\r\n\r\n<ul><li><span>Support\r\n1 – 25200</span></li><li><span>Support\r\n2 – 24900</span></li><li><span>Support\r\n3 – 24500</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"text-align:justify;\">Major\r\nResistance Levels for Nifty</span></p>\r\n\r\n<ul><li><span>Resistance\r\n1 – 25900</span></li><li><span>Resistance\r\n2 – 26200</span></li><li><span>Resistance\r\n3 – 26500</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Major\r\nSupport Levels for Banknifty</span></p>\r\n\r\n<ul><li><span>Support\r\n1 – 56500</span></li><li><span>Support\r\n2 – 56000</span></li><li><span>Support\r\n3 – 55500</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>Major\r\nResistance Levels for Banknifty</span></p>\r\n\r\n<ul><li><span>Resistance\r\n1 – 57800</span></li><li><span>Resistance\r\n2 – 58200</span></li><li><span>Resistance\r\n3 – 58700</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n<p><b><span>1)\r\nATGL</span></b></p><div style=\"text-align:justify;\"><span style=\"text-align:justify;\">CMP\r\n@ 682<br /></span><span style=\"text-align:justify;\">Buy\r\nAbove @ 700<br /></span><span>Stop\r\nLoss Below @ 640<br /></span><span>Targets\r\n@ 740, 790 and 890</span></div><div style=\"text-align:justify;\"><b><span>2)\r\nBIRLACORPN</span></b></div>\r\n\r\n<div style=\"text-align:justify;\"><span>CMP\r\n@ 1335<br /></span><span>Buy\r\nAbove @ 1350<br /></span><span>Stop\r\nLoss @ 1260<br /></span><span>Targets\r\n@ 1390, 1440 and 1490</span></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>3)\r\nKPRMILL</span></b></p>\r\n\r\n<div style=\"text-align:justify;\"><span>CMP\r\n@ 1140<br /></span><span>Buy\r\nAbove @ 1155<br /></span><span>Stop\r\nLoss @ 1110<br /></span><span>Targets\r\n@ 1195, 1245 and 1295</span></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>4)\r\nHEG</span></b></p>\r\n\r\n<div style=\"text-align:justify;\"><span>CMP\r\n@ 510<br /></span><span>Buy\r\nAbove @ 530<br /></span><span>Stop\r\nLoss @ 490<br /></span><span>Targets\r\n@ 555, 585 and 625</span></div><div style=\"text-align:justify;\"><span><span style=\"color:#FF0000;\">The\r\nsecurities quoted are for illustration only and are not recommendatory. Investment\r\nin securities market are subject to market risks. Read and agree Disclaimer and\r\nrelated all the documents carefully before investing, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;\">www.nikhilbhatt.in</span></a></span></span></div>','https://blogger.googleusercontent.com/img/a/AVvXsEisNAxO9aR8pjBtUE8-E3O_vCsE7yvX3wLmrwV4ir7ygahqFgtstTnWyw77G9sbjaA6AjPwlm5oquE1UUWSrfe1a2vXCxdOLDQrn93_osMAV9FXP5QbouWnqzF_eFyoQWheeZc-AoMXp2dUBOzyaXobdcwxmK-Avin-Wfz1musvOBiPX92lM2xszx_7Y6E','2025-06-28','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(257,'7940170220010585005','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૮ જુન ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEh6HglOe5Vh_GDyqLgtdndfdkVy22hdUmQvdXeBYw3o1J9SPOn0WT5Ytn-Pq70ZzoyMLj_6c5zrMJWH18HlgvhC3FjapFFh_2rXbCCFyjZqQvZg3_UwLyo8tNR0V3zboeMXacs39PK3aKY8zpe6TjTfyjioynu06G1MlxmRhxIovU3S2QXdO38ajsU4saw\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEh6HglOe5Vh_GDyqLgtdndfdkVy22hdUmQvdXeBYw3o1J9SPOn0WT5Ytn-Pq70ZzoyMLj_6c5zrMJWH18HlgvhC3FjapFFh_2rXbCCFyjZqQvZg3_UwLyo8tNR0V3zboeMXacs39PK3aKY8zpe6TjTfyjioynu06G1MlxmRhxIovU3S2QXdO38ajsU4saw\" width=\"281\" /></a></b></div><div style=\"text-align:center;\"><b><span style=\"color:#0000FF;\">આશિષ શાહ<br /></span></b><b><span style=\"color:#0000FF;\">Wealth\r\nMultilpliers<br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઈમ્સ:</span></b></span></p>\r\n\r\n<ul><li><span>નાણામંત્રી પીએસયૂ\r\nબેંકોને ક્રેડિટ વૃદ્ધિ અને નફાકારકતા જાળવવા પ્રોત્સાહન આપે છે</span></li><li><span>ભારતના</span><span>વિદેશી</span><span>વિનિમય</span><span>ભંડાર</span><span>₹</span><span>1.02 </span><span>બિલિયન</span><span>ઘટીને</span><span>₹</span><span>697.93 </span><span>બિ</span><span>લિયન (20 જૂન સુધી)</span></li><li><span>કાપેલા</span><span>અને</span><span>પોલિશ્ડ</span><span>હીરાના</span><span>નિકાસમાં</span><span>FY</span><span>26માં 7%-10% ઘટાડો\r\nથશે: </span><span>ICRA</span></li><li><span>JSW </span><span>પેઇન્ટ્સનું </span><span>₹</span><span>12,915 </span><span>કરોડનું</span><span>અકઝો</span><span>નોબેલ</span><span>ઈન્ડિયાનું</span><span>પ્રસ્તાવિત</span><span>અધિગ્રહણ</span><span>ટોપ</span><span>ડીલ્સમાં</span></li><li><span>ચીનની</span><span>ફેશન</span><span>રિટેલર</span><span>શેઇન</span><span>હૉંગકોંગ</span><span>IPO </span><span>માટે ગુપ્ત રીતે\r\nફાઈલ કરશે: સૂત્રો</span></li><li><span>આઈ</span><span>સીઆઈસીઆઈ બેંક પોતાના </span><span>AMC ICICI\r\nPrudential </span><span>માં 2% વધુ હિસ્સો ખરીદશે</span></li><li><span>LTTS </span><span>ટેક્સાસમાં એન્જિનિયરિંગ હબ શરૂ કરશે</span><span>;\r\n</span><span>350 નોકરીઓ ઊભી કરશે</span></li><li><span>JSW </span><span>અકઝો નોબેલ ડીલ માટે </span><span>₹</span><span>4,000 </span><span>કરોડનું</span><span>દેવું</span><span>બહાર</span><span>પાડશે</span></li><li><span>રિયલ</span><span>એસ્ટેટ</span><span>માર્કેટ</span><span> 2-3 </span><span>વર્ષ</span><span>મજબૂત</span><span>રહેશે</span><span>;\r\n</span><span>પ્રીમિયમ હાઉસિંગ ગ્રોથ લાવશે: રોનાલ્ડ સિયોની</span></li><li><span>TVS </span><span>એ નવું એપાચે </span><span>RTR </span><span>160 </span><span>₹</span><span>1.34 </span><span>લાખમાં</span><span>લૉન્ચ</span><span>કર્યું</span></li><li><span>GIA </span><span>લૅબ-ગ્રોણ હીરા માટે 4</span><span>Cs </span><span>સર્ટિફિકેશન બંધ કરશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ:</span></b></span></p>\r\n\r\n<ul><li><span>માર્ચ 2025 સુધીમાં એમએસએમઈ ક્રેડિટ </span><span>₹</span><span>40 લાખ કરોડથી વધુ</span><span>, </span><span>દર વર્ષે 20% વૃદ્ધિ</span></li><li><span>ઓરોબિન્ડો ફાર્મા અમેરિકામાં 4,600 થી વધુ બોટલ પેઇનકિલર પાછી મંગાવે છે</span></li><li><span>એસબીઆઈ ઓગસ્ટ સુધી ટિયર </span><span>II </span><span>બૉન્ડ ઇશ્યૂથી\r\nઋણ ઉપાડવાની શક્યતા</span></li><li><span>બાયોકોન બાયોલોજિક્સ કૅનેડામાં આગામી મહિને યેસાફિલી નામનું આયલિયા બાયોસિમિલર\r\nલૉન્ચ કરશે</span></li><li><span>ઇઝરાયેલ-ઈરાન યુદ્ધવિરામ બાદ માંગમાં વધારો</span><span>, </span><span>ચા\r\nનિકાસકર્તાઓમાં સાવચેતી સાથે આશાવાદ</span></li><li><span>ઉદ્ભયમાન શહેરો અને એજ સેન્ટર્સ ડેટા સ્ટોરેજ ઇન્ફ્રા વધારશે: એનઇએસ ડેટા</span></li><li><span>વેકફિટ ઇનોવેશન્સે સેબી સાથે ડ્રાફ્ટ પેપર ફાઈલ કર્યા</span><span>; </span><span>₹</span><span>468 કરોડ ઉઠાવવાની તૈયારી</span></li><li><span>શોભા ગ્રેટર નોઇડામાં નવી લક્ઝરી હોમ સ્કીમ માટે </span><span>₹</span><span>800 કરોડનું રોકાણ કરશે</span></li><li><span>સરકાર અને ઉદ્યોગ મળીને રેર અર્થ મેગ્નેટ મુદ્દાઓને ઉકેલવા પ્રયાસશીલ: મેઇટી અધિકારી</span></li><li><span>ડીએચએલ એક્સપ્રેસે બૅન્ગલોરમાં </span><span>₹</span><span>34 કરોડના સર્વિસ સેન્ટરનો\r\nપ્રારંભ કર્યો</span></li><li><span>જીયો બ્લૅકરૉક બ્રોકિંગને બ્રોકરેજ બિઝનેસ માટે સેબીથી મંજૂરી મળી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ:</span></b></span></p>\r\n\r\n<ul><li><span>ભારતે યુએસ સાથેના\r\nવેપાર કરારમાં ખેડૂતો</span><span>, </span><span>ડિજિટલ ઈકોસિસ્ટમ અને નીતિ સ્થાને સંરક્ષણ\r\nઆપવું જોઈએ: </span><span>GTRI</span></li><li><span>મેમાં</span><span>રશિયાથી</span><span>ભારતનો</span><span>કૉલ</span><span> આયાત છેલ્લા બે\r\nવર્ષમાં સૌથી વધુ: અહેવાલ</span></li><li><span>ઓએનજીસીએ</span><span>આસામના</span><span>શિવસાગરમાં</span><span>ક્રૂડ</span><span>તેલનો</span><span>બ્લોઆઉટ</span><span>કાબૂમાં</span><span>લીધો</span><span>: </span><span>હરદીપસિંહ</span><span>પુરી</span></li><li><span>ભારતે</span><span>કતારમાં</span><span>ગુલાબી</span><span>સુગંધવાળા</span><span>લિચીનો</span><span>પહેલો</span><span>જથ્થો</span><span>નિકાસ</span><span>કર્યો</span></li><li><span>યુએસ</span><span>-</span><span>ચીન</span><span>વચ્ચે</span><span>વેપાર</span><span>કરાર</span><span>પૂર્ણ</span><span>, </span><span>રેર અર્થ નિકાસ ઉપર\r\nધ્યાન કેન્દ્રિત</span></li><li><span>5</span><span>G\r\n</span><span>પછી</span><span>, </span><span>બીએસએનએલ નવા\r\nગ્રાહકો માટે ‘ફ્લેશ સેલ’ લાવશે</span></li><li><span>વેદાંતા</span><span>થી</span><span>ટાટા</span><span>સ્ટીલ</span><span>: </span><span>H</span><span>1</span><span>CY</span><span>25માં ઉતાર-ચઢાવ પછી ધાતુ ઇન્ડેક્સ માટે </span><span>H</span><span>2 આશાસ્પદ</span></li><li><span>PNB </span><span>હાઉસિંગ </span><span>₹</span><span>10,000 </span><span>કરોડ</span><span>ઉઠાવવા</span><span>બોર્ડ</span><span>મીટીંગનું</span><span>આયોજન</span><span>કરશે</span></li><li><span>ક્રેડિલા</span><span>ફાઇનાન્સીયલ</span><span>સર્વિસેસે</span><span>IPO </span><span>માટે </span><span>₹</span><span>5,000 </span><span>કરોડનું</span><span>ફા</span><span>ઈલિંગ કર્યું</span></li><li><span>JSW, </span><span>બ્લૅકસ્ટોન</span><span>, </span><span>સેરેન્ટિકા</span><span>,\r\n</span><span>બ્રુકફિલ્ડ – વાઈબ્રન્ટ એનર્જીના અધિગ્રહણ માટે રસ\r\nદર્શાવ્યો</span></li><li><span>બીરા</span><span>બિયર</span><span>ઉત્પાદકે</span><span>₹</span><span>85 કરોડનું રાઇટ્સ ઇશ્યૂ બહાર પાડ્યું</span><span>,\r\n</span><span>ખર્ચ ઘટાડવા કર્મચારીઓ ઘટાડ્યા</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEh6HglOe5Vh_GDyqLgtdndfdkVy22hdUmQvdXeBYw3o1J9SPOn0WT5Ytn-Pq70ZzoyMLj_6c5zrMJWH18HlgvhC3FjapFFh_2rXbCCFyjZqQvZg3_UwLyo8tNR0V3zboeMXacs39PK3aKY8zpe6TjTfyjioynu06G1MlxmRhxIovU3S2QXdO38ajsU4saw','2025-06-28','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(258,'3512530513858265486','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૭ જુન ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiD-tiUIDPCPItM2Mernjzyid1-WZi1ZNuvaZ1CnfPxA1qJDKhGPf42MO5T0ZTcpzZxkR3Ppuxt6LN2pvSD9b2zBk_6fpB5aV6QtEKvpVx86EhHjKeqyNoZ2mntyNlqa3qHHqEh21tEUUdTVlGosnO-ch-YQj33VZqVmsM3XPfeER5ZsS515dswq5Vb7ds\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiD-tiUIDPCPItM2Mernjzyid1-WZi1ZNuvaZ1CnfPxA1qJDKhGPf42MO5T0ZTcpzZxkR3Ppuxt6LN2pvSD9b2zBk_6fpB5aV6QtEKvpVx86EhHjKeqyNoZ2mntyNlqa3qHHqEh21tEUUdTVlGosnO-ch-YQj33VZqVmsM3XPfeER5ZsS515dswq5Vb7ds\" width=\"281\" /></a></b></div><div style=\"text-align:center;\"><b><span><span style=\"color:#2b00fe;\">આશિષ શાહ<br /></span></span></b><b><span><span style=\"color:#2b00fe;\">Wealth\r\nMultilpliers</span><br /></span></b><b><span style=\"color:#FF0000;\">મો. XXXXX XXXXX<br /></span></b><b><span style=\"color:#FF0000;\">E</span></b><b><span style=\"color:#FF0000;\">mail -</span></b><b><span style=\"color:#FF0000;\"> <span>contact@example.com</span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span><span style=\"color:#2b00fe;\">ઇકોનોમિક ટાઈમ્સ:</span></span></b></p>\r\n\r\n<ul><li style=\"text-align:left;\"><span>કેન્દ્ર સરકાર વર્ષ\r\n</span><span>2026</span><span>માં પ્રથમ રાષ્ટ્રીય ઘરકમાણી સર્વે કરવાની\r\nયોજના બનાવી રહી છે</span></li><li style=\"text-align:left;\"><span>ઓમાન</span><span>આવકવેરો</span><span>લાગુ</span><span>કરનાર</span><span>પ્રથમ</span><span>ખાડી</span><span>દેશ</span><span>બન્યો</span></li><li style=\"text-align:left;\"><span>નાણાં</span><span>મંત્રાલય</span><span>યુનિફાઇડ</span><span>લેન્ડિંગ</span><span>ઇન્ટરફેસને</span><span>વિસ્તૃત</span><span>કરવાના</span><span>મુદ્દે</span><span>બેઠક</span><span>આયોજિત</span><span>કરી</span></li><li style=\"text-align:left;\"><span>ભારતીય</span><span>કંપનીઓ</span><span>ચીનના</span><span>રેયર</span><span>અર્થ</span><span>પરના</span><span>પ્રભાવને</span><span>ઓછી</span><span>કરવા</span><span>માટે</span><span>યોજના</span><span>રજૂ</span><span>કરે</span><span>છે</span></li><li style=\"text-align:left;\"><span>ખરીફ ડાંગરનું વાવેતર </span><span>58</span><span>% વધીને </span><span>13.22</span><span> લાખ હેક્ટર\r\nથયું: સરકાર</span></li><li style=\"text-align:left;\"><span>ઈઝરાયલ</span><span>-</span><span>ઈરાન</span><span>તણાવથી</span><span>ભારતનું</span><span>ચલણ</span><span>ખાધ</span><span> જીડીપીના 0.3% જેટલું વધે તેવો અંદાજ: </span><span>ICRA</span></li><li style=\"text-align:left;\"><span>કોલગેટ</span><span>-</span><span>પામોલિવ</span><span>પોતાના</span><span>વૈશ્વિક</span><span>પોર્ટફોલિયોમાંથી</span><span>વધુ</span><span>બ્રાન્ડ્સ</span><span>ભારતમાં</span><span>રજૂ</span><span>કરશે</span></li><li style=\"text-align:left;\"><span>ઇન્કસ્પેઝે</span><span>ટ્રાયોસનું</span><span>અધિગ્રહણ</span><span>કર્યું</span><span>;\r\n</span><span>$25 મિલિયનના પ્રી-</span><span>IPO </span><span>માટે તૈયારી</span></li><li style=\"text-align:left;\"><span>મીશોનું</span><span>રિવર્સ</span><span>ફ્લિપ</span><span>પ્રક્રિયા</span><span>પૂર્ણ</span><span>;\r\n</span><span>2–3 અઠવાડિયામાં </span><span>DRHP </span><span>ફાઇલ કરી શકે છે</span></li><li style=\"text-align:left;\"><span>પમ્પ્લિયાનો</span><span> $1 </span><span>બિલિયનના</span><span>મર્જર</span><span>દ્વારા</span><span>બિટકોઇન</span><span>ટ્રેઝરી</span><span>કંપની</span><span>બનાવશે</span></li><li style=\"text-align:left;\"><span>પેયુ</span><span>ઇન્ડિયાની</span><span>આવક</span><span>FY</span><span>25માં 12% વધીને </span><span>₹</span><span>4,300 </span><span>કરોડ</span><span>થઇ</span></li><li style=\"text-align:left;\"><span>પ્રસસે</span><span>વર્ષભરનાં</span><span>કમાણી</span><span>લક્ષ્યાંકો</span><span>પાર</span><span>કરીને</span><span> $7.4 </span><span>બિલિયન</span><span>હાંસલ</span><span>કર્યા</span></li><li style=\"text-align:left;\"><span>ભારત–અમેરિકા</span><span>વેપાર</span><span>કરાર</span><span> 26% </span><span>ટેરિફ</span><span>ડેડ</span><span>લાઇન પહેલાં અટક્યો</span></li><li style=\"text-align:left;\"><span>વારી</span><span>રિન્યુએબલ</span><span>ટેકે</span><span>વિયેતનામમાં</span><span> 100 </span><span>મેગાવોટ</span><span>સૌરઉર્જા</span><span>માટે</span><span>કરાર</span><span>કર્યો</span></li><li style=\"text-align:left;\"><span>બંધન</span><span>બેંકે</span><span>ચાર</span><span>રાજ્યોમાં</span><span> 18 </span><span>નવી</span><span>શાખાઓ</span><span>શરૂ</span><span>કરી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span><span style=\"color:#2b00fe;\">બિઝનેસ સ્ટાન્ડર્ડ:</span></span></b></p>\r\n\r\n<ul><li style=\"text-align:left;\"><span>ટાટા કેપિટલ $2\r\nબિલિયન </span><span>IPO\r\n</span><span>પહેલાં રાઈટ્સ ઈશ્યૂ લાવવાની તૈયારીમાં</span></li><li style=\"text-align:left;\"><span>એડેલવાઈસ</span><span>ARC </span><span>₹</span><span>6,000 </span><span>કરોડ</span><span>વસૂલાત</span><span> અને </span><span>₹</span><span>1,000 </span><span>કરોડ</span><span>NPA </span><span>ખરીદીની યોજના બનાવે છે</span></li><li style=\"text-align:left;\"><span>B-</span><span>30 વિસ્તારોમાં </span><span>SIP </span><span>બંધ થવાનો દર વધારે\r\nરહ્યો</span></li><li style=\"text-align:left;\"><span>કેન્દ્રએ</span><span>એકીકૃત</span><span>પેન્શન</span><span>યોજના</span><span>પસંદ</span><span>કરવાની</span><span>ડેડલાઇન</span><span> 30 </span><span>સપ્ટેમ્બર</span><span> 2025 </span><span>સુધી</span><span>વિસ્તારી</span></li><li style=\"text-align:left;\"><span>મે</span><span>મહિનામાં</span><span>ભારતનું</span><span>આઉટવર્ડ</span><span>FDI </span><span>ઘટીને $2.83 બિલિયન\r\nથયો</span></li><li style=\"text-align:left;\"><span>રેમંડે</span><span>આંધ્ર</span><span>પ્રદેશ</span><span>માં </span><span>₹</span><span>1,200 </span><span>કરોડનું</span><span>રોકાણ</span><span>કરવાનું</span><span>જાહેરાત</span><span>કરી</span></li><li style=\"text-align:left;\"><span>SBI </span><span>જનરલમાં વોર્બર્ગે પોતાનો 10% હિસ્સો વેચવા માટે પ્રેમજી\r\nઇન્વેસ્ટ અને </span><span>SBI\r\n</span><span>સાથે ચર્ચા કરી</span></li><li style=\"text-align:left;\"><span>આઈડીઆફોર્જ</span><span>ટેકનોલોજીને</span><span>ભારતીય</span><span>સેના</span><span>તરફથી</span><span>₹</span><span>137 </span><span>કરોડનો</span><span>ડ્રોન</span><span>ઓર્ડર</span></li><li style=\"text-align:left;\"><span>બ્રિગેડ</span><span>એન્ટરપ્રાઇઝે</span><span>ચેન્નઈમાં</span><span>નવા</span><span>હાઉસિંગ</span><span>પ્ર</span><span>ોજેક્ટમાંથી </span><span>₹</span><span>2,100 </span><span>કરોડ</span><span>કમાવાનો</span><span>લક્ષ્યાંક</span><span>રાખ્યો</span></li><li style=\"text-align:left;\"><span>પશ્ચિમી</span><span>એશિયાની</span><span>તણાવ</span><span>વચ્ચે</span><span>રૂપિયો</span><span> 16 </span><span>પૈસા</span><span>ઘટીને</span><span> 86.74/</span><span>$ </span><span>પર બંધ</span></li><li style=\"text-align:left;\"><span>એસીમ</span><span>સોલરે</span><span>રાજસ્થાનમાં</span><span> 250 </span><span>મેગાવોટ</span><span>પ્રોજેક્ટ</span><span>માટે</span><span>₹</span><span>1,072 </span><span>કરોડનું</span><span>રિફાઇનાન્સિંગ</span><span>મેળવ્યું</span></li><li style=\"text-align:left;\"><span>એનટિપીસી</span><span>બોન્ડ</span><span>દ્વારા</span><span>₹</span><span>18,000 </span><span>કરોડ</span><span>ઉઠાવવાની</span><span>મંજ</span><span>ૂરી માટે\r\nશેયરહોલ્ડરોની મંજૂરી માંગશે</span></li><li style=\"text-align:left;\"><span>ફોનપે</span><span> $1.5 </span><span>બિલિયન</span><span>IPO </span><span>લાવશે</span><span>,\r\n</span><span>ઓગસ્ટની શરૂઆતમાં ડ્રાફ્ટ પેપર ફાઈલ કરાશે</span></li><li style=\"text-align:left;\"><span>2025 </span><span>ની</span><span>પહેલી</span><span>છમાસિક</span><span>દરમિયાન</span><span>રિયલ</span><span>એસ્ટેટમાં</span><span>ઇન્સ્ટિટ્યુશનલ</span><span>મૂડી</span><span>પ્રવાહ</span><span> 37% </span><span>ઘટ્યો</span></li><li style=\"text-align:left;\"><span>રિલાયન્સ</span><span>ઈન્ફ્રાની</span><span>સહાયક</span><span>કંપનીએ</span><span>યેસ</span><span>બેંકને</span><span>₹</span><span>273 </span><span>કરોડ</span><span>ચૂકવ્ય</span><span>ા</span></li><li style=\"text-align:left;\"><span>ઉદ્યોગોને</span><span>GST </span><span>લાભદાયી લાગ્યો\r\nપરંતુ સ્પષ્ટતા અને વિવાદ નિવારણની માગણી</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span><span style=\"color:#2b00fe;\">ફાઇનાન્સિયલ એક્સપ્રેસ:</span></span></b></p>\r\n\r\n<ul><li style=\"text-align:left;\"><span>રિટેલ દિશામાં આગલા\r\nપગલાં: આદિત્ય બિરલાએ દર વર્ષે </span><span>₹</span><span>300</span><span> કરોડનું રોકાણ\r\nકરવાનું લક્ષ્ય</span></li><li style=\"text-align:left;\"><span>પેપર અરિઝોનાએ </span><span>₹</span><span>100</span><span> કરોડ આવક પાર કરી</span><span>; 2026</span><span>માં </span><span>IPO </span><span>લાવવાનો આયોજન</span></li><li style=\"text-align:left;\"><span>ફાર્મઇઝીના સ્થાપકો\r\nફરી મળીને ‘ઓલ હોમ’ નામની ઈન્ટિરિયર ડિઝાઇન કંપની શરૂ કરશે</span><span>;\r\n</span><span>મૂલ્યાંકન </span><span>$120</span><span> મિલિયન</span></li><li style=\"text-align:left;\"><span>કૃષિ ઉત્પાદનોની\r\nનિકાસ એપ્રિલ-મેમાં </span><span>8% </span><span>વધીને </span><span>$4.2 </span><span>બિલિયન થઈ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span><span style=\"color:#2b00fe;\">મિન્ટ:</span></span></b></p>\r\n\r\n<ul><li style=\"text-align:left;\"><span>ઈટાલિયન એનર્જી\r\nગ્રૂપ</span><span>એ </span><span>Plenitude</span><span>માં પોતાની </span><span>20%</span><span> હિસ્સદારી </span><span>$2.3</span><span> બિલિયનમાં વેચી</span></li><li style=\"text-align:left;\"><span>ઝુકરબર્ગે </span><span>AI </span><span>માટે </span><span>₹</span><span>100</span><span> મિલિયન પેકેજ સાથે ભરતી ઝુંબેશ ચલાવી</span></li><li style=\"text-align:left;\"><span>અદાણીએ ભારતનો\r\nપહેલો ઓફ-ગ્રિડ ગ્રીન હાઈડ્રોજન પ્લાન્ટ શરૂ કર્યો</span></li><li style=\"text-align:left;\"><span>HSBC </span><span>રિપોર્ટ મુજબ\r\nજૂનમાં ભારતની આર્થિક પ્રવૃત્તિએ </span><span>14</span><span> મહિનાનો ટોચનો અંક સ્પર્શ્યો</span></li><li style=\"text-align:left;\"><span>SECI 7.24 </span><span>લાખ ટન ગ્રીન\r\nએમોનિયા ઉત્પાદન માટે ટેન્ડર અંતિમ કરવા તૈયારીમાં</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<span style=\"color:#FF0000;\">The securities quoted are\r\nfor illustration only and are not recommendatory. Investment in securities\r\nmarket are subject to market risks. Read and agree Disclaimer and related all\r\nthe documents carefully before investing, mentioned </span>','https://blogger.googleusercontent.com/img/a/AVvXsEiD-tiUIDPCPItM2Mernjzyid1-WZi1ZNuvaZ1CnfPxA1qJDKhGPf42MO5T0ZTcpzZxkR3Ppuxt6LN2pvSD9b2zBk_6fpB5aV6QtEKvpVx86EhHjKeqyNoZ2mntyNlqa3qHHqEh21tEUUdTVlGosnO-ch-YQj33VZqVmsM3XPfeER5ZsS515dswq5Vb7ds','2025-06-27','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(259,'3159355580432944573','બિઝનેસ ન્યુઝ હેડલાઇન્સ - ૨૬ જુન ૨૦૨૫',NULL,'<div style=\"text-align:center;\">\r\n\r\n<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEidwqwFIr_No8TxQ8L4N3DytdErrZJQR-vo90iOASQeMxtqx0_g4Mate8y6gOGbwz7wqyeboBcN17_0kuL764YRnXJxCzLg1w_RdJ2BLwIFo-mF3GA48RuDQBAQ1Clw1jy-3OENeQavI-QAFzMr_lpyFAQtKNILAGFAJ4KthQy1WdiRV4XHXoYR3VP5r4c\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEidwqwFIr_No8TxQ8L4N3DytdErrZJQR-vo90iOASQeMxtqx0_g4Mate8y6gOGbwz7wqyeboBcN17_0kuL764YRnXJxCzLg1w_RdJ2BLwIFo-mF3GA48RuDQBAQ1Clw1jy-3OENeQavI-QAFzMr_lpyFAQtKNILAGFAJ4KthQy1WdiRV4XHXoYR3VP5r4c\" width=\"281\" /></a></b></div><p><b><span><span style=\"color:#2b00fe;\">આશિષ શાહ</span></span></b></p><b><span><span style=\"color:#2b00fe;\">Wealth Multilpliers</span><br /></span></b><span style=\"color:#FF0000;\"><b><span>Mo. XXXXX XXXXX<br /></span></b><b><span>E</span></b><b><span>mail -</span></b></span><b><span><span><span style=\"color:#FF0000;\">contact@example.com</span></span></span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>બિઝનેસ સ્ટાન્ડર્ડ\r\n:</span></b></span></p>\r\n\r\n<ul style=\"text-align:left;\"><li><span style=\"text-align:justify;\">સરકાર તરફથી પુણે\r\nમેટ્રો ફેઝ-</span><span style=\"text-align:justify;\">2</span><span style=\"text-align:justify;\"> માટે </span><span style=\"text-align:justify;\">₹</span><span style=\"text-align:justify;\">3,626</span><span style=\"text-align:justify;\"> કરોડ મંજૂર</span><span style=\"text-align:justify;\">,\r\n</span><span style=\"text-align:justify;\">જે મહત્વના </span><span style=\"text-align:justify;\">IT </span><span style=\"text-align:justify;\">હબ્સને જોડશે</span></li><li><span>2025</span><span> ની પ્રથમ છ મહિને ભારતીય સ્ટાર્ટઅપ ફંડિંગમાં </span><span>25%</span><span> ઘટાડો</span><span>, </span><span>ટ્રેક્સન અનુસાર\r\nવિશ્વમાં ત્રીજી સ્થાને</span></li><li><span>બેંકોને ગ્રાહક\r\nસેવા વધુ સુધારવાની જરૂર: ડીએફએસ સચિવ</span></li><li><span>ઇન્ડિયાબોન્ડ્સે\r\nવૃદ્ધિ માટે પ્રથમ ફંડિંગ રાઉન્ડમાં </span><span>₹</span><span>32.5</span><span> કરોડ ભેગા કર્યા</span></li><li><span>FASTag </span><span>વાર્ષિક પાસથી ટોલ રોડ ઑપરેટર્સને </span><span>4-8%</span><span> આવક ઘટાડો થઈ શકે છે: ક્રિસિલ</span></li><li><span>ટાટા પ્લે નું </span><span>FY25</span><span> નુકસાન વધીને </span><span>₹</span><span>529</span><span> કરોડ થયું</span><span>, </span><span>આવક ઘટીને </span><span>₹</span><span>4,082</span><span> કરોડ રહી</span></li><li><span>યુકે વડા પ્રધાન\r\nકિઅર સ્ટારમરે જણાવ્યું કે તેઓ ન્યુક્લિયર બોમ્બ લઈ જવા સક્ષમ </span><span>F-35</span><span> જેટ ખરીદશે</span></li><li><span>ગ્રીન્ઝો એનર્જીને\r\nઓસવાલ એનર્જીઝ તરફથી </span><span>₹</span><span>320</span><span> કરોડની ઓર્ડર મળી</span></li><li><span>કોલ ઇન્ડિયાનું\r\nકોકિંગ કૉલ ઉત્પાદન મે મહિનામાં </span><span>9%</span><span> ઘટીને </span><span>4.53</span><span> મિલિયન ટન થયું</span></li><li><span>રેમન્ડ રિયલ્ટી </span><span>FY26</span><span> માં </span><span>30%</span><span> વધારાની વેચાણ\r\nઅપેક્ષા રાખે છે</span><span>, </span><span>ઘરોની માંગ મજબૂત</span></li><li><span>ટ્રેડન્સ\r\nકંપની આગામી </span><span>5</span><span> વર્ષમાં વૃદ્ધિ માટે જનરેટિવ </span><span>AI </span><span>પર દાવ લગાવે છે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇકોનોમિક ટાઇમ્સ :</span></b></span></p><ul><li><span>રોયલ ઓર્ચિડ\r\nહોટેલ્સ આગામી </span><span>5</span><span> વર્ષમાં હોટેલની સંખ્યા </span><span>300</span><span> અને રૂમ કાઉન્ટ </span><span>20,000</span><span> કરતા વધુ કરવા\r\nમાગે છે: સીએમડી</span></li><li><span>સરકારે અત્યાર સુધી\r\n</span><span>12</span><span> પીએલઆઇ યોજનાઓ હેઠળ </span><span>₹</span><span>21,534</span><span> કરોડ વિતરણ કર્યા</span></li><li><span>કેન્દ્ર સરકારે\r\nઆગ્રામાં </span><span>₹</span><span>111.5</span><span> કરોડની સહાયથી બટાકાની સંશોધન સંસ્થા મંજૂર કરી</span></li><li><span>ઝોહો</span><span>,\r\n</span><span>ફોર્સ મોટર્સ માટે બિઝનેસ વૃદ્ધિમાં મદદરૂપ બનશે</span></li><li><span>GACM </span><span>ટેક્નોલોજીઝ </span><span>AI </span><span>એડટેક કંપની </span><span>WeXL\r\n</span><span>માં </span><span>30%</span><span> હિસ્સો ખરીદશે</span></li><li><span>CIL </span><span>નું કોકિંગ કૉલ ઉત્પાદન મે મહિનામાં </span><span>9%</span><span> ઘટ્યું</span></li><li><span>રિલાયન્સ ડિફેન્સે\r\nરાઇનમેટલ જર્મની તરફથી </span><span>₹</span><span>600</span><span> કરોડની નિકાસ\r\nઓર્ડર જીતી</span></li><li><span>ડચ ટેક રોકાણકાર\r\nપ્રોસસ ઇકોમર્સ આવક વધારવા તૈયાર</span></li><li><span>લુપિને ક્રોનિક\r\nકબજિયાત માટેની જનરિક દવાઈ માટે </span><span>USFDA </span><span>પાસેથી મંજૂરી મેળવી</span></li><li><span>એસીમ સિકાર સોલર\r\nકંપનીએ રાજસ્થાનમાં </span><span>300</span><span> મેગાવોટ પ્રોજેક્ટમાંથી વિજળી સપ્લાય\r\nકરવા માટે કરાર કર્યો</span></li><li><span>અમેરિકા\r\nસાથેના દ્વિપક્ષીય વેપાર કરારથી ભારતનો વ્યાપાર સરપ્લસ ઘટી શકે છે: ક્રિસિલ</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>મિન્ટ :</span></b></span></p><ul><li><span>ઇલેવનલેબ્સે </span><span>iOS\r\n</span><span>અને </span><span>Android </span><span>એપથી </span><span>AI\r\n</span><span>અવાજ સાધનોની સુવિધા વિસ્તારીઃ આશીષ</span></li><li><span>3,000</span><span> વાહનો (</span><span>800 EV </span><span>સહિત) લઈ જતી\r\nકાર્ગો શિપ પેસિફિક મહાસાગરમાં ડૂબી</span></li><li><span>પહેલી ઇલેક્ટ્રિક\r\nવિમાને મુસાફરોને લઈ </span><span>130</span><span> કિમી ઉડાન ભરી</span><span>, </span><span>ખર્ચ ફક્ત </span><span>₹</span><span>700 : </span><span>આશીષ</span></li><li><span>ગીવા કંપનીએ લેબમાં\r\nબનાવેલા હીરોની વધતી માંગને ધ્યાનમાં રાખીને </span><span>₹</span><span>530</span><span> કરોડ ભેગા કર્યા</span></li><li><span>ચાઇના +</span><span>1</span><span> વ્યૂહરચના ફાર્મા ક્ષેત્રમાં ગતિ પકડે છે</span><span>,\r\n</span><span>પણ સંપૂર્ણ નાણાકીય લાભમાં હજુ </span><span>2-3</span><span> વર્ષ લાગશે : ગોલ્ડમેન સૅક્સ</span></li><li><span>IPL </span><span>ને ભારતમાં સૌથી વધુ કમાણી કરતું લીગ રાખવા માટે </span><span>JioStar\r\n</span><span>₹</span><span>500</span><span> મિલિયનના ભંડોળ પર નિર્ભર</span></li><li><span>હિન્દાલ્કો ઉચ્ચ\r\nટેકનોલોજી અલ્યુમીના ક્ષેત્રમાં પ્રવેશ કરવા માટે </span><span>₹</span><span>1.25</span><span> કરોડ ડોલરમાં અલુકેમ ખરીદવા તૈયાર : આશીષ</span></li><li><span>EV </span><span>પ્રાઇસ યુદ્ધ વચ્ચે\r\n</span><span>CATL </span><span>ઓવરસીઝ વિસ્તરણને પ્રથમિકતા આપે છે</span></li><li><span>વોડાફોન આઇડિયા </span><span>₹</span><span>2.9</span><span> બિલિયન લોન મેળવવા માગે છે</span><span>, </span><span>નેટવર્ક મજબૂત કરવા\r\nમાટે</span></li><li><span><span>વૈશ્વિક\r\nઅસ્થિરતાને વચ્ચે પણ ભારતની અર્થવ્યવસ્થા સ્થિર છે: આરબીઆઈ</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEidwqwFIr_No8TxQ8L4N3DytdErrZJQR-vo90iOASQeMxtqx0_g4Mate8y6gOGbwz7wqyeboBcN17_0kuL764YRnXJxCzLg1w_RdJ2BLwIFo-mF3GA48RuDQBAQ1Clw1jy-3OENeQavI-QAFzMr_lpyFAQtKNILAGFAJ4KthQy1WdiRV4XHXoYR3VP5r4c','2025-06-26','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(260,'9031669610973510179','Research Report : Indian Financial Markets Outlook - 26th June 2025',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjsgL4PLijPFuigDXvmm57LuWtKpsh9yi1vlzd-8h4LgwWfo9tMf9Ln1ibfZVOx-Qt_VpTSyr3OksoK6NXoq-vo2EJ5_SvIsLKv7Hw8XKYOBGEGUSRBHZQSf2tyIw0yhesbPn7jBM7nfZwTQ7aryiicbeucRwvqjUg-6cdMZ5Y1ABmFxNi5RNIX5mVJTAA\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjsgL4PLijPFuigDXvmm57LuWtKpsh9yi1vlzd-8h4LgwWfo9tMf9Ln1ibfZVOx-Qt_VpTSyr3OksoK6NXoq-vo2EJ5_SvIsLKv7Hw8XKYOBGEGUSRBHZQSf2tyIw0yhesbPn7jBM7nfZwTQ7aryiicbeucRwvqjUg-6cdMZ5Y1ABmFxNi5RNIX5mVJTAA\" width=\"240\" /></a></b></div><div style=\"text-align:center;\"><b><b><span>Ravi </span></b><b><span>Bhatt</span></b></b></div><p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p><p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Markets turns cautious as\r\nTrump tariff deadline approaches</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhEL4z4yD573MnLBHGgjl82ogTLjKOCPUFx-RBnjsfNpaDxoqQYHmU4a9Y10pZyW0Kc0jyD4459EIGOG-V2nsbBteZQHwZooa8qSeu6ufeBQIyBADcikI2YtwtUkbVCICubTH7eaQGNfK-8ti--LsuhEnEw-xJ0YpuqQPyQJtO9Tiz6aNXJjREx_8ITEYI\"><img alt=\"\" height=\"331\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhEL4z4yD573MnLBHGgjl82ogTLjKOCPUFx-RBnjsfNpaDxoqQYHmU4a9Y10pZyW0Kc0jyD4459EIGOG-V2nsbBteZQHwZooa8qSeu6ufeBQIyBADcikI2YtwtUkbVCICubTH7eaQGNfK-8ti--LsuhEnEw-xJ0YpuqQPyQJtO9Tiz6aNXJjREx_8ITEYI=w579-h331\" width=\"579\" /></a></div><p style=\"text-align:justify;\"><span>Markets\r\nin Asia-Pacific turned negative on Thursday morning. Earlier, share indices\r\nrose tracking an advance in the technology stocks on the back of Nvidia Corp\'s\r\nhigh. But suddenly, the KOSPI and CSI 300 were trading 2.16% and 0.20% down,\r\nrespectively. The Hang Seng was down 0.64% in the morning worried about US\r\ntrade tariff deadline getting nearer. US futures were trading slightly lower in\r\nAsia session. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Market\r\nparticipants are cautious as they braced for a July 9 deadline for trade deals\r\nwith the USA. On Wednesday, US share indices ended on a mixed note with the\r\nS&amp;P 500 ending near record high. Technology stocks lifted the Nasdaq\r\nComposite index. The GIFT Nifty was trading 0.09%, or 21.50 points higher at\r\n25,306.50, which implied a higher open for the benchmark Nifty 50.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Greenzo Energy –</span></b><span>The\r\ncompany has received order worth </span><span>₹</span><span>320\r\ncrore from Oswal Energies. <span><span style=\"color:#0000FF;\">Positive</span></span></span></li></ul><ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><b><span style=\"color:#FF0000;\">Coal India -</span></b><span>Coal\r\nIndia\'s coking coal output falls 9% to 4.53 million tonne in May. <span><span style=\"color:#FF0000;\">Negative</span></span></span></li></ul><ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Raymond Realty –</span></b><span>The\r\ncompany eyes 30% rise in FY26 sales on robust housing demand.<span><span style=\"color:#0000FF;\"> Positive</span></span></span></li></ul><ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><b><span style=\"color:#0000FF;\">Reliance Defence –</span></b><span>The\r\ncompany has secured Rs 600 cr export order from Rheinmetall Germany. <span><span style=\"color:#0000FF;\">Positive</span></span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li><b><span>NIFTY - </span></b><span>The\r\nNifty index regained upside momentum to settle at 25,244 on Wednesday. Index\r\nturned positive as crude oil prices eased further, reducing burden on Indian\r\neconomy. Index is likely to march towards 25,350 during the day. Today’s range\r\n– 25,050 – 25,350.</span></li></ul><ul><li><b><span>BANKNIFTY - </span></b><span>Bank\r\nnifty too made marginal gains to settle at 56,621 on Wednesday. Index has near\r\nterm resistance at 56,900 and 57K while index seem well supported at 56,280 and\r\n56,000 (17 day EMA) in the near term. Today’s range – 56,250 – 57,000.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjsgL4PLijPFuigDXvmm57LuWtKpsh9yi1vlzd-8h4LgwWfo9tMf9Ln1ibfZVOx-Qt_VpTSyr3OksoK6NXoq-vo2EJ5_SvIsLKv7Hw8XKYOBGEGUSRBHZQSf2tyIw0yhesbPn7jBM7nfZwTQ7aryiicbeucRwvqjUg-6cdMZ5Y1ABmFxNi5RNIX5mVJTAA','2025-06-26','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(261,'75914647952650546','Research Report : Indian Financial Markets Outlook - 25th June 2025',NULL,'<p style=\"text-align:center;\"> <b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiFpoc0Mm8E051r0kk_NQfD4ik8w5Zbx1Lo1dtZ6ZFLzagJpOC_6buaimaXxh4vPDeXiOMzpBm5t06b3-LzlKVWhCrWPGhhtGeeHbW3c4BNbCtV_4jGEJBbPHjjRdJTgV5CQYShV74uargRb-tnj8b0vdzKZRXKZHDuRp3_z_Cdv99e4JXIV5UpQRS9TJk\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiFpoc0Mm8E051r0kk_NQfD4ik8w5Zbx1Lo1dtZ6ZFLzagJpOC_6buaimaXxh4vPDeXiOMzpBm5t06b3-LzlKVWhCrWPGhhtGeeHbW3c4BNbCtV_4jGEJBbPHjjRdJTgV5CQYShV74uargRb-tnj8b0vdzKZRXKZHDuRp3_z_Cdv99e4JXIV5UpQRS9TJk\" width=\"240\" /></a></b></p><p style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></p>\r\n\r\n<span style=\"color:#FF0000;\">Markets turns towards\r\neconomic fundamental, Powell indicated possible rate cut in USA</span><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhlccJYC1A4lDytBf21fSZ2O8oX6gZXtg87jQKZNUAeP1TgsuZqtGilyKIuPk9GJMPTevqgCBQ4ADxo6AYBgf911eVsG9BnIxGrtowN3ILUXvcU4W8ROf7s1ketkMJOAA_4c54-cf9eEKtv7ZKzjtaG4ZZwbGnuUTqiutMO-2xWC1x58uGppeGyCbkAcVk\"><img alt=\"\" height=\"323\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhlccJYC1A4lDytBf21fSZ2O8oX6gZXtg87jQKZNUAeP1TgsuZqtGilyKIuPk9GJMPTevqgCBQ4ADxo6AYBgf911eVsG9BnIxGrtowN3ILUXvcU4W8ROf7s1ketkMJOAA_4c54-cf9eEKtv7ZKzjtaG4ZZwbGnuUTqiutMO-2xWC1x58uGppeGyCbkAcVk=w545-h323\" width=\"545\" /></a></div><br /><span style=\"text-align:justify;\">Most\r\nof the markets in Asia – Pacific region are largely flat. Euro Stoxx 50 futures\r\nrose by 0.21%. Futures for Hong Kong’s Hang Seng Index increased by 0.8% while\r\nJapan’s Topix index moved 0.15% lower. Australia’s S&amp;P/ASX 200 index future\r\ndeclined by 0.03%. Earlier, the S&amp;P 500 rose 1.1%, Nasdaq was up 1.5% on\r\nTuesday, reporting its first record since February. The US dollar declined\r\nextended its decline and US Treasury futures also fell. This comes amid easing\r\nMiddle East tensions and comments from Federal Reserve Chair Jerome Powell that\r\nif it turns out that inflation pressures do remain contained, then rate cut\r\nwill be sooner rather later.</span>\r\n\r\n<p style=\"text-align:justify;\"><span>Oil\r\nsnapped its two-day declining streak and rose over 1% on Wednesday as industry\r\nreport indicated a decline in inventories last week. This comes after West\r\nTexas Intermediate crude, dropped by up to 6% on Tuesday. Earlier, the Nifty\r\nended 72.45 points, or 0.29% higher at 25,044.35, while the Sensex closed\r\n158.32 points, or 0.19% up at 82,055.11. During the day, the Nifty rose 1.38%\r\nto trade at 25,317.70 and the Sensex rose 1.37% to 83,018.16.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span>PTC\r\nIndustries - </span></b><span>The Company’s arm Aerolloy Tech\r\nsigned an MoU with Safran Aircraft Engines for Military Aircraft Engines.\r\nPositive</span></li></ul><ul><li style=\"text-align:justify;\"><b><span>Vodafone\r\nIdea - </span></b><span>The Company clarified that it has\r\nnot received any communication from government on relief of Rs 84,000 crore\r\ndues on AGR dues. Negative</span></li></ul><ul><li style=\"text-align:justify;\"><b><span>Zydus\r\nWellness - </span></b><span>The Company’s arm Naturell\r\nIndia passes resolution and accords in-principle approval for voluntarily\r\nliquidation. Negative</span></li></ul><ul><li style=\"text-align:justify;\"><b><span>Hindalco-\r\n</span></b><span>The Company signed agreements to\r\nacquire 100% stake in AluChem companies for $125 million. Positive</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span>NIFTY - </span></b><span>The\r\nNifty index slipped after early gain to settle at 25,044 on Tuesday. Index\r\nturned negative after early gains to 25,318 but later succumbed towards 25K on\r\nheavy FIIs selling. Today’s range – 24,900 – 25,200.</span></li></ul><ul><li style=\"text-align:justify;\"><b><span>BANKNIFTY -</span></b><span> Bank\r\nnifty gained towards 57K before closing at 56,461 on Tuesday. Index has taken\r\nsupport at 56,270 while 56,900 remain near term resistance. Today’s range – 56,150\r\n– 57,000.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEiFpoc0Mm8E051r0kk_NQfD4ik8w5Zbx1Lo1dtZ6ZFLzagJpOC_6buaimaXxh4vPDeXiOMzpBm5t06b3-LzlKVWhCrWPGhhtGeeHbW3c4BNbCtV_4jGEJBbPHjjRdJTgV5CQYShV74uargRb-tnj8b0vdzKZRXKZHDuRp3_z_Cdv99e4JXIV5UpQRS9TJk','2025-06-25','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(262,'5484491934717962583','Research Report : Indian Financial Markets Outlook - 24th June 2025',NULL,'<p style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiLbiLutCs3jdVWqLBKedYOKczi4MEohL_f3rNF3QJfWpB49ZaSinspXZwqhCbkfSWp27Wb-YydyLJjN7Yyb5dmABqKjIw7qd-os9ax5kF1gL-rqza0l_azAlj6G2DhgspC1mWBC4PHux_1tDuGlRloD_oqJlEFhJbxvlAjOcpvs5bBBHFhrwke5IlJtCs\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiLbiLutCs3jdVWqLBKedYOKczi4MEohL_f3rNF3QJfWpB49ZaSinspXZwqhCbkfSWp27Wb-YydyLJjN7Yyb5dmABqKjIw7qd-os9ax5kF1gL-rqza0l_azAlj6G2DhgspC1mWBC4PHux_1tDuGlRloD_oqJlEFhJbxvlAjOcpvs5bBBHFhrwke5IlJtCs\" width=\"240\" /></a></p><p style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt</span></b></p><p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p><p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Market cheer over Trump’s\r\nannouncement of ceasefire between Iran – Israel</span></p>\r\n\r\n\r\n\r\n<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjyz_nyuY33Wf2reNBFBtfVvndY-9FitQ2T0w_ugGtyGl6SD1mOH2FrkpmhNpSz3Zp2sgzXU5ig0B7eQqd-rDf_3hW2R8GD-Z16OvVxhKoKxuFCnO_Eu8CvrxDbxkMQl0NmRzvZ2ow3ewsf64v7GKoCW6A2bVXrWCQbWxBr9J2VEXAbQyNXJk8E9pcQtcs\"><img alt=\"\" height=\"288\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjyz_nyuY33Wf2reNBFBtfVvndY-9FitQ2T0w_ugGtyGl6SD1mOH2FrkpmhNpSz3Zp2sgzXU5ig0B7eQqd-rDf_3hW2R8GD-Z16OvVxhKoKxuFCnO_Eu8CvrxDbxkMQl0NmRzvZ2ow3ewsf64v7GKoCW6A2bVXrWCQbWxBr9J2VEXAbQyNXJk8E9pcQtcs=w504-h288\" width=\"504\" /></a></div><br /><div style=\"text-align:justify;\"><span>Asian markets welcome ceasefire news and Hong Kong’s Hang Seng Index\r\nincreased by 0.3% while Japan’s Topix index moved higher by 1%.. US stock-index\r\nfutures too advanced after Donald Trump stated that Israel and Iran had agreed\r\nto a temporary ceasefire, raising expectations that tensions in the Middle East\r\nmay ease. Futures linked to the S&amp;P 500 rose 0.5% on Tuesday, with equities\r\nopening in positive territory in both Japan and Australia.</span></div><div style=\"text-align:justify;\"><span>The\r\nUS dollar declined against all major currencies in the Group-of-10, and US\r\nTreasury future. Oil prices, particularly West Texas Intermediate crude,\r\ndropped by up to 6% in early trading across Asian markets after Trump published\r\nthe statement on his Truth Social platform. The comment followed Iran’s missile\r\nattacks on a US military facility in Qatar, which were largely viewed as\r\nsymbolic. The GIFT Nifty traded 0.45% higher at 25,162.00 as of 6:55 am,\r\nsignalling a positive start to Indian equities.</span></div>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li><b><span>TVS\r\nMotors -</span></b><span> The company announced the launch of\r\nthe all new TVS HLX 150 5G in the Republic of Congo. Positive</span></li></ul><ul><li><b><span>ITI\r\n-</span></b><span> The Company received a final\r\ntranche of Rs 25 crore from C-DOT, as part of executed sale agreement between\r\nITI and C-DOT. Positive </span></li></ul><ul><li><b><span>Lemon\r\nTree Hotels -</span></b><span> The Company signed a new\r\n47-Room Property in Punjab. Positive </span></li></ul><ul><li><b><span>Tata\r\nMotors -</span></b><span> The Company revealed the\r\nintroductory pricing of the Harrier.EV for the rear-wheel drive variants.\r\nPositive</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li><b><span>NIFTY – </span></b><span>The\r\nNifty index recovered after early slump to settle at 24,971 on Monday. Index\r\nturned negative or Middle East geopolitical risk however close above 17 day EMA\r\nis positive signal. Today’s range – 24,900 – 25,200. </span></li></ul><ul><li><b><span>BANKNIFTY –</span></b><span>\r\nBank nifty too recovered after early fall to close at 56,059 on Monday. Index\r\nhas taken support at 17 day EMA 55,870 while 56,500 remain near term\r\nresistance. Today’s range – 55,800 – 56,500.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEiLbiLutCs3jdVWqLBKedYOKczi4MEohL_f3rNF3QJfWpB49ZaSinspXZwqhCbkfSWp27Wb-YydyLJjN7Yyb5dmABqKjIw7qd-os9ax5kF1gL-rqza0l_azAlj6G2DhgspC1mWBC4PHux_1tDuGlRloD_oqJlEFhJbxvlAjOcpvs5bBBHFhrwke5IlJtCs','2025-06-24','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(263,'8531310653422066693','Research Report : Indian Financial Markets Outlook - 23th June 2025',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEi5kVKQo_ywEUNAzas3w43lYANvA59eQubvOCw1LlhwE60gRNHj5ZkriGSKYDWCLb7hqAIaMOIWEnCmABQW8LJjH49Lg8b3jRNjYLmIk1xkM2Eq1VTW8wpf6uFw_Upbrdc_iCo8vaCvPPoV-BL7Ef1oveNS4kgEz_7EgIgPCUwX8DeXZc-pb10YSaolvsA\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEi5kVKQo_ywEUNAzas3w43lYANvA59eQubvOCw1LlhwE60gRNHj5ZkriGSKYDWCLb7hqAIaMOIWEnCmABQW8LJjH49Lg8b3jRNjYLmIk1xkM2Eq1VTW8wpf6uFw_Upbrdc_iCo8vaCvPPoV-BL7Ef1oveNS4kgEz_7EgIgPCUwX8DeXZc-pb10YSaolvsA\" width=\"240\" /></a></b></div><p style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></p>\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Market turbulence increased\r\non US strikes on Iran’s nuclear sites</span></p><div style=\"text-align:center;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEh356YlEI2hQJVfILsac82cL5YSk-bzT4OfXw_kQQGJZAEgdgc2z97Z0-OwU4PD8KC12z3pI8YHbsk5vRBvreajDSS6OkFlBUeOiKk_qCEtGFwZV5lMSqpbpmJ5DCDBnmwDaZZshwZrzHjhmdo65URKTnnds-EUZXse2dc06yB37peOYqRWO69IV1GxBMk\"><img alt=\"\" height=\"287\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEh356YlEI2hQJVfILsac82cL5YSk-bzT4OfXw_kQQGJZAEgdgc2z97Z0-OwU4PD8KC12z3pI8YHbsk5vRBvreajDSS6OkFlBUeOiKk_qCEtGFwZV5lMSqpbpmJ5DCDBnmwDaZZshwZrzHjhmdo65URKTnnds-EUZXse2dc06yB37peOYqRWO69IV1GxBMk=w508-h287\" width=\"508\" /></a></div></div><p style=\"text-align:justify;\"><span>Asian\r\nmarkets stocks fell on Monday after US strikes on Iran\'s nuclear sites over the\r\nweekend. US stock-futures too dropped on Monday morning. Hang Sang is down 0.6%\r\nwhile Nikkei is down 0.5% in the morning session. Additionally, Brent jumped\r\nover 2.6% on Monday and dollar rose against the euro and most other peers. The\r\nGIFT Nifty was down 0.57% at 24,986 in the morning, signaling a gap down start\r\nto Indian markets today. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nbenchmark equity indices reversed their declining streak as they ended the week\r\nwith gains on Friday. The NSE Nifty 50 ended 319.15 points or 1.29% higher at\r\n25,112.40, while the BSE Sensex closed 1,046 points or 1.29% higher at 82,408.\r\nForeign portfolio investors continued buying Indian equities for the fourth\r\nconsecutive session on Friday. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nFPIs net bought shares worth Rs 7,704 crore, according to the provisional data\r\nfrom the National Stock Exchange. Domestic institutional investors turned\r\nsellers for the first time after 25 sessions as they offloaded equities worth\r\napproximately Rs 3,658 crore, the data showed.</span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li><b><span>Hindustan\r\nAeronautics -</span></b><span> The company became a\r\nsuccessful bidder for the manufacturing and design technology of the Small\r\nSatellite Launch Vehicle, developed by ISRO. Positive</span></li></ul><ul><li><b><span>Tata\r\nConsultancy Services -</span></b><span> The company set up\r\ntwo new automotive delivery centres in Germany and an engineering centre in\r\nRomania. Positive</span></li></ul><ul><li><b><span>Vidhi\r\nSpecialty -</span></b><span> Gujarat Industrial Development\r\nCorp allots land for a new manufacturing plant. Positive</span></li></ul><ul><li><b><span>Tanla\r\nPlatforms -</span></b><span> The company\'s arm Karix Mobile\r\nincorporated a subsidiary, Karix Mobile LLC, at Saudi Arabia. Positive</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li><b><span>NIFTY\r\n- </span></b><span>The Nifty index surged above 25K to\r\nsettle at 25,112 on Friday. Index looks positive to make further upside journey\r\nbut rising geopolitical risk may cap any gain. Today’s range – 24,850 – 25,200.</span></li></ul><ul><li><b><span>BANKNIFTY\r\n- </span></b><span>Bank nifty too zoomed past 56K to\r\nclose at 56,252 on Friday. Index has gained momentum recently after RBI’s easy\r\nmonetary policy. Index faces resistance at 56,600 while 17 day EMA 55,840 is\r\nnear term support. Today’s range – 55,850 – 56,400.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEi5kVKQo_ywEUNAzas3w43lYANvA59eQubvOCw1LlhwE60gRNHj5ZkriGSKYDWCLb7hqAIaMOIWEnCmABQW8LJjH49Lg8b3jRNjYLmIk1xkM2Eq1VTW8wpf6uFw_Upbrdc_iCo8vaCvPPoV-BL7Ef1oveNS4kgEz_7EgIgPCUwX8DeXZc-pb10YSaolvsA','2025-06-23','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(264,'9165782201870400869','Nifty Outlook :- 23.06.2025 - CFA Hitesh Somani',NULL,'<div style=\"background-color:#FFFFFF;font-weight:bold;text-align:center;\"><div style=\"font-weight:400;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEit0GeGFRtdtz2yBMgRJGcOCeMRW3t9m3wUAYiR0IgJMg-D-haHc09QUJJajYga7x6xKDjOW3Yrk5UqIDo9P70gmk96wHY4OiDQBdC6ClBgZS2q9aSLvdNX7q5pGlzobgmRO2aB2PMnDVrYkAskJubTtbZVie7tbJB4vinP5OnRf5sFtRKUh18L7fJAJGo\"><span style=\"color:#000000;\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEit0GeGFRtdtz2yBMgRJGcOCeMRW3t9m3wUAYiR0IgJMg-D-haHc09QUJJajYga7x6xKDjOW3Yrk5UqIDo9P70gmk96wHY4OiDQBdC6ClBgZS2q9aSLvdNX7q5pGlzobgmRO2aB2PMnDVrYkAskJubTtbZVie7tbJB4vinP5OnRf5sFtRKUh18L7fJAJGo\" width=\"255\" /></span></a></b></div><div><b>CFA </b><span>Hitesh Somani</span></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div style=\"font-weight:bold;\">MD - Aapka Investments </div><div style=\"font-weight:bold;\">Website - https://www.aapkainvestments.in</div></div></div><p style=\"text-align:justify;\"><b><span>NIFTY\r\nFINALLY CLOSED IN STRONG GREEN ON FRIDAY WILL IT BREAK THE MAKE OF BREAK LEVEL\r\nTHIS WEEK….??</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Last\r\nweek was a momentum bullish week for Nifty but on Friday it skyrocketed and\r\nclosed above 25100 levels which could be a very good signal for investors as\r\nnow the nifty is very close to its crucial resistance of 25200 levels. If in\r\nthe next week nifty succeeds to surpass this important level then we may see a\r\nsharp upside in nifty and other indexes.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Nifty\r\nnow have a major support @24700, till it is above these levels we can see the\r\nbullish sentiments intact and markets are in safe zone. From last few weeks\r\nNifty is stucked in a narrow range of 25200 to 24600 levels and now also till\r\nit closes above 25200 which is its major resistance we should wait and watch.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Banknifty\r\nalso witnessed sharp upmove in the last week and closed above 56200 levels, now\r\nbanknifty have a major resistance @56500 levels, if it manages to close above\r\n56500 levels then we may see a fresh high in banknifty in the coming weeks</span></p><p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Major\r\nSupport Levels for Nifty</span></p>\r\n\r\n<ul><li><span>Support\r\n1 – 24700</span></li><li><span>Support\r\n2 – 24400</span></li><li><span>Support\r\n3 – 24150</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>Major\r\nResistance Levels for Nifty</span></p>\r\n\r\n<ul><li><span>Resistance\r\n1 – 25200</span></li><li><span>Resistance\r\n2 – 25400</span></li><li><span>Resistance\r\n3 – 25600</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Major\r\nSupport Levels for Banknifty</span></p>\r\n\r\n<ul><li><span>Support\r\n1 – 55700</span></li><li><span>Support\r\n2 – 55100</span></li><li><span>Support\r\n3 – 54600</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>Major\r\nResistance Levels for Banknifty</span></p>\r\n\r\n<ul><li><span>Resistance\r\n1 – 56500</span></li><li><span>Resistance\r\n2 – 57000</span></li><li><span>Resistance\r\n3 – 57500</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>1)\r\n<b>JBCHEM</b></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>CMP\r\n@ 1770</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Buy\r\nAbove @ 1801 </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Stop\r\nLoss Below @ 1660</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Targets\r\n@ 1870, 1970 and 2070</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span><br />\r\n<br />\r\n2) <b>JSWSTEEL</b></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>CMP\r\n@ 1005</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Buy\r\nAbove @ 1025</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Stop\r\nLoss @ 980</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Targets\r\n@ 1050, 1075 and 1100</span></p>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>3)\r\n<b>KAYNES</b></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>CMP\r\n@ 5865</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Buy\r\nAbove @ 5890</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Stop\r\nLoss @ 5660</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Targets\r\n@ 6100, 6300 and 6500</span></p>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span>4)\r\n</span><b>ULTRATECH CEMENT</b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>CMP\r\n@ 11450</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Buy\r\nAbove @ 11530</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Stop\r\nLoss @ 11300</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Targets\r\n@ 11700, 11900 and 12100</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEit0GeGFRtdtz2yBMgRJGcOCeMRW3t9m3wUAYiR0IgJMg-D-haHc09QUJJajYga7x6xKDjOW3Yrk5UqIDo9P70gmk96wHY4OiDQBdC6ClBgZS2q9aSLvdNX7q5pGlzobgmRO2aB2PMnDVrYkAskJubTtbZVie7tbJB4vinP5OnRf5sFtRKUh18L7fJAJGo','2025-06-21','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(265,'5935346581555683624','Research Report : Indian Financial Markets Outlook - 19th June 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjjWIE7reEmB0KlT3F4bgE8I496U_-uFB6vBPJqj2aL19Eo_QUgkGZEjEG87cn19zDjqLdEXWqRS7vpNgVHdhycK6hz2xwuBE11XxuLx1AlofXpnLGqF7_gsllv-kAkfnQ4Lut_3HOkMP-xDCVcZy50JkiEqc9qPRnM4RpxtxqDPKmIaTWtMrRv78BpX5U\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjjWIE7reEmB0KlT3F4bgE8I496U_-uFB6vBPJqj2aL19Eo_QUgkGZEjEG87cn19zDjqLdEXWqRS7vpNgVHdhycK6hz2xwuBE11XxuLx1AlofXpnLGqF7_gsllv-kAkfnQ4Lut_3HOkMP-xDCVcZy50JkiEqc9qPRnM4RpxtxqDPKmIaTWtMrRv78BpX5U\" width=\"240\" /></a></div><br /><p style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></p><p style=\"text-align:justify;\"><span style=\"color:#FF0000;text-align:left;\">Fed Reserve holds interest\r\nrate steady, markets remain muted</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjEzuYegZ_ppiSrmvpkw69gnrkuHWTxfDH96ePDaWsz7hkxlh3_3RMkxjg1K7oX0ksWVOO-VVPiPuR-_Upu-8eIkmbvh9nisKosL54UN1Fnk-a3hgpmOGaor3nMuVv7TT3eaWhcXvkvYy3Po5GDbIu2NKUoy0mjBWlzVwN4irnO08IGe76hWibq5V1D95Q\"><img alt=\"\" height=\"268\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjEzuYegZ_ppiSrmvpkw69gnrkuHWTxfDH96ePDaWsz7hkxlh3_3RMkxjg1K7oX0ksWVOO-VVPiPuR-_Upu-8eIkmbvh9nisKosL54UN1Fnk-a3hgpmOGaor3nMuVv7TT3eaWhcXvkvYy3Po5GDbIu2NKUoy0mjBWlzVwN4irnO08IGe76hWibq5V1D95Q=w474-h268\" width=\"474\" /></a></div><p style=\"text-align:justify;\"><span>In\r\nthe morning session, US equity futures edged lower alongside declines in Asian\r\nmarkets, following Wednesday’s selloff on Wall Street after Federal Reserve\r\nChair Jerome Powell on Wednesday said he expected inflation to pickup in the\r\ncoming months. Japan’s Topix index was down 0.6% while Australia’s S&amp;P/ASX\r\n200 slipped 0.2%. The Fed left the rates unchanged in its meeting and indicated\r\nthat there could be two further cuts this year. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nGIFT Nifty fell 0.21% to 24,810 in the morning, signning a negative start to\r\nthe Indian equities. The FOMC decided to keep rates unchanged at the 4.25-4.5%\r\nrange for the fourth time in a unanimous decision Foreign portfolio investors\r\nremained net buyers of Indian equities for the second consecutive session on\r\nWednesday, mopping stocks worth Rs 891 crore, according to the provisional data\r\nfrom the National Stock Exchange. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Domestic\r\ninstitutional investors continued to stay net buyers for the 24th straight\r\nsession as they obtained equities worth Rs 1,091.3 crore, the data showed.</span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<h2></h2><ul><li style=\"text-align:justify;\"><span>Vodafone\r\nIdea -</span><span> <span style=\"font-weight:normal;\">The company signed an agreement\r\nwith AST Spacemobile to expand mobile connectivity and bring direct-to-device\r\nsatellite broadband connectivity. Positive</span></span></li></ul><ul><li style=\"text-align:justify;\"><span style=\"text-align:left;\">Garware\r\nTechnical -</span><span style=\"font-weight:normal;text-align:left;\"> The company incorporated wholly\r\nowned subsidiary Garwares Technical Fibres AS in Norway. Positive</span></li></ul><ul><li style=\"text-align:justify;\"><span style=\"text-align:left;\"><span>E</span>SAF\r\nSmall Finance Bank -</span><span style=\"font-weight:normal;text-align:left;\"> The bank approved\r\nthe proposal for sale of NPA, written-off loans to Asset Reconstruction\r\nCompany. Positive</span></li></ul><ul><li style=\"text-align:justify;\"><span style=\"text-align:left;\">Inox\r\nGreen Energy -</span><span style=\"text-align:left;\"><span style=\"font-weight:normal;\"> Promoter Devansh Trademart\r\nfurther acquired 30,000 shares of the company via open market transactions.\r\nPositive</span></span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<h2></h2><ul><li style=\"text-align:justify;\"><span>NIFTY\r\n- </span><span style=\"font-weight:normal;\">The Nifty index dragged lower amid\r\nweak sentiments to settle at 24,812 on Wednesday. Index hovers near 17day EMA\r\nof 24,837. Today’s range – 24,700 – 24,950.</span></li></ul><ul><li style=\"text-align:justify;\"><span style=\"text-align:left;\">BANKNIFTY\r\n-</span><span style=\"text-align:left;\"><span style=\"font-weight:normal;\">Bank nifty regained early losses to\r\nclose marginally higher at 55,828 on Wednesday. Index continues trade in narrow\r\nrange. Today’s range – 55,250 – 56,050.</span></span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjjWIE7reEmB0KlT3F4bgE8I496U_-uFB6vBPJqj2aL19Eo_QUgkGZEjEG87cn19zDjqLdEXWqRS7vpNgVHdhycK6hz2xwuBE11XxuLx1AlofXpnLGqF7_gsllv-kAkfnQ4Lut_3HOkMP-xDCVcZy50JkiEqc9qPRnM4RpxtxqDPKmIaTWtMrRv78BpX5U','2025-06-19','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(266,'3886510504635402608','Federal Reserve meeting today - 18th June 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjPqa3ps9VxTTygFxiuC1Uqh2c5HwotsWCEa7dhwoVGb9IgeuVAwhNAV0QY6auHtYkXUJ7NN2gQaeiCjthg_Eq8SA9Ic9OpQ5qWZrx4atoF4pzxHHjFgWv2YtEc9JGpoqnW_Jv-XqYP_YUYUwtf9jdmXXk7hd39_9pqr3_AyFJjhCpTr03BDbbgP0C-UsQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjPqa3ps9VxTTygFxiuC1Uqh2c5HwotsWCEa7dhwoVGb9IgeuVAwhNAV0QY6auHtYkXUJ7NN2gQaeiCjthg_Eq8SA9Ic9OpQ5qWZrx4atoF4pzxHHjFgWv2YtEc9JGpoqnW_Jv-XqYP_YUYUwtf9jdmXXk7hd39_9pqr3_AyFJjhCpTr03BDbbgP0C-UsQ\" width=\"240\" /></a></div><br />\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><span><a href=\"http://www.capsavaj.com/\"><b><span>www.capsavaj.com</span></b></a></span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">શું પૉવેલ (</span><span style=\"color:#FF0000;\">Powell) </span><span style=\"color:#FF0000;\">ટ્રમ્પના (</span><span style=\"color:#FF0000;\">Trump\'s) </span><span style=\"color:#FF0000;\">રેટ કટના (</span><span style=\"color:#FF0000;\">rate cut) </span><span style=\"color:#FF0000;\">દબાણ સામે</span><span style=\"color:#FF0000;\">ઝૂકી જશે</span><span style=\"color:#FF0000;\">?</span></p><p style=\"text-align:justify;\"><span>યુએસ ફેડરલ રિઝર્વ\r\n(</span><span>US Federal Reserve) </span><span>આજે યુએસની નાણાકીય નીતિ (</span><span>monetary\r\npolicy) </span><span>પર જાહેરાત કરવા માટે તૈયાર છે</span><span>,\r\n</span><span>અને રોકાણકારો માની રહ્યા છે કે વર્તમાન </span><span>4.25-4.5\r\n</span><span>ટકાની રેન્જમાં રહેલા વ્યાજ દરોમાં (</span><span>interest\r\nrates) </span><span>લગભગ કોઈ ફેરફાર નહીં થાય. બજારોને (</span><span>Markets)\r\n</span><span>આ વર્ષના અંત સુધીમાં બે કટની (</span><span>cuts)\r\n</span><span>અપેક્ષા છે</span><span>, </span><span>જેમાં સપ્ટેમ્બર મહિનો સૌથી પહેલો હોઈ શકે છે જ્યારે દરો\r\nફરીથી ઘટવાનું શરૂ કરશે. રોકાણકારો એવી અપેક્ષા રાખી રહ્યા છે કે પૉવેલ</span><span>,\r\n</span><span>ટ્રમ્પના દબાણથી પ્રભાવિત થયા વગર પોતાનું કામ ચાલુ રાખશે. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>ટ્રમ્પે છેલ્લા\r\nકેટલાક અઠવાડિયાથી દરોમાં પૂરા એક ટકાના ઘટાડાની માંગ કરી છે</span><span>,\r\n</span><span>અને ફેડ ચેરમેનને “</span><span>numbskull”\r\n</span><span>કહ્યા છે અને જણાવ્યું છે કે તેમને “કદાચ કંઈક દબાણપૂર્વક\r\nકરાવવું પડશે”. ટ્રમ્પે તો પૉવેલને ફેડરલ રિઝર્વના ચીફ (</span><span>Chief\r\nof Federal Reserve) </span><span>પદેથી હટાવવાનો પણ પ્રયાસ કર્યો હતો</span><span>,\r\n</span><span>પરંતુ બજારમાં આ વિચારને સારો પ્રતિસાદ મળ્યો ન હતો. સંભવ\r\nછે કે પૉવેલ આજે પછીથી યોજાનારી</span><span>, </span><span>મીટિંગ પછીની તેમની પ્રેસ કોન્ફરન્સમાં (</span><span>press\r\nconference) “</span><span>સાવચેતીભરી ધીરજ” (</span><span>cautious\r\npatience) </span><span>નો સૂર અપનાવશે.</span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Economic\r\nData </span><span style=\"color:#FF0000;\">(<span>આર્થિક ડેટા</span></span><span style=\"color:#FF0000;\">)</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEjScSQWBq_wRGFQJJiWmLClnBAKTu9aRx_dcxmLRbVxY7yreG4sF6Bv5Lxm55pOBM4Nkl0GMAqGLkhbQ-1og3k31CEkUhdMnDeFZH7ZawZQFAhUujeRb5bPiR_wu7ZSkmohKtmnsy3mxMe4LsuDfkKXoT4IczRNFrN0KCvf1DXaHhszhJ6uSvND0uZ1910\"><img alt=\"\" height=\"174\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEjScSQWBq_wRGFQJJiWmLClnBAKTu9aRx_dcxmLRbVxY7yreG4sF6Bv5Lxm55pOBM4Nkl0GMAqGLkhbQ-1og3k31CEkUhdMnDeFZH7ZawZQFAhUujeRb5bPiR_wu7ZSkmohKtmnsy3mxMe4LsuDfkKXoT4IczRNFrN0KCvf1DXaHhszhJ6uSvND0uZ1910=w320-h174\" width=\"320\" /></a></div>\r\n\r\n<h2></h2><ul><li><span>Inflation\r\nand labour markets :-</span><span style=\"font-weight:normal;\">છેલ્લા એક </span><span style=\"font-weight:normal;\">quarter\r\n</span><span style=\"font-weight:normal;\">દરમિયાન</span><span style=\"font-weight:normal;\">, USA </span><span style=\"font-weight:normal;\">માં </span><span style=\"font-weight:normal;\">inflation (</span><span style=\"font-weight:normal;\">ફુગાવો) </span><span style=\"font-weight:normal;\">2% </span><span style=\"font-weight:normal;\">ના લક્ષ્યાંક કરતાં થોડું વધારે રહ્યું છે</span><span style=\"font-weight:normal;\">,\r\n</span><span style=\"font-weight:normal;\">જ્યારે </span><span style=\"font-weight:normal;\">job growth </span><span style=\"font-weight:normal;\">સાધારણ રીતે ધીમું પડી રહ્યું છે. આ સૂચવે છે કે </span><span style=\"font-weight:normal;\">US\r\neconomy </span><span style=\"font-weight:normal;\">માં નબળાઈ ધીમે ધીમે વધી રહી છે અને નીચો </span><span style=\"font-weight:normal;\">growth\r\n</span><span style=\"font-weight:normal;\">આગળ જતાં </span><span style=\"font-weight:normal;\">rate cut </span><span style=\"font-weight:normal;\">ની સંભાવનાઓ વધારી શકે છે.                                                  </span>                          <a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEi4DNuwcASWuZTIXSPRXiiaGs-bvqgREz7bMl1llF88Fxj0Bf_FqQUBuLn868Ifn-a2vXQzGP2lfH37_pzccrhqb4fWeFMiP83EZnyCNvz6JLPdHL-b4mGK8Vo_zagtTIQC_h-fLl9ZKgVQtb2_Aavk_hOWvc1sG2Ft9b8tNWjRQ24o7wevoUxCDgmNbQc\"><img alt=\"\" height=\"179\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEi4DNuwcASWuZTIXSPRXiiaGs-bvqgREz7bMl1llF88Fxj0Bf_FqQUBuLn868Ifn-a2vXQzGP2lfH37_pzccrhqb4fWeFMiP83EZnyCNvz6JLPdHL-b4mGK8Vo_zagtTIQC_h-fLl9ZKgVQtb2_Aavk_hOWvc1sG2Ft9b8tNWjRQ24o7wevoUxCDgmNbQc\" width=\"320\" /></a></li></ul><ul><li style=\"text-align:justify;\"><span>Manufacturing\r\nPMI</span><span>:-</span><span style=\"font-weight:normal;\">ISM\r\nPMI </span><span style=\"font-weight:normal;\">માર્ચમાં </span><span style=\"font-weight:normal;\">50.3</span><span style=\"font-weight:normal;\"> થી ઘટીને મે મહિનામાં </span><span style=\"font-weight:normal;\">48.5</span><span style=\"font-weight:normal;\"> પર આવી ગયો છે</span><span style=\"font-weight:normal;\">, </span><span style=\"font-weight:normal;\">જે </span><span style=\"font-weight:normal;\">50</span><span style=\"font-weight:normal;\"> ની </span><span style=\"font-weight:normal;\">threshold (</span><span style=\"font-weight:normal;\">સપાટી) ની નીચે સતત ત્રીજો મહિનો છે અને </span><span style=\"font-weight:normal;\">manufacturing\r\nactivity</span><span style=\"font-weight:normal;\">માં </span><span style=\"font-weight:normal;\">contraction\r\n(</span><span style=\"font-weight:normal;\">સંકોચન) નો સંકેત આપે છે. </span><span style=\"font-weight:normal;\">મુખ્ય</span><span style=\"font-weight:normal;\">sub-indices\r\n</span><span style=\"font-weight:normal;\">પણ વધુ </span><span style=\"font-weight:normal;\">strain (</span><span style=\"font-weight:normal;\">દબાણ) દર્શાવે છે : </span><span style=\"font-weight:normal;\">new\r\norders </span><span style=\"font-weight:normal;\">અને</span><span style=\"font-weight:normal;\">production </span><span style=\"font-weight:normal;\">નબળા રહ્યા છે</span><span style=\"font-weight:normal;\">, </span><span style=\"font-weight:normal;\">જ્યારે </span><span style=\"font-weight:normal;\">supplier delivery\r\ntimes </span><span style=\"font-weight:normal;\">વધી રહ્યા છે - જે સંભવતઃ </span><span style=\"font-weight:normal;\">tariff-related\r\nsupply-chain bottlenecks </span><span style=\"font-weight:normal;\">ને કારણે છે.</span></li></ul><div style=\"text-align:justify;\"><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEhjsaACgv8_5VjmoiauukP1F_P-Fcp51iGrbZiOqm-2UrbeW5m48RnFjEU_ZG72n-89_DCQ4NL8vtIZsZzuVA4J2YeuY1xXbHob85t2e_EDXoAmGeYZ9NLVcy5xaE_56H2PSD-E9hhKQXOBXVRFjRQu0-rq--6Jv0H6PB0BS8KX_UA7wrnYKe2oEhQBwDY\"><img alt=\"\" height=\"185\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEhjsaACgv8_5VjmoiauukP1F_P-Fcp51iGrbZiOqm-2UrbeW5m48RnFjEU_ZG72n-89_DCQ4NL8vtIZsZzuVA4J2YeuY1xXbHob85t2e_EDXoAmGeYZ9NLVcy5xaE_56H2PSD-E9hhKQXOBXVRFjRQu0-rq--6Jv0H6PB0BS8KX_UA7wrnYKe2oEhQBwDY\" width=\"320\" /></a></div><br /><ul><li><span style=\"font-weight:normal;text-align:left;\"><b><span>Retail\r\nSales:</span></b> </span><span style=\"font-weight:normal;text-align:left;\"><span>U.S. Commerce Department</span>એ ગઈકાલે </span><span style=\"font-weight:normal;text-align:left;\">report</span><span style=\"font-weight:normal;text-align:left;\"> કર્યો કે મે મહિનામાં</span><span style=\"font-weight:normal;text-align:left;\">U.S. retail sales\r\n0.9%</span><span style=\"font-weight:normal;text-align:left;\"> ઘટ્યું છે</span><span style=\"font-weight:normal;text-align:left;\">,\r\n</span><span style=\"font-weight:normal;text-align:left;\">જે </span><span style=\"font-weight:normal;text-align:left;\">0.7%</span><span style=\"font-weight:normal;text-align:left;\"> ના </span><span style=\"font-weight:normal;text-align:left;\">decline (</span><span style=\"font-weight:normal;text-align:left;\">ઘટાડા) ની અપેક્ષા કરતાં વધુ છે અને છેલ્લા ચાર મહિનામાં\r\nસૌથી મોટો ઘટાડો છે. </span><span style=\"font-weight:normal;text-align:left;\">કેટલાક</span><span style=\"font-weight:normal;text-align:left;\">economists\r\n</span><span style=\"font-weight:normal;text-align:left;\">ના મતે</span><span style=\"font-weight:normal;text-align:left;\">, </span><span style=\"font-weight:normal;text-align:left;\">જૂનમાં નાનો ઘટાડો દર્શાવતા </span><span style=\"font-weight:normal;text-align:left;\">revisions\r\n(</span><span style=\"font-weight:normal;text-align:left;\">સુધારા) સાથેનો </span><span style=\"font-weight:normal;text-align:left;\">retail\r\nsales report, </span><span style=\"font-weight:normal;text-align:left;\">ધીમા પડેલા </span><span style=\"font-weight:normal;text-align:left;\">auto\r\nsales </span><span style=\"font-weight:normal;text-align:left;\">થી ખૂબ પ્રભાવિત હતો. વર્ષની શરૂઆતમાં</span><span style=\"font-weight:normal;text-align:left;\">,\r\nimported vehicles </span><span style=\"font-weight:normal;text-align:left;\">પર </span><span style=\"font-weight:normal;text-align:left;\">25%\r\nlevies (</span><span style=\"font-weight:normal;text-align:left;\">કર) ટાળવાની આશા રાખતા </span><span style=\"font-weight:normal;text-align:left;\">consumers\r\n</span><span style=\"font-weight:normal;text-align:left;\">ને કારણે </span><span style=\"font-weight:normal;text-align:left;\">auto sales </span><span style=\"font-weight:normal;text-align:left;\">માં એક </span><span style=\"font-weight:normal;text-align:left;\">surge (</span><span style=\"font-weight:normal;text-align:left;\">ઉછાળો) આવ્યો હતો. ખરાબ હવામાન (</span><span style=\"font-weight:normal;text-align:left;\">Bad\r\nweather) </span><span style=\"font-weight:normal;text-align:left;\">પણ આ ઘટાડાનું એક કારણ હોઈ શકે છે.</span></li></ul></div>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;text-align:left;\">Likely\r\nOutcome (</span><span style=\"color:#FF0000;text-align:left;\">સંભવિત પરિણામ)</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>મોટા ભાગના </span><span>economic\r\ndata, Federal Reserve </span><span>ને </span><span>dovish\r\nstand </span><span>લેવા અને </span><span>economic\r\ngrowth </span><span>ને </span><span>boost\r\n</span><span>કરવા માટે </span><span>25 bps rate cut </span><span>કરવા માટે એક સારું પ્લેટફોર્મ પૂરું પાડે છે. પરંતુ\r\nતાજેતરના મધ્ય પૂર્વના તણાવ (</span><span>middle east\r\ntensions) </span><span>એ શક્યતાઓ ઓછી કરી દીધી છે</span><span>,\r\n</span><span>કારણ કે </span><span>oil prices </span><span>માં આવેલો </span><span>surge (</span><span>ઉછાળો) </span><span>inflation forecast </span><span>ને જટિલ બનાવી શકે છે. જોકે</span><span>,\r\n</span><span>ઇઝરાયેલ અને ઈરાન વચ્ચેના તીવ્ર </span><span>missile\r\nexchanges </span><span>ના દિવસોએ </span><span>Fed\r\n</span><span>ને વધુ સાવચેત રહેવા માટે કારણ આપ્યું છે</span><span>,\r\n</span><span>કારણ કે મંગળવારે </span><span>oil\r\nprices </span><span>ફરી ઉછળ્યા અને </span><span>inflation\r\n</span><span>ના સંભવિત નવા સ્ત્રોત તરીકે ઉભરી આવ્યા.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>વધતી કિંમતોનું\r\nજોખમ </span><span>central bank </span><span>માટે એક મુખ્ય ચિંતાનો વિષય છે</span><span>,\r\n</span><span>ભલે એવા સંકેતો હોય કે એકંદરે </span><span>economy\r\n</span><span>ધીમી પડી રહી છે. ટ્રમ્પના અંતિમ </span><span>tariff\r\nplans </span><span>હજુ પણ અસ્પષ્ટ છે</span><span>,\r\n</span><span>જેમાં </span><span>trade deals </span><span>ના વચનો અપાયા છે પરંતુ તે હજુ સુધી ડઝનેક દેશો સાથે થયા\r\nનથી</span><span>, </span><span>જેમને તેમણે </span><span>tax\r\n</span><span>લગાવવાની ધમકી આપી છે. આ ઉપરાંત</span><span>,\r\nappliances </span><span>જેવી ચોક્કસ </span><span>goods\r\n</span><span>પર </span><span>levy (</span><span>કર) લગાવવાના </span><span>one-off\r\nproposals </span><span>અમલમાં આવી પણ શકે છે અને નહીં પણ.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>માર્ચ </span><span>meeting\r\n</span><span>દરમિયાન</span><span>, Fed </span><span>એ આ વર્ષે </span><span>economic growth </span><span>માટેની તેમની અપેક્ષાઓ ઘટાડી હતી અને અપેક્ષિત </span><span>inflation\r\n</span><span>નું સ્તર વધાર્યું હતું</span><span>,\r\n</span><span>પરંતુ આ વર્ષે બે </span><span>quarter-percentage-point\r\nrate cuts </span><span>માટેના </span><span>median\r\noutlook </span><span>ને યથાવત રાખ્યો હતો. </span><span>Central\r\nbank </span><span>દ્વારા </span><span>inflation\r\n</span><span>ને નિયંત્રિત રાખવા પર ભાર મૂકવામાં આવતા અને ટ્રમ્પના નવા </span><span>tariffs\r\n</span><span>થી હજુ પણ </span><span>price increases </span><span>થશે તેવી અપેક્ષાઓને ધ્યાનમાં લેતા</span><span>,\r\n</span><span>વધુ </span><span>hawkish shift </span><span>ની શક્યતા છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>આથી</span><span>,\r\nFed </span><span>આ </span><span>meeting\r\n</span><span>દરમિયાન </span><span>interest rate </span><span>ને </span><span>HOLD </span><span>કરે તેવી સૌથી વધુ શક્યતા છે</span><span>,\r\n</span><span>પરંતુ નબળી પડી રહેલી </span><span>US\r\neconomy </span><span>ને ધ્યાનમાં રાખીને આ વર્ષ દરમિયાન </span><span>rate\r\ncut </span><span>માટે </span><span>couple\r\nof dots (</span><span>સંકેતો) </span><span>plot\r\n</span><span>કરી શકે છે. આવો </span><span>policy shift\r\nmarkets </span><span>ને ઉપર તરફ ધકેલી શકે છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has\r\nexercised due diligence in checking the correctness and authenticity of the\r\ninformation before publishing research report. We shall not be in any way\r\nresponsible for any loss or damage in analysis or views obtained from the use\r\nof information contained in this report and especially states that we have no\r\nfinancial liability whatsoever to the user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEjPqa3ps9VxTTygFxiuC1Uqh2c5HwotsWCEa7dhwoVGb9IgeuVAwhNAV0QY6auHtYkXUJ7NN2gQaeiCjthg_Eq8SA9Ic9OpQ5qWZrx4atoF4pzxHHjFgWv2YtEc9JGpoqnW_Jv-XqYP_YUYUwtf9jdmXXk7hd39_9pqr3_AyFJjhCpTr03BDbbgP0C-UsQ','2025-06-18','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(267,'4802660958114752619','Research Report : Indian Financial Markets Outlook - 17th JUNE 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEg-Xp3SZWi-RSnkM-RWHUhfGVVERmzBxaaU4olk1GuNpUrZFmXeAuMeC5BX073hj07wM3BqtIBZDjgXLR56n76vdjCrEIFPWLUDGgnvnGLHuKGNDpYbifAKelP4y7S605PHkPixbDO0cToFdcxMFg4I2fpWFvVBlHk6ZwzPCcVGcu8m5lY_LDSpwEkdGI0\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEg-Xp3SZWi-RSnkM-RWHUhfGVVERmzBxaaU4olk1GuNpUrZFmXeAuMeC5BX073hj07wM3BqtIBZDjgXLR56n76vdjCrEIFPWLUDGgnvnGLHuKGNDpYbifAKelP4y7S605PHkPixbDO0cToFdcxMFg4I2fpWFvVBlHk6ZwzPCcVGcu8m5lY_LDSpwEkdGI0\" width=\"240\" /></a></div>\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#222222;\">Ravi </span></b><b><span style=\"color:#000000;\">Bhatt</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591</span></b></p>\r\n\r\n<p style=\"text-align:center;\"><b><span style=\"color:#666666;\">Website - </span></b><b><span><a href=\"http://www.capsavaj.com/\">www.capsavaj.com</a></span></b></p>\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Markets turn weak after\r\nevacuate Tehran call by Donald Trump</span></p><div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEj06nDWHW9E07SCJEVY0bnzSQGSm83bmusdQRSCXJwOQvB8Knq9694JfPolR6SRfQM3JymaPze0LfL-V6h6t4DvP2E0Hxzi0LZMcPTe1Mu1oHsJWnjr7eiy2dR_JERJR75z-0Uewe8AhagxtY_Rd3U98e5t76gshFC1ujFms7zXD5lZ2hT_5iI949Ngjrg\"><img alt=\"\" height=\"290\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEj06nDWHW9E07SCJEVY0bnzSQGSm83bmusdQRSCXJwOQvB8Knq9694JfPolR6SRfQM3JymaPze0LfL-V6h6t4DvP2E0Hxzi0LZMcPTe1Mu1oHsJWnjr7eiy2dR_JERJR75z-0Uewe8AhagxtY_Rd3U98e5t76gshFC1ujFms7zXD5lZ2hT_5iI949Ngjrg=w489-h290\" width=\"489\" /></a></div><br /><p style=\"text-align:justify;\"><span>US\r\nfutures slipped in Asia session in the morning as US President Donald Trump\r\nasked people to evacuate Tehran after deciding to leave G-7 summit Monday. His\r\nactions are in contrast to what Trump said earlier. He assured that the\r\nconflict between Israel and Tehran will not end into a full-fledged war.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>The\r\nDow Jones Industrial Average and S&amp;P Futures were trading 0.32% and 0.34%\r\ndown, respectively in the morning. The GIFT NIFTY too turned weak in the\r\nmorning session down 45 points at 24,971. West Texas Intermediate crude rose\r\n1.9% to $73.11 a barrel while Spot gold rose 0.5% to $3,400.49 an ounce. The\r\nForeign investors remained net sellers yesterday, drawing 1,256 crores from\r\nIndian equity markets.</span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span>Biocon\r\n-</span></b><span> The Company opened a QIP of Rs 4,500\r\ncrore at a floor price of Rs 340.2 per share. Proceeds from the QIP are to be\r\nused to reduce debt. Positive</span></li><li style=\"text-align:justify;\"><b><span>Vishal\r\nMega Mart -</span></b><span> Promoter Kedaara Capital via\r\nSamayat Services LLP will sell a 10% stake via block deals. Negative</span></li><li style=\"text-align:justify;\"><b><span>TCS\r\n-</span></b><span> The Company partnered with the\r\nCouncil of Europe Development Bank to transform reconciliation processes.\r\nPositive</span></li><li style=\"text-align:justify;\"><b><span>HCL\r\nTech -</span></b><span> The Company signed an agreement\r\nwith E.ON to accelerate product-based transformation. Positive</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><b><span>NIFTY\r\n-</span></b><span> The Nifty index continued upward\r\nmarch rising over 200 points to settle at 24,946 on Monday. Index shrugged off\r\nIsrael Iran war and close above 17 day EMA of 24,840. Index likely to hit 25K\r\nas near term resistance while support remains at 24,850. Today’s range – 24,850\r\n– 25,050.</span></li><li style=\"text-align:justify;\"><b><span>BANKNIFTY\r\n-</span></b><span> Bank nifty too gained further and\r\nclose above 17 day EMA at 55,944 on Monday. Index has taken support at 55,300\r\nwhile 56350 is near term resistance. Today’s range – 55,300 – 56,350.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in\r\nchecking the correctness and authenticity of the information before publishing\r\nresearch report. We shall not be in any way responsible for any loss or damage\r\nin analysis or views obtained from the use of information contained in this\r\nreport and especially states that we have no financial liability whatsoever to\r\nthe user of this report.</span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEg-Xp3SZWi-RSnkM-RWHUhfGVVERmzBxaaU4olk1GuNpUrZFmXeAuMeC5BX073hj07wM3BqtIBZDjgXLR56n76vdjCrEIFPWLUDGgnvnGLHuKGNDpYbifAKelP4y7S605PHkPixbDO0cToFdcxMFg4I2fpWFvVBlHk6ZwzPCcVGcu8m5lY_LDSpwEkdGI0','2025-06-17','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(268,'5161896963666813811','Research Report : Indian Financial Markets Outlook - 16th JUNE 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEilcLRkqCEXC3Fk4u85Qxejw6T1UHEzRruHqmcr3jumGi26Tued6cOZyduwvJdk08XNbGlwWeS_vXUeiADlDVmJdMNgC4xzHopT_V8aYRDdfWwDhEcBBUlz-XHcxXfdMXZ4oeSGpCABJas_rUIKKmwOdD0XIE3SPVq-RmtMAQ4ZmWxA79zSr5k8Z6STzzo/s1563/WhatsApp%20Image%202025-06-16%20at%2010.11.55%20AM.jpeg\"><img height=\"167\" src=\"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEilcLRkqCEXC3Fk4u85Qxejw6T1UHEzRruHqmcr3jumGi26Tued6cOZyduwvJdk08XNbGlwWeS_vXUeiADlDVmJdMNgC4xzHopT_V8aYRDdfWwDhEcBBUlz-XHcxXfdMXZ4oeSGpCABJas_rUIKKmwOdD0XIE3SPVq-RmtMAQ4ZmWxA79zSr5k8Z6STzzo/w167-h167/WhatsApp%20Image%202025-06-16%20at%2010.11.55%20AM.jpeg\" width=\"167\" alt=\"WhatsApp%20Image%202025-06-16%20at%2010.11.55%20AM.jpeg\" /></a></div>\r\n\r\n<h3 style=\"text-align:center;\"></h3><div><b><span style=\"color:#222222;\">Ravi </span></b><b><span>Bhatt<br /></span></b><span style=\"color:#df7231;\">Sebi Registered Research Analyst - </span><b><span>INH000012591<br /></span></b><b><span style=\"color:#666666;\">Website -</span> </b><b><span>www.capsavaj.com</span></b></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Oil price remained elevated\r\nas Israel – Iran conflict continues</span></p>\r\n\r\n<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEgioaDKOsec_cFeqEPh8K3o82TTZzMmIMxwL9dTIODDYugp-1ZoNhZjw3AwR9GJBDDGzTTFqXXJV73Kfp89imjgWUZl_pZfnxLrgppAocjLou3k_mPGONJZlBqUj4BwY0D4nekxD7JbQ3dkcIOK_Bg4JBIbfBlk6BdHqF1oa-iF9_v5Ipd8hEyk3kAAe1o\"><img alt=\"\" height=\"305\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEgioaDKOsec_cFeqEPh8K3o82TTZzMmIMxwL9dTIODDYugp-1ZoNhZjw3AwR9GJBDDGzTTFqXXJV73Kfp89imjgWUZl_pZfnxLrgppAocjLou3k_mPGONJZlBqUj4BwY0D4nekxD7JbQ3dkcIOK_Bg4JBIbfBlk6BdHqF1oa-iF9_v5Ipd8hEyk3kAAe1o=w537-h305\" width=\"537\" /></a></div>\r\n\r\n<p style=\"text-align:justify;\"><span>Asia\r\n– Pacific markets rose on Monday morning seeing a pullback from the losses in\r\nthe previous sessions. Additionally, investors sought refuge in safe-haven\r\nassets like gold and oil as Israel and Iran continued attacks on each other\r\nover the weekend. Equity-index futures for the S&amp;P 500 rose 0.1%, while\r\nAsian markets also rose on Monday. The Israeli Air Force launched an attack on\r\nthe giant South Pars gas field after strike on Iran’s nuclear sites. </span></p><p style=\"text-align:justify;\"><span>The GIFT\r\nNifty was up 0.16% at 24,780 in the morning, signaling a positive start to\r\nIndian markets today. Foreign portfolio investors remained net sellers of\r\nIndian equities for the third straight session, offloading stocks worth Rs\r\n1,263.52 crore, according to the provisional data from NSE. Domestic\r\ninstitutional investors continued to stay net buyers for the 21st straight\r\nsession as they obtained equities worth Rs 3,041.44 crore.</span></p>\r\n\r\n<p><span style=\"color:#FF0000;\">Fundamental Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span><b>ITC\r\n-</b> The company acquired Sresta Natural Bioproducts for an upfront consideration\r\nof Rs 400 crore. SNBPL has become a wholly owned subsidiary of the company\r\npost-acquisition. Positive </span></li></ul><ul style=\"text-align:left;\"><li style=\"text-align:justify;\"><span><b>Yes\r\nBank -</b> Moody’s upgraded the bank ratings to Ba2 from Ba3 and changed the rating\r\noutlook to stable from positive. Positive </span></li><li><p style=\"text-align:justify;\"><span><b>Natco\r\nPharma -</b> The USFDA, in its inspection from June 9 to June 13 at the API\r\nmanufacturing plant located in Hyderabad, concluded with one observation in\r\nform-483. Positive</span></p></li><li><p style=\"text-align:justify;\"><span><b>Tata\r\nMotors -</b> Moody’s raised Jaguar Land Rover’ rating to Ba1 from Ba2 and revised\r\noutlook to positive. Positive</span></p></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p><span style=\"color:#FF0000;\">Technical Update</span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span><b>NIFTY\r\n–</b> The Nifty index recovered after early slump on Friday to settle at 24,718.\r\nIndex sentiments were battered after increased geopolitical risks in Middle\r\nEast. Index likely to trade in range with resistance at 17 day EMA of 24,825.\r\nToday’s range – 24,550 – 24,850.</span></li></ul><ul><li style=\"text-align:justify;\"><span><b>BANKNIFTY\r\n– </b>Bank nifty too recovered to 55,527 after early weakness on Friday. Index has\r\ntaken support at 55K while 17 day EMA of 55,825 is near term resistance.\r\nToday’s range – 55,000 – 56,150.</span></li></ul>\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span style=\"color:#444142;\">Disclaimer: </span></b><span style=\"color:#444142;\">This report is prepared by an analyst who has exercised due diligence in checking the correctness and authenticity of the information before publishing research report. We shall not be in any way responsible for any loss or damage in analysis or views obtained from the use of information contained in this report and especially states that we have no financial liability whatsoever to the user of this report.</span></p>','https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEilcLRkqCEXC3Fk4u85Qxejw6T1UHEzRruHqmcr3jumGi26Tued6cOZyduwvJdk08XNbGlwWeS_vXUeiADlDVmJdMNgC4xzHopT_V8aYRDdfWwDhEcBBUlz-XHcxXfdMXZ4oeSGpCABJas_rUIKKmwOdD0XIE3SPVq-RmtMAQ4ZmWxA79zSr5k8Z6STzzo/w167-h167/WhatsApp%20Image%202025-06-16%20at%2010.11.55%20AM.jpeg','2025-06-16','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(269,'6669678660328399446','Nifty Outlook :- 09.06.2025 - CFA Hitesh Somani',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEit0GeGFRtdtz2yBMgRJGcOCeMRW3t9m3wUAYiR0IgJMg-D-haHc09QUJJajYga7x6xKDjOW3Yrk5UqIDo9P70gmk96wHY4OiDQBdC6ClBgZS2q9aSLvdNX7q5pGlzobgmRO2aB2PMnDVrYkAskJubTtbZVie7tbJB4vinP5OnRf5sFtRKUh18L7fJAJGo\"><span style=\"color:#000000;\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEit0GeGFRtdtz2yBMgRJGcOCeMRW3t9m3wUAYiR0IgJMg-D-haHc09QUJJajYga7x6xKDjOW3Yrk5UqIDo9P70gmk96wHY4OiDQBdC6ClBgZS2q9aSLvdNX7q5pGlzobgmRO2aB2PMnDVrYkAskJubTtbZVie7tbJB4vinP5OnRf5sFtRKUh18L7fJAJGo\" width=\"255\" /></span></a></div><div style=\"background-color:#FFFFFF;font-weight:bold;text-align:center;\"><b>CFA </b><span>Hitesh Somani</span></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div style=\"font-weight:bold;\">MD - Aapka Investments </div><div style=\"font-weight:bold;\">Website - https://www.aapkainvestments.in</div><div><p style=\"font-weight:bold;text-align:justify;\"><b><span>Nifty\r\nclosed with strong bullish move amid RBI Rate Cut. Banking and Finance Sectors\r\non Fire.</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Last\r\nweek nifty faced major resistance at 25000 levels and it fell sharply from\r\nthose levels to 24600 as we said in the last article but finally on Friday amid\r\nRBI rate cut decision as RBI once again slashed 50 basis points in the interest\r\nrates, markets reacted strongly and nifty finally closed above 25000 levels on\r\nFriday. Banknifty and Finance Companies like Bajaj Finance, Shriram Finance\r\nalso showed a big bullish move amid this news. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>We\r\ncan see this strong rally in the next week also if nifty manages to close above\r\n25200 levels in the next week then we can see nifty towards 25500 and 25800\r\nlevels soon. Banknifty closed above 56500 levels which is its fresh lifetime\r\nhigh. Banknifty may show 57000 and 57500.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>One\r\nshould have a strong bullish view for markets in the next week. Nifty and\r\nbanknifty both are in strong bullish moves. Major support levels for nifty is\r\n24600, till it sustains above these levels it would be strong but of it closes\r\nbelow that we may see a sharp fall in the markets.</span></p>\r\n\r\n<p style=\"font-weight:bold;text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p><p style=\"font-weight:bold;text-align:justify;\"><span style=\"text-align:center;\">Major\r\nSupport Levels for Nifty</span></p></div></div></div><blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><div><div><div><p style=\"text-align:justify;\"><span>Support 1 – 24800</span></p></div></div></div></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><div><div><div><div><p style=\"text-align:justify;\"><span>Support 2 – 24600</span></p></div></div></div></div></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><div><div><div><div><p style=\"text-align:justify;\"><span>Support 3 – 24250</span></p></div></div></div></div></div></div></div></blockquote><p> <span style=\"background-color:#FFFFFF;font-weight:bold;text-align:justify;\">Major\r\nResistance Levels for Nifty</span></p><blockquote></blockquote><blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Resistance\r\n1 – 25200 </span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Resistance\r\n2 – 25450</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Resistance\r\n3 – 25700</span></p></div></div></div></blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div>\r\n\r\n\r\n\r\n<p style=\"font-weight:bold;text-align:justify;\"><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p><p style=\"font-weight:bold;text-align:justify;\"><span style=\"text-align:center;\">Major\r\nSupport Levels for Banknifty</span></p></div></div></div><blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><div><div><div><p style=\"text-align:justify;\"><span>Support 1 – 55800</span></p></div></div></div></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><div><div><div><div><p style=\"text-align:justify;\"><span>Support 2 – 55200</span></p></div></div></div></div></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><div><div><div><div><p style=\"text-align:justify;\"><span>Support 3 – 54800</span></p></div></div></div></div></div></div></div></blockquote><p> <span style=\"background-color:#FFFFFF;font-weight:bold;text-align:center;\">Major\r\nResistance Levels for Banknifty</span></p><blockquote></blockquote><blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Resistance\r\n1 – 56900</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Resistance\r\n2 – 57400</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Resistance\r\n3 – 57900</span></p></div></div></div></blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;font-weight:bold;\"><div><p style=\"text-align:justify;\"><b><b><span>Important\r\nStocks to Watch Next Week</span></b></b></p><p style=\"text-align:justify;\"><b><span>1)\r\n<b>AMBUJACEM</b></span></b></p></div></div></div><blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>CMP  </span><span>@ </span><span>556</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Buy\r\nAbove </span><span>@ </span><span>565</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Stop\r\nLoss Below </span><span>@ </span><span>540</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Targets </span><span>@ </span><span>580, 600 and 625</span></p></div></div></div></blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;font-weight:bold;\"><div><p style=\"text-align:justify;\"><b><span><br />\r\n2) <b>AXISBANK</b></span></b></p></div></div></div><blockquote><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>CMP @ 1195</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Buy\r\nAbove </span><span>@</span><span> 1210</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Stop\r\nLoss </span><span>@</span><span> 1120</span></p></div></div></div><div style=\"text-align:center;\"><div style=\"background-color:#FFFFFF;\"><div><p style=\"text-align:justify;\"><span>Targets </span><span>@ </span><span>1280, 1340 and 1380</span></p></div></div></div></blockquote>','https://blogger.googleusercontent.com/img/a/AVvXsEit0GeGFRtdtz2yBMgRJGcOCeMRW3t9m3wUAYiR0IgJMg-D-haHc09QUJJajYga7x6xKDjOW3Yrk5UqIDo9P70gmk96wHY4OiDQBdC6ClBgZS2q9aSLvdNX7q5pGlzobgmRO2aB2PMnDVrYkAskJubTtbZVie7tbJB4vinP5OnRf5sFtRKUh18L7fJAJGo','2025-06-09','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(270,'4634724124967268984','Nifty Outlook :- 02.06.2025 - CFA Hitesh Somani',NULL,'<div style=\"font-weight:bold;text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEiUfODxvZyNlwyjJdd2q7Ryt1eNdo5zyt-AeN7W57KSy7dgHDfZSIQTrsprnB9g8WnCWrWKnH0V2Kirxk_nxLC6ythEKyspMR4Aoie3YIQt9R8vsgFlpE_eGO_sJQyk00DmLon_1crSqriTqUGX_gnT_L-rhdrGsQc-oAukqHyi1uozrKk8wLqVTITcg6Q\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEiUfODxvZyNlwyjJdd2q7Ryt1eNdo5zyt-AeN7W57KSy7dgHDfZSIQTrsprnB9g8WnCWrWKnH0V2Kirxk_nxLC6ythEKyspMR4Aoie3YIQt9R8vsgFlpE_eGO_sJQyk00DmLon_1crSqriTqUGX_gnT_L-rhdrGsQc-oAukqHyi1uozrKk8wLqVTITcg6Q\" width=\"255\" /></a></div><div style=\"font-weight:bold;text-align:center;\"><b>CFA </b><span>Hitesh Somani</span></div><div style=\"font-weight:bold;text-align:center;\"><div><b>MD - Aapka Investments </b></div><div><b>Website - https://www.aapkainvestments.in</b></div></div><p><b><span>Nifty\r\nclosed in Green for 3<sup>rd</sup> Consecutive Week, markets clearly on bull\r\nside but Nifty facing major resistance at 25000 levels.</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Last\r\nweek was the monthly expiry week for derivatives markets and nifty closed in\r\nperfect green for 3<sup>rd</sup> consecutive week. In the last week we saw a\r\ntough fight between bulls and bears and market saw major whipsaws which clearly\r\nindices that at 25000 levels is the major resistance and investors are showing\r\nprofit bookings at that level. Banknifty is managing and trading in a narrow\r\nrange of 55000 to 56000 levels. If in the next week banknifty breaks and close\r\nabove 56000 levels then banknifty may hit a new life time high and nifty can\r\nalso close above 25500 levels. </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>If\r\nnifty manages to close above 25200 levels in the next week we can see a good\r\nbullish move in the markets and nifty may hit 25700 levels soon. And if\r\nbanknifty manages to close above 56200 levels it would be clear signal for it\r\nto hit 57000 levels soon</span></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Nifty Next Week</span></b></p>\r\n\r\n<ul><li><span>Major\r\nSupport Levels for Nifty</span></li></ul>\r\n\r\n<blockquote><p style=\"text-align:justify;\"><span>Support 1 – 24600</span></p><p style=\"text-align:justify;\"><span>Support 2 – 24300</span></p><p style=\"text-align:justify;\"><span>Support 3 – 24000</span></p></blockquote>\r\n\r\n\r\n\r\n\r\n\r\n<ul><li><span>Major\r\nResistance Levels for Nifty</span></li></ul>\r\n\r\n<blockquote><p style=\"text-align:justify;\"><span>Resistance 1 – 25000</span></p><p style=\"text-align:justify;\"><span>Resistance 2 – 25350</span></p><p style=\"text-align:justify;\"><span>Resistance 3 – 25700</span></p></blockquote>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nLevels for Banknifty Next Week</span></b></p>\r\n\r\n<ul><li><span>Major\r\nSupport Levels for Banknifty</span></li></ul>\r\n\r\n<blockquote><p style=\"text-align:justify;\"><span>Support 1 – 54800</span></p><p style=\"text-align:justify;\"><span>Support 2 – 54200</span></p><p style=\"text-align:justify;\"><span>Support 3 – 53600</span></p></blockquote>\r\n\r\n\r\n\r\n\r\n\r\n<ul><li><span>Major\r\nResistance Levels for Banknifty </span></li></ul>\r\n\r\n<blockquote><p style=\"text-align:justify;\"><span>Resistance 1 – 56200</span></p><p style=\"text-align:justify;\"><span>Resistance 2 – 56600</span></p><p style=\"text-align:justify;\"><span>Resistance 3 – 57000</span></p></blockquote>\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>Important\r\nStocks to Watch Next Week</span></b></p>\r\n\r\n<p style=\"text-align:justify;\"><b><span>1)\r\nINDIAMART</span></b></p>\r\n\r\n<blockquote><p style=\"text-align:justify;\"><span>CMP @ 2330</span></p><p style=\"text-align:justify;\"><span>Buy Above @ 2420</span></p><p style=\"text-align:justify;\"><span>Stop Loss Below @ 2250</span></p><p style=\"text-align:justify;\"><span>Targets @ 2490, 2590 and 2690</span></p></blockquote>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span><br />\r\n<b>2) ABCAPITAL</b></span></p>\r\n\r\n<blockquote><p style=\"text-align:justify;\"><span>CMP @ 222</span></p></blockquote><blockquote><p style=\"text-align:justify;\"><span>Buy Above</span><span>@ </span><span>224.5</span></p></blockquote><blockquote><p style=\"text-align:justify;\"><span>Stop Loss Below </span><span>@ </span><span>212</span></p></blockquote><blockquote><p style=\"text-align:justify;\"><span>Targets </span><span>@</span><span> 228.5, 234.5 and 242.5</span></p></blockquote>','https://blogger.googleusercontent.com/img/a/AVvXsEiUfODxvZyNlwyjJdd2q7Ryt1eNdo5zyt-AeN7W57KSy7dgHDfZSIQTrsprnB9g8WnCWrWKnH0V2Kirxk_nxLC6ythEKyspMR4Aoie3YIQt9R8vsgFlpE_eGO_sJQyk00DmLon_1crSqriTqUGX_gnT_L-rhdrGsQc-oAukqHyi1uozrKk8wLqVTITcg6Q','2025-05-31','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(271,'1422299499952219139','Invitation To SEBI-Registered Research Analysts For Article Contributions',NULL,'<p style=\"text-align:justify;\"><span>Dear Sir/Madam,</span></p><p style=\"text-align:justify;\"><span>This\r\ncommunication is an official invitation to all SEBI-registered Research\r\nAnalysts to contribute original, stock market-related articles for publication\r\nin the Daily Digital Newsletter (in English and Gujarati), the Weekly Gujarati\r\nBusiness Newspaper, and on the website of Investment Point\r\n(www.investmentpoint.in) under the section titled <b>\"Expert\'s View.\"</b></span></p><p style=\"text-align:justify;\"><b><span>Purpose :-</span></b><span> The objective of\r\nthis invitation is to aggregate expert perspectives on stock market trends and\r\nprovide readers with insightful, high-quality market analysis from qualified\r\nprofessionals.</span></p><p style=\"text-align:justify;\"><span>Benefits</span></p><p style=\"text-align:justify;\"><b><span>1. </span></b><b><span>Exposure:</span></b><span> Your articles\r\nwill be distributed to business professionals and investors through both print\r\nand digital platforms.</span></p><p style=\"text-align:justify;\"><b><span>2. </span></b><b><span>Showcase Expertise:</span></b><span> This is an\r\nopportunity to demonstrate your analytical skills and knowledge in business,\r\nfinance, and economics.</span></p><p style=\"text-align:justify;\"><b><span>3. </span></b><b><span>Submission Guidelines</span></b></p><ul><li><b><span>Originality:</span></b><span> All submitted\r\narticles must be original and relevant to business, markets, or economic\r\ntrends.</span></li><li><b><span>Required\r\nInformation:</span></b><span> Each submission must include your biodata, SEBI\r\nRegistration Number, email address, and contact details.</span></li><li><b><span>Selection:</span></b><span> Articles may be\r\nselected for publication in daily briefs or weekly features at the sole\r\ndiscretion of the editorial team.</span></li><li><b><span>Voluntary\r\nParticipation:</span></b><span> Participation in this initiative is voluntary and\r\nunpaid.</span></li><li><b><span>Consent:</span></b><span> By submitting an\r\narticle, you consent to the publication of your work and to any necessary\r\nediting by the editorial team.</span></li><li><b><span>Social\r\nMedia/Links:</span></b><span> If you wish, you may provide links to your blog, website,\r\nor Facebook page for direct reference or sharing.</span></li></ul><p style=\"text-align:justify;\"><b><span>4. </span></b><b><span>Contact Information :</span></b><span> For further\r\ninformation or to submit articles, please contact :</span></p><div style=\"text-align:justify;\"><span>Nikhil Bhatt<br /></span><span>Business Editor<br /></span><span>Phone: +91\r\n9939080808</span><span>Email:\r\contact@example.com<br /></span><span>Website:\r\nwww.nikhilbhatt.in</span></div><p style=\"text-align:justify;\"><span>We look forward\r\nto your valuable contributions.</span></p><p style=\"text-align:justify;\">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<b><span>Note :</span></b><span> This\r\ninvitation does not constitute a binding contract and is for informational\r\npurposes only. Participation is entirely at the discretion of the invitee.</span></p>',NULL,'2025-05-29','active','2026-09-25 07:55:45','2026-09-25 07:55:45'),
(272,'9028127910220746256','ન્યુઝ હેડલાઇન્સ - ૦૯ ડીસેમ્બર ૨૦૨૫',NULL,'<div style=\"text-align:center;\"><b><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEguU3pDY9m7n0bQNAgqSio1bYfoUsCYSzH0yiuoHT0lxYul76bHdlMOjsQYZM7B6pvewnVlbGun_dtu1zQfu3Q35frPRRlGDcfZEIVy3VrWsl30_dSR7kwatfW3jytTfbCO9QQKWHf0aPcswJDdM7JVBD38jKzfTXBbviEyl052PsIuquY0WyxnT3kOTZQ\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEguU3pDY9m7n0bQNAgqSio1bYfoUsCYSzH0yiuoHT0lxYul76bHdlMOjsQYZM7B6pvewnVlbGun_dtu1zQfu3Q35frPRRlGDcfZEIVy3VrWsl30_dSR7kwatfW3jytTfbCO9QQKWHf0aPcswJDdM7JVBD38jKzfTXBbviEyl052PsIuquY0WyxnT3kOTZQ\" width=\"152\" /></a></b></div><h2 style=\"text-align:center;\"><b><span>મંગળવાર</span></b><b><span>, </span></b><b><span>ડિસેમ્બર ૯,</span></b><b><span>૨૦૨૫<br /></span></b><b><span style=\"color:#0000FF;\">સંકલન </span></b><b><span style=\"color:#0000FF;\">:-</span></b><b><span style=\"color:#0000FF;\">Navin\r\nDesai ( </span></b><b><span style=\"color:#0000FF;\">ન્યુ જર્સી</span></b><b><span style=\"color:#0000FF;\"> )<br /></span></b></h2><b><span style=\"color:#FF0000;\">મો.</span></b><b><span style=\"color:#FF0000;\">+1 201 699 8042<br /></span></b><b><span style=\"color:#0000FF;\">E</span></b><b><span style=\"color:#0000FF;\">mail -</span></b><b><span style=\"color:#0000FF;\"> <span>contact@example.com</span></span></b>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:center;\"><span><a href=\"http://www.capsavaj.com/\"></a></span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#2b00fe;\"><b><span>📌</span></b><b><span>ઇન્ડિયન ન્યૂઝ:</span></b></span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>1. શેર માર્કેટમાં ઈન્ડિગોનું ‘ક્રેશ લેન્ડિંગ’ ! 5 દિવસમાં 16% ગાબડું</span><span>, </span><span>સરકારની કડકાઈ બાદ\r\nરોકાણકારોમાં હલચલ. ઈન્ડેક્સ : આજે ઈન્ડેક્સ 85624.84 થી શરૂ થઇ નીચે 84875.59 થયો\r\nઅને ઉપરમાં 85722.97 થયા પછી બંધ 85102.69 રહ્યો.</span></li><li style=\"text-align:justify;\"><span>2. જાપાનમાં 7.6ની તીવ્રતાનો મોટો ભૂકંપ</span><span>, </span><span>સુનામીની ચેતવણી જાહેર</span></li><li style=\"text-align:justify;\"><span>3. થાઈલેન્ડ-કમ્બોડિયા વચ્ચે ડોનાલ્ડ ટ્રમ્પે કરાવેલો યુદ્ધ વિરામ માત્ર 44\r\nદિવસમાં જ ખત્મ : બંને એકબીજાને ભાંડે છે- કમ્બોડિયા ચીનનું આશ્રિત છે તેનાં\r\nલશ્કરી થાણા ત્યાં છે- જુલાઈમાં બંને દેશો વચ્ચે સંઘર્ષ ફાટી નીકળ્યો હતો</span><span>, </span><span>તેમાં 48ના મૃત્યુ\r\nથયા હતા અને ત્રણ લાખથી વધુ વિસ્થાપિત થયા હતા</span></li><li style=\"text-align:justify;\"><span>4. ભારત-અમેરિકા વચ્ચે હવે ટ્રેડ ડીલ પર લાગશે મહોર</span><span>? </span><span>ફાઈનલ ચર્ચા માટે 3 દિવસની મહત્ત્વપૂર્ણ બેઠક</span></li><li style=\"text-align:justify;\"><span>5. ક્વાડના માધ્યમથી ભારત સાથે સહયોગ વધારવાનો અમેરિકાનો પ્લાન</span><span>, US </span><span>સાંસદોએ જાહેર\r\nકર્યું વાર્ષિક સંરક્ષણ નીતિ વિધેયક</span></li><li style=\"text-align:justify;\"><span>6. પહેલો સગો પાડોશી! દિતવાહ વાવાઝોડાથી અસરગ્રસ્ત શ્રીલંકાની મદદ માટે ભારતે\r\nવધુ 4 યુદ્ધ જહાજ મોકલ્યા</span></li><li style=\"text-align:justify;\"><span>7. વિદેશ મંત્રાલયની ભારતીયોને ચેતવણી</span><span>, </span><span>ચીનની મુસાફરી સમયે સાવધાની રાખજો</span><span>, </span><span>ચીની એરપોર્ટ્સ પર ટ્રાન્ઝિટ કરનારા ભારતીયો સાથે અયોગ્ય\r\nઅને ભેદભાવપૂર્ણ વર્તન ન થવું જોઈએ.</span></li><li style=\"text-align:justify;\"><span>8. 18 વર્ષ પછી </span><span>IPO</span><span>ની સંખ્યા પહેલી વાર 100ને પાર- ઈશ્યુ થકી કંપનીઓએ કુલ રૂ.\r\n૧.૭૦ લાખ કરોડ એકત્ર કર્યા- ૨૦૨૫માં અત્યાર સુધી ૯૬ કંપનીઓએ આઈપીઓ કર્યા</span><span>,</span><span>આગામી દિવસોમાં\r\nવધુ પાંચ ઇશ્યૂ આવવાના હોવાથી આ વર્ષે ઇશ્યૂની સંખ્યા ૧૦૦ને વટાવી જશે</span></li><li style=\"text-align:justify;\"><span>9. રેપો રેટમાં ઘટાડાથી અર્થતંત્રને ટેકો પરંતુ શેરબજારમાં મર્યાદિત લાભ :\r\nનિષ્ણાંતો- વિશ્લેષકોના મતે યુએસ ટેરિફના કારણે બજારમાં તીવ્ર તેજી આવવાની શક્યતા\r\nઓછી</span></li><li style=\"text-align:justify;\"><span>10. અમે લશ્કર-એ-તૈયબાને કર્યું એમ હમાસને આતંકવાદી જાહેર કરે ભારત: ઈઝરાયલની\r\nમાગ</span></li><li style=\"text-align:justify;\"><span>11. પુતિન સાથે મિત્રતા વધારવા ટ્રમ્પે રશિયા પરથી </span><span>\'</span><span>દુશ્મન</span><span>\'</span><span>નો ટેગ હટાવ્યો! મોસ્કો ખુશ</span><span>, </span><span>યુરોપમાં ફફડાટ</span></li><li style=\"text-align:justify;\"><span>12. ફ્રાન્સના મેક્રોને ટ્રમ્પ સ્ટાઈલમાં જ ચીનને આપી ધમકી</span><span>, </span><span>ભારત માટે કેમ </span><span>\'</span><span>ગોલ્ડન ચાન્સ</span><span>\'? </span><span>મેક્રોને આ\r\nમુદ્દાને યુરોપિયન ઉદ્યોગ માટે જીવન અને મૃત્યુનો સવાલ ગણાવ્યો</span><span>, </span><span>સાથે જ એક નવી\r\nડીલનો પ્રસ્તાવ મૂક્યો જે ભારત માટે સુવર્ણ તક સમાન છે. </span></li><li style=\"text-align:justify;\"><span>13. રિઝર્વ બેન્ક દ્વારા રેટ કટની વર્તમાન સાઈકલ લગભગ પૂરી થયાનો મત- વ્યાજ\r\nદરમાં હવે પછીની કપાત વિકાસ દરના ઘટાડાના કિસ્સામાં જ જોવા મળશે</span></li><li style=\"text-align:justify;\"><span>14. રૂપિયો નબળો પડતા નિકાસકારો સાવધ આયાતકારોની હેજિંગ માટે દોડધામ- રૂપિયો\r\nડિસેમ્બર ૨૦૨૬ સુધીમાં ૮૯.૫૦-૯૧.૦૦ની રેન્જમાંથી બહાર નીકળી ૯૩.૦૦ સુધી તુટશે</span></li><li style=\"text-align:justify;\"><span>15. સોના-ચાંદીમાં ઈફેકટીવ ઈમ્પોર્ટ ડયુટીમાં વૃદ્ધિ : બજાર ભાવ ઉંચકાયા-\r\nઆયાતકારો માટે ડોલરના ભાવ રૂ.૮૯.૫૦થી વધારી રૂ.૯૧.૩૦ કરાયા :- સાઉદીએ એશિયા માટે\r\nક્રૂડતેલના ભાવ ઘટાડયા: વિશ્વ બજાર પણ વધી</span></li><li style=\"text-align:justify;\"><span>16. શું તમે લગ્નનો વીમો ઉતરાવ્યો છે</span><span>?:</span><span>લાખોના ખર્ચે થતા લગ્નને અણધાર્યા જોખમોથી બચાવો</span><span>, </span><span>જાણો વેડિંગ\r\nઇન્શ્યોરન્સના ફાયદા અને ક્લેમની શરતો</span></li><li style=\"text-align:justify;\"><span>17. દુબઈ અને મુંબઈને આંટી જશે અમદાવાદ</span><span>, </span><span>ગુજરાતનું બુર્જ ખલીફા બનશે:સ્કાય સિટી બની વિશ્વમાં ડંકો\r\nવગાડશે</span><span>, </span><span>100 મીટરથી ઉંચી\r\n31 બિલ્ડિંગનું કામ ટોપ ગિયરમાં</span></li><li style=\"text-align:justify;\"><span>18. ગ્લોબલ ગુજરાતી-1 : </span><span>\'</span><span>જ્યારે સ્વામી બોલ્યા</span><span>, </span><span>પટેલ થઈને નોકરી કરે છે</span><span>?\':</span><span>દાદાએ ગાંધીજીની પ્રેક્ટિસ આફ્રિકામાં શરૂ કરાવી</span><span>, </span><span>પ્રમુખ સ્વામીના\r\nઆશીર્વાદથી દવાની દુકાન શરૂ કરી</span><span>; </span><span>₹</span><span>500 </span><span>કરોડનું</span><span>ટર્નઓવર</span></li><li style=\"text-align:justify;\"><span>19. શું </span><span>RBI</span><span>એ જાણી જોઈને\r\nરૂપિયો ઘટવા દીધો કે કોઈ મોટી અનહોની</span><span>; </span><span>રેકોર્ડ 1 ડોલર 90 રૂપિયાને પાર જવાથી સામાન્ય લોકો પર શું\r\nઅસર</span><span>?</span></li><li style=\"text-align:justify;\"><span>20. પશુઓ સાથે શૂટિંગમાં પરસેવો છૂટી ગયો’:‘વેલજીભાઈની વાર્તામાં </span><span>\'</span><span>જીવ</span><span>\' </span><span>પૂર્યો’</span><span>, \'</span><span>સુપરપાવર નહીં</span><span>, </span><span>રોટલાવાળો મહાનાયક</span><span>\'; </span><span>સ્ટારકાસ્ટે\r\nસિનેમાની સામાજિક જવાબદારી સમજાવી</span></li><li style=\"text-align:justify;\"><span>21. 300 બોટ કિનારે લાગી</span><span>, </span><span>પ્રવાસીઓના મોઢા વીલા</span><span>, </span><span>નળસરોવર સુમસાન:સરકારની </span><span>SOP </span><span>અને બોટ સંચાલકોની ખેંચતાણમાં વિદેશી પક્ષીઓને નિહાળવાની\r\nમજા બગડી</span><span>, </span><span>આ વખતની સિઝન પણ\r\nફેલ</span></li><li style=\"text-align:justify;\"><span>22. બાળકીનો હાથ કાપવો પડશે</span><span>\', </span><span>અમદાવાદ સિવિલના ડૉક્ટરની વાતથી પરિવાર ચોંક્યો:વિસનગરની\r\nપાર્થ હોસ્પિટલ સામે પિતાનો આક્ષેપ</span><span>, </span><span>કહ્યું- ડૉક્ટરની ભૂલના કારણે બાળકીનો હાથ કાળો પડ્યો</span></li><li style=\"text-align:justify;\"><span>23. ધર્મેન્દ્રની 90મી બર્થ એનિવર્સરી:</span><span>\'</span><span>પડતાં ઝાડને હીરોની જેમ રોકી ક્રૂનો જીવ બચાવ્યો</span><span>\', \'</span><span>ટ્રક ડ્રાઈવર\r\nપાસેથી કપડાં ઉધાર લઈ શૂટિંગ કર્યું</span><span>\'; </span><span>અનટોલ્ડ કિસ્સાઓ</span></li><li style=\"text-align:justify;\"><span>24. ક્રેડિટ સ્કોર કરો તો </span><span>CIBIL </span><span>ઘટી જાય</span><span>?:</span><span>લોન અને </span><span>CIBIL</span><span>ની 6 મોટી ગેરસમજણ</span><span>, </span><span>લોન </span><span>\'</span><span>સેટલ</span><span>\' </span><span>કરવી ફાયદાકારક છે</span><span>? </span><span>3 ચીજથી સ્કોર સુધરશે!</span></li><li style=\"text-align:justify;\"><span>25. નહેરમાં ફેંકેલી દીકરી 68 દિવસ પછી જીવતી મળી:ફિરોઝપુરમાં પિતાએ બંને હાથ\r\nબાંધીને ફેંકી</span><span>, </span><span>વીડિયો બનાવી\r\nકહ્યું હતું- મારીને દૂર કરી દીધી</span><span>; </span><span>જાણો કેવી રીતે જીવ બચાવ્યો. ફિરોઝપુર</span></li><li style=\"text-align:justify;\"><span>26. મિત્રતા</span><span>, </span><span>શરીર સંબંધ</span><span>, </span><span>સ્પાય વીડિયો</span><span>, </span><span>બ્લેકમેઈલ અને ખંડણીનો ખેલ:સુરતના બિલ્ડરને હનીટ્રેપમાં\r\nફસાવનાર યુવતી અને વકીલ 20 લાખની ખંડણી લેતા રંગેહાથ ઝડપાયા</span></li><li style=\"text-align:justify;\"><span>27. સોલા ભાગવત નજીક ક્લોરિન ગેસ લીકેજથી હડકંપ:અજાણ્યો શખસ બાટલો ફેંકીને ફરાર</span><span>, </span><span>ફાયર જવાનો સહિત\r\nલોકોને આંખ-શ્વાસની તકલીફ</span><span>; </span><span>બે જવાન હોસ્પિટલમાં દાખલ</span></li><li style=\"text-align:justify;\"><span>28. તૂટેલી ખોપરી</span><span>, </span><span>શરીરે બચકાં</span><span>, </span><span>ચહેરે ડામઃ બેબી ફલકને કોણે મારી</span><span>?:</span><span>2 લાખમાં માતાને વેશ્યાવૃત્તિમાં વેચી મારી</span><span>, </span><span>બેબી ફલકની\r\nટ્રેજેડી પર નેટફ્લિક્સ સિરીઝ આવી</span></li><li style=\"text-align:justify;\"><span>29. ઇન્ડિગો એરલાઇને અત્યાર સુધીમાં </span><span>₹</span><span>610 </span><span>કરોડ</span><span>રિફંડ</span><span>કર્યા</span><span>:</span><span>દેશભરમાં</span><span> 3 </span><span>હજાર</span><span>યાત્રીઓનો</span><span>સામાન</span><span>પણ</span><span>પાછો</span><span>આપ્યો</span><span>; </span><span>છઠ્ઠા દિવસે 650+ ફ્લાઇટ કેન્સલ</span></li><li style=\"text-align:justify;\"><span>30. દરિયામાં ચીનની હરકત પર જાપાન ગુસ્સે ભરાયું</span><span>, </span><span>ડ્રેગને કહ્યું - અમે તો પહેલા જ જણાવી દીધું હતું</span></li><li style=\"text-align:justify;\"><span>31. બ્રાઝિલમાં 700 કિલો સોનું મેળવીને 900 કરોડ કમાયેલા ખાણિયાએ દેવાળીયું\r\nફૂંક્યું</span><span>, </span><span>કારણ બેંક!</span></li><li style=\"text-align:justify;\"><span>32. ભારત પાછા ફર્યા બાદ પુતિનનું યુક્રેન પર આક્રમણ</span><span>, </span><span>653 ડ્રોન</span><span>, </span><span>51 મિસાઈલ સાથે સૈન્યનો હુમલો</span></li><li style=\"text-align:justify;\"><span>33. ઈયુ-જી7 દેશો રશિયન ક્રૂડના સમુદ્રી પરિવહન પર સંપૂર્ણ પ્રતિબંધો મૂકશે-\r\nપુતિનના ભારત પ્રવાસના બીજા જ દિવસે યુરોપ-જી7 દેશોનું આકરું વલણ- નવા સંભવિત\r\nપ્રતિબંધોથી રશિયન ક્રૂડની નિકાસ માટે જહાજો અને વીમા સેવા બંધ થશે : રશિયાએ શેડો\r\nફ્લીટ વધારવી પડશે</span></li><li style=\"text-align:justify;\"><span>34. ગુજરાત </span><span>ATS</span><span>એ </span><span>MD </span><span>ડ્રગ્સની મોટી ફેક્ટ્રીનો કર્યો પર્દાફાશ</span><span>, </span><span>2 કરોડના ડ્રગ્સ\r\nસાથે 6ની ધરપકડ</span></li><li style=\"text-align:justify;\"><span>35. ફટાકડા ફોડતા લાગી આગ...</span><span>\', </span><span>ગોવાના નાઇટ ક્લબમાં અગ્નિકાંડ મામલે </span><span>CM</span><span>નો મોટો ખુલાસો</span><span>, </span><span>4 અધિકારીની ધરપકડ</span></li><li style=\"text-align:justify;\"><span>36. બેંગલુરુમાં યોજાશે </span><span>IPL-</span><span>2026ની મેચ</span><span>, BCCI </span><span>પહેલા કર્ણાટક સરકારે કરી મોટી જાહેરાત</span></li><li style=\"text-align:justify;\"><span>37. બિગ બોસ 19ની સીઝનનો વિનર બન્યો ગૌરવ ખન્ના</span><span>, </span><span>જીત્યા 50 લાખ રૂપિયા</span></li><li style=\"text-align:justify;\"><span>38. મંત્રમુગ્ધ કરી દેનારો </span><span>VIDEO: </span><span>ભારતીય વાયુસેનાની સારંગ ટીમે અંકલેશ્વરના આકાશમાં કર્યો\r\nઅદભુત એર શો</span></li><li style=\"text-align:justify;\"><span>39. તેઓ ફોન કરીને ક્યારેય તમારા વખાણ નહીં કરે...</span><span>\', </span><span>બોલિવૂડ કલાકારો અંગે મનોજ બાજપેયી ખુલીને કરી વાત</span></li><li style=\"text-align:justify;\"><span>40. રાજકોટમાં વાયુસેનાનો રોમાંચક એર શો</span><span>, </span><span>8000 ફૂટની ઊંચાઈથી કૂદ્યા જવાનો</span><span>, </span><span>શૌર્ય-સ્ટંટ જોઈ લોકો દંગ</span></li><li style=\"text-align:justify;\"><span>41. નાસિકમાં ઇનોવા કાર 1000 ફૂટ ઊંડી ખીણમાં ખાબકી</span><span>, </span><span>પટેલ પરિવારના 6 લોકોના મોત</span></li><li style=\"text-align:justify;\"><span>42. 150 દેશોના લોકોને એપલ-ગૂગલની ચેતવણી</span><span>, </span><span>ખતરનાક જાસૂસી સોફ્ટવેર ચિંતા વધારી</span><span>, </span><span>બચવા માટે કરો આ\r\nજરૂરી કામ</span></li><li style=\"text-align:justify;\"><span>43. સુરતના સચિન વિસ્તારમાં ગેસ લીકેજથી મકાનમાં આગની ઘટના</span><span>, </span><span>ગંભીર રીતે\r\nઈજાગ્રસ્ત 2 યુવતીનું સારવાર દરમિયાન મોત</span></li><li style=\"text-align:justify;\"><span>44. </span><span>UIDAI</span><span>ની નવી જાહેરાત: </span><span>QR </span><span>કોડ અને નવી એપથી\r\nફટાફટ થશે આધાર વેરિફિકેશન</span><span>, </span><span>જાણો વિગતવાર</span></li><li style=\"text-align:justify;\"><span>45. કોઈપણ વ્યક્તિ બાબરીના નામે મસ્જિદ બનાવશે તો...’ મુર્શિદાબાદમાં\r\nખાતમુહૂર્ત મામલે ભડક્યા </span><span>UP</span><span>ના નાયબ </span><span>CM</span></li><li style=\"text-align:justify;\"><span>46. 5 સેકન્ડમાં 5 માળની બિલ્ડિંગ ધરાશાયી</span><span>, </span><span>દીવાલોમાં તિરાડો દેખાતા લોકો બહાર દોડી ગયા હતા.માલવિયા નગર સેક્ટર 9માં નિર્માણાધીન પાંચ\r\nમાળની હોટલ નમી જતાં મોટી દુર્ઘટના થતા ટળી છે</span></li><li style=\"text-align:justify;\"><span>47. શું </span><span>\'</span><span>વંદે માતરમ્</span><span>\'</span><span>માં મુસલમાનોને\r\nમારવાનું આહવાન</span><span>?:</span><span>ગાંધીજીએ અલ્લાહુ\r\nઅકબર સાથે સરખામણી કરી હતી</span><span>, </span><span>નહેરુએ એક ભાગ કેમ હટાવ્યો</span><span>?; </span><span>સંપૂર્ણ કહાની</span></li><li style=\"text-align:justify;\"><span>48. યોગી પૌડી ગઢવાલમાં પોતાની મોટી બહેનને મળ્યા:5 દિવસ પહેલા બનેવીનું\r\nમૃત્યુ થયું હતું</span><span>; </span><span>કોટદ્વારમાં સિદ્ધબલી બાબાના દર્શન કર્યા</span></li><li style=\"text-align:justify;\"><span>49. ભાવનગરમાંથી રૂ.719 કરોડના આંતરરાષ્ટ્રીય કૌભાંડનો પર્દાફાશ</span><span>, </span><span>દુબઈ-ચીન કનેક્શન\r\nખુલ્યું</span></li><li style=\"text-align:justify;\"><span>50. કોંગ્રેસે ઝીણા સામે ઘૂંટણ ટેકવ્યા</span><span>, </span><span>નેહરુને મુસ્લિમો ભડકશે તેવો ડર હતો: વંદે માતરમ્ મુદ્દે </span><span>PM </span><span>મોદીનું સંસદમાં\r\nસંબોધન. એક સમયે વંદે માતરમ્ ગાવા પર હતો પાંચ રૂપિયાનો દંડ! જાણો આઝાદીના અમર\r\nગીતનો 150 વર્ષનો ઈતિહાસ</span></li><li style=\"text-align:justify;\"><span>51. માત્ર 72 જ કલાકમાં રૂ.100 કરોડના ક્લબમાં સામેલ થઈ ધુરંધર ફિલ્મ! રણવીર\r\nસિંહ-અક્ષય ખન્નાએ બોક્સ ઓફિસ ગજવ્યું</span></li><li style=\"text-align:justify;\"><span>52. સુરત: વરાછામાં વૃદ્ધ મહિલા સાથે અભદ્ર વર્તન કરનાર પાલિકા અધિકારીને </span><span>\'</span><span>શો કોઝ</span><span>\' </span><span>નોટિસ: 3 દિવસમાં\r\nખુલાસો માંગ્યો</span></li><li style=\"text-align:justify;\"><span>53. ધર્મ પરિવર્તન પછી પણ અનામતનો લાભ લેનારાની મુશ્કેલી વધશે! મોટું અભિયાન\r\nશરૂ કરવાની તૈયારી</span></li><li style=\"text-align:justify;\"><span>54. કોંગ્રેસના સાંસદો ભાજપને</span><span>, </span><span>ભાજપના સાંસદો કોંગ્રેસને વોટ કરી શકે તેવી છૂટ આપો...:\r\nદિગ્ગજ નેતા લાવ્યા બિલ. (</span><span>Private Member\r\nBill). </span><span>કોંગ્રેસના વરિષ્ઠ સાંસદ મનીષ તિવારી.</span></li><li style=\"text-align:justify;\"><span>55. અંતરિક્ષમાં ભારત-રશિયાની મિત્રતા એક ઓર્બિટમાં બન્નેના સ્પેસ સ્ટેશનો.\r\nરશિયાએ સ્પેસમાં પણ ભારત સાથે કામ કરવાની જાહેરાત કરી. એક જ ઓર્બિટમાં બન્ને\r\nદેશોના સ્પેસ સ્ટેશનો ભ્રમણ કરશે તો સાથે મળી સંશોધન કરી મદદરૂપ થઇ શકશે</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><b><span>📌</span></b><b><span>આંતરાષ્ટ્રીય સમાચાર:</span></b></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span>1. </span><span>અહેવાલો અનુસાર</span><span>, </span><span>બે શંકાસ્પદ રશિયન જાસૂસો ગુપ્ત રીતે કાર્ગો જહાજો પર\r\nયુકેમાં પ્રવેશ્યા હોવાનું માનવામાં આવે છે અને પછી તેઓ મુખ્ય લશ્કરી થાણાઓ અને\r\nમહત્વપૂર્ણ સરકારી માળખાગત સુવિધાઓની નજીકના સ્થળોએ ગયા હતા.</span></li><li style=\"text-align:justify;\"><span>2. </span><span>રશિયાએ યુક્રેન પર </span><span>700</span><span> હવાઈ હુમલા\r\nકર્યા:ભુલથી પોતાના જ શહેર પર </span><span>1000</span><span> કિલોગ્રામનો\r\nબોમ્બ ઝીંક્યો</span><span>; </span><span>યુદ્ધ અટકાવવા માટે </span><span>US-</span><span>યુક્રેન વાટાઘાટો નિષ્ફળ</span></li><li style=\"text-align:justify;\"><span>3. </span><span>ગ્રોકે યુઝર્સના સરનામા</span><span>, </span><span>ફોન નંબર</span><span>, </span><span>પરિવારની વિગતો લીક કર્યાનો આક્ષેપ- ઈલોન મસ્કની એક્સ સામે\r\nગંભીર નૈતિક-કાયદાકીય સવાલો ઉઠયા- ગ્રોક પાસે માત્ર એક સરનામાની વિગત મગાતા ફોન\r\nનંબર</span><span>, </span><span>ઈ-મેલ આઈડી સહિત પરિવારના સભ્યોની માહિતી પણ આપી દીધી </span></li><li style=\"text-align:justify;\"><span>4. </span><span>અફઘાનિસ્તાન-પાક. વચ્ચે ગોળીબાર પાંચનાં મોત બાદ યુદ્ધના ભણકારા</span></li><li style=\"text-align:justify;\"><span>5. </span><span>૨૦૨૬ માં </span><span>NJ </span><span>સહિત ૫ રાજ્યોમાં બાકીના અમેરિકા કરતાં સોશ્યિલ સેક્યુરીટી\r\nના પેમેન્ટ માં વધારો જોવા મળશે.</span></li><li style=\"text-align:justify;\"><span>6. </span><span>સંગીત સાથે</span><span>, </span><span>યુક્રેન રશિયાના હાઇપરસોનિક મિસાઇલોને લક્ષ્યથી દૂર ફેંકી\r\nરહ્યું છે. મેક ૫.૭ ની ઝડપે હવામાં ૧૫.૫ માઇલ જેટલી ઉંચી</span><span>, </span><span>રશિયાની\r\n૪.૭-ટન કિંઝાલ મિસાઇલ - જે સુધારેલા મિકોયાન </span><span>MiG-</span><span>૩૧ ઇન્ટરસેપ્ટર દ્વારા છોડવામાં આવી છે - ૩૦૦ માઇલના અંતરે ૧</span><span>,</span><span>૦૦૦ પાઉન્ડનું વોરહેડ પહોંચાડી શકે છે.</span></li><li style=\"text-align:justify;\"><span>7. </span><span>પુતિને ટ્રમ્પનો સોદો સ્વીકારવો જોઈતો હતો. હવે રશિયાનું ભાંગી પડેલું\r\nઅર્થતંત્ર તેમના પતન તરફ દોરી શકે છે.</span></li><li style=\"text-align:justify;\"><span>8. </span><span>રવિવારે બેનિનમાં જાહેર કરાયેલ બળવાને \"નિષ્ફળ\" કહેવામાં આવ્યું\r\nછે.\"રવિવાર</span><span>, 7</span><span> ડિસેમ્બર</span><span>, 2025</span><span> ના રોજ વહેલી સવારે</span><span>, </span><span>સૈનિકોના\r\nએક નાના જૂથે રાજ્ય અને તેની સંસ્થાઓને અસ્થિર કરવાના ઉદ્દેશ્યથી બળવો શરૂ કર્યો</span><span>,\"</span></li><li style=\"text-align:justify;\"><span>9. </span><span>યુક્રેનમાં રાત્રે રશિયન હુમલામાં </span><span>2</span><span> લોકોના મોત</span></li><li style=\"text-align:justify;\"><span>10. \'</span><span>હવે શ્રીમાન નાઇસ વ્યક્તિ નહીં</span><span>\': </span><span>માફી પછી\r\nડેમોક્રેટ તરીકે ચૂંટણી લડવા બદલ ટ્રમ્પે પ્રતિનિધિ હેનરી કુએલરની ટીકા કરી.\r\nટેક્સાસ ડેમોક્રેટે ગયા અઠવાડિયે કહ્યું હતું કે તેમની માફી માટે વ્હાઇટ હાઉસ સાથે\r\nકોઈ સોદો થયો નથી.</span></li><li style=\"text-align:justify;\"><span>11. </span><span>નેતન્યાહૂ કહે છે કે તેઓ ટૂંક સમયમાં ટ્રમ્પને મળશે</span><span>, </span><span>ગાઝા\r\nયોજનાનો બીજો તબક્કો </span><span>\'</span><span>બંધ</span><span>\' </span><span>થયો છે.\r\nપેલેસ્ટિનિયન એન્ક્લેવમાં બે વર્ષના યુદ્ધને સમાપ્ત કરવાની ટ્રમ્પની યોજનાના આગામી\r\nતબક્કાઓ પર વાટાઘાટો ચાલુ છે.</span></li><li style=\"text-align:justify;\"><span>12. </span><span>ન્યાયાધીશે કોમી કેસમાં બરતરફ કરાયેલા પુરાવાના ઉપયોગને અસ્થાયી રૂપે ન્યાય\r\nવિભાગ દ્વારા અટકાવ્યો</span></li><li style=\"text-align:justify;\"><span>13. </span><span>યુક્રેનની ફ્રન્ટ લાઇન પર પાછા ફરવાની રાહ જોઈ રહેલા ઘાયલ રશિયન સૈનિકોનો\r\nવિડિઓ જાહેર</span></li><li style=\"text-align:justify;\"><span>14. </span><span>કેન્ટુકીના યુ.એસ. સેનેટર રેન્ડ પોલે બધા અમેરિકનોને આરોગ્ય બચત ખાતા માટે\r\nલાયક બનાવવા માટે બિલ દાખલ કર્યું</span></li><li style=\"text-align:justify;\"><span>15. </span><span>વિશ્વનું સૌથી મોટું રહસ્ય: સેક્રેટરી રુબિયો કાર્યવાહી માટે ટ્રમ્પ સાથે\r\nજોડાયા. \"પ્રતિબંધિત પરમાણુ સુવિધાઓ પર હવાઈ ક્ષેત્રમાં કંઈક કાર્યરત હોવાના\r\nવારંવારના કિસ્સાઓ ... અને તે આપણા નથી. </span><span>UFO</span></li><li style=\"text-align:justify;\"><span>16. </span><span>યુક્રેન અદ્યતન પાણીની અંદરના ડ્રોનનો ઉપયોગ કરીને રશિયન જહાજો</span><span>, </span><span>બંદરોને ફટકારી રહ્યું છે</span></li><li style=\"text-align:justify;\"><span>17. </span><span>રશિયાએ યુએસ રાષ્ટ્રીય સુરક્ષા વ્યૂહરચનામાં ફેરફારોનું સ્વાગત કર્યું છે</span><span>, </span><span>અને કહ્યું છે કે વોશિંગ્ટનની અગાઉની નીતિથી આમૂલ પ્રસ્થાન\r\nદર્શાવતા ફેરફારો મોસ્કોના દ્રષ્ટિકોણ સાથે \"મોટે ભાગે સુસંગત\" હતા.</span></li><li style=\"text-align:justify;\"><span>18. </span><span>ટ્રમ્પ વહીવટીતંત્રે કાનૂની દરજ્જા વિના યુ.એસ.માં સ્થળાંતર કરનારાઓ માટે </span><span>$5,000</span><span> ની નવી \"આશંકા ફી\" રજૂ કરી છે</span><span>, </span><span>એક વરિષ્ઠ બોર્ડર પેટ્રોલ અધિકારીએ જાહેરાત કરી.</span></li><li style=\"text-align:justify;\"><span>19. </span><span>જ્યારે રાષ્ટ્રપતિ ટ્રમ્પ આવતા વર્ષની શરૂઆતમાં નવા વેપાર કરારને અંતિમ સ્વરૂપ\r\nઆપવા માટે બેઇજિંગનો પ્રવાસ કરશે</span><span>, </span><span>ત્યારે ચીન\r\nતેની મનપસંદ દબાણ યુક્તિઓમાંથી એકનો ઉપયોગ કરશે: દુર્લભ પૃથ્વી તત્વોની નિકાસ પર\r\nપ્રતિબંધ.</span></li><li style=\"text-align:justify;\"><span>20. </span><span>રશિયન વિપક્ષી વ્યક્તિ કહે છે કે યુક્રેનમાં હાર વિરોધ પ્રદર્શનોને વેગ આપી\r\nશકે છે</span></li><li style=\"text-align:justify;\"><span>21. </span><span>મિનિયાપોલિસમાં </span><span>ICE </span><span>ઓપરેશનમાં સાત </span><span>\'</span><span>ખરાબ</span><span>\' </span><span>ગુનેગાર ગેરકાયદેસર વિદેશીઓની ધરપકડ</span></li><li style=\"text-align:justify;\"><span>22. </span><span>ટ્રમ્પના પુત્રનો દાવો છે કે યુક્રેનિયન શહેર પર રશિયાના હુમલા પછી - યુએસ\r\nનેતા શાંતિ કરારથી દૂર જઈ શકે છે</span></li><li style=\"text-align:justify;\"><span>23. </span><span>અર્થશાસ્ત્રીઓએ ચેતવણી આપી છે કે વેનેઝુએલાની નાજુક અર્થવ્યવસ્થા માદુરોના વિરોધ\r\nછતાં અમેરિકા સાથે યુદ્ધનો સામનો કરશે નહીં: અહેવાલ</span></li><li style=\"text-align:justify;\"><span>24. </span><span>મુલાકાત પછી મેક્રોને ચીનને વેપાર પ્રતિબંધોની ધમકી આપી</span></li><li style=\"text-align:justify;\"><span>25. </span><span>રશિયાનું બુલેટપ્રૂફ </span><span>Su-25</span><span>\r\nફ્રોગફૂટ—કંઈપણ ટકી રહેવા માટે બનેલ</span></li><li style=\"text-align:justify;\"><span>26. </span><span>જાપાની જેટ પર ચીની લશ્કરી વિમાન દ્વારા તેના રડાર બંધ કર્યા પછી જાપાન વિરોધ\r\nકરે છે</span></li><li style=\"text-align:justify;\"><span>27. </span><span>ડીસીના યુએસ એટર્ની જીનીન પિરોએ વાદળી રાજ્યના ગવર્નરોને નિશાન બનાવ્યા</span><span>, </span><span>કહ્યું કે ગેરકાયદેસર સ્થળાંતર કરનારાઓને </span><span>\'</span><span>આ દેશમાં રહેવાનો અધિકાર નથી</span><span>\'</span></li><li style=\"text-align:justify;\"><span>28. </span><span>ફ્રાન્સ અને જર્મનીએ ઝેલેન્સકીને ચેતવણી આપી છે કે ટ્રમ્પનું યુએસ તેમને દગો\r\nઆપી શકે છે અને તેમણે </span><span>\'</span><span>ખૂબ જ સાવચેત</span><span>\' </span><span>રહેવું જોઈએ</span></li><li style=\"text-align:justify;\"><span>29. </span><span>ટ્રમ્પના ભૂતપૂર્વ રાષ્ટ્રીય સુરક્ષા સલાહકારે તાઇવાનને કહ્યું\"ડરવું જોઈએ\"</span></li><li style=\"text-align:justify;\"><span>30. </span><span>ગ્રોઝનીના એક બિઝનેસ સેન્ટર પર ડ્રોન હુમલા પછી ચેચન નેતા જાહેરમાં દેખાયા અને\r\nયુક્રેનિયન અધિકારીઓ સાથે બેઠકની વિનંતી કરતું નિવેદન આપ્યું.</span></li><li style=\"text-align:justify;\"><span>31. </span><span>કૃત્રિમ બુદ્ધિનો ઉપયોગ કરીને નવા પાઇલટ પ્રોગ્રામ પર ચોક્કસ રાજ્યોના ડોકટરો\r\nમેડિકેર પ્રાપ્તકર્તાઓ માટે એલાર્મ વગાડી રહ્યા છે. પૂર્વ અધિકૃતતા] ખૂબ જ\r\nસમસ્યારૂપ બની રહી છે કારણ કે તે મૂળભૂત રીતે અવરોધ તરીકે કાર્ય કરે છે. ઘણા બધા\r\nઇનકાર અને લાંબી અપીલ પ્રક્રિયાઓ છે</span></li><li style=\"text-align:justify;\"><span>32. </span><span>જાપાની જેટ પર ચીની રડાર લોક પછી જાપાન અને ઓસ્ટ્રેલિયા શાંત રહેવાની વિનંતી\r\nકરે છે</span></li><li style=\"text-align:justify;\"><span>33. </span><span>પરમાણુ સબમરીન બેઝ પર ગેરકાયદેસર ડ્રોન તોડી પાડવામાં આવ્યું. ફ્રેન્ચ\r\nઅધિકારીઓએ એટલાન્ટિક કિનારે રાષ્ટ્રના પરમાણુ સશસ્ત્ર સબમરીન બેઝ પર અનધિકૃત ડ્રોન\r\nદ્વારા ઉડાન ભરવાની તપાસ શરૂ કરી છે.</span></li><li style=\"text-align:justify;\"><span>34. </span><span>એફબીઆઈના મોસ્ટ વોન્ટેડ શંકાસ્પદ હમીદ નઝીરની ધરપકડ માટે અમેરિકા ભારતનો ટેકો\r\nમાંગે છે.</span></li><li style=\"text-align:justify;\"><span>35. </span><span>સેન્ટ્રલ બેંક ઓફ બોલિવિયાના નવા પ્રમુખ ડેવિડ એસ્પિનોઝાએ જણાવ્યું હતું કે\r\nદેશના આંતરરાષ્ટ્રીય સોનાના ભંડારમાંથી છ ટન છ વિદેશી બેંકોમાં દેવા માટે કોલેટરલ\r\nતરીકે ઉપયોગમાં લેવાય છે.</span></li><li style=\"text-align:justify;\"><span>36. </span><span>બશર અલ-અસદની સરકારના પતનના એક વર્ષ પછી</span><span>, </span><span>ભૂતપૂર્વ\r\nસમર્થકો જે હવે રશિયામાં છે તેઓ સીરિયા પાછા ફરવાની યોજના સાથે ૫૦</span><span>,</span><span>૦૦૦ લોકોનું સશસ્ત્ર જૂથ બનાવી રહ્યા છે.</span></li><li style=\"text-align:justify;\"><span>37. </span><span>દૂર ઉત્તરમાં રશિયાની લશ્કરી વસાહતો ઝડપથી વસ્તી ગુમાવી રહી છે</span></li><li style=\"text-align:justify;\"><span>38. </span><span>નેટફ્લિક્સે શુક્રવારે એક મોટા સોદા સાથે બ્લોકબસ્ટર દિવસનો અંત કર્યો</span><span>, </span><span>જેમાં ભૂતપૂર્વ ફોર્ટ મોનમાઉથ</span><span>, NJ </span><span>મિલકતની ખરીદીનો સમાવેશ થાય છે જ્યાં તે એક વિશાળ નવો મેગા-સ્ટુડિયો બનાવવાની\r\nયોજના ધરાવે છે.</span></li><li style=\"text-align:justify;\"><span>39. </span><span>પ્રત્યાર્પણ કરાયેલા મેક્સીકન ડ્રગ કિંગપિન્સને યુએસ સત્તાવાળાઓ સાથે સહયોગ\r\nકરવા અથવા જેલમાં કઠોર સજા ભોગવવાની ઓફર કરવામાં આવી રહી છે: રિપોર્ટ</span></li><li style=\"text-align:justify;\"><span>40. </span><span>વેનેઝુએલાએ રવિવારે સ્વીકાર્યું કે એક વિપક્ષી વ્યક્તિનું કસ્ટડીમાં મૃત્યુ\r\nથયું હતું</span><span>, </span><span>કારણ કે ટ્રમ્પ વહીવટીતંત્રે કારાકાસને \"અધમ\"\r\nગણાવ્યો હતો અને દક્ષિણ અમેરિકન દેશની સેનાએ યુએસ લશ્કરી દબાણમાં વધારો થવા વચ્ચે\r\nહજારો નવા સૈનિકોને શપથ લીધા હતા.</span></li><li style=\"text-align:justify;\"><span>41. </span><span>એક અજાણ્યા વિમાને જોડાણના હવાઈ ક્ષેત્રમાં ભંગ કર્યા બાદ નાટો સભ્ય\r\nરાષ્ટ્રમાં લશ્કરી સ્થાપનમાંથી બે ફાઇટર જેટ છોડવામાં આવ્યા હતા. નેધરલેન્ડ્સ</span></li><li style=\"text-align:justify;\"><span>42. </span><span>રવિવારે સવારે ટ્રુથ સોશિયલ પર રાષ્ટ્રપતિ દ્વારા ટ્રમ્પ પર લાંબી ટીકા કર્યા\r\nબાદ માફ કરાયેલા ડેમોક્રેટ હેનરી કુએલરે તેમનો સંદેશ શેર કર્યો છે.</span></li><li style=\"text-align:justify;\"><span>43. </span><span>તાઇવાન પર ચીનનો હુમલો જાપાન માટે \"અસ્તિત્વનો ખતરો\" બની શકે છે\r\nતેવી ચેતવણી આપ્યા બાદ જાપાન ટ્રમ્પ વહીવટીતંત્ર પર વધુ મજબૂત રીતે બચાવ કરવા દબાણ\r\nકરી રહ્યું હોવાના અહેવાલ છે</span><span>, </span><span>જેના કારણે\r\nબેઇજિંગ તરફથી ઉગ્ર પ્રતિક્રિયાઓ આવી હતી.</span></li><li style=\"text-align:justify;\"><span>44. </span><span>યુએસ કસ્ટમ્સ અને બોર્ડર પ્રોટેક્શન અને કોસ્ટ ગાર્ડ અમેરિકન પાણીમાં\r\nહાઇ-સ્પીડ દાણચોરી કરતા જહાજોને અટકાવવા માટે વિશિષ્ટ યુક્તિઓ અને ટેકનોલોજી તૈનાત\r\nકરે છે. </span></li><li style=\"text-align:justify;\"><span>45. </span><span>રશિયન નિષ્ણાત </span><span>\'</span><span>ફ્લાઇંગ ચેર્નોબિલ</span><span>\' </span><span>પરમાણુ\r\nશસ્ત્ર શોધવાનું સરળ હોવાનું કહેતા પુતિન ટીકાનો સામનો કરી રહ્યા છે.\r\n\"ફ્લાઇંગ ચેર્નોબિલ\" તરીકે ઓળખાતું આ શસ્ત્ર કથિત રીતે વિશ્વભરના સ્થળોએ\r\nવિનાશક પરમાણુ શસ્ત્રો લઈ જઈ શકે છે.</span></li><li style=\"text-align:justify;\"><span>46. </span><span>વ્લાદિમીર પુતિન સાથેની તાજેતરની યુક્રેન શાંતિ વાટાઘાટો ફરી એકવાર નિષ્ફળ ગઈ\r\nછે</span><span>, </span><span>અને યુરોપે અકલ્પ્ય વિચારવાનું શરૂ કર્યું છે. રશિયાના વધતા\r\nસાયબર હુમલાઓ</span><span>, </span><span>તોડફોડ અને તેના હવાઈ ક્ષેત્રના ઉલ્લંઘનને ધ્યાનમાં રાખીને</span><span>, </span><span>તે વધુ આક્રમક બનવા અને રશિયા સાથે યુદ્ધ કરવાની યોજના\r\nબનાવી રહ્યું છે.</span></li><li style=\"text-align:justify;\"><span>47. </span><span>રશિયન દળો યુક્રેનિયન સૈનિકો પાછા ખેંચીને પશ્ચિમી- દેશોએ સપ્લાય કરેલા\r\nશસ્ત્રો કબજે કરે છે</span></li><li style=\"text-align:justify;\"><span>48. </span><span>યુક્રેન યુદ્ધની પેટર્નને સૌથી મહત્વપૂર્ણ રીતે બદલી રહ્યું છે. રશિયન સૈનિકો\r\nદ્વારા નાગરિકો પર બળાત્કારથી લઈને અપહરણ અને અપમાન સુધીના જાતીય હુમલાઓ</span><span>, </span><span>યુક્રેન તે ચક્રને તોડવા માટે કામ કરી રહ્યું છે. બચી ગયેલા\r\nલોકો સાથે વિકસિત</span><span>, </span><span>ફક્ત તેમના માટે નહીં</span><span>, </span><span>પણ\r\nવૈશ્વિક સ્તરે સંઘર્ષની પરિસ્થિતિઓમાં ન્યાય કેવી રીતે પહોંચાડવામાં આવે છે તે\r\nબદલી શકે છે.</span></li><li style=\"text-align:justify;\"><span>49. </span><span>​​ઇઝરાયલ અને હમાસ ગાઝા પર ઇઝરાયલના નરસંહાર યુદ્ધને સમાપ્ત કરવા માટે\r\nયુનાઇટેડ સ્ટેટ્સની આગેવાની હેઠળના બ્લુપ્રિન્ટના બીજા તબક્કા તરફ આગળ વધવાની\r\nતૈયારી કરી રહ્યા છે</span><span>, </span><span>ત્યારે ઘેરાયેલા પેલેસ્ટિનિયન એન્ક્લેવમાં આંતરરાષ્ટ્રીય\r\nસ્થિરીકરણ દળની હજુ સુધી વ્યાખ્યાયિત ભૂમિકા પર મતભેદો છવાઈ રહ્યા છે.</span></li><li style=\"text-align:justify;\"><span>50. </span><span>અસદ પછીના સીરિયામાં ન્યાય માટે નાજુક લડાઈ. અલ-અસદના પતનના એક વર્ષ પછી</span><span>, </span><span>સીરિયાના નવા નેતૃત્વને ન્યાયમાં વિલંબ અથવા નકારથી નિરાશ\r\nસીરિયન લોકોના ભયનો સામનો કરવો પડી રહ્યો છે.</span></li><li style=\"text-align:justify;\"><span>51. </span><span>હોંગકોંગે તેની વિધાનસભાની ચૂંટણીઓમાં લગભગ રેકોર્ડ-ઓછું મતદાન નોંધાવ્યું છે</span><span>, </span><span>કારણ કે લગભગ આઠ દાયકામાં શહેરમાં થયેલી સૌથી ખરાબ આગ\r\nપ્રત્યેના ગુસ્સાએ \"દેશભક્તો\" સુધી મર્યાદિત મતદાન માટે સમર્થન મેળવવાના\r\nસરકારી પ્રયાસોને ઢાંકી દીધા હતા.</span></li><li style=\"text-align:justify;\"><span>52. </span><span>રવાન્ડાના રાષ્ટ્રપતિ પોલ કાગામે </span><span>\'</span><span>લોકશાહી</span><span>, </span><span>સ્વતંત્રતા અને માનવ અધિકારો</span><span>\' </span><span>પર ભાર\r\nમૂકવા બદલ ટ્રમ્પિયન રાજદ્વારીની પ્રશંસા કરી.ડેમોક્રેટિક રિપબ્લિક ઓફ કોંગો અને રવાન્ડા વચ્ચેના સંઘર્ષ પર અમેરિકન\r\nરાષ્ટ્રપતિએ જે ધ્યાન</span><span>, </span><span>ધ્યાન</span><span>, </span><span>ઉર્જા અને\r\nદબાણ લાવ્યું હતું તે તેમણે ક્યારેય જોયું નથી</span><span>, </span><span>જેના\r\nકારણે </span><span>4</span><span> ડિસેમ્બરે વોશિંગ્ટનમાં બંને પક્ષો વચ્ચે એક કામચલાઉ કરાર\r\nપર હસ્તાક્ષર થયા.</span></li><li style=\"text-align:justify;\"><span>53. </span><span>કેનેડાએ સીરિયાને </span><span>\'</span><span>આતંકવાદ</span><span>\'</span><span>ને સમર્થન આપતા રાજ્યોની યાદીમાંથી દૂર કર્યું. ઓટાવા\r\nદેશમાં સ્થિરતા વધારવા માટે યુએસ તેમજ સીરિયન સરકારના પ્રયાસો દ્વારા સમાન પગલાનો\r\nઉલ્લેખ કરે છે.</span></li></ul>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">નોંધ :- </span><span style=\"color:#FF0000;\">AI </span><span style=\"color:#FF0000;\">અને ઈન્ટરનેટ સૉફ્ટવેરની મદદથી અહીં આપેલા\r\nહેડલાઈન્સ માત્ર ગુજરાતી ભાષાંતર છે જેનું સંકલન</span><span style=\"color:#FF0000;\">, </span><span style=\"color:#FF0000;\">સમન્વય અને પુનઃક્રમબદ્ધતા માત્ર શૈક્ષણિક અને\r\nશિક્ષણ હેતુઓ માટે આપવામાં આવેલ છે.</span></p>\r\n\r\n<p style=\"text-align:justify;\"><span style=\"color:#FF0000;\">The securities quoted are for illustration only and are not\r\nrecommendatory. Investment in securities market are subject to market risks.\r\nRead and agree Disclaimer and related all the documents carefully before\r\ninvesting, mentioned on </span><span><a href=\"http://www.nikhilbhatt.in/\"><span style=\"color:#0000FF;text-decoration:none;\">www.nikhilbhatt.in</span></a></span></p>','https://blogger.googleusercontent.com/img/a/AVvXsEguU3pDY9m7n0bQNAgqSio1bYfoUsCYSzH0yiuoHT0lxYul76bHdlMOjsQYZM7B6pvewnVlbGun_dtu1zQfu3Q35frPRRlGDcfZEIVy3VrWsl30_dSR7kwatfW3jytTfbCO9QQKWHf0aPcswJDdM7JVBD38jKzfTXBbviEyl052PsIuquY0WyxnT3kOTZQ','2025-12-09','active','2026-09-25 07:56:21','2026-09-25 07:56:21'),
(273,'46586263705740095','Fund Houses Update - 08 December 2025',NULL,'<div style=\"text-align:center;\"><a href=\"https://blogger.googleusercontent.com/img/a/AVvXsEg6CYtwv9uJYsupwBBcaXH5PyODuyu0vhuCXq9vUTXj5brHKimRcutFTR6467hYqA_GAF_Oqz9QKh3g5C57GNbJyWY1gWD3c3Ruv3rC2vwn0-eJcVWqSKotbBSWGtmfp1r4TKCCYBRJTjHlTgwI8Y5TPM-EIFygK9Q6jKH5zKBEfoT_b0fNjn-iYrPieRs\"><img alt=\"\" height=\"240\" src=\"https://blogger.googleusercontent.com/img/a/AVvXsEg6CYtwv9uJYsupwBBcaXH5PyODuyu0vhuCXq9vUTXj5brHKimRcutFTR6467hYqA_GAF_Oqz9QKh3g5C57GNbJyWY1gWD3c3Ruv3rC2vwn0-eJcVWqSKotbBSWGtmfp1r4TKCCYBRJTjHlTgwI8Y5TPM-EIFygK9Q6jKH5zKBEfoT_b0fNjn-iYrPieRs\" width=\"266\" /></a></div><p style=\"text-align:justify;\"><span>Dear\r\nTrader... </span></p>\r\n\r\n<p style=\"text-align:justify;\"><span>Fund\r\nHouses Recommendations </span></p>\r\n\r\n<ul><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">GS on KIMS: </span><span>Initiate Buy on\r\nCompany, target price at Rs 900/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">GS on Max Health: </span><span>Initiate Buy on\r\nCompany, target price at Rs 1325/<span style=\"color:#0000FF;\">Sh (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Nuvama on Sona BLW: </span><span>Maintain Buy on\r\nCompany, target price at Rs 750/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">MS on Suzlon: </span><span>Maintain Overweight\r\non Company, target price at Rs 78/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">Kotak on Tata Capital: </span><span>Initiate Add\r\non Company, target price at Rs 360/Sh<span style=\"color:#0000FF;\"> (Positive)</span></span></li><li style=\"text-align:justify;\"><span style=\"color:#0000FF;\">MS on Bajaj Finance: </span><span>Maintain Overweigh