INSERT INTO `user_blogs` (`id`,`user_id`,`author_name`,`author_email`,`author_photo`,`author_designation`,`author_reg_no`,`author_website`,`title`,`slug`,`content`,`status`,`approved_at`,`created_at`,`updated_at`) VALUES (8,NULL,'Het Pathak',NULL,NULL,'Sales Manager - Kotak Life',NULL,NULL,'દર વર્ષે વીમાનું પ્રીમિયમ ભરો છો? તો આ તક વિશે જાણો!','user-blog','<p>આજના સમયમાં દરેક વ્યક્તિ પોતાના અને પરિવારના સુરક્ષિત ભવિષ્ય માટે જીવન વીમો લે છે. બાળકોના શિક્ષણથી લઈને પરિવારની આર્થિક સુરક્ષા અને નિવૃત્તિના આયોજન સુધી, જીવન વીમો મહત્ત્વની ભૂમિકા ભજવે છે. લોકો દર વર્ષે પોતાની પૉલિસીનું પ્રીમિયમ ભરે છે, પરંતુ શું તેઓ વીમા ક્ષેત્રમાં સલાહકાર તરીકે જોડાઈને આવક મેળવવાની તક વિશે જાણે છે?</p>
INSERT INTO `user_blogs` (`id`,`user_id`,`author_name`,`author_email`,`author_photo`,`author_designation`,`author_reg_no`,`author_website`,`title`,`slug`,`content`,`status`,`approved_at`,`created_at`,`updated_at`) VALUES (9,NULL,'Paresh Dave',NULL,'blog-authors/zMasxohNkVPtTzKoKegl0xEQSSfUcjiEoZuMiQw5.jpg','Diploma in Mechanical Engineering',NULL,NULL,'Short-Term Effects of a Gulf War on the Indian Market','short-term-effects-of-a-gulf-war-on-the-indian-market','<p>A war or military conflict in the Gulf countries can have significant short-term effects on the Indian market. Since India is heavily dependent on crude oil imports, any increase in international crude oil prices caused by a war can directly affect the Indian economy.</p>
